                {
                    text2 = "An";
                    string text4 = "";
                    string text4Loc = "";
                    foreach (Ability ability in value.Abilities)
                    {
                        text4 = text4 + ", " + AbilitiesUtil.GetInfo(ability).rulebookName;
                        text4Loc = text4Loc + ", " + RussianLanguagePack.Localize(AbilitiesUtil.GetInfo(ability).rulebookName);
                    }
                    text4 += ".";
                    text4Loc += ".";
                    text3 = string.Format("An {0} is defined as: {1} Power, {2} Health", value.DisplayedName, value.Attack, value.Health) + text4;
                    text3Loc = string.Format("{0}: атака {1}, здоровье {2}", value.DisplayedNameLocalized, value.Attack, value.Health) + text4Loc;
                }
                string text5 = string.Concat(new string[] { text2, " ", value.DisplayedName, " is created in your hand. ", text3 });
                string text5LocCardName = value.DisplayedNameLocalized;
                string text5Loc = string.Concat(new string[] { text2Loc, " ", text5LocCardName, " появится у вас в руке. ", text3Loc });
                Translate(GUID, null, text5, text5Loc, Language.Russian);
                Translate(GUID, null, "While " + value.DisplayedNameLocalized + " is on the board, remove ally Terrain and Pelt cards and transform the rest into random Apostles.", "Пока карта " + value.DisplayedNameLocalized + " находится на столе, удалите союзные карты местности и шкур, а остальные превратите в случайных Апостолов.", Language.Russian);
                Translate(GUID, null, "[c:bR]The Clock[c:] and your [c:bR]" + value.DisplayedNameLocalized + "[c:] will remain in that abandoned time.", "[c:bR]Часы[c:] и твоя карта [c:bR]" + value.DisplayedNameLocalized + "[c:] останутся в этом забытом времени.", Language.Russian);
                Translate(GUID, null, "False " + value.DisplayedNameLocalized, "Ложный " + value.DisplayedNameLocalized, Language.Russian);
                Translate(GUID, null, "[c:bB]That " + value.DisplayedNameLocalized + " costs more energy than you have.[c:]", "[c:bB]У тебя недостаточно энергии для карты " + value.DisplayedNameLocalized + ".[c:]", Language.Russian);
            }
            if (source == null)
            for (int max = 1; max <= 10; max++)
            {
                Translate(GUID, null, "[c:bB]Do you still not get it? It costs " + max.ToString() + " energy and you don't have enough.[c:]", "[c:bB]Всё ещё не понял? Нужно энергии: " + max.ToString() + ", а у тебя недостаточно.[c:]", Language.Russian);
                for (int count = 0; count < max; count++)
                {
                    Translate(GUID, null, "[c:bB]That costs " + max.ToString() + " energy and you have " + count.ToString() + ".[c:]", "[c:bB]Нужно энергии: " + max.ToString() + "; у тебя есть " + count.ToString() + ".[c:]", Language.Russian);
                }
            }


            // LifeCostAPI
            if (source == null) Debug.Log("Post Register Translations for LifeCostAPI");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped to play [c:bG]" + value.DisplayedNameLocalized + "[c:].", "Твои [c:bG]весы[c:] слишком сильно склонены против тебя, чтобы разыграть [c:bG]" + value.DisplayedNameLocalized + "[c:].", Language.Russian);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]" + value.DisplayedNameLocalized + "[c:] requires you to pay in life, in which you can not fullfill without killing yourself.", "Карта [c:bG]" + value.DisplayedNameLocalized + "[c:] требует оплаты жизнью; ты не можешь заплатить, не погибнув.", Language.Russian);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You would kill yourself if you played [c:bG]" + value.DisplayedNameLocalized + "[c:]. Your [c:bG]Scales[c:] are too tipped", "Разыграв [c:bG]" + value.DisplayedNameLocalized + "[c:], ты погибнешь. Твои [c:bG]весы[c:] слишком сильно склонены.", Language.Russian);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bG]Scales[c:] are too tipped and you lack the [c:gray]Foils[c:] to play " + value.DisplayedNameLocalized + ".", "Твои [c:bG]весы[c:] слишком сильно склонены, а [c:gray]фойловых карт[c:] не хватает для розыгрыша " + value.DisplayedNameLocalized + ".", Language.Russian);
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You lack the foils to play that [c:gray]" + value.DisplayedNameLocalized + "[c:].", "У тебя недостаточно фойловых карт для розыгрыша [c:gray]" + value.DisplayedNameLocalized + "[c:].", Language.Russian);
                for (int count = 0; count <= 20; count++)
                {
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:gray]" + value.DisplayedNameLocalized + "[c:] requires you pay it's cost in [c:gray]foils[c:], that which you have [c:gray]" + count.ToString() + "[c:].", "Стоимость [c:gray]" + value.DisplayedNameLocalized + "[c:] нужно оплатить [c:gray]фойловыми картами[c:]; у тебя их [c:gray]" + count.ToString() + "[c:].", Language.Russian);
                    Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That [c:gray]" + value.DisplayedNameLocalized + "[c:] has the cost of [c:gray]" + count.ToString() + "[c:] foils, which you do not have.", "Карта [c:gray]" + value.DisplayedNameLocalized + "[c:] стоит [c:gray]" + count.ToString() + "[c:] фойловых карт, а у тебя их недостаточно.", Language.Russian);
                }
            }

            // Sire_MoDeers
            if (source == null) Debug.Log("Post Register Translations for Sire_MoDeers");
            foreach (var value in cards)
            {
                if (!value.HasDisplayedNameEnglish) continue;
                Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, value.DisplayedName + "'s Protector", "Защитник: " + value.DisplayedNameLocalized, Language.Russian);
            }

            if (source == null) Debug.Log("Post Register Translations Ended");
            stopwatch.Stop();
            if (source == null) Debug.Log($"PostRegisterTranslations 执行时间: {stopwatch.ElapsedMilliseconds} ms");
        }

        private static List<PostRegisterCardData> CachePostRegisterCardData(IEnumerable<CardInfo> source)
        {
            var cards = new List<PostRegisterCardData>();
            foreach (var card in source)
            {
                if (card.SafeIsUnityNull()) continue;
                cards.Add(new PostRegisterCardData(card, card.IsBaseGameCard()));
            }
            return cards;
        }

        private sealed class PostRegisterCardData
        {
            public PostRegisterCardData(CardInfo card, bool isBaseGameCard)
            {
                IsBaseGameCard = isBaseGameCard;
                DisplayedNameEnglish = card.DisplayedNameEnglish;
                DisplayedNameLocalized = card.DisplayedNameLocalized;
                DisplayedName = card.displayedName;
                Description = card.description;
                Name = card.name;
                Attack = card.Attack;
                Health = card.Health;
                Abilities = card.Abilities?.ToArray() ?? Array.Empty<Ability>();
            }

            public bool IsBaseGameCard { get; }
            public string DisplayedNameEnglish { get; }
            public string DisplayedNameLocalized { get; }
            public string DisplayedName { get; }
            public string Description { get; }
            public string Name { get; }
            public int Attack { get; }
            public int Health { get; }
            public Ability[] Abilities { get; }
            public bool HasDisplayedNameEnglish => DisplayedNameEnglish != null;
            public bool HasDisplayedName => DisplayedName != null;
        }
        private static bool NameStartsWithVowel(string name)
        {
            if (string.IsNullOrEmpty(name))
            {
                return false;
            }
            char c = name.ToLowerInvariant()[0];
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        }

    }

