            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONTINUE GRIMORA RUN", "ПРОДОЛЖИТЬ ЗАХОД ЗА ГРИМОРУ", Language.Russian);

