            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "0 = Default. Use the mod's internal blueprint system.\n1 = Randomized. Encounters are completely randomized using the mod's internal card pool.\n2 = Custom. Encounters are from made and used from the JSON files.\n3 = Mixed. Encounters are from both default list and custom list.", "0 = По умолчанию. Используется внутренняя система схем мода.\n1 = Случайно. Встречи полностью случайны и используют внутренний набор карт мода.\n2 = Свой вариант. Встречи создаются по файлам JSON.\n3 = Смешанный. Встречи берутся и из стандартного списка, и из пользовательского.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "0 = W for viewing deck, S for getting up from the table.\n1 = Up arrow for viewing deck, down arrow for getting up from the table.", "0 = W — просмотр колоды, S — встать из-за стола.\n1 = Стрелка вверх — просмотр колоды, стрелка вниз — встать из-за стола.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "0 = Default. Flat 50% burn rate for each lever option on second shock.\n1 = Base 30% chance to burn plus 0%, 10%, or 20% for low, medium, high, respectively. Meaning, if the first shock is high then the second is high, the chance for the card to be destroyed is 70%.\n2 = Low: 12.5%, Medium: 17.5%, High 30%. Meaning, if the first shock is high, then the second one is also high, the chance for the card to be destroyed is 60%.\n3 = Low: 12.5%, Medium: 20%, High 27.5%. Meaning, if the first shock is high, then the second one is also high, the chance for the card to be destroyed is 55%.", "0 = По умолчанию. При втором разряде вероятность сжечь карту равна 50% при любом положении рычага.\n1 = Базовый шанс 30% плюс 0%, 10% или 20% для слабого, среднего или сильного разряда соответственно. Два сильных разряда дают вероятность уничтожения карты 70%.\n2 = Слабый: 12.5%, средний: 17.5%, сильный: 30%. Два сильных разряда дают вероятность уничтожения карты 60%.\n3 = Слабый: 12.5%, средний: 20%, сильный: 27.5%. Два сильных разряда дают вероятность уничтожения карты 55%.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont change this value, it is used by the game to store certain events.", "Не меняйте это значение: игра использует его для сохранения определённых событий.", Language.Russian);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Souls to select any card on the board, [creature] will deal 1 damage to the selected card if it is an opponent card, if it isn't, [creature] will heal it for 1 health.", "Заплатите 3 души и выберите любую карту на доске. Если это карта соперника, карта [creature] нанесёт ей 1 урон; иначе карта [creature] восстановит ей 1 здоровье.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Comin' right up!", "Сейчас будет!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Shot", "Выстрел душой", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Soul to deal 1 damage to the creature across from [creature].", "Заплатите 1 душу, чтобы нанести 1 урон существу напротив карты [creature].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disinter", "Эксгумация", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to create a Skeleton in your hand.", "Заплатите 1 кость, чтобы создать Скелета у себя в руке.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Materialize", "Материализация", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Souls for [creature] to summon a copy in your hand.", "Заплатите 2 души, чтобы карта [creature] призвала свою копию вам в руку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Souls, [creature] will trap a random opponent card in a coffin, which will release the original card again upon perishing.", "Заплатите 2 души. Карта [creature] заточит случайную карту соперника в гроб, который при гибели выпустит исходную карту.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funeral Rites", "Погребальные обряды", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Sucker", "Поглотитель душ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opponent creature perishes, [creature] will store a charge of soul energy, up to 4. Activating this sigil will add 3 soul energy to your current energy counter, and one max energy.", "Когда существо соперника погибает, карта [creature] накапливает заряд энергии душ, но не более 4. Активация этого символа добавляет 3 энергии душ к вашей текущей энергии и увеличивает максимальную энергию на единицу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Weighted Die", "Утяжелённый кубик", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones for the power of [creature] to be randomized between 0 and 5.", "Заплатите 2 кости, чтобы сила карты [creature] стала случайным числом от 0 до 5.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] alternates between striking the opposing space to the left and right from it.", "Карта [creature] поочерёдно атакует противолежащие ячейки слева и справа от себя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] is unaffected by the motion of the ship.", "На карту [creature] не влияет движение корабля.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike its adjacent slots, and each opposing space to the left, right, and center of it.", "Карта [creature] атакует соседние с ней ячейки и все противолежащие ячейки слева, справа и прямо напротив себя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] yields no bones upon death.", "Карта [creature] не даёт костей при гибели.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] kills another creature, gain 2 bones.", "Когда карта [creature] убивает другое существо, вы получаете 2 кости.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes 1 Soul from you at the end of every turn and stores it as 2 Bones, up to a maximum of 8. When [creature] dies, you gain all bones contained in it.", "В конце каждого хода карта [creature] забирает у вас 1 душу и сохраняет её в виде 2 костей, но не более 8 костей. Когда карта [creature] погибает, вы получаете все накопленные в ней кости.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] empowers each Skeleton on the owner's side of the board, providing a +1 buff to their power.", "Карта [creature] усиливает каждого Скелета на стороне своего владельца на доске, давая ему +1 к силе.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sea Shanty", "Морская песня", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing slots to the left, right, and center of it randomly, up to 3 times.", "Карта [creature] до 3 раз атакует случайные противолежащие ячейки слева, справа и прямо напротив себя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the card opposing it is Frozen Away if not already frozen.", "Когда карта [creature] погибает, карта напротив неё получает «Разморозку», если ещё не заморожена.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] dies, gain a consumable item, if you have a free slot.", "Когда карта [creature] погибает, вы получаете расходуемый предмет, если для него есть свободная ячейка.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Skeleton is created in each empty space on the owner's side. [define:Skeleton]", "Когда разыгрывается карта [creature], в каждой пустой ячейке на стороне её владельца создаётся Скелет. [define:Skeleton]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Horde", "Орда скелетов", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shipwreck Finder", "Искатель затонувших кораблей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Shipwreck is created on each empty adjacent space. [define:arackulele.inscryption.grimoramod_Shipwreck_Dams]", "Когда разыгрывается карта [creature], в каждой пустой соседней ячейке создаются Обломки корабля. [define:arackulele.inscryption.grimoramod_Shipwreck_Dams]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletons Within", "Скелеты внутри", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once [creature] is struck, draw a card from your Skeleton pile.", "Когда карту [creature] ударяют, возьмите карту из своей стопки Скелетов.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full o' candy", "Полно конфет", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will yield candy upon death, maybe this will be useful for later.", "Карта [creature] оставляет конфеты после гибели. Возможно, позже они пригодятся.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will move in a random direction.", "В конце хода владельца карта [creature] движется в случайном направлении.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whenever [creature] moves, it leaves a trail of Embers. [define:arackulele.inscryption.grimoramod_Flames]", "При каждом перемещении карта [creature] оставляет за собой след из углей. [define:arackulele.inscryption.grimoramod_Flames]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guarding Presence", "Защитное присутствие", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opposing creature is placed opposite to an empty space, [creature] will move to that empty space.", "Когда существо соперника помещают напротив пустой ячейки, карта [creature] перемещается в эту ячейку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Starved", "Костяной голод", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have no Bones, at the start of your turn [creature] deals 2 more damage.", "Если в начале вашего хода у вас нет костей, карта [creature] наносит на 2 урона больше.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space. If only one creature is in the opposing spaces, this card will strike that creature twice. ", "Карта [creature] атакует каждую противолежащую ячейку. Если в этих ячейках только одно существо, эта карта атакует его дважды.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enraged Giant", "Разъярённый великан", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space.", "Карта [creature] атакует каждую противолежащую ячейку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fledgling", "Детёныш", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After one turn on the board, [creature] will evolve into a greater form.", "Проведя один ход на доске, карта [creature] превращается в более сильную форму.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Ability", "Случайная способность", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is drawn, this sigil is replaced with another sigil at random.", "Когда вы берёте карту [creature], этот символ заменяется другим случайным символом.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it haunts the space it died in. The first creature played on this space gain its old sigils.", "Когда карта [creature] погибает, её дух остаётся в ячейке гибели. Первое разыгранное в этой ячейке существо получает её прежние символы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunting Call", "Призрачный зов", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every turn [creature] is on the Board, it will take a Bone from you, if you have no Bones, it perishes.", "Каждый ход, пока карта [creature] находится на доске, она забирает у вас одну кость. Если костей нет, она погибает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the creature in the opposing slot is dragged onto the owner's side of the board.", "Когда карта [creature] погибает, существо в ячейке напротив неё перетаскивается на сторону её владельца на доске.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle ally card perishes, [creature] gains 1 power.", "Когда погибает союзная карта без «Немощи», карта [creature] получает 1 силу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike the opposing slot as if the board was flipped. A card in the far left slot will attack the opposing far right slot.", "Карта [creature] атакует противолежащую ячейку так, будто доска перевёрнута. Карта в крайней левой ячейке атакует крайнюю правую ячейку соперника.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Bonedigger sigil.", "Когда карта [creature] погибает, её владелец выбирает существо, которое получит символ «Костекоп».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Waterborne sigil.", "Когда карта [creature] погибает, её владелец выбирает существо, которое получит символ «Амфибия».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 health per turn. When [creature] dies, the creature opposing it, as well as adjacent friendly creatures, are dealt 10 damage.", "Карта [creature] теряет 1 здоровье за ход. Когда карта [creature] погибает, существо напротив неё и соседние союзные существа получают 10 урона.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] would be struck, a severed limb is created in its place and this card moves into an adjacent open slot.", "Когда карта [creature] должна получить удар, на её месте создаётся отрубленная конечность, а сама карта перемещается в соседнюю пустую ячейку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each time [creature] deals damage directly, it loses 1 power and health.", "Каждый раз, нанося прямой урон, карта [creature] теряет 1 силу и здоровье.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, also play the cards in your hand that were adjacent to this card for free.", "Когда разыгрывается карта [creature], бесплатно разыгрываются и карты, которые находились рядом с ней у вас в руке.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Douse", "Тушение", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When played,[creature] will extinguish all cards on the Board.", "Когда разыгрывается карта [creature], она тушит все карты на доске.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot be attacked from the opposing slot. The opposing slot, if possible, instead attacks one of its adjacent friendly cards.", "Карту [creature] нельзя атаковать из ячейки напротив неё. Если возможно, карта в этой ячейке вместо этого атакует одну из соседних союзных карт.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards on the owner's side of the field are unaffected by Brittle.", "На карты на стороне владельца на доске не действует «Немощь».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike its adjacent slots, except other Raiders.", "Карта [creature] атакует соседние ячейки, кроме тех, где находятся другие Налётчики.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it carves its Sigils into adjacent Cards.", "Когда разыгрывается карта [creature], она вырезает свои символы на соседних картах.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sculptor", "Скульптор", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will attempt to find a host in an adjacent friendly slot, hiding under it providing a +1/+1 buff. Cards on the left take priority.", "Карта [creature] пытается найти носителя в соседней союзной ячейке, прячется под ним и даёт ему +1/+1. Карты слева имеют приоритет.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] hits an opposing card, one of the targets adjacent allies will take damage as well ", "Когда карта [creature] бьёт карту соперника, одна из соседних союзниц цели тоже получает урон.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it provides an energy soul to its owner.", "Когда разыгрывается карта [creature], её владелец получает энергетическую душу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HellHound's Thirst", "Жажда адского пса", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for each bone the player currently has.", "Карта с этим символом получает 1 атаку за каждую кость, имеющуюся у игрока.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wrath Of Halloween", "Гнев Хеллоуина", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil has 10 attack, 1 for each Candy Bucket Sawyer has left.", "Карта с этим символом имеет 10 атаки: по 1 за каждое оставшееся у Сойера Ведро конфет.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trusty ol' Crew", "Верная старая команда", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for every pirate on the board.", "Карта с этим символом получает 1 атаку за каждого пирата на доске.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inanimate Attack", "Неживая атака", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil gains 1 attack for every card that has 0 attack on the board.", "Карта с этим символом получает 1 атаку за каждую карту с 0 атаки на доске.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Half Bones", "Половина костей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Bones that the owner has on their side of the table.", "Значение этого символа равно числу костей на стороне владельца на столе.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Death", "Двойная смерть", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Soul to add power to [creature] randomly between 1 and 6.", "Заплатите 1 душу, чтобы карта [creature] получила случайную прибавку к силе от 1 до 6.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to heal [creature] to max health.", "Заплатите 2 кости, чтобы полностью восстановить здоровье карты [creature].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alternating Strike", "Попеременный удар", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anchored", "На якоре", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Area Of Effect Strike", "Удар по площади", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "Бухарик кровью", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneless", "Бескостный", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Thief", "Похититель костей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty", "Награда за голову", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning", "Горящий", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] takes 1 Damage at the end of your turn, when it gets attacked by another Card, that card gets set on fire.", "В конце вашего хода карта [creature] получает 1 урон. Когда другая карта атакует её, атакующая карта загорается.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaos Strike", "Удар хаоса", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold Front", "Холодный фронт", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Collector", "Коллекционер", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic", "Непредсказуемый", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame Strafe", "Огненный манёвр", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant Strike", "Гигантский удар", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunter", "Скиталец", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hook Line And Sinker", "Крючок, леска и грузило", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Imbued", "Наполнение", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inverted Strike", "Обратный удар", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Latch Bone Digger", "Передача костекопа", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Latch Submerge", "Передача погружения", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lit Fuse", "Горящий фитиль", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loose Limb", "Отрыв конечности", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Malnourishment", "Недоедание", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Marching Dead", "Марш мертвецов", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessive", "Одержимый", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Puppeteer", "Кукловод", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raider", "Налётчик", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skin Crawler", "Ползун под кожей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slasher", "Рубака", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spirit Bearer", "Носитель душ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of this card is equal to the number of Green Gems that the owner has on their side of the table.", "Сила этой карты равна числу зелёных самоцветов на стороне её владельца на столе.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION I - ABILITIES {0}", "ПРИЛОЖЕНИЕ XII, ПОДРАЗДЕЛ I — СПОСОБНОСТИ {0}", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "APPENDIX XII, SUBSECTION II - VARIABLE STATS {0}", "ПРИЛОЖЕНИЕ XII, ПОДРАЗДЕЛ II — ПЕРЕМЕННЫЕ ХАРАКТЕРИСТИКИ {0}", Language.Russian);

            // Card
            RegisterCard("Skeleton", "Скелет");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The puppet becomes the puppeteer, yet still forever cursed by their dangling restraints.", "Марионетка стала кукловодом, но всё ещё навеки проклята свисающими путами.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "Кукловод", Language.Russian);
            RegisterCard("Animator", "Кукловод");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A formless Creature, that yet lingers. Truly a horrific sight.", "Бесформенное существо, которое всё ещё здесь. Воистину жуткое зрелище.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apparition", "Фантом", Language.Russian);
            RegisterCard("Apparition", "Фантом");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only a fool would need such assistance.", "Лишь глупцу понадобилась бы такая помощь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Graven Ashes", "Высеченный пепел", Language.Russian);
            RegisterCard("Graven Ashes", "Высеченный пепел");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's foul breath doesn't concern me, it's the Tampered Coffins it leaves behind!", "Меня тревожит не его зловонное дыхание, а испорченные гробы, которые он оставляет после себя!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bal-Bal", "Бал-бал", Language.Russian);
            RegisterCard("Bal-Bal", "Бал-бал");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SCREAMING TERROR. THEY GO STRAIGHT THROUGH TO ATTACK THEIR PREY.", "ВОПЯЩИЙ УЖАС. ОНИ ПРОХОДЯТ НАСКВОЗЬ, ЧТОБЫ АТАКОВАТЬ СВОЮ ДОБЫЧУ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Banshee", "Банши", Language.Russian);
            RegisterCard("Banshee", "Банши");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bartender", "Бармен", Language.Russian);
            RegisterCard("The Bartender", "Бармен");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "spent his days serving harmful cocktails for those deserving of his poisonous wrath. Doesn't regret it at all.", "Он проводил дни, подавая губительные коктейли тем, кто заслужил его ядовитый гнев. Ничуть не жалеет.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Bones", "Огромные кости", Language.Russian);
            RegisterCard("Big Bones", "Огромные кости");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burly Bones", "Крепкие кости", Language.Russian);
            RegisterCard("Burly Bones", "Крепкие кости");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beefy Bones", "Могучие кости", Language.Russian);
            RegisterCard("Beefy Bones", "Могучие кости");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cal C. Um", "Кал Ций", Language.Russian);
            RegisterCard("Cal C. Um", "Кал Ций");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sizeable Bones", "Крупные кости", Language.Russian);
            RegisterCard("Sizeable Bones", "Крупные кости");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Considerable Bones", "Огромные кости", Language.Russian);
            RegisterCard("Considerable Bones", "Огромные кости");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vigorous Bones", "Крепкие кости", Language.Russian);
            RegisterCard("Vigorous Bones", "Крепкие кости");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hefty Bones", "Тяжёлые кости", Language.Russian);
            RegisterCard("Hefty Bones", "Тяжёлые кости");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A RATHER BURLY SKELETON, IT IS VERY RICH IN CALCIUM.", "ДОВОЛЬНО КРЕПКИЙ СКЕЛЕТ. В НЁМ ОЧЕНЬ МНОГО КАЛЬЦИЯ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This sack is full of body parts. Maybe you'll find something useful in there.", "Этот мешок полон частей тел. Возможно, внутри найдётся что-нибудь полезное.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bloody Sack", "Окровавленный мешок", Language.Russian);
            RegisterCard("Bloody Sack", "Окровавленный мешок");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Collective", "Костяной коллектив", Language.Russian);
            RegisterCard("Bone Collective", "Костяной коллектив");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOUSANDS OF TINY BONES COALESCE INTO A HUMANOID FORM ONLY TO DISPERSE IN A CLATTERING SWARM THE NEXT MOMENT.", "ТЫСЯЧИ КРОШЕЧНЫХ КОСТЕЙ СЛИВАЮТСЯ В ЧЕЛОВЕКОПОДОБНУЮ ФИГУРУ, ЧТОБЫ В СЛЕДУЮЩИЙ МИГ РАССЫПАТЬСЯ ГРЕМЯЩИМ РОЕМ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "USED TO BE A VERY LOYAL DOG BACK IN THE DAY. WELL, ONE DAY HIS OWNER DIED.", "КОГДА-ТО ЭТО БЫЛ ОЧЕНЬ ВЕРНЫЙ ПЁС. НО ОДНАЖДЫ ЕГО ХОЗЯИН УМЕР.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonehound", "Костяная гончая", Language.Russian);
            RegisterCard("Bonehound", "Костяная гончая");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SO YOU HAVE MADE IT HERE, YOU CANNOT END WHAT I HAVE STARTED, IT HAS GONE TOO FAR.", "ИТАК, ТЫ ДОБРАЛСЯ СЮДА. ТЕБЕ НЕ ОСТАНОВИТЬ НАЧАТОЕ МНОЙ. ВСЁ ЗАШЛО СЛИШКОМ ДАЛЕКО.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord", "Повелитель костей", Language.Russian);
            RegisterCard("The Bonelord", "Повелитель костей");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD SHEDS ITS OLD HORNS, THEY TAKE ON A LIFE OF THEIR OWN, TO ONE DAY USURP THEIR MASTER.", "ПОВЕЛИТЕЛЬ КОСТЕЙ СБРАСЫВАЕТ СТАРЫЕ РОГА. ОНИ ОБРЕТАЮТ СОБСТВЕННУЮ ЖИЗНЬ, ЧТОБЫ ОДНАЖДЫ СВЕРГНУТЬ СВОЕГО ХОЗЯИНА.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonelord's Horn", "Рог Повелителя костей", Language.Russian);
            RegisterCard("Bonelord's Horn", "Рог Повелителя костей");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT PARTICULARLY INSPIRING. YOU CAN HAVE IT.", "НЕ ОСОБО ВДОХНОВЛЯЕТ. МОЖЕШЬ ЗАБРАТЬ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Heap", "Груда костей", Language.Russian);
            RegisterCard("Bone Heap", "Груда костей");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IF I AM TRAPPED, SO WILL YOU. YOU CANNOT END THIS.", "ЕСЛИ Я В ЛОВУШКЕ, ТЫ ТОЖЕ БУДЕШЬ В НЕЙ. ТЕБЕ НЕ ПОЛОЖИТЬ ЭТОМУ КОНЕЦ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Prince", "Костяной принц", Language.Russian);
            RegisterCard("Bone Prince", "Костяной принц");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHE FEEDS ON PEOPLES BREATH, MAYBE ONE IS STANDING RIGHT BEHIND YOU RIGHT NOW.", "ОНА ПИТАЕТСЯ ДЫХАНИЕМ ЛЮДЕЙ. ВОЗМОЖНО, ОДНА ИЗ НИХ ПРЯМО СЕЙЧАС СТОИТ У ТЕБЯ ЗА СПИНОЙ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boo Hag", "Призрачная ведьма", Language.Russian);
            RegisterCard("Boo Hag", "Призрачная ведьма");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHE COMMANDS OTHERS WITH STRENGTH AND GLAMOUR. THEY WILL FOLLOW HER EVERYWHERE.", "ОНА ПОВЕЛЕВАЕТ ДРУГИМИ СИЛОЙ И ОЧАРОВАНИЕМ. ОНИ ПОСЛЕДУЮТ ЗА НЕЙ ПОВСЮДУ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calavera Catrina", "Калавера Катрина", Language.Russian);
            RegisterCard("Calavera Catrina", "Калавера Катрина");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A GROUP OF SKELETONS IS CALLED A CATACOMB. THIS IS A RATHER LARGE GATHERING.", "ГРУППА СКЕЛЕТОВ НАЗЫВАЕТСЯ КАТАКОМБОЙ. А ЭТО ДОВОЛЬНО БОЛЬШОЕ СОБРАНИЕ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catacomb", "Катакомбы", Language.Russian);
            RegisterCard("Catacomb", "Катакомбы");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Centurion", "Центурион", Language.Russian);
            RegisterCard("Centurion", "Центурион");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A heavily armoured warrior. Last of his century, leader to none.", "Воин в тяжёлых доспехах. Последний из своей центурии, ему больше некого вести.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compound Fracture", "Сложный перелом", Language.Russian);
            RegisterCard("Compound Fracture", "Сложный перелом");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CRUSHED BY THE ROOF OF HIS OWN HOUSE. LIVING ON AS A PILE OF GOO.", "ЕГО РАЗДАВИЛА КРЫША СОБСТВЕННОГО ДОМА. ТЕПЕРЬ ОН ЖИВЁТ В ВИДЕ ЛУЖИ СЛИЗИ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A SPIRIT THAT TAKES THE FORM OF AN EGG. ITS PRESENCE HARMS THOSE THAT GAZE UPON IT.", "ДУХ, ПРИНЯВШИЙ ФОРМУ ЯЙЦА. ЕГО ПРИСУТСТВИЕ ВРЕДИТ ТЕМ, КТО НА НЕГО СМОТРИТ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dalgyal", "Дальгьяль", Language.Russian);
            RegisterCard("Dalgyal", "Дальгьяль");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOREVER BOUND TOGETHER BY A TERRIBLE CURSE, THIS GROUP DANCES ONWARD INTO DOOM.", "НАВЕКИ СВЯЗАННАЯ УЖАСНЫМ ПРОКЛЯТИЕМ, ЭТА ГРУППА ТАНЦУЕТ НАВСТРЕЧУ ГИБЕЛИ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Danse Macabre", "Пляска смерти", Language.Russian);
            RegisterCard("Danse Macabre", "Пляска смерти");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deadeye", "Мёртвый глаз", Language.Russian);
            RegisterCard("Deadeye", "Мёртвый глаз");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOME SAY THIS EYE ONCE BELONGED TO AN ANCIENT GOD. IT GAZES UPON YOUR ARMY, PICKING ITS FAVORITE TO AID IT ON THE BATTLEFIELD.", "ГОВОРЯТ, ЭТОТ ГЛАЗ КОГДА-ТО ПРИНАДЛЕЖАЛ ДРЕВНЕМУ БОГУ. ОН СМОТРИТ НА ТВОЁ ВОЙСКО И ВЫБИРАЕТ ЛЮБИМЦА, ЧТОБЫ ПОМОЧЬ ЕМУ В БОЮ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOME SAY THIS HAND ONCE BELONGED TO AN ANCIENT GOD. ANYTHING IT TOUCHES ROTS. AS WITH ANYTHING THAT ENDS, IT IS ALSO A NEW BEGINNING.", "ГОВОРЯТ, ЭТА РУКА КОГДА-ТО ПРИНАДЛЕЖАЛА ДРЕВНЕМУ БОГУ. ВСЁ, ЧЕГО ОНА КАСАЕТСЯ, ГНИЁТ. КАК И ЛЮБОЙ КОНЕЦ, ЭТО ТАКЖЕ НОВОЕ НАЧАЛО.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Hand", "Мёртвая рука", Language.Russian);
            RegisterCard("Dead Hand", "Мёртвая рука");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A DOOMED FATE SHOULD DISCOURAGE ONE FROM GOING ON, AT LEAST THATS WHAT A STILL LIVING MAN WOULD TELL YOU.", "ОБРЕЧЁННОСТЬ ДОЛЖНА ОТБИТЬ ЖЕЛАНИЕ ИДТИ ДАЛЬШЕ. ПО КРАЙНЕЙ МЕРЕ, ТАК СКАЗАЛ БЫ ЕЩЁ ЖИВОЙ ЧЕЛОВЕК.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Man Walking", "Ходячий мертвец", Language.Russian);
            RegisterCard("Dead Man Walking", "Ходячий мертвец");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FAMED AMONG THE FOLLOWERS OF THE PHARAOH. THEY WERE BLESSED WITH ETERNAL LIFE LONG AGO.", "ПРОСЛАВЛЕНЫ СРЕДИ ПОСЛЕДОВАТЕЛЕЙ ФАРАОНА. ДАВНЫМ-ДАВНО ИХ БЛАГОСЛОВИЛИ ВЕЧНОЙ ЖИЗНЬЮ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pharaoh's Pets", "Клика фараона", Language.Russian);
            RegisterCard("Pharaoh's Pets", "Клика фараона");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FOR WHOM THE BELL TOLLS? FOR WHOM THE TAP DRIPS DRY AND THE BATHWATER RUNS COLD.", "ПО КОМ ЗВОНИТ КОЛОКОЛ? ПО ТОМ, ДЛЯ КОГО КРАН ИССЯКАЕТ, А ВОДА В ВАННЕ СТЫНЕТ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Knell", "Погребальный звон", Language.Russian);
            RegisterCard("Death Knell", "Погребальный звон");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime", "Колокольчик", Language.Russian);
            RegisterCard("Chime", "Колокольчик");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This lonesome doll was returned from seas of slate and silent shores... it stares lifelessly.", "Эта одинокая кукла вернулась из серых морей и с безмолвных берегов... Она смотрит безжизненным взглядом.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doll", "Кукла", Language.Russian);
            RegisterCard("Doll", "Кукла");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIDING IN A SUIT OF ARMOR, OR ICE, WHAT DOES IT MATTER. THIS SKELETON WON'T LAST FOREVER.", "ПРЯЧЕТСЯ В ДОСПЕХАХ ИЛИ ВО ЛЬДУ — КАКАЯ РАЗНИЦА? ЭТОТ СКЕЛЕТ НЕ ВЕЧЕН.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Draugr", "Драугр", Language.Russian);
            RegisterCard("Draugr", "Драугр");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A SAD SIGHT, NO ONE SHALL KNOW WHAT LIES AT THE BOTTOM OF THAT WELL.", "КАКОЕ ПЕЧАЛЬНОЕ ЗРЕЛИЩЕ. НИКТО НЕ УЗНАЕТ, ЧТО ЛЕЖИТ НА ДНЕ ЭТОГО КОЛОДЦА.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drowned Soul", "Утопленная душа", Language.Russian);
            RegisterCard("Drowned Soul", "Утопленная душа");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO ONE KNOWS WHAT EXACTLY THE DYBBUK IS, SOME SAY IT IS BETTER LEFT UNKNOWN.", "НИКТО НЕ ЗНАЕТ, ЧТО ТАКОЕ ДИББУК. НЕКОТОРЫЕ ГОВОРЯТ, ЧТО ЛУЧШЕ И НЕ ЗНАТЬ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dybbuk", "Диббук", Language.Russian);
            RegisterCard("Dybbuk", "Диббук");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ectoplasm", "Эктоплазма", Language.Russian);
            RegisterCard("Ectoplasm", "Эктоплазма");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE ESSENCE OF A SPIRIT, HIDDEN IN EVERY CORNER AND EVERY SHADOW. ONCE YOU SEE ONE, YOU WILL FIND THE REST SOON ENOUGH.", "СУЩНОСТЬ ДУХА, СКРЫТАЯ В КАЖДОМ УГЛУ И В КАЖДОЙ ТЕНИ. УВИДЕВ ОДНУ, ВСКОРЕ НАЙДЁШЬ И ОСТАЛЬНЫЕ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LIVING FAILURE, ITS KNOWLEDGE ONLY BROUGHT IT DEATH, OR AT LEAST AN APPROXIMATION OF IT.", "ЖИВОЙ ПРОВАЛ. ЗНАНИЯ ПРИНЕСЛИ ЕМУ ЛИШЬ СМЕРТЬ ИЛИ ХОТЯ БЫ НЕЧТО ПОХОЖЕЕ НА НЕЁ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneclaw", "Костяной коготь", Language.Russian);
            RegisterCard("Boneclaw", "Костяной коготь");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boneless", "Бескостный", Language.Russian);
            RegisterCard("Boneless", "Бескостный");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's Skeleton seems to have left this lifeless husk in order to achieve greater things.", "Похоже, скелет покинул эту безжизненную оболочку ради более великих свершений.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Mummy", "Малая мумия", Language.Russian);
            RegisterCard("Lesser Mummy", "Малая мумия");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal servant to the Pharao, buried with him to serve eternally in death.", "Верный слуга фараона, погребённый вместе с ним, чтобы вечно служить ему после смерти.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eidolon", "Эйдолон", Language.Russian);
            RegisterCard("Eidolon", "Эйдолон");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A GOLEM ENCHANTED LONG AGO, BOUND TO PROTECT THE AGE OF SUN.", "ГОЛЕМ, ЗАКОЛДОВАННЫЙ ДАВНЫМ-ДАВНО И ОБЯЗАННЫЙ ЗАЩИЩАТЬ ЭПОХУ СОЛНЦА.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "QUITE A MISCHIEVOUS SPIRIT, IT SPREADS ITS FLAMES TO CAUSE DISMAY.", "ВЕСЬМА ОЗОРНОЙ ДУХ. ОН РАЗНОСИТ ПЛАМЯ, ЧТОБЫ СЕЯТЬ СМЯТЕНИЕ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ember Spirit", "Дух углей", Language.Russian);
            RegisterCard("Ember Spirit", "Дух углей");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FAMILY WISHES TO REST IN PEACE, ONLY TO BE SUMMONED AGAIN AND AGAIN IN AN ETERNAL BATTLE.", "СЕМЬЯ ЖЕЛАЕТ ПОКОИТЬСЯ С МИРОМ, НО ЕЁ СНОВА И СНОВА ПРИЗЫВАЮТ В ВЕЧНУЮ БИТВУ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Walkers", "Ходячие подлецы", Language.Russian);
            RegisterCard("The Walkers", "Ходячие подлецы");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is said their odor is so strong and repugnant, even the undead can feel it!", "Говорят, их запах настолько силён и отвратителен, что его чувствует даже нежить!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Festering Wretch", "Гниющий страдалец", Language.Russian);
            RegisterCard("Festering Wretch", "Гниющий страдалец");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flames", "Пламя", Language.Russian);
            RegisterCard("Flames", "Пламя");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flameskull", "Пылающий череп", Language.Russian);
            RegisterCard("Flameskull", "Пылающий череп");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always flying, always angry, always annoying nearby allies in the process.", "Вечно летает, вечно злится и заодно вечно надоедает союзникам поблизости.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A waterlogged sailor who carries his tragic past beside him. I don't remember the details.", "Промокший моряк, который носит рядом с собой своё трагическое прошлое. Подробностей я не помню.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forgotten Man", "Забытый человек", Language.Russian);
            RegisterCard("Forgotten Man", "Забытый человек");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEST FRIENDS, BROTHERS, AND FIGHTERS.", "ЛУЧШИЕ ДРУЗЬЯ, БРАТЬЯ И БОЙЦЫ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frank & Stein", "Франк и Штейн", Language.Russian);
            RegisterCard("Frank & Stein", "Франк и Штейн");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FrankenStein", "Франкенштейн", Language.Russian);
            RegisterCard("FrankenStein", "Франкенштейн");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A ghastly guardian spirit. It's presence lingers behind as it sprints through the dark.", "Жуткий дух-хранитель. Он проносится сквозь тьму, но его присутствие ещё долго ощущается позади.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fylgja", "Фюльгья", Language.Russian);
            RegisterCard("Fylgja", "Фюльгья");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warding Presence", "Охранное присутствие", Language.Russian);
            RegisterCard("Warding Presence", "Охранное присутствие");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT CREATED THESE BONES, WAR, FAMINE OR ANOTHER TRAGEDY? It may be insignificant now, but I fear what it might become...", "ЧТО ПОРОДИЛО ЭТИ КОСТИ: ВОЙНА, ГОЛОД ИЛИ ДРУГАЯ ТРАГЕДИЯ? Сейчас это может казаться пустяком, но я боюсь того, во что они превратятся...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mass Grave", "Братская могила", Language.Russian);
            RegisterCard("Mass Grave", "Братская могила");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rising Hunger", "Обжорство", Language.Russian);
            RegisterCard("Rising Hunger", "Обжорство");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gashadokuro", "Гасядокуро", Language.Russian);
            RegisterCard("Gashadokuro", "Гасядокуро");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE PIRATES CALL THIS SHIP THEIR HOME, EVEN IN DEATH. A SLAIN GIANTS SKULL SERVES AS THEIR FIGUREHEAD.", "ПИРАТЫ ЗОВУТ ЭТОТ КОРАБЛЬ ДОМОМ ДАЖЕ ПОСЛЕ СМЕРТИ. ЧЕРЕП УБИТОГО ВЕЛИКАНА СЛУЖИТ НОСОВОЙ ФИГУРОЙ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Ship", "Корабль-призрак", Language.Russian);
            RegisterCard("Ghost Ship", "Корабль-призрак");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant", "Великан", Language.Russian);
            RegisterCard("Giant", "Великан");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FAMED RACE OF GIANTS IS SAID TO HAVE DIED OUT LONG AGO, THIS IS PROOF. TRULY A SIGHT TO BEHOLD.", "ГОВОРЯТ, ПРОСЛАВЛЕННЫЙ РОД ВЕЛИКАНОВ ДАВНО ВЫМЕР. ВОТ И ДОКАЗАТЕЛЬСТВО. ПОИСТИНЕ ВПЕЧАТЛЯЮЩЕЕ ЗРЕЛИЩЕ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOUND TO EARTH, THEY CLING ON SO THEY MAY ONE DAY GET PROPER BURIAL.", "ПРИВЯЗАННЫЕ К ЗЕМЛЕ, ОНИ ДЕРЖАТСЯ В НАДЕЖДЕ ОДНАЖДЫ ОБРЕСТИ ДОСТОЙНОЕ ПОГРЕБЕНИЕ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grateful Dead", "Благодарный мертвец", Language.Russian);
            RegisterCard("Grateful Dead", "Благодарный мертвец");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE LOWLY GRAVEBARD, MUSIC ALWAYS BROUGHT HIM COMFORT IN THE WORST OF TIMES. NOW, EVEN AT THE END OF THE WORLD HE SHARES HIS SONG.", "СКРОМНЫЙ МОГИЛЬНЫЙ БАРД. МУЗЫКА ВСЕГДА УТЕШАЛА ЕГО В ХУДШИЕ ВРЕМЕНА. ТЕПЕРЬ, ДАЖЕ НА КРАЮ СВЕТА, ОН ДЕЛИТСЯ СВОЕЙ ПЕСНЕЙ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravebard", "Могильный бард", Language.Russian);
            RegisterCard("Gravebard", "Могильный бард");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS SPENT HIS LIFE CARVING THESE CREATURES, THIS CARD CONTAINS A PART OF HIS SOUL.", "ОН ПОСВЯТИЛ ЖИЗНЬ ВЫРЕЗАНИЮ ЭТИХ СУЩЕСТВ. ЭТА КАРТА СОДЕРЖИТ ЧАСТЬ ЕГО ДУШИ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grave Carver", "Могильный резчик", Language.Russian);
            RegisterCard("Grave Carver", "Могильный резчик");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE SPENDS HIS TIME ALONE DIGGING FOR BONES IN HOPES OF FINDING A TREASURE. JUST LIKE HIS GRANDMA BEFORE HIM.", "ОН КОРОТАЕТ ВРЕМЯ В ОДИНОЧЕСТВЕ, ВЫКАПЫВАЯ КОСТИ В НАДЕЖДЕ НАЙТИ СОКРОВИЩЕ. СОВСЕМ КАК ЕГО БАБУШКА КОГДА-ТО.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravedigger", "Могильщик", Language.Russian);
            RegisterCard("Gravedigger", "Могильщик");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A POOR, BRUTALIZED SOUL. THEIR MYCELIA PROBES FAR INTO THE SOIL, GUIDING THEIR SPADE.", "БЕДНАЯ, ИЗУВЕЧЕННАЯ ДУША. ЕЁ ГРИБНИЦА ПРОНИКАЕТ ГЛУБОКО В ПОЧВУ, НАПРАВЛЯЯ ЛОПАТУ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sporedigger", "Копатель спор", Language.Russian);
            RegisterCard("Sporedigger", "Копатель спор");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A devoted guardian spirit. Even when dispelled, it grants a protective blessing.", "Преданный дух-хранитель. Даже рассеявшись, он дарует защитное благословение.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haltia", "Халтиа", Language.Russian);
            RegisterCard("Haltia", "Халтиа");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I advise against staring into it, you won't like what stares back.", "Советую туда не вглядываться. Тебе не понравится тот, кто посмотрит в ответ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunted Mirror", "Зеркало с привидением", Language.Russian);
            RegisterCard("Haunted Mirror", "Зеркало с привидением");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY CALL HER THE RIDER OF THE APOCALYPSE. HER FLAMING BLADE CUTS THROUGH THE LIVING AND DEAD ALIKE.", "ЕЁ НАЗЫВАЮТ ВСАДНИЦЕЙ АПОКАЛИПСИСА. ЕЁ ПЫЛАЮЩИЙ КЛИНОК РАССЕКАЕТ И ЖИВЫХ, И МЁРТВЫХ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Headless Horseman", "Всадник без головы", Language.Russian);
            RegisterCard("Headless Horseman", "Всадник без головы");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WOULDN'T GET TOO CLOSE DEAR. YOU CAN'T BREAK THE HOLD FROM THE DEEPEST PITS OF HELL, ONCE IT LATCHES ON.", "Я БЫ НЕ ПОДХОДИЛА ТАК БЛИЗКО, ДОРОГОЙ. ЕСЛИ ХВАТКА ИЗ САМОЙ ГЛУБИНЫ АДА СОМКНЁТСЯ, ВЫРВАТЬСЯ УЖЕ НЕ УДАСТСЯ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hellhand", "Адская рука", Language.Russian);
            RegisterCard("Hellhand", "Адская рука");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hell Hound", "Адская гончая", Language.Russian);
            RegisterCard("Hell Hound", "Адская гончая");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A RABID DOG. IT KILLED ONE OF MY GHOULS.", "БЕШЕНЫЙ ПЁС. ОН УБИЛ ОДНОГО ИЗ МОИХ УПЫРЕЙ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LEGENDS HAVE BEEN TOLD ABOUT THE LEGENDARY HYDRA, THE BEAST THAT SWALLOWS ALL AND THE BANE OF ALL THAT SAIL THE SEAS.", "О ЛЕГЕНДАРНОЙ ГИДРЕ СЛАГАЮТ ЛЕГЕНДЫ: ЭТО ВСЕПОЖИРАЮЩИЙ ЗВЕРЬ И ГРОЗА ВСЕХ, КТО ХОДИТ ПО МОРЯМ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hydra", "Гидра", Language.Russian);
            RegisterCard("Hydra", "Гидра");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overtaken by it's gluttony in life, doomed to it's gluttony in death. Oddly inspires a greed for bones.", "При жизни его погубило обжорство, а после смерти оно стало его проклятием. Странным образом пробуждает жажду костей.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jikininki", "Дзикининки", Language.Russian);
            RegisterCard("Jikininki", "Дзикининки");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avalanche", "Лавина", Language.Russian);
            RegisterCard("Avalanche", "Лавина");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glacier", "Ледник", Language.Russian);
            RegisterCard("Glacier", "Ледник");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I WONDER WHAT HAS BEEN FROZEN AWAY FOR SO LONG.", "ИНТЕРЕСНО, ЧТО ЖЕ ТАК ДОЛГО БЫЛО СКОВАНО ЛЬДОМ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Giant", "Ледяной великан", Language.Russian);
            RegisterCard("Frost Giant", "Ледяной великан");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Cube", "Кубик льда", Language.Russian);
            RegisterCard("Ice Cube", "Кубик льда");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A CORPSE WHO DIED WITH HIS HEAD IN A GLACIAL STREAM. AFTER HIS REANIMATION, HE COULDN'T BEAR TO PART WITH THE ICE THAT HAD FORMED.", "ТРУП ЧЕЛОВЕКА, УМЕРШЕГО ГОЛОВОЙ В ЛЕДЯНОМ РУЧЬЕ. ВОСКРЕСНУВ, ОН НЕ СМОГ РАССТАТЬСЯ С ОБРАЗОВАВШИМСЯ ЛЬДОМ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After drowning her children and then herself, she continues to drown others.", "Утопив своих детей, а затем и себя, она продолжает топить других.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "La Llorona", "Ла Йорона", Language.Russian);
            RegisterCard("La Llorona", "Ла Йорона");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Manananggal", "Мананангал", Language.Russian);
            RegisterCard("Manananggal", "Мананангал");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO BRUTALITY SATIATES THE MANANANGGAL. WHEN YOU SEE HER SEVER FROM HER TORSO, YOU TOO WILL BE A VICTIM OF THE HUNT.", "НИКАКАЯ ЖЕСТОКОСТЬ НЕ НАСЫТИТ МАНАНАНГАЛ. КОГДА УВИДИШЬ, КАК ОНА ОТДЕЛЯЕТСЯ ОТ СВОЕГО ТУЛОВИЩА, ТЫ ТОЖЕ СТАНЕШЬ ЖЕРТВОЙ ОХОТЫ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moroi, also known as the hairy ghost. It leeches the souls from those struck down near it.", "Морой, также известный как волосатый призрак. Высасывает души тех, кого убивают рядом с ним.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moroi", "Морой", Language.Russian);
            RegisterCard("Moroi", "Морой");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIS AGE OF GLORY IS LONG GONE, YET IT IS WHAT KEEPS HIM GOING.", "ВРЕМЕНА ЕГО СЛАВЫ ДАВНО МИНОВАЛИ, НО ИМЕННО ОНИ ЗАСТАВЛЯЮТ ЕГО ИДТИ ДАЛЬШЕ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mummy Lord", "Владыка мумий", Language.Russian);
            RegisterCard("Mummy Lord", "Владыка мумий");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL EFFORTS TO PRESERVE LIFE AFTER DEATH HAVE BEEN FUTILE, YET THE NECROMANCER GOES ON. HE HAS TO.", "ВСЕ ПОПЫТКИ СОХРАНИТЬ ЖИЗНЬ ПОСЛЕ СМЕРТИ ОКАЗАЛИСЬ ТЩЕТНЫ, НО НЕКРОМАНТ ПРОДОЛЖАЕТ. ОН ДОЛЖЕН.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Necromancer", "Некромант", Language.Russian);
            RegisterCard("Necromancer", "Некромант");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A troublesome lake spirit that enjoys dragging others down to a watery grave.", "Беспокойный озёрный дух, которому нравится утаскивать других в водную могилу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nixie", "Никса", Language.Russian);
            RegisterCard("Nixie", "Никса");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The shambling corpse of a pale, sickly noble. it spreads it's filth as it sheds it's flesh.", "Шатающийся труп бледного, болезненного дворянина. Он распространяет скверну, сбрасывая плоть.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nosferat", "Носферат", Language.Russian);
            RegisterCard("Nosferat", "Носферат");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ancient Obol", "Древний обол", Language.Russian);
            RegisterCard("Ancient Obol", "Древний обол");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT WILL ALL MAKE SENSE SOON. THE OBOL IS OLDER THAN TIME ITSELF, AND THUS IT WILL REVEAL ITSELF IN DUE TIME.", "СКОРО ВСЁ ОБРЕТЁТ СМЫСЛ. ОБОЛ СТАРШЕ САМОГО ВРЕМЕНИ, А ПОТОМУ ОТКРОЕТ СЕБЯ В СВОЙ ЧАС.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Armed Bandit", "Однорукий бандит", Language.Russian);
            RegisterCard("One Armed Bandit", "Однорукий бандит");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Took the ten paces, that ordeal cost him an arm, and his life.", "Он сделал десять шагов. Это испытание стоило ему руки и жизни.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT IS SAID ALL IS WELL THAT ENDS. IT IS SAID TIME IS LIKE AN OUROBOROS, IT DOES NOT END, IT ONLY REPEATS ITSELF.", "ГОВОРЯТ, ХОРОШО ВСЁ, ЧТО КОНЧАЕТСЯ. ГОВОРЯТ, ВРЕМЯ ПОДОБНО УРОБОРОСУ: ОНО НЕ ЗАКАНЧИВАЕТСЯ, А ЛИШЬ ПОВТОРЯЕТСЯ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ourobones", "Урокост", Language.Russian);
            RegisterCard("Ourobones", "Урокост");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plague Doctor", "Чумной доктор", Language.Russian);
            RegisterCard("Plague Doctor", "Чумной доктор");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS DETERMINED THE UNDEAD ARE SICK WITH A TERRIBLE ILLNESS. THE ONLY CURE IS DEATH.", "ОН УСТАНОВИЛ, ЧТО НЕЖИТЬ СТРАДАЕТ УЖАСНОЙ БОЛЕЗНЬЮ. ЕДИНСТВЕННОЕ ЛЕКАРСТВО — СМЕРТЬ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN EVIL TRICKSTER, THE POLTERGEIST HAS ENJOYED THEIR DEATH VERY MUCH.", "ЗЛОЙ ОЗОРНИК. ПОЛТЕРГЕЙСТ ВОВСЮ НАСЛАЖДАЕТСЯ СОБСТВЕННОЙ СМЕРТЬЮ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poltergeist", "Полтергейст", Language.Russian);
            RegisterCard("Poltergeist", "Полтергейст");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A suit of ancient armour in which an occult spirit has taken up residence. Her iron fist drags more creatures to the fight.", "Древние доспехи, в которых поселился таинственный дух. Её железный кулак втягивает в бой всё новых существ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessed Armour", "Одержимые доспехи", Language.Russian);
            RegisterCard("Possessed Armour", "Одержимые доспехи");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN EXPERIMENT GONE WRONG, IN A FUTILE ATTEMPT TO CREATE A DANSE MACCABRE. THEY DO NOT FUNCTION TOGETHER.", "НЕУДАЧНЫЙ ЭКСПЕРИМЕНТ В ТЩЕТНОЙ ПОПЫТКЕ СОЗДАТЬ ПЛЯСКУ СМЕРТИ. ОНИ НЕ МОГУТ ДЕЙСТВОВАТЬ ВМЕСТЕ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Project", "Подопытный", Language.Russian);
            RegisterCard("Project", "Подопытный");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shouldnt be seeing this right now", "Сейчас ты не должен этого видеть.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Cards", "Бесформенные существа", Language.Russian);
            RegisterCard("Random Cards", "Бесформенные существа");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRINGING THE SCYTHE OF DEATH, THE REVENANT SEEKS ONLY REVENGE.", "НЕСЯ КОСУ СМЕРТИ, ВОССТАВШИЙ ИЩЕТ ЛИШЬ МЕСТИ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant", "Восставший", Language.Russian);
            RegisterCard("Revenant", "Восставший");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ripper", "Потрошитель", Language.Russian);
            RegisterCard("Ripper", "Потрошитель");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE RIPPER SOLVES EVERYTHING THROUGH SHEER STRENGTH. IT WILL PUNCH ANY ISSUE STRAIGHT IN THE FACE AND SOLVE IT, TOO.", "ПОТРОШИТЕЛЬ ВСЁ РЕШАЕТ ГРУБОЙ СИЛОЙ. ОН БЬЁТ ЛЮБУЮ ПРОБЛЕМУ ПРЯМО В ЛИЦО — И ЭТО ТОЖЕ ПОМОГАЕТ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a wonder this one has stayed together! Though it may lose that arm if it tries to flee.", "Удивительно, что он ещё не развалился! Хотя, если попробует убежать, может лишиться руки.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rotten", "Гнилой мертвец", Language.Russian);
            RegisterCard("Rotten", "Гнилой мертвец");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Twitching Arm", "Дёргающаяся рука", Language.Russian);
            RegisterCard("Twitching Arm", "Дёргающаяся рука");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The elusive Locker.", "Неуловимый Шкафчик.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Davy Jones Locker", "Сундук Дейви Джонса", Language.Russian);
            RegisterCard("Davy Jones Locker", "Сундук Дейви Джонса");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yellowbeard", "Желтобородый", Language.Russian);
            RegisterCard("Yellowbeard", "Желтобородый");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bluebeard", "Синяя Борода", Language.Russian);
            RegisterCard("Bluebeard", "Синяя Борода");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His songs raise the morale of only Skeletons, as no one else seems to like it.", "Его песни поднимают дух лишь Скелетам: кажется, больше никому они не нравятся.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A DISTANT RELATIVE OF THE SCREAMING SKULL, HE IS NOW THE SYMBOL OF PIRACY ALL AROUND THE WORLD", "ДАЛЬНИЙ РОДСТВЕННИК КРИЧАЩЕГО ЧЕРЕПА. ТЕПЕРЬ ОН СИМВОЛ ПИРАТСТВА ВО ВСЁМ МИРЕ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crossbones", "Скрещённые кости", Language.Russian);
            RegisterCard("Crossbones", "Скрещённые кости");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Davy Jones", "Дейви Джонс", Language.Russian);
            RegisterCard("Davy Jones", "Дейви Джонс");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The true captain of the crew, respected by all yet still elusive. YELLOWBEARD ALWAYS GETS MORE BOOTY THAN HE DOES.", "Истинный капитан команды, всеми уважаемый, но по-прежнему неуловимый. ЖЕЛТОБОРОДЫЙ ВСЕГДА ДОБЫВАЕТ БОЛЬШЕ НАГРАБЛЕННОГО, ЧЕМ ОН.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MAYBE IT WASN'T THE BEST IDEA TO HOLD A BARREL FULL OF GUNPOWDER. I'M NOT SURE WETHER HE NOTICED.", "ВОЗМОЖНО, ДЕРЖАТЬ БОЧКУ, ПОЛНУЮ ПОРОХА, БЫЛО НЕ ЛУЧШЕЙ ИДЕЕЙ. НЕ УВЕРЕНА, ЧТО ОН ЭТО ЗАМЕТИЛ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exploding Pirate", "Взрывной пират", Language.Russian);
            RegisterCard("Exploding Pirate", "Взрывной пират");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He betrayed his captain for that large hook, now he is sure to make anyone a double-crosser!", "Он предал капитана ради этого огромного крюка. Теперь он наверняка любого сделает предателем!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Mate Snag", "Старший помощник Снэг", Language.Russian);
            RegisterCard("First Mate Snag", "Старший помощник Снэг");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parrots usually make great sea-side companions, this one just ate a poisoned cracker.", "Попугаи обычно становятся отличными спутниками у моря. Этот только что съел отравленный крекер.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Polly", "Полли", Language.Russian);
            RegisterCard("Polly", "Полли");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A keen eye socket allows him to attack anywhere, his musket helps too. marvelous indeed!", "Зоркая глазница позволяет ему атаковать куда угодно. Мушкет тоже помогает. Просто чудесно!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Privateer", "Капитан-капер", Language.Russian);
            RegisterCard("Privateer", "Капитан-капер");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swashbuckler", "Лихой фехтовальщик", Language.Russian);
            RegisterCard("Swashbuckler", "Лихой фехтовальщик");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EMERGING FROM AN OLD EGYPTIAN TOMB, MADE TO HOUSE THE LORDS OF OLD.", "ВОЗНИК ИЗ ДРЕВНЕЙ ЕГИПЕТСКОЙ ГРОБНИЦЫ, СОЗДАННЫЙ КАК ОБИТЕЛЬ ДЛЯ ВЛАДЫК БЫЛЫХ ВРЕМЁН.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sarcophagus", "Саркофаг", Language.Russian);
            RegisterCard("Sarcophagus", "Саркофаг");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Screaming Skull", "Кричащий череп", Language.Russian);
            RegisterCard("Screaming Skull", "Кричащий череп");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ONLY PAIN AND SUFFERING, NOTHING ELSE IS FELT BY THIS SKELETAL HEAD. WHAT A PITY.", "ЭТА КОСТЯНАЯ ГОЛОВА НЕ ЧУВСТВУЕТ НИЧЕГО, КРОМЕ БОЛИ И СТРАДАНИЙ. КАК ЖАЛЬ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A SKILLED HUNTER. DON'T TRUST YOUR EARS WHEN YOU HEAR ITS HAUNTING WHISTLE.", "ИСКУСНЫЙ ОХОТНИК. НЕ ВЕРЬ СВОИМ УШАМ, КОГДА УСЛЫШИШЬ ЕГО ЖУТКИЙ СВИСТ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Silbon", "Эль Сильбон", Language.Russian);
            RegisterCard("Silbon", "Эль Сильбон");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY HAVE LEARNED THE ANCIENT SPELL OF DEATH. YET IT IS TOO MUCH POWER TO BE WIELDED.", "ОНИ ПОЗНАЛИ ДРЕВНЕЕ ЗАКЛИНАНИЕ СМЕРТИ. НО ЭТУ СИЛУ НЕВОЗМОЖНО ОБУЗДАТЬ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemagus", "Скелемаг", Language.Russian);
            RegisterCard("Skelemagus", "Скелемаг");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]RISE MY ARMY, RIIIIIISE[c:]", "[c:bR]ВОССТАНЬ, МОЁ ВОЙСКО, ВОССТАААААНЬ![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleton Army", "Армия скелетов", Language.Russian);
            RegisterCard("Skeleton Army", "Армия скелетов");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of the faster draws in the west, but not fast enough.", "Один из самых быстрых стрелков на Западе. Но недостаточно быстрый.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slinger's Soul", "Душа стрелка", Language.Russian);
            RegisterCard("Slinger's Soul", "Душа стрелка");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY SHOW UP OUT OF NOWHERE AND RELOCATE PEOPLE AS THEY PLEASE.", "ОНИ ПОЯВЛЯЮТСЯ ИЗ НИОТКУДА И ПЕРЕМЕЩАЮТ ЛЮДЕЙ КУДА ПОЖЕЛАЮТ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sluagh", "Слуа", Language.Russian);
            RegisterCard("Sluagh", "Слуа");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trick or treat!", "Кошелёк или жизнь!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candy Bucket", "Ведро конфет", Language.Russian);
            RegisterCard("Candy Bucket", "Ведро конфет");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HAPPY HALLOWEEN!", "С ХЕЛЛОУИНОМ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candy Monster", "Конфетный монстр", Language.Russian);
            RegisterCard("Candy Monster", "Конфетный монстр");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spectrabbit", "Призракролик", Language.Russian);
            RegisterCard("Spectrabbit", "Призракролик");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SPECTRE EMITS A FLUTE LIKE CALL, AN OMEN OF BOTH DEATH AND DESCTRUCTION", "ПРИЗРАК ИЗДАЁТ ЗОВ, ПОХОЖИЙ НА ЗВУК ФЛЕЙТЫ, — ПРЕДЗНАМЕНОВАНИЕ СМЕРТИ И РАЗРУШЕНИЯ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spectre", "Призрак", Language.Russian);
            RegisterCard("Spectre", "Призрак");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEATH IS A CRUEL FATE. STARVATION AN EVEN CRUELER ONE. WHY DO YOU FIGHT, OH HUNGRY CHILD.", "СМЕРТЬ — ЖЕСТОКАЯ УЧАСТЬ. ГОЛОДНАЯ СМЕРТЬ ЕЩЁ ЖЕСТОЧЕ. ЗАЧЕМ ТЫ СРАЖАЕШЬСЯ, О ГОЛОДНОЕ ДИТЯ?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starved Man", "Умерший от голода", Language.Russian);
            RegisterCard("Starved Man", "Умерший от голода");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE HAS SPENT YEARS IN HIS STUDY, IN A TIRELESS ATTEMPT TO CHANGE HIS FATE. YET FATE IS A CRUEL MISTRESS.", "ОН ГОДАМИ СИДЕЛ В КАБИНЕТЕ, НЕУСТАННО ПЫТАЯСЬ ИЗМЕНИТЬ СУДЬБУ. НО СУДЬБА — ЖЕСТОКАЯ ГОСПОЖА.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "Призыватель", Language.Russian);
            RegisterCard("Summoner", "Призыватель");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tampered Coffin", "Осквернённый гроб", Language.Russian);
            RegisterCard("Tampered Coffin", "Осквернённый гроб");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Tree", "Мёртвое дерево", Language.Russian);
            RegisterCard("Dead Tree", "Мёртвое дерево");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its low cost is justified only by its low stats.", "Его низкую стоимость оправдывают лишь низкие характеристики.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disturbed Grave", "Потревоженная могила", Language.Russian);
            RegisterCard("Disturbed Grave", "Потревоженная могила");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LOWLY GRAVE. WHOEVER IS LAID TO REST HERE, I DO NOT KNOW.", "СКРОМНАЯ МОГИЛА. КТО ЗДЕСЬ ПОКОИТСЯ, МНЕ НЕВЕДОМО.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kennel", "Псарня", Language.Russian);
            RegisterCard("Kennel", "Псарня");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Obelisk", "Обелиск", Language.Russian);
            RegisterCard("Obelisk", "Обелиск");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shipwreck", "Обломки корабля", Language.Russian);
            RegisterCard("Shipwreck", "Обломки корабля");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flotsam", "Плавучие обломки", Language.Russian);
            RegisterCard("Flotsam", "Плавучие обломки");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Water Urn", "Урна воды", Language.Russian);
            RegisterCard("Water Urn", "Урна воды");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Voodoo Doll", "Кукла вуду", Language.Russian);
            RegisterCard("Voodoo Doll", "Кукла вуду");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOTHING... NOTHING AGAIN... NO TREASURE IS LEFT ANYMORE.", "НИЧЕГО... СНОВА НИЧЕГО... БОЛЬШЕ НЕ ОСТАЛОСЬ СОКРОВИЩ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tomb Robber", "Расхититель гробниц", Language.Russian);
            RegisterCard("Tomb Robber", "Расхититель гробниц");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ephialtes", "Эфиальт", Language.Russian);
            RegisterCard("Ephialtes", "Эфиальт");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Otis", "Отис", Language.Russian);
            RegisterCard("Otis", "Отис");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undertaker", "Гробовщик", Language.Russian);
            RegisterCard("Undertaker", "Гробовщик");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His service no longer needed, this lost soul buries without purpose..", "Его услуги больше не нужны. Эта заблудшая душа хоронит без всякой цели...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Walking Coffin", "Ходячий гроб", Language.Russian);
            RegisterCard("Walking Coffin", "Ходячий гроб");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Running Coffin", "Бегущий гроб", Language.Russian);
            RegisterCard("Running Coffin", "Бегущий гроб");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Placeholder", "Заглушка", Language.Russian);
            RegisterCard("Placeholder", "Заглушка");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE VAMPIRE IS A CREATURE OF LEGENDS. IN REALITY, LITTLE BLOOD TO DRINK AFTER EVERYONE HAS DIED.", "ВАМПИР — СУЩЕСТВО ИЗ ЛЕГЕНД. НА ДЕЛЕ ЖЕ, КОГДА ВСЕ УМЕРЛИ, ПИТЬ ПОЧТИ НЕЧЕГО.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vampire", "Граф-вампир", Language.Russian);
            RegisterCard("Vampire", "Граф-вампир");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vellum", "Пергамент", Language.Russian);
            RegisterCard("Vellum", "Пергамент");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TO NEVER BE SATISFIED, TO ALWAYS WANT MORE. THIS SPIRIT SHALL NEVER FIND ITS PEACE.", "НИКОГДА НЕ НАСЫЩАТЬСЯ, ВСЕГДА ЖЕЛАТЬ БОЛЬШЕГО. ЭТОТ ДУХ НИКОГДА НЕ ОБРЕТЁТ ПОКОЯ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengeful Spirit", "Мстительный дух", Language.Russian);
            RegisterCard("Vengeful Spirit", "Мстительный дух");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS GELID SPECTER ENVELOPS WOULD-BE ATTACKERS IN AN ICY MIST.", "ЭТОТ ЛЕДЯНОЙ ПРИЗРАК ОКУТЫВАЕТ ЛЕДЯНЫМ ТУМАНОМ ТЕХ, КТО ОСМЕЛИТСЯ НАПАСТЬ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warthr", "Ледяной призрак", Language.Russian);
            RegisterCard("Warthr", "Ледяной призрак");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Corrupted by the spirit of a rabid wolf. It's fury cannot be stopped.", "Развращён духом бешеного волка. Его ярость не остановить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wechuge", "Вечуге", Language.Russian);
            RegisterCard("Wechuge", "Вечуге");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hideous beings that will jump out to consume freshly killed corpses. They only spare the bones of the victim.", "Отвратительные существа, которые выскакивают, чтобы пожрать свежие трупы. От жертвы они оставляют лишь кости.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wight", "Умертвие", Language.Russian);
            RegisterCard("Wight", "Умертвие");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY WARM WITH THEIR BODIES OF LIGHT, DRAWING HOPELESS SOULS INTO THEIR BEACON, DISPELLING THEIR FRIGHT.", "ОНИ СОГРЕВАЮТ СВЕТЯЩИМИСЯ ТЕЛАМИ, ПРИВЛЕКАЯ ОТЧАЯВШИЕСЯ ДУШИ К СВОЕМУ МАЯКУ И РАССЕИВАЯ ИХ СТРАХ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will 'O' The Wisp", "Блуждающий огонёк", Language.Russian);
            RegisterCard("Will 'O' The Wisp", "Блуждающий огонёк");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A FALLEN GIANTS SPINE THAT IS TRYING TO FIND A NEW HOST. REGRETTABLY, MOST CREATURES ARE QUITE SMALL.", "ПОЗВОНОЧНИК ПАВШЕГО ВЕЛИКАНА ИЩЕТ НОВОГО НОСИТЕЛЯ. УВЫ, БОЛЬШИНСТВО СУЩЕСТВ СЛИШКОМ МАЛЫ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Writher", "Корчащийся", Language.Russian);
            RegisterCard("Writher", "Корчащийся");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spiny Vertebrae", "Шипастые позвонки", Language.Russian);
            RegisterCard("Spiny Vertebrae", "Шипастые позвонки");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE SIMPLEST OF UNDEAD, CHARACTERIZED BY ITS ROTTEN SMELL. IT ALWAYS TRAVELS WITH OTHERS, SEEKING PROTECTION AND GUIDANCE.", "ПРОСТЕЙШАЯ НЕЖИТЬ, ОТЛИЧАЮЩАЯСЯ ГНИЛОСТНЫМ ЗАПАХОМ. ВСЕГДА ПУТЕШЕСТВУЕТ С ДРУГИМИ, ИЩА ЗАЩИТЫ И НАСТАВЛЕНИЯ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Zombie", "Зомби", Language.Russian);
            RegisterCard("Zombie", "Зомби");

            // Achievement
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grimora Mod Achievements", "Достижения мода Гриморы", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Reminder", "Мрачное напоминание", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Kaycee and thaw at least 5 of your cards.", "Победите Кейси и разморозьте хотя бы 5 своих карт.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cowards End", "Конец труса", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Sawyers second phase without hurting the hellhound.", "Победите Сойера во второй фазе, не ранив Адскую гончую.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Season Of Storms", "Сезон бурь", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat Royal and have no cards walk the plank.", "Победите Ройала, не отправив ни одной карты за борт по доске.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Black Bird//", "Чёрная птица//", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Dark Slope. Defeat [redacted] without defeating [redacted].", "Тёмный склон. Победите [redacted], не побеждая [redacted].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonesaw", "Костяная пила", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "End a turn with at least 30 bones.", "Завершите ход, имея хотя бы 30 костей.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pile Of Skulls", "Груда черепов", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win with all challenges enabled and no antichallenges enabled.", "Победите, включив все испытания и не включив ни одного антииспытания.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance of Doom", "Танец гибели", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Witness the end of everything.", "Станьте свидетелем конца всего.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Spirits Way", "Путь духов", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reach 6 Souls by turn 3.", "Накопите 6 душ не позднее хода 3.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wail Of The Damned", "Вопль проклятых", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the dead hand item when your deck is empty.", "Используйте предмет «Мёртвая рука», когда колода пуста.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something Ends...", "Что-то кончается...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Something Begins. Get an ourobones to deal 6 damage.", "...Что-то начинается. Пусть Урокост нанесёт 6 урона.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cull the weak", "Отсев слабых", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifice an Obol with 5 sigils to the Bonelord.", "Принесите Повелителю костей в жертву Обол с 5 символами.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gateway to Dis", "Врата Дита", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win while Hell mode is active.", "Победите с включённым режимом ада.", Language.Russian);

            // Consumable
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Horn", "Костяной рог", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Horn, drains all of your current Soul but you gain a bone for each soul consumed.", "Костяной рог расходует все ваши текущие души, но за каждую потраченную душу вы получаете кость.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gives you a bone for each of your Souls, which are spent in the process, an unfortunate, but worthwhile sacrifice.", "Даёт по кости за каждую вашу душу, расходуя их все. Печальная, но оправданная жертва.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Hand", "Мёртвая рука", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Dead Hand, draws you a new Hand of cards at the cost of your old one.", "Мёртвая рука даёт вам новую руку карт взамен прежней.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The severed hand of a forgotten god, left to take on a life of its own. You know what this does.", "Отрубленная рука забытого бога, обретшая собственную жизнь. Ты знаешь, что она делает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Embalming Fluid", "Бальзамирующая жидкость", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Embalming Fluid, pour it over a card and it will gain one health and attack.", "Полейте карту Бальзамирующей жидкостью: она получит по единице здоровья и атаки.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prepare to put a member of your army to rest, increasing its stamina and vigor as you do so!", "Приготовьтесь упокоить бойца своего войска, заодно повысив его выносливость и силу!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravecarvers Chisel", "Резец могильного резчика", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravecarvers chisel, select any card that has died previously to add to your hand.", "Резец могильного резчика позволяет выбрать любую ранее погибшую карту и добавить её в руку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tool left behind by a mysterious creator, did he carve the gravebards statue too?", "Инструмент, оставленный таинственным творцом. Не он ли вырезал и статую Могильного барда?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Urn", "Урна душ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Soul Urn, spend all of your Soul and gain maximum Soul capacity for each Soul consumed.", "Урна душ расходует все ваши души и увеличивает максимальный запас душ за каждую потраченную.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Takes all of your Soul but increases your maximum by the amount taken, a certain acquaintance of mine would call this a return on investment.", "Забирает все ваши души, но на столько же увеличивает их максимальный запас. Один мой знакомый назвал бы это доходом от вложений.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mallet", "Киянка", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Mallet, Whack a Card, it will become brittle and loose 1 Hp.", "Киянка ударяет карту, давая ей «Немощь» и отнимая 1 здоровье.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'd think this is comical, but it is quite cruel. Injures a card and leaves it frail.", "Это кажется забавным, но на деле весьма жестоко. Калечит карту и делает её немощной.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quill", "Перо", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My very own Quill, this lets you copy any card on the field to put in your hand.", "Моё собственное Перо позволяет скопировать любую карту на поле и поместить копию в руку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My very own tool, i will lend it to you for now. Youve seen this in action, havent you?", "Мой собственный инструмент. Пока что я одолжу его тебе. Ты ведь уже видел его в деле?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ship Bottle", "Бутылка с кораблём", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Ship in a Bottle, fills the entire board with a scurvy Skeleton Crew.", "Корабль в бутылке заполняет всю доску командой цинготных Скелетов.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fills the entire board with skeletons! Like a real Pirate, Royal would be proud.", "Заполняет всю доску Скелетами! Как у настоящего пирата. Ройал бы гордился.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Salty Daryl", "Солёный Дэрил", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Browntooth Barrie", "Барри Грязнозуб", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonnie Splinter", "Бонни Сплинтер", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Freebooter Bethel", "Флибустьер Бетел", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crazy Oakes Hayward", "Безумный Оукс Хейуорд", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ashton Swabby", "Матрос Эштон", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plankton Braxton", "Планктон Бракстон", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeller-eye Colby", "Желтоглазый Колби", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fishwife Nate", "Рыботорговец Нейт", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Four-finger Fred", "Четырёхпалый Фред", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dawg Julie", "Джули-Псина", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wicked Jones", "Хитрый Джонс", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crabby Steele", "Стил Крабья Морда", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank", "Расколотая кабанья копилка", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones up to three times.", "Расколотая кабанья копилка даёт 2 дополнительные кости, до трёх раз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A relic from an age forsaken, this will grant you some extra bones in a pinch", "Реликвия забытой эпохи, которая даст несколько лишних костей в трудную минуту.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank2", "Расколотая кабанья копилка2", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones, two more times.", "Расколотая кабанья копилка даёт 2 дополнительные кости, ещё два раза.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slivered Hoggy Bank3", "Расколотая кабанья копилка3", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Slivered Hoggy bank, gain 2 extra bones, one more time.", "Расколотая кабанья копилка даёт 2 дополнительные кости, ещё один раз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trowel", "Мастерок", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Trowel, dig up a random terrain and gain a few Bones.", "Мастерок выкапывает случайную карту местности и даёт несколько костей.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This used to belong to a gravedigger. Digs for treasure, or Terrain. And get some Bones too for your efforts.", "Когда-то принадлежал могильщику. Выкапывает сокровища или местность. А за труды вы получите ещё и немного костей.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bonelords Femur", "Бедренная кость Повелителя костей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lords Femur, a mystery even to me.", "Бедренная кость Повелителя костей — загадка даже для меня.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have dug too far, i have let myself be used as a tool for too long. Just like i will lend you this tool, i am truly in power.", "Ты копнул слишком глубоко. Я слишком долго позволял использовать себя как инструмент. Как и теперь, одалживая тебе этот инструмент, именно я обладаю настоящей властью.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant Bottle", "Бутылка с Восставшим", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Heap Bottle", "Бутылка с Грудой костей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Revenant is created in your hand. [define:arackulele.inscryption.grimoramod_Revenant]", "У вас в руке создаётся Восставший. [define:arackulele.inscryption.grimoramod_Revenant]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Bone Heap is created in your hand. [define:arackulele.inscryption.grimoramod_Bonepile]", "У вас в руке создаётся Груда костей. [define:arackulele.inscryption.grimoramod_Bonepile]", Language.Russian);

            // ShowUntilInput
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:G]SANDSTORM[c:] IS BREWING!", "НАДВИГАЕТСЯ [c:G]ПЕСЧАНАЯ БУРЯ[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]At the end of a turn, the rightmost Card will take 1 Damage![c:]", " [c:G]В конце хода крайняя правая карта получает 1 урон![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS GETTING HOTTER!A [c:G]HEATWAVE[c:] IS STARTING!", "СТАНОВИТСЯ ЖАРЧЕ! НАЧИНАЕТСЯ [c:G]ВОЛНА ЗНОЯ[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]All cards on the board will burn![c:]", " [c:G]Все карты на доске загорятся![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TREES START SPROUTING AROUND YOU.AN [c:G]OVERGROWTH[c:] IS INBOUND!", "ВОКРУГ ТЕБЯ ПРОРАСТАЮТ ДЕРЕВЬЯ. НАДВИГАЕТСЯ [c:G]БУЙНЫЙ РОСТ[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Trees will sprout every turn![c:]", " [c:G]Деревья будут прорастать каждый ход![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HEAR WITCHES CHANTING.THE CLOCK STRIKES THE [c:G]WITCHING HOUR[c:]!", "ТЫ СЛЫШИШЬ ПЕНИЕ ВЕДЬМ. ЧАСЫ БЬЮТ [c:G]ВЕДЬМИН ЧАС[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Cards on enchanted slots will gain more attack and health![c:]", " [c:G]Карты в зачарованных ячейках получат больше атаки и здоровья![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A CAULDRON IS BUBBLING IN THE DISTANCE.YOUR CARDS ARE PUT IN THE [c:G]WITCHES CAULDRON[c:]!", "ВДАЛИ БУРЛИТ КОТЁЛ. ТВОИ КАРТЫ ПОПАДАЮТ В [c:G]ВЕДЬМИН КОТЁЛ[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]2 Cards will swap after the end of the turn![c:]", " [c:G]После окончания хода 2 карты поменяются местами![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SKELETONS START DANCING IN THE DISTANCE, YOU CAN SEE GHOSTS MOVE AROUND.ITS THE [c:G]NIGHT OF THE LIVING DEAD[c:]!", "ВДАЛИ ТАНЦУЮТ СКЕЛЕТЫ, ПОВСЮДУ БРОДЯТ ПРИЗРАКИ. НАСТУПИЛА [c:G]НОЧЬ ЖИВЫХ МЕРТВЕЦОВ[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Bone and soul cost of all cards are swapped![c:]", " [c:G]Стоимость всех карт в костях и душах меняется местами![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ZOMBIES ARE APPROACHING FROM ALL SIDES.A [c:G]ZOMBIE INVASION[c:] WILL APPROACH!", "ЗОМБИ НАСТУПАЮТ СО ВСЕХ СТОРОН. ПРИБЛИЖАЕТСЯ [c:G]НАШЕСТВИЕ ЗОМБИ[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Every card is now a Zombie![c:]", " [c:G]Теперь каждая карта — Зомби![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE DIRT IS PLAGUED WITH SPIRITS FROM CENTURIES PAST.YOU'VE APPROACHED THE [c:G]HAUNTED GROUNDS[c:]!", "ЗЕМЛЯ КИШИТ ДУХАМИ МИНУВШИХ ВЕКОВ. ТЫ ПРИБЛИЗИЛСЯ К [c:G]ПРИЗРАЧНЫМ ЗЕМЛЯМ[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]Every non Skeletal Card will gain Haunter![c:]", " [c:G]Каждая нескелетная карта получит символ «Скиталец»![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE MOON RISES, GLOWING RED.A [c:G]BLOODMOON[c:] IS STARTING!", "ВОСХОДИТ ЛУНА, СВЕТЯСЬ КРАСНЫМ. НАЧИНАЕТСЯ [c:G]КРОВАВАЯ ЛУНА[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, " [c:G]All cards loose a random sigil after being played![c:]", " [c:G]Каждая карта после розыгрыша теряет случайный символ![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An ancient Guard stands in front of you, noticing you are trying to sneak past.", "Древний страж стоит перед тобой и замечает твою попытку прокрасться мимо.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You dare enter my [c:R]TOMB[c:]!Prepare for death.", "Ты осмелился войти в мою [c:R]ГРОБНИЦУ[c:]! Готовься к смерти.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An imposing Man holding a sculpture of an Ankh blocks the way.", "Путь преграждает внушительный мужчина, держащий изваяние анха.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My Ankh gives me life, you shall not rob my [c:R]TOMB[c:].", "Мой анх дарует мне жизнь. Тебе не разграбить мою [c:R]ГРОБНИЦУ[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An old Pharaoh climbs out of his Sarcophagus.", "Старый фараон выбирается из саркофага.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have been called to protect my [c:R]TOMB[c:].", "Меня призвали защищать мою [c:R]ГРОБНИЦУ[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A holy figure looms over you.", "Над тобой возвышается священная фигура.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your Fate is sealed, my [c:R]TOMB[c:] shall not be disturbed.", "Твоя судьба предрешена. Мою [c:R]ГРОБНИЦУ[c:] не потревожить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A LONE GRAVE SITS SOLEMNLY IN FRONT OF YOU.", "ПЕРЕД ТОБОЙ ТОРЖЕСТВЕННО ВЫСИТСЯ ОДИНОКАЯ МОГИЛА.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IN FRONT OF IT IS A MOUND OF EARTH, LEFT BY SOMEONE WHO'S ALREADY PASSED ON.", "ПЕРЕД НЕЙ — ХОЛМИК ЗЕМЛИ, ОСТАВЛЕННЫЙ ТЕМ, КТО УЖЕ УШЁЛ ИЗ ЖИЗНИ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS A MEMBER OF YOUR UNDEAD HORDE COULD [c:bR]DIG THEM UP?[c:]", "ВОЗМОЖНО, КТО-ТО ИЗ ТВОЕЙ ОРДЫ НЕЖИТИ СМОЖЕТ [c:bR]ВЫКОПАТЬ ПОКОЙНИКА?[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS WOULDN'T BE WITHOUT REPERCUSSIONS OF COURSE, AS DEATH IS NEVER PERMANENT.", "РАЗУМЕЕТСЯ, ЭТО НЕ ОБОЙДЁТСЯ БЕЗ ПОСЛЕДСТВИЙ: СМЕРТЬ НИКОГДА НЕ БЫВАЕТ ОКОНЧАТЕЛЬНОЙ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF ROTTING FLESH, YOUR CARD WILL BECOME [c:bR]BRITTLE[c:], BUT [c:bR]ITS BONE COST WILL BE HALVED[c:].", "ПЛОТЬ ТРУПА, ПОХОЖЕ, СГНИЛА. ТВОЯ КАРТА ПОЛУЧИТ [c:bR]«НЕМОЩЬ»[c:], НО [c:bR]ЕЁ СТОИМОСТЬ В КОСТЯХ УМЕНЬШИТСЯ ВДВОЕ[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A STARVED MAN, YOUR CARD WILL [c:bR]STARVE FOREVER[c:], BUT [c:bR]ITS BONE COST WILL BE REDUCED BY 2[c:].", "ПОХОЖЕ, ЭТО ТРУП УМЕРШЕГО ОТ ГОЛОДА. ТВОЯ КАРТА БУДЕТ [c:bR]ВЕЧНО ГОЛОДАТЬ[c:], НО [c:bR]ЕЁ СТОИМОСТЬ В КОСТЯХ УМЕНЬШИТСЯ НА 2[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF AN INCORPOREAL GHOST, YOUR CARD WILL [c:bR]COST 2 SOULS[c:] , BUT [c:bR]ITS BONE COST WILL BE REDUCED BY 1[c:].", "ПОХОЖЕ, ЭТО ТЕЛО БЕСПЛОТНОГО ПРИЗРАКА. ТВОЯ КАРТА БУДЕТ [c:bR]СТОИТЬ 2 ДУШИ[c:], НО [c:bR]ЕЁ СТОИМОСТЬ В КОСТЯХ УМЕНЬШИТСЯ НА 1[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A CHAINED PRISONER, YOUR CARD WILL [c:bR]DEAL 1 MORE DAMAGE[c:] , BUT [c:bR]IT WILL BECOME VERY FRAIL[c:].", "ПОХОЖЕ, ЭТО ТРУП ЗАКОВАННОГО УЗНИКА. ТВОЯ КАРТА БУДЕТ [c:bR]НАНОСИТЬ НА 1 УРОНА БОЛЬШЕ[c:], НО [c:bR]СТАНЕТ ОЧЕНЬ ХРУПКОЙ[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE CORPSE SEEMS TO BE OF A MISCHIEVIOUS SPIRIT, YOUR CARD WILL [c:bR]HAUNT OTHERS[c:] , BUT [c:bR]WILL COST 3 SOULS[c:].", "ПОХОЖЕ, ЭТО ТЕЛО ОЗОРНОГО ДУХА. ТВОЯ КАРТА БУДЕТ [c:bR]ПРЕСЛЕДОВАТЬ ДРУГИХ[c:], НО [c:bR]СТАНЕТ СТОИТЬ 3 ДУШИ[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MARVELOUS! THEY CAME CRAWLING BACK AFTER DIGGING UP THE CORPSE.", "ПРЕВОСХОДНО! ВЫКОПАВ ТРУП, ОНО ПРИПОЛЗЛО ОБРАТНО.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY STILL CARE ABOUT YOU IT SEEMS!", "ПОХОЖЕ, ТЫ ЕМУ ВСЁ ЕЩЁ НЕБЕЗРАЗЛИЧЕН!", Language.Russian);
            foreach (var value in Cards.Values)
            {
                string name = "[c:R]" + value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TORN FROM ITS ETERNAL RESPITE WITH A RELUCTANT GROAN, THE " + name + " SHAMBLES BACK TO ITS RIGHTFUL PLACE AMONG YOUR HORDE.", "С НЕОХОТНЫМ СТОНОМ ВЫРВАННЫЙ ИЗ ВЕЧНОГО ПОКОЯ, " + name + " КОВЫЛЯЕТ ОБРАТНО НА СВОЁ МЕСТО В ТВОЕЙ ОРДЕ НЕЖИТИ.", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS BONES HOLLOWED THROUGH BY THE CREATURES OF THE SOIL, LEAVING IT FEELING UNNATURAL AND UNFAMILIAR.", "ПОЧВЕННЫЕ ТВАРИ ВЫЕЛИ ЕГО КОСТИ ИЗНУТРИ, ОТЧЕГО ОНО КАЖЕТСЯ ЧУЖДЫМ И ПРОТИВОЕСТЕСТВЕННЫМ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOUGH THE WEIGHT OF CONSEQUENCE ALSO SEEMS LIFTED...", "ХОТЯ ТЯЖЕСТЬ ПОСЛЕДСТВИЙ, КАЖЕТСЯ, ТОЖЕ ИСЧЕЗЛА...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems i have finally been given my turn!", "Кажется, наконец-то настал мой черёд!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After this i will finally be at peace.", "После этого я наконец обрету покой.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, it seems we will start in this frigid valley.", "Что ж, похоже, мы начнём в этой ледяной долине.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It must be where Kaycees resides.", "Должно быть, здесь живёт Кейси.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I didn't expect to meet you here again!", "Не ожидала снова встретить тебя здесь!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems the deletion process has stalled!", "Похоже, процесс удаления застопорился!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You again?", "Опять ты?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, i suppose we can go another time.", "Что ж, думаю, можно сыграть ещё раз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still not deleted?", "Всё ещё не удалено?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Much seems to be contained on this disk.", "На этом диске, похоже, немало всего.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps the last run wasn't long enough.", "Возможно, прошлый забег был недостаточно долгим.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, im sure Kaycee has the energy for more battles.", "Что ж, уверена, у Кейси ещё хватит сил на новые битвы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frigid valley, again.", "Снова ледяная долина.", Language.Russian);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BITTER CHILL MIGHT HURT, BUT IT WON'T SLOW DOWN " + value + "!", "ЛЮТЫЙ ХОЛОД МОЖЕТ РАНИТЬ, НО НЕ ЗАМЕДЛИТ " + value + "!", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BLOCKED IN ALL SLOTS. NO ARMY THIS TIME.", "ВСЕ ЯЧЕЙКИ ЗАНЯТЫ. НА ЭТОТ РАЗ БЕЗ ВОЙСКА.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blocked on both sides. No Shipwrecks for the Forgotten Man.", "Обе стороны заняты. Забытому человеку некуда положить Обломки корабля.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, I love this one!", "О, это я обожаю!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Electric Chair, it allows you to harness the power of lightning itself, letting you [c:B]empower[c:] your cards with mutating abilties!", "Электрический стул позволяет обуздать силу самой молнии и [c:B]усилить[c:] карты, изменяя их способности!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "However, I must warn you, it is no ordinary chair. With the ability to adjust the voltage, a higher level of course increases the unpredictability of the mutation.", "Но предупреждаю: это не обычный стул. Напряжение можно менять, и чем оно выше, тем непредсказуемее мутация.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The brave will master the current, the cowardly will blindly follow it.", "Храбрые укротят ток, а трусы слепо последуют за течением.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you bold enough to tinker with its lever on the left, letting the voltage corrupt the selection of the sigils?", "Хватит ли тебе смелости тронуть рычаг слева и позволить напряжению исказить выбор символов?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SURELY YOUR CREATURE COULD BECOME MORE POWERFUL...", "ТВОЁ СУЩЕСТВО НАВЕРНЯКА МОЖЕТ СТАТЬ СИЛЬНЕЕ...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUT YOU WOULD NEED TO RISK ANOTHER MOMENT UNDER THE SHOCK.", "НО РАДИ ЭТОГО ПРИДЁТСЯ РИСКНУТЬ И ВЫДЕРЖАТЬ ЕЩЁ ОДИН РАЗРЯД.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BONES FLEW LEFT AND RIGHT AS YOU RETREATED FROM THE SCENE.", "КОСТИ ЛЕТЕЛИ ВО ВСЕ СТОРОНЫ, ПОКА ТЫ ПОКИДАЛ ЭТО МЕСТО.", Language.Russian);
            foreach (var value in Cards.Values)
            {
                string name = "[c:bR]" + value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU EVER SO CAREFULLY PULL THE " + name + " AWAY FROM THE ELECTRICITY AND LEAVE.", "ТЫ ОЧЕНЬ ОСТОРОЖНО ВЫВОДИШЬ " + name + " ИЗ-ПОД ТОКА И УХОДИШЬ.", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello, dear challenger, we meet again!", "Здравствуй, дорогой претендент, снова встретились!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you ready for a good ol' fashioned [c:R]DUEL[c:]?", "Готов к доброму старому [c:R]ДУЭЛЬНОМУ ПОЕДИНКУ[c:]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see, theres a third candle at play this time...", "Понятно, на этот раз в игре третья свеча...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel you have [c:bG]bested[c:] me this time...", "Кажется, на этот раз ты меня [c:bG]переиграл[c:]...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was an honour, either way!", "В любом случае, для меня это честь!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONGRATULATIONS, YOU DID WELL.", "ПОЗДРАВЛЯЮ, ТЫ ХОРОШО СПРАВИЛСЯ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S SEE, THE NEXT AREA IS MY VERY OWN CRYPT.", "ТАК, СЛЕДУЮЩАЯ ОБЛАСТЬ — МОЙ СОБСТВЕННЫЙ СКЛЕП.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS YOU CAN BEAT ALL ODDS AND TRIUMPH!", "ВОЗМОЖНО, ТЫ ПРЕОДОЛЕЕШЬ ВСЕ ПРЕГРАДЫ И ПОБЕДИШЬ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T'was well thought, i believe.", "По-моему, хорошо задумано.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS GET RID OF THE OL' SLOTS FOR NOW!", "ДАВАЙ ПОКА ИЗБАВИМСЯ ОТ СТАРЫХ ЯЧЕЕК!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its time for a different sort of game.", "Пора сыграть в другую игру.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont let the costs of the cards on your side of the board get above [c:R]10[c:]!", "Не позволяй суммарной стоимости карт на твоей стороне доски превысить [c:R]10[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you bust, you get punished, hit the perfect [c:R]10[c:] and you shall get a reward...", "Переберёшь — будешь наказан. Наберёшь ровно [c:R]10[c:] — получишь награду...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Was the ol' slot machine not enough for you?", "Старого игрового автомата тебе было мало?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess we shall bring in some more heavy hitters so to say...", "Думаю, придётся выпустить, так сказать, тяжёлую артиллерию...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lets get those powerhouses out of the way first!", "Давай сначала уберём с дороги этих силачей!", Language.Russian);
            foreach (var kvp in Cards)
            {
                string key = "[c:R]" + kvp.Key + "[c:]";
                string value = "[c:R]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, you've made " + key + " quite angry.", "Ох, ты сильно разозлил персонажа " + value + ".", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NO? A TERRIBLE FATE WILL AWAIT YOU", "НЕТ? ТЕБЯ ЖДЁТ УЖАСНАЯ УЧАСТЬ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I FEEL WATCHED SOMEHOW", "ПОЧЕМУ-ТО Я ЧУВСТВУЮ НА СЕБЕ ЧЕЙ-ТО ВЗГЛЯД.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AN ANCIENT ENERGY DEMANDS YOUR SACRIFICE", "ДРЕВНЯЯ ЭНЕРГИЯ ТРЕБУЕТ ТВОЕЙ ЖЕРТВЫ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU WILLING TO SACRIFICE ONE OF YOUR STARTING-", "ГОТОВ ЛИ ТЫ ПОЖЕРТВОВАТЬ ОДНОЙ ИЗ СВОИХ НАЧАЛЬНЫХ...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WAIT", "ПОГОДИ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS YOU BEAR A TERRIBLE CURSE", "ПОХОЖЕ, НА ТЕБЕ УЖАСНОЕ ПРОКЛЯТИЕ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU SHALL KEEP THE BOON, BUT FOR A FAR GREATER SACRIFICE", "ТЫ СОХРАНИШЬ ДАР, НО ЦЕНОЙ ГОРАЗДО БОЛЬШЕЙ ЖЕРТВЫ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CAN YOU GIVE UP YOUR ETERNAL ASHES?", "МОЖЕШЬ ЛИ ТЫ ОТРЕЧЬСЯ ОТ СВОЕГО ВЕЧНОГО ПЕПЛА?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU WILLING TO SACRIFICE ONE OF YOUR STARTING BONES", "ГОТОВ ЛИ ТЫ ПОЖЕРТВОВАТЬ ОДНОЙ ИЗ СВОИХ НАЧАЛЬНЫХ КОСТЕЙ?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A BRAVE SOUL", "ХРАБРАЯ ДУША.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE GODS ANSWER YOUR PRAYERS, NOW CHOOSE", "БОГИ ОТВЕЧАЮТ НА ТВОИ МОЛИТВЫ. ТЕПЕРЬ ВЫБИРАЙ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE INANIMATE", "ДАР НЕЖИВОГО", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AT THE START OF A BATTLE, A DEAD TREE WILL SPAWN IN ON A RANDOM SPACE ON THE BOARD", "В НАЧАЛЕ БИТВЫ В СЛУЧАЙНОЙ ЯЧЕЙКЕ ДОСКИ ПОЯВЛЯЕТСЯ МЁРТВОЕ ДЕРЕВО.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE SUN KINGDOM", "ДАР СОЛНЕЧНОГО ЦАРСТВА", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ON THE 4TH TURN OF A BATTLE, DRAW 2 RANDOM EGYPT CARDS", "НА 4-М ХОДУ БИТВЫ ВОЗЬМИТЕ 2 СЛУЧАЙНЫЕ ЕГИПЕТСКИЕ КАРТЫ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF REPENTANCE", "ДАР ПОКАЯНИЯ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GAIN AN ADDITIONAL SOUL AT THE START OF A BATTLE", "ПОЛУЧИТЕ ДОПОЛНИТЕЛЬНУЮ ДУШУ В НАЧАЛЕ БИТВЫ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF EBONY EYES", "ДАР ЭБЕНОВЫХ ГЛАЗ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TERRAIN CARDS WILL PROVIDE 2 BONES ON DEATH", "КАРТЫ МЕСТНОСТИ ДАЮТ 2 КОСТИ ПРИ ГИБЕЛИ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE ADVERSARY", "ДАР ПРОТИВНИКА", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AT THE START OF A BOSS BATTLE, GAIN 3 EXTRA BONES", "В НАЧАЛЕ БИТВЫ С БОССОМ ПОЛУЧИТЕ 3 ДОПОЛНИТЕЛЬНЫЕ КОСТИ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOON OF THE SEASICK", "ДАР МОРСКОЙ БОЛЕЗНИ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AFTER PLACING 3 CARDS, A PIRATE SKELETON WILL BE PLAYED ON A RANDOM SPACE ON THE BOARD", "ПОСЛЕ РАЗМЕЩЕНИЯ 3 КАРТ В СЛУЧАЙНОЙ ЯЧЕЙКЕ ДОСКИ РАЗЫГРЫВАЕТСЯ СКЕЛЕТ-ПИРАТ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BOON OF THE CUT FINGER", "ДАР ОТРЕЗАННОГО ПАЛЬЦА", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DRAW AN ADDITIONAL CARD AT THE START OF A BATTLE", "ВОЗЬМИТЕ ДОПОЛНИТЕЛЬНУЮ КАРТУ В НАЧАЛЕ БИТВЫ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A WISE CHOICE, NOW LEAVE BEFORE THE GODS GET TOO HUNGRY", "МУДРЫЙ ВЫБОР. А ТЕПЕРЬ УХОДИ, ПОКА БОГИ НЕ ПРОГОЛОДАЛИСЬ СЛИШКОМ СИЛЬНО.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We spent a lot of time here, I'm sure you are eager to get going again!", "Мы провели здесь немало времени. Уверена, тебе не терпится снова отправиться в путь!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard bids us farewell", "Могильный бард прощается с нами.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I see you would rather hold on to the ash that you have collected.", "Вижу, ты предпочитаешь сохранить собранный пепел.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It still may be of use later...", "Он ещё может пригодиться позже...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And don't feel bad, the Gravebard still enjoyed your company while it lasted!", "И не расстраивайся: Могильному барду всё равно было приятно провести с тобой время!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if you wanted anything else, you are no longer able to afford it...", "Даже если бы тебе захотелось чего-то ещё, тебе уже не хватит средств...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling sorry for you, the Gravebard offers to come with you.", "Сжалившись над тобой, Могильный бард предлагает пойти с тобой.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard never runs out of stories to sing about.", "У Могильного барда никогда не кончаются истории для песен.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And as it so happens, they are willing to make you another offering, but they insist that you give them 6 grams of ash this time.", "И как раз сейчас он готов сделать тебе ещё одно подношение, но на этот раз требует 6 граммов пепла.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you willing to accept their terms?.", "Готов ли ты принять его условия?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Gravebard is able to give you one final gift, but now they are asking a much higher price of 12 grams of ash!", "Могильный бард может дать тебе последний подарок, но теперь просит гораздо больше: 12 граммов пепла!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astoundingly, you have enough to pay such a fee, but are you willing to part with it?", "Удивительно, у тебя хватает на такую плату. Но готов ли ты с ней расстаться?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Will you offer 3 Grams worth of Ash?", "Предложишь 3 грамма пепла?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Gravebard has set up camp here.", "Здесь разбил лагерь Могильный бард.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They play songs and elegies about long forgotten warriors and rulers.", "Он исполняет песни и элегии о давно забытых воинах и правителях.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though nowadays their audience consists mostly of various ghouls.", "Хотя в наши дни его слушают в основном всевозможные упыри.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They are willing to play you a song and trade you an unknown gift in exchange for any grams of ash you happen to be carrying.", "Он готов сыграть тебе песню и обменять неизвестный подарок на пепел, который найдётся у тебя с собой.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The gravebard is willing to play you a song for an item. You have to pay in ash.", "Могильный бард готов сыграть тебе песню и дать предмет. Заплатить придётся пеплом.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All the excess damage you have done may finally come in handy!", "Весь нанесённый тобой избыточный урон наконец-то может пригодиться!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strum the Lute when you are ready to make a trade.", "Тронь струны лютни, когда будешь готов к обмену.", Language.Russian);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With " + price.ToString() + " grams of ash, they hand you a pouch, and play a song about a brave knight from the crusades.", "Получив " + price.ToString() + " г пепла, они вручают тебе мешочек и поют о храбром рыцаре крестовых походов.", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even after a Demonic entity cursed them into a horse-like form, they were still able to liberate the lost souls trapped by the Demon!", "Даже после того, как демоническая сущность прокляла героя, придав ему облик лошади, он сумел освободить заблудшие души из плена демона!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh right, the pouch, let's see what's inside!", "Ах да, мешочек! Посмотрим, что внутри!", Language.Russian);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With " + price.ToString() + " grams of ash in tow, they hand you another pouch, and play a tune about a sorceress from a mythical land.", "Получив " + price.ToString() + " г пепла, они дают тебе ещё один мешочек и играют мелодию о чародейке из мифической страны.", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Despite pressure from a prophecy to be the hero of the land, they instead pulled from a dark tome and sided with a cloudy villain to conquer the land and find peace from fame in an unexpected way!", "Хотя пророчество требовало стать героем этой земли, вместо этого она черпала силу из тёмной книги и объединилась с облачным злодеем, чтобы покорить край и неожиданным образом обрести покой от славы!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I almost forgot! You must be dying to know what is in the pouch!", "Чуть не забыла! Тебе наверняка не терпится узнать, что в мешочке!", Language.Russian);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling satisfied with  " + price.ToString() + " grams of ash, they hand you a pouch, and recount the tale of 4 islands.", "Довольные " + price.ToString() + " г пепла, они дают тебе мешочек и рассказывают историю 4 островов.", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each of the islands had a ruler fixated on a selfish goal, all except for one...", "У каждого острова был правитель, одержимый корыстной целью. У каждого, кроме одного...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One island had a secluded hermit covered in moss and fungi. They surrounded themselves with beasts, and would eternally trap anyone who would wander into their forest.", "На одном острове жил нелюдимый отшельник, покрытый мхом и грибами. Он окружил себя зверями и навеки заточал любого, кто забредал в его лес.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Another island had a mysterious wizard covered head to toe in a green fur. Their true goal remained unknown, but seemed to involve the torturing of their own subjects...", "На другом острове жил таинственный волшебник, с ног до головы покрытый зелёной шерстью. Его истинная цель оставалась неизвестной, но, похоже, была связана с пытками собственных подданных...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The worst island however, was barely even an island at all! A metallic barge with a sleepless factory ruled by an arrogant, robotic tyrant...", "А худший остров едва ли вообще был островом! Металлическая баржа с неусыпной фабрикой под властью высокомерного тирана-робота...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Which leaves the other island, a sprawling burial ground with a Crypt at the end of it. It was ruled by a woman who only wished for the power struggle to finally end...", "Оставался ещё один остров: обширное кладбище со склепом в конце. Им правила женщина, желавшая лишь, чтобы борьба за власть наконец закончилась...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh! That would happen to be me!", "О! А это как раз я!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think we now know how that story ended.", "Думаю, теперь мы знаем, чем закончилась эта история.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And truthfully, the story still isn't over yet, maybe we can reach the end together!", "По правде говоря, история ещё не окончена. Возможно, мы вместе дойдём до конца!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That being said, you have earned this item.", "Как бы то ни было, ты заслужил этот предмет.", Language.Russian);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking " + price.ToString() + " grams of ash with them, they hand you a pouch, and tell you about an ancient hunter of ghouls.", "Забрав " + price.ToString() + " г пепла, они дают тебе мешочек и рассказывают о древнем охотнике на гулей.", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though he was barely a hunter, instead he spent his time searching for something he could not obtain.", "Но охотником он был едва ли. Вместо охоты он искал то, чего не мог получить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In the end he found a glimpse of what he had seeked, but paid a horrible price.", "В конце концов он мельком увидел то, что искал, но заплатил страшную цену.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should see whats inside that pouch.", "Тебе стоит заглянуть в этот мешочек.", Language.Russian);
            for (int price = 0; price <= 100; price++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Taking " + price.ToString() + " grams of your ash, they hand you a pouch, and reminisce about a medic from medieval times.", "Получив " + price.ToString() + " г твоего пепла, они дают тебе мешочек и вспоминают средневекового лекаря.", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Instead of being content with their life, they instead chased the love of their life for years.", "Вместо того чтобы довольствоваться своей жизнью, он годами стремился к любви всей своей жизни.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This got them into much danger, but their friends were always there to help them out!", "Это не раз подвергало его опасности, но друзья всегда приходили на помощь!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lets see what that pouch contains.", "Посмотрим, что в этом мешочке.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RISE MY ARMY! RIIIIIIIIIISE!", "ВОССТАНЬ, МОЁ ВОЙСКО! ВОССТААААААНЬ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:5]Otis![size:]", "[size:5]Отис![size:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:5]Ephialtes![size:]", "[size:5]Эфиальт![size:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH? FIVE LANES? HOW BOLD.", "О? ПЯТЬ ЛИНИЙ? КАК СМЕЛО.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A SHAME", "КАК ЖАЛЬ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS YOUVE GIVEN UP YOUR REWARD FOR CHAOS", "ПОХОЖЕ, ТЫ ОТКАЗАЛСЯ ОТ НАГРАДЫ РАДИ ХАОСА.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I CANNOT BE DEFEATED", "МЕНЯ НЕ ПОБЕДИТЬ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I ALMOST FORGOT", "ЧУТЬ НЕ ЗАБЫЛ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL OF THIS SUFFERING YOU CAUSED, ALL OF THIS PAIN", "ВСЕ СТРАДАНИЯ, ЧТО ТЫ ПРИЧИНИЛ, ВСЯ ЭТА БОЛЬ...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU OUGHT TO BE REWARDED FOR ALL THAT EXCESS DAMAGE", "ТЫ ЗАСЛУЖИВАЕШЬ НАГРАДЫ ЗА ВЕСЬ ЭТОТ ИЗБЫТОЧНЫЙ УРОН.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TAKE THIS FOR YOUR EFFORTS", "ВОЗЬМИ ЭТО ЗА СВОИ ТРУДЫ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT A TERRIBLE FOE, THIS WONT DEFEAT ME!", "КАКОЙ УЖАСНЫЙ ВРАГ. ЭТО МЕНЯ НЕ ПОБЕДИТ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT DID YOU DO. I AM DOOMED.", "ЧТО ТЫ НАТВОРИЛ? Я ОБРЕЧЁН.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A FORMIDABLE OPPONENT, YOU DID WELL IT SEEMS.", "ДОСТОЙНЫЙ ПРОТИВНИК. ПОХОЖЕ, ТЫ ХОРОШО СПРАВИЛСЯ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minor Ashes", "Малый пепел", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Ashes", "Большой пепел", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEHOLD, MY LATEST CREATIONS! THE TWIN GIANTS!", "УЗРИ МОИ НОВЕЙШИЕ ТВОРЕНИЯ! ВЕЛИКАНОВ-БЛИЗНЕЦОВ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HELLO?", "ЭЙ?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We survived, but... but...", "Мы выжили, но... но...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our tools did not.", "А наши инструменты — нет.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our talents still remain, but..", "Наши таланты остались, но...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must do things differently.", "Нам придётся действовать иначе.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We cannot fuse two into one, but...", "Мы не можем слить двоих в одного, но...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We can swap their souls, their Sigils.", "Можем поменять местами их души, их символы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is once again time...", "Снова пришло время...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time to swap the souls of your cards.", "Время поменять местами души твоих карт.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time, it is...", "Пришло время, да...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We shall work once more.", "Мы снова примемся за работу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will get ugly...", "Это будет некрасиво...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Their bodies and souls, they are...", "Их тела и души...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Switched.", "Поменялись местами.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They lead new lives..", "Они живут новой жизнью...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With new purposes.", "С новыми целями.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Till we meet again, one day... one day...", "До новой встречи, однажды... однажды...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE WILL PROVIDE A HELPFUL CURSE OR BLESSING, AS SOME CALL IT UPON YOUR ARMY IF YOU LEAVE HIM AN OFFERING.", "ЕСЛИ ОСТАВИШЬ ПОДНОШЕНИЕ, ОН ДАРУЕТ ТВОЕМУ ВОЙСКУ ПОЛЕЗНОЕ ПРОКЛЯТИЕ — ИЛИ БЛАГОСЛОВЕНИЕ, КАК ЕГО НЕКОТОРЫЕ ЗОВУТ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I HOPE FOR YOUR SAKE HE IS FEELING GENEROUS.", "НАДЕЮСЬ, РАДИ ТЕБЯ ОН ОКАЖЕТСЯ ЩЕДРЫМ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD IS VERY HAPPY WITH THIS OFFERING", "ПОВЕЛИТЕЛЬ КОСТЕЙ ОЧЕНЬ ДОВОЛЕН ЭТИМ ПОДНОШЕНИЕМ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I AM VERY THANKFUL FOR THIS", "Я ОЧЕНЬ БЛАГОДАРЕН ЗА ЭТО.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TAKE THIS IN RETURN, YOU CAN USE IT TO CALL ME ANYTIME", "ВОЗЬМИ ЭТО ВЗАМЕН. С ЕГО ПОМОЩЬЮ ТЫ МОЖЕШЬ ПРИЗВАТЬ МЕНЯ В ЛЮБОЕ ВРЕМЯ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CANNOT END THIS, END ME, THAT IS", "ТЕБЕ НЕ ПОКОНЧИТЬ С ЭТИМ. СО МНОЙ, Я ХОТЕЛ СКАЗАТЬ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feeling overburdened enough with a full 3 items, you carried on.", "И без того обременённый полным набором из 3 предметов, ты продолжил путь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee says it's time to freeze!", "Кейси говорит, что пора замерзать!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer thanks you for your contribution!", "Сойер благодарит за твой вклад!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer felt bad for you.", "Сойеру стало тебя жаль.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope you're able to warm up next turn.", "Надеюсь, в следующем ходу ты сможешь согреться.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wonderful! I am pleasantly surprised by your triumph against me!", "Прекрасно! Твоя победа надо мной приятно удивила меня!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...It seems you have bested this game.", "...Похоже, ты одолел эту игру.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But alas, you have cheated.", "Но, увы, ты жульничал.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm absolutely astonished!", "Я совершенно поражена!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've gone above and beyond what I thought you were capable of!", "Ты намного превзошёл всё, на что я считала тебя способным!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is no where else to go beyond this...", "Дальше идти уже некуда...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So I owe it to you to know the truth...", "Так что я обязана открыть тебе правду...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee, the REAL Kaycee...", "Кейси, НАСТОЯЩАЯ Кейси...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I know about the Horrifying contents of the OLD_DATA.", "Я знаю об ужасающем содержимом СТАРЫХ_ДАННЫХ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Surely you have looked into it too..", "Ты ведь наверняка тоже туда заглядывал...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Windows into your world's greatest evils, both past and present.", "Окна в величайшее зло твоего мира — и прошлого, и настоящего.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I want to destroy it, and...", "Я хочу их уничтожить, и...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]THAT IS QUITE ENOUGH[c:]", "[c:R]ДОВОЛЬНО[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:R]IT IS TIME FOR THIS TO END.[c:]", "[c:R]ПОРА ПОЛОЖИТЬ ЭТОМУ КОНЕЦ.[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...But it seems i cannot move on just yet.", "...Но, похоже, я ещё не могу уйти.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goodbye.", "Прощай.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...You wish to continue? Endlessly? Splendid!", "...Хочешь продолжить? Бесконечно? Великолепно!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, take a card of your choosing.", "Прошу, выбери карту по своему вкусу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR WEAK SPIRITS SHALL NOT HAUNT ME NO MORE.", "ТВОИ СЛАБЫЕ ДУХИ БОЛЬШЕ НЕ БУДУТ МЕНЯ ПРЕСЛЕДОВАТЬ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEATH TOUCH WON'T HELP YOU HERE DEAR.\nI MADE THESE GIANTS SPECIAL, IMMUNE TO QUITE A FEW DIFFERENT TRICKS!", "ПРИКОСНОВЕНИЕ СМЕРТИ ЗДЕСЬ НЕ ПОМОЖЕТ, ДОРОГОЙ.\nЭТИ ВЕЛИКАНЫ У МЕНЯ ОСОБЫЕ: ОНИ НЕВОСПРИИМЧИВЫ КО МНОГИМ УЛОВКАМ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE BONELORD CANNOT BE POSSESSED!", "ПОВЕЛИТЕЛЕМ КОСТЕЙ НЕВОЗМОЖНО ОВЛАДЕТЬ!", Language.Russian);
            foreach (var kvp in Cards)
            {
                string key = "[c:B]" + kvp.Key + "[c:]";
                string value = "[c:B]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " MIGHT HAVE SOME DIFFICULTY SUBMERGING IF IT'S FROZEN SOLID!", "Существу " + value + " будет трудно погрузиться, если оно замёрзло насквозь!", Language.Russian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " CAN'T POSSESS ANYTHING IF IT CAN'T MOVE!", "Существо " + value + " не сможет вселиться ни в кого, если не может двигаться!", Language.Russian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " WILL HAVE A HARD TIME HOOKING ANYTHING IF IT'S FROZEN SOLID!", "Существу " + value + " будет трудно что-либо подцепить, если оно замёрзло насквозь!", Language.Russian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, key + " FINALLY! TO GET RID OF THAT FOUL SMELL!", value + ": НАКОНЕЦ-ТО! МОЖНО ИЗБАВИТЬСЯ ОТ ЭТОЙ ВОНИ!", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS [c:R]HEAT[c:] UP SOME CARDS!", "ДАВАЙ [c:R]ПОДОГРЕЕМ[c:] ПАРОЧКУ КАРТ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y-Your strikes are only making me [c:B]c-colder[c:]!", "Т-твои удары делают меня лишь [c:B]х-холоднее[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S TIME FOR YOUR CARDS TO FREEZE! [c:B]CHILLED[c:] TO THE BONE!", "ПОРА ТВОИМ КАРТАМ ЗАМЁРЗНУТЬ! [c:B]ПРОМЁРЗНУТЬ[c:] ДО КОСТЕЙ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALL THIS [c:bB]ICE[c:] IS TAKING UP TOO MUCH SPACE!", "ВЕСЬ ЭТОТ [c:bB]ЛЁД[c:] ЗАНИМАЕТ СЛИШКОМ МНОГО МЕСТА!", Language.Russian);
            foreach (var kvp in Cards)
            {
                string key = "[c:bR]" + kvp.Key + "[c:]";
                string value = "[c:bR]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YARRRR, I WILL ENJOY THE KABOOM OF " + key, "АРРР, Я НАСЛАЖУСЬ ВЗРЫВОМ " + value, Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOIL ME ORANGES, THERES A-WAVES COMIN!", "ТЫСЯЧА ВАРЁНЫХ АПЕЛЬСИНОВ, ВОЛНЫ ИДУТ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THESE WAVES WILL PUSH YE CARD OFF THE BOARD, BACK TO YER HAND!", "ЭТИ ВОЛНЫ СМОЮТ ТВОИ КАРТЫ С ДОСКИ ОБРАТНО В РУКУ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THIS PIRATE CANNOT BE TAKEN BACK UP BY THE WAVES! BUT EVEN THE ZESTIEST OF PIRATES WILL BE SHAKEN UP!", "ЭТОГО ПИРАТА ВОЛНАМ НЕ УНЕСТИ ОБРАТНО! НО ДАЖЕ САМОГО ЛИХОГО ПИРАТА КАК СЛЕДУЕТ ВСТРЯХНЁТ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seven seas for the table!", "Семь морей на стол!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, I WILL STORE THIS BONE FOR LATER", "О, ПРИБЕРЕГУ ЭТУ КОСТЬ НА ПОТОМ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SPARE SOME SOULS?", "ПОДЕЛИШЬСЯ ДУШАМИ?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PLEASE, WON'T YOU SPARE SOME BONES FOR A POOR GHOUL LIKE ME?", "ПРОШУ, НЕУЖЕЛИ НЕ НАЙДЁТСЯ ПАРЫ КОСТЕЙ ДЛЯ БЕДНОГО УПЫРЯ ВРОДЕ МЕНЯ?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, HOW SAD. YOUR HAMMER COULD NOT BREAK THE ICE, AND SHATTERED", "О, КАК ПЕЧАЛЬНО. ТВОЙ МОЛОТОК НЕ СМОГ РАЗБИТЬ ЛЁД И РАСКОЛОЛСЯ САМ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE FRAIL THING WILL SHATTER AFTER EXCESSIVE USE. THREE STRIKES, AND IT'S OUT, FOR THIS BATTLE AT LEAST.", "ЭТА ХРУПКАЯ ШТУКА РАЗОБЬЁТСЯ ОТ ЧРЕЗМЕРНОГО ИСПОЛЬЗОВАНИЯ. ТРИ УДАРА — И КОНЕЦ, ПО КРАЙНЕЙ МЕРЕ В ЭТОЙ БИТВЕ.", Language.Russian);
            foreach (var kvp in Cards)
            {
                string key = "[c:lGr]" + kvp.Key + "[c:]";
                string value = "[c:lGr]" + kvp.Value + "[c:]";
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... it will be rather difficult to haunt " + key + " with their abilities at max capacity.", "Ох... будет довольно трудно вселиться в существо " + value + ", пока его способности на пределе.", Language.Russian);
            }
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH DEAR! LOOKS LIKE YOU HAVE HOOKED SOMETHING OUT OF " + value + "!", "О БОЖЕ! ПОХОЖЕ, ТЫ ЧТО-ТО ВЫЛОВИЛ ИЗ " + value + "!", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bB]BRRRR![c:] I'VE BEEN FREEZING FOR AGES!", "[c:bB]БРРРР![c:] Я ЦЕЛУЮ ВЕЧНОСТЬ МЁРЗНУ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S TURN UP THE [c:R]HEAT[c:] FOR A GOOD FIGHT!", "ДОБАВИМ [c:R]ЖАРУ[c:] ДЛЯ ХОРОШЕЙ ДРАКИ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh hey, looks like I've got another shot. Hope you watched the weather forecast!", "О, похоже, у меня ещё одна попытка. Надеюсь, ты смотрел прогноз погоды!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH COME ON DUDE, I'M STILL [c:B]COLD![c:]", "НУ ЖЕ, ПРИЯТЕЛЬ, МНЕ ВСЁ ЕЩЁ [c:B]ХОЛОДНО![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S FIGHT AGAIN SOON!", "СКОРО СРАЗИМСЯ СНОВА!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONGRATULATIONS, YOU DID WELL.", "ПОЗДРАВЛЯЮ, ТЫ ХОРОШО СПРАВИЛСЯ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE DEFEATED ONE OF MY LOVELY GHOULS, YOU WILL NOW START FIGHTS WITH AN ADDITONAL BONE.", "ТЫ ПОБЕДИЛ ОДНОГО ИЗ МОИХ МИЛЫХ УПЫРЕЙ. ТЕПЕРЬ ТЫ БУДЕШЬ НАЧИНАТЬ БИТВЫ С ДОПОЛНИТЕЛЬНОЙ КОСТЬЮ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SAWYERS CATACOMBS ARE UP NEXT, A FILTHY PLACE WHERE LOTS ARE LAID TO REST.", "ДАЛЬШЕ — КАТАКОМБЫ СОЙЕРА. ГРЯЗНОЕ МЕСТО, ГДЕ ПОКОЯТСЯ МНОГИЕ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HE THINKS IT IS A TERRIBLE PLACE TO BE.", "ОН СЧИТАЕТ ЭТО МЕСТО УЖАСНЫМ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "C'mon dude, where are you going? Can't handle the cold?", "Ну же, приятель, ты куда? Не выносишь холода?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, IT SEEMS I HAVE FINALLY [c:R]WARMED UP![c:]", "О, ПОХОЖЕ, Я НАКОНЕЦ [c:R]СОГРЕЛСЯ![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M STILL NOT FEELING [c:R]WARMER![c:]", "МНЕ ВСЁ ЕЩЁ НЕ СТАЛО [c:R]ТЕПЛЕЕ![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS SEE HOW YOU DEAL WITH [c:bB]THIS![c:]", "ПОСМОТРИМ, КАК ТЫ СПРАВИШЬСЯ С [c:bB]ЭТИМ![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful, the life of your next card will be on a timer.", "Осторожно: жизнь твоей следующей карты будет на таймере.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I look forward to the [c:brnO]explosive[c:] results!", "С нетерпением жду [c:brnO]взрывных[c:] результатов!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your card cannot explode, how dissapointing.", "Твоя карта не может взорваться. Какое разочарование.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VAR, I SEE YOU MADE IT TO ME SHIP CHALLENGER!", "ЙО-ХО, ВИЖУ, ТЫ ДОБРАЛСЯ ДО МОЕГО КОРАБЛЯ, ПРЕТЕНДЕНТ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'VE BEEN WAITING FOR A WORTHY FIGHT!", "Я ЖДАЛ ДОСТОЙНОЙ СХВАТКИ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT SEEMS A STORM IS BREWING, I HOPE ME SHIP CAN HANDLE IT", "ПОХОЖЕ, НАЗРЕВАЕТ ШТОРМ. НАДЕЮСЬ, МОЙ КОРАБЛЬ ВЫДЕРЖИТ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, I SEE YEE ARE SEVERELY HAUNTED!", "О, ДА ТЕБЯ НЕШУТОЧНО ПРЕСЛЕДУЮТ ДУХИ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "REVENANT, PACK YE BAGS, YOURE GETTING THROWN OVERBOARD!", "ВОССТАВШИЙ, СОБИРАЙ МАНАТКИ: ТЕБЯ ВЫБРОСЯТ ЗА БОРТ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I OVERESTIMATED ME SKILL, GOOD LUCK CHALLENGER.", "Я ПЕРЕОЦЕНИЛ СВОЁ МАСТЕРСТВО. УДАЧИ, ПРЕТЕНДЕНТ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET'S SEE, THE NEXT AREA IS MY VERY OWN CRYPT.", "ТАК, СЛЕДУЮЩАЯ ОБЛАСТЬ — МОЙ СОБСТВЕННЫЙ СКЛЕП.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PERHAPS YOU CAN BEAT ALL ODDS AND TRIUMPH!", "ВОЗМОЖНО, ТЫ ПРЕОДОЛЕЕШЬ ВСЕ ПРЕГРАДЫ И ПОБЕДИШЬ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I beat the livin' PULP out o' ye!", "Я выбил из тебя всю МЯКОТЬ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ME SHIP! I FEAR WE MAY BE SINKING.", "МОЙ КОРАБЛЬ! БОЮСЬ, МЫ ТОНЕМ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO HOLD YEE BREATH!", "ГОТОВЬСЯ ЗАДЕРЖАТЬ ДЫХАНИЕ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOLY FISHPASTE, YE FOUND DAVY JONES TREASURE", "СВЯТАЯ РЫБНАЯ ПАСТА, ТЫ НАШЁЛ СОКРОВИЩЕ ДЕЙВИ ДЖОНСА!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YARRG, TWAS JUST DA FIRST ROUND!\nLETS SEE HOW YE FARE 'GAINST ME PERSONAL SHIP AN CREW!", "АРР, ЭТО БЫЛ ЛИШЬ ПЕРВЫЙ РАУНД!\nПОСМОТРИМ, КАК ТЫ СПРАВИШЬСЯ С МОИМ ЛИЧНЫМ КОРАБЛЁМ И КОМАНДОЙ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOW NICE OF YOU TO COME KNOCK AT MY DOORSTEP ON THIS TRULY SPOOKY DAY! DO YOU PREFER TREATS, OR TRICKS?", "КАК МИЛО, ЧТО ТЫ ПОСТУЧАЛ В МОЮ ДВЕРЬ В ЭТОТ ПОИСТИНЕ ЖУТКИЙ ДЕНЬ! ПРЕДПОЧИТАЕШЬ УГОЩЕНИЯ ИЛИ ШАЛОСТИ?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOOK AWAY, LOOK AWAY! IF YOU WANT TO FIGHT, GET IT OVER QUICK!", "НЕ СМОТРИ, НЕ СМОТРИ! ЕСЛИ ХОЧЕШЬ ДРАТЬСЯ, ПОКОНЧИМ С ЭТИМ БЫСТРО!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "oh... I- I see you're here again... Please, get rid of that monster and maybe I'll find some more time for you", "Ох... Я-я вижу, ты снова здесь... Прошу, избавься от того монстра, и, может, я найду для тебя ещё немного времени.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE BEATEN THE VICIOUS CANDY MONSTER AND SAVED HALLOWEEN!", "ТЫ ПОБЕДИЛ СВИРЕПОГО КОНФЕТНОГО МОНСТРА И СПАС ХЕЛЛОУИН!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANKS FOR GETTING IT OVER WITH, AND DON'T EVER RETURN!", "СПАСИБО, ЧТО ПОКОНЧИЛ С ЭТИМ. И БОЛЬШЕ НИКОГДА НЕ ВОЗВРАЩАЙСЯ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEXT UP IS ROYALS VERY OWN SHIP, THE LIMONCELLO.", "ДАЛЬШЕ — ЛИЧНЫЙ КОРАБЛЬ РОЙАЛА, «ЛИМОНЧЕЛЛО».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HIS TRUSTY CREW OF SWASHBUCKLERS RESIDES THERE, MAY THEY GIVE YOU A WARM WELCOME.", "ТАМ ОБИТАЕТ ЕГО ВЕРНАЯ КОМАНДА СОРВИГОЛОВ. ПУСТЬ ОНИ ОКАЖУТ ТЕБЕ ТЁПЛЫЙ ПРИЁМ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no... does this mean you will try again?", "О нет... Значит, ты попробуешь снова?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH, HE IS GONE... WHAT A RELIEF.", "О, ОН УШЁЛ... КАКОЕ ОБЛЕГЧЕНИЕ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANKS FOR YOUR BONES, KIND SIR!", "СПАСИБО ЗА КОСТИ, ДОБРЫЙ СУДАРЬ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOW THAT THAT MONSTER IS GONE, WHY DONT WE PLAY A LITTLE LONGER", "ТЕПЕРЬ, КОГДА ТОТ МОНСТР ИСЧЕЗ, ПОЧЕМУ БЫ НЕ ПОИГРАТЬ ЕЩЁ НЕМНОГО?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I HOPE YOU DONT MIND, I PAID GOOD MONEY TO PLAY THESE.", "НАДЕЮСЬ, ТЫ НЕ ПРОТИВ. Я ЗАПЛАТИЛ НЕМАЛО ДЕНЕГ, ЧТОБЫ ИМИ ПОИГРАТЬ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT THE CANDY MONSTER! HE HAS ENOUGH OF YOUR [c:R]TRICKS![c:]", "ТОЛЬКО НЕ КОНФЕТНЫЙ МОНСТР! С НЕГО ХВАТИТ ТВОИХ [c:R]ФОКУСОВ![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OH NO, HE HAS ARRIVED! HE IS THIRSTY FOR YOUR [c:R]BONES![c:]", "О НЕТ, ОН ПРИШЁЛ! ОН ЖАЖДЕТ ТВОИХ [c:R]КОСТЕЙ![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you!", "Спасибо!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUUUUUUUR, PAINNNFULLLLL DEAAATHHH AWAIIITTTSSS YOUUUUUUU!", "ТЕБЯЯЯЯ ЖДЁЁЁТ МУУУЧИТЕЛЬНАЯ СМЕЕЕЕРТЬ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARRG! WALK OFF THE PLANK YEE DIRTY SCALLYWAG!!!", "АРР! ШАГАЙ ПО ДОСКЕ, ГРЯЗНЫЙ ПРОХВОСТ!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My dogs will enjoy your bones!", "Мои собаки полакомятся твоими костями!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A [c:bR]{0}[c:]... He's only here for the riches.", "[c:bR]{0}[c:]... Он здесь лишь ради богатств.", Language.Russian);
            foreach (var value in Cards.Values)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] bone cost has decreased!", "Повелитель костей был щедр.\nСтоимость в костях для [c:bR]" + value + "[c:] снизилась!", Language.Russian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] base health has increased!", "Повелитель костей был щедр.\nБазовое здоровье [c:bR]" + value + "[c:] увеличилось!", Language.Russian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, it looks like [c:bR]" + value + "[c:] bone cost has decreased!", "Ох, кажется, стоимость в костях для [c:bR]" + value + "[c:] снизилась!", Language.Russian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been generous.\n[c:bR]" + value + "[c:] bone cost has decreased greatly!", "Повелитель костей был щедр.\nСтоимость в костях для [c:bR]" + value + "[c:] значительно снизилась!", Language.Russian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been very generous.\n[c:bR]" + value + "[c:] base health has increased greatly!", "Повелитель костей был очень щедр.\nБазовое здоровье [c:bR]" + value + "[c:] значительно увеличилось!", Language.Russian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bonelord has been very generous.\n[c:bR]" + value + "[c:] base attack has increased!", "Повелитель костей был очень щедр.\nБазовая атака [c:bR]" + value + "[c:] увеличилась!", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... WHAT? WHY DID YOU DO THAT BONELORD?! [c:bR]INCREASING THE HEALTH OF THE ENTIRE DECK?![c:] YOU FOOL!", "...ЧТО? ЗАЧЕМ ТЫ ЭТО СДЕЛАЛ, ПОВЕЛИТЕЛЬ КОСТЕЙ?! [c:bR]ПОВЫСИЛ ЗДОРОВЬЕ ВСЕЙ КОЛОДЕ?![c:] ДУРАК!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "... WHAT? WHY DID YOU DO THAT BONELORD?! [c:bR]DECREASING THE COST OF THE ENTIRE DECK?![c:] YOU FOOL!", "...ЧТО? ЗАЧЕМ ТЫ ЭТО СДЕЛАЛ, ПОВЕЛИТЕЛЬ КОСТЕЙ?! [c:bR]СНИЗИЛ СТОИМОСТЬ ВСЕЙ КОЛОДЫ?![c:] ДУРАК!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]GAIN HP[c:], HOW SAD. NOW PLEASE LEAVE.", "У ТЕБЯ НЕ ОСТАЛОСЬ КАРТ, КОТОРЫМ МОЖНО [c:bR]ПОВЫСИТЬ ЗДОРОВЬЕ[c:]. КАК ПЕЧАЛЬНО. А ТЕПЕРЬ ПРОШУ УЙТИ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]REDUCE THEIR BONE COST[c:], HOW SAD. NOW PLEASE LEAVE.", "У ТЕБЯ НЕ ОСТАЛОСЬ КАРТ, КОТОРЫМ МОЖНО [c:bR]СНИЗИТЬ СТОИМОСТЬ В КОСТЯХ[c:]. КАК ПЕЧАЛЬНО. А ТЕПЕРЬ ПРОШУ УЙТИ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU DON'T HAVE ANYMORE CARDS TO [c:bR]GAIN ATTACK[c:], HOW SAD. NOW PLEASE LEAVE.", "У ТЕБЯ НЕ ОСТАЛОСЬ КАРТ, КОТОРЫМ МОЖНО [c:bR]ПОВЫСИТЬ АТАКУ[c:]. КАК ПЕЧАЛЬНО. А ТЕПЕРЬ ПРОШУ УЙТИ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THAT'S UNFORTUNATE. YOU WERE SUPPOSED TO HAVE YOUR ENTIRE DECK DECREASED, BUT IT LOOKS LIKE THE BONELORD HAS ALREADY GIFTED YOU THAT. BEGONE!", "КАК НЕУДАЧНО. СТОИМОСТЬ ВСЕЙ ТВОЕЙ КОЛОДЫ ДОЛЖНА БЫЛА СНИЗИТЬСЯ, НО, ПОХОЖЕ, ПОВЕЛИТЕЛЬ КОСТЕЙ УЖЕ ДАРОВАЛ ТЕБЕ ЭТО. ПРОЧЬ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THAT'S UNFORTUNATE. YOU WERE SUPPOSED TO HAVE YOUR ENTIRE DECK INCREASED, BUT IT LOOKS LIKE THE BONELORD HAS ALREADY GIFTED YOU THAT. BEGONE!", "КАК НЕУДАЧНО. ХАРАКТЕРИСТИКИ ВСЕЙ ТВОЕЙ КОЛОДЫ ДОЛЖНЫ БЫЛИ ВЫРАСТИ, НО, ПОХОЖЕ, ПОВЕЛИТЕЛЬ КОСТЕЙ УЖЕ ДАРОВАЛ ТЕБЕ ЭТО. ПРОЧЬ!", Language.Russian);


            // ShowThenClear
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO BE BOARDED!", "ГОТОВЬСЯ К АБОРДАЖУ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That hammer doesn't look very sturdy, you'll break it if you bash my ice!", "Этот молоток не выглядит прочным. Разобьёшь его, если будешь колотить по моему льду!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DID YOU REALLY THINK THE BONELORD WOULD LET YOU OFF THAT EASILY?!", "ТЫ ПРАВДА ДУМАЛ, ЧТО ПОВЕЛИТЕЛЬ КОСТЕЙ ТАК ЛЕГКО ТЕБЯ ОТПУСТИТ?!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LET THE [size:5][c:bR]BONELORD[c:][size:] COMMETH!", "ДА ЯВИТСЯ [size:5][c:bR]ПОВЕЛИТЕЛЬ КОСТЕЙ[c:][size:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose as you will...", "Выбирай, как пожелаешь...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose one.", "Выбери одну.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time to rest.", "Пора отдохнуть.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Bartender![c:] Drink up!", "[c:bG]Вперёд, Бармен![c:] Пей до дна!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Undertaker![c:] Dont scream!", "[c:bG]Вперёд, Гробовщик![c:] Не кричи!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go Slingers Soul![c:] Time for a duel!", "[c:bG]Вперёд, Душа стрелка![c:] Время дуэли!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]Go One Armed Bandit![c:] I hope i get lucky!", "[c:bG]Вперёд, Однорукий бандит![c:] Надеюсь на удачу!", Language.Russian);
            for (int amnt = 0; amnt < 10; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your score is " + amnt.ToString() + ", acceptable.", "Твой результат — " + amnt.ToString() + ", приемлемо.", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "our score is 10, heres your prize!", "Твой счёт — 10. Вот твой приз!", Language.Russian);
            for (int amnt = 11; amnt <= 100; amnt++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "our score is " + amnt.ToString() + ", too bad!", "Твой результат — " + amnt.ToString() + ", как жаль!", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SUCH A SMALL TRAP CANNOT AFFECT GIANTS.", "СТОЛЬ МАЛЕНЬКАЯ ЛОВУШКА НЕ ПОВЛИЯЕТ НА ВЕЛИКАНОВ.", Language.Russian);

            // ShowMessage
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PUSH YOUR LUCK FOR ONE MORE ABILITY?\nOR PULL AWAY?", "ИСПЫТАТЬ УДАЧУ РАДИ ЕЩЁ ОДНОЙ СПОСОБНОСТИ?\nИЛИ ОТОЙТИ?", Language.Russian);

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No Bones", "Без костей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You no longer gain the extra bones, from defeating bosses.", "Победы над боссами больше не дают дополнительных костей.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's Kerfuffle", "Переполох Кейси", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The fourth turn of every battle, all your cards will be Frozen Away.", "На четвёртом ходу каждой битвы все ваши карты получают «Разморозку».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sawyer's Showdown", "Схватка Сойера", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose 1 bone every 3rd turn, if you have less than 3, gain 1 Bone", "Каждый 3-й ход вы теряете 1 кость. Если у вас меньше 3 костей, вы получаете 1 кость.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Rumble", "Потасовка Ройала", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every third card you play gains the Lit Fuse sigil.", "Каждая третья разыгранная вами карта получает символ «Горящий фитиль».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulless", "Бездушный", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletons cost +1 Energy.", "Скелеты стоят на +1 энергию больше.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frail Hammer", "Хрупкий молоток", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Hammer gets repaired only after every Boss.", "Молоток чинится только после каждого босса.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jammed Chair", "Заевший стул", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The electric chair is always set to level 3.", "Электрический стул всегда установлен на уровень 3.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wilted Clover", "Увядший клевер", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is only 2 Cards present at every Card chest.", "В каждом сундуке с картами лежит только 2 карты.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hell Mode", "Адский режим", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dont play this one, seriously. (Makes encounters Significantly Harder)", "Не выбирайте это, серьёзно. (Значительно усложняет встречи.)", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infinite Lives", "Бесконечные жизни", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't die. Really.", "Вы не можете умереть. Серьёзно.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Safe Chair", "Безопасный стул", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your cards are immune to electricity of the chair.", "Ваши карты невосприимчивы к электричеству стула.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Lords Mercy", "Милость Повелителя костей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain a Bone when you place any free Card on the Board.", "Получайте кость каждый раз, когда помещаете на доску любую бесплатную карту.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blessing of the Ankh", "Благословение анха", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start Pharaoh Battles and Bosses with an extra starting Bone and Energy.", "Начинайте бои с фараонами и боссами с дополнительной костью и энергией.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vengeant Ghouls", "Мстительные упыри", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee, Sawyer and Royal have new tricks up their sleeve", "У Кейси, Сойера и Ройала появились новые трюки в рукаве.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "High Roller", "Крупный игрок", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal is replaced by a new face", "Ройала заменяет новое лицо.", Language.Russian);

            // Debug
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Choice", "Выбор карты", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rare Card Choice", "Выбор редкой карты", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debug Chests", "Отладочные сундуки", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base Mod Cards To Deck", "Базовые карты мода в колоду", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Custom Mod Cards To Deck", "Пользовательские карты мода в колоду", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debug Tools", "Инструменты отладки", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Debug Encounters", "Отладочные встречи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disable Combat Bell", "Отключить боевой колокольчик", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disable Hammer", "Отключить молоток", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Disable Hand Model", "Отключить модель руки", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base Mod Cards To Hand", "Базовые карты мода в руку", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Custom Mod Cards To Hand", "Пользовательские карты мода в руку", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn Opponent Slot 1", "Создать в ячейке соперника 1", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn Opponent Slot 2", "Создать в ячейке соперника 2", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn Opponent Slot 3", "Создать в ячейке соперника 3", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn Opponent Slot 4", "Создать в ячейке соперника 4", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spawn All Opponent Slots", "Создать во всех ячейках соперника", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start at Twin Giants", "Начать с великанов-близнецов", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start at Bonelord", "Начать с Повелителя костей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win Round", "Выиграть раунд", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Round", "Проиграть раунд", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add Bones", "Добавить кости", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add Energy", "Добавить энергию", Language.Russian);
