    public class MagnificusMod
    {
        public static Dictionary<string, string> Cards = new();
        public static Dictionary<string, List<KeyValuePair<string, string>>> CardsDescription = new();

        public static Dictionary<string, string> Abilities = new();

        public static void RegisterCard(string en, string zh, string desen, string deszh)
        {
            if (!Cards.ContainsKey(en))
            {
                Cards.Add(en, zh);
            }
            if (!CardsDescription.ContainsKey(en))
            {
                CardsDescription[en] = new List<KeyValuePair<string, string>>();
            }
            CardsDescription[en].Add(new KeyValuePair<string, string>(desen, deszh));
        }

        public static void RegisterAbility(string en, string zh)
        {
            Abilities.Add(en, zh);
        }

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Magnificus Mod");
            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "New Magnificus Run", "НОВЫЙ ЗАХОД ЗА МАГНИФИКУСА", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEW MAGNIFICUS RUN", "НОВЫЙ ЗАХОД ЗА МАГНИФИКУСА", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "View Deck", "Просмотр колоды", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TOWER OF MAGICKS", "БАШНЯ МАГИИ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GOO DUNGEON", "СЛИЗЕВОЕ ПОДЗЕМЕЛЬЕ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LAVA DUNGEON", "ЛАВОВОЕ ПОДЗЕМЕЛЬЕ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VOID DUNGEON", "ПОДЗЕМЕЛЬЕ ПУСТОТЫ", Language.Russian);

            // Config
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Automatically unlocks every challenge and starter deck in Magnificus' Kaycees Mod. This does NOT change your magnificus challenge point value. If you have a change of heart and decide to unlock the challenges fairly, your challenge points will remain the same.", "Автоматически открывает все испытания и начальные колоды в моде Кейси для Магнификуса. Ваши очки испытаний Магнификуса НЕ изменяются. Если вы передумаете и решите открывать испытания честно, количество очков останется прежним.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Base wizard cards from act 2 will keep their original statlines.", "Базовые карты волшебников из акта 2 сохраняют исходные характеристики.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use the old 2D flat card designs instead of the new 3D models.", "Использовать старые плоские 2D-карты вместо новых 3D-моделей.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Add paint splashes to the background of every card (like in the original magnificus finale).", "Добавлять брызги краски на фон каждой карты, как в оригинальном финале Магнификуса.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third person perspective for magnificus' game. Disable if you want the classic first person experience.", "Вид от третьего лица в игре Магнификуса. Отключите для классического вида от первого лица.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Show a grid around the player in tabletop mode.", "Показывать сетку вокруг игрока в настольном режиме.", Language.Russian);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blank Mox", "Пустой мокс", Language.Russian);
            RegisterAbility("Blank Mox", "Пустой мокс");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, it will materialize into a random Mox Crystal. \n When on another card, the card will generate a random Mox Crystal.", "Когда вы берёте карту с этим символом, она материализуется в случайный кристалл мокса.\n На другой карте этот символ заставляет её создавать случайный кристалл мокса.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undecided Mox", "Неопределённый мокс", Language.Russian);
            RegisterAbility("Undecided Mox", "Неопределённый мокс");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, select a mox type for this card to provide.", "Когда разыгрывается карта с этим символом, выберите тип мокса, который она будет давать.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Heart", "Рубиновое сердце", Language.Russian);
            RegisterAbility("Ruby Heart", "Рубиновое сердце");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Ruby Mox in its place.", "Когда карта с этим символом погибает, на её месте создаётся Рубиновый мокс.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sapphire Heart", "Сапфировое сердце", Language.Russian);
            RegisterAbility("Sapphire Heart", "Сапфировое сердце");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Sapphire Mox in its place.", "Когда карта с этим символом погибает, на её месте создаётся Сапфировый мокс.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Marrow", "Костный мозг", Language.Russian);
            RegisterAbility("Bone Marrow", "Костный мозг");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When one of your non-gem cards perishes, a card bearing this sigil gains 1 power, maxing out at 5.", "Когда погибает одна из ваших карт, не являющаяся самоцветом, карта с этим символом получает 1 силу, до предела в 5.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation", "Стимуляция", Language.Russian);
            RegisterAbility("Stimulation", "Стимуляция");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 1 power, maxing out at 4.", "В конце каждого хода карта с этим символом получает 1 силу, до предела в 4.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stimulation (Health)", "Стимуляция (здоровье)", Language.Russian);
            RegisterAbility("Stimulation (Health)", "Стимуляция (здоровье)");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigil gains 2 health, maxes out at 10.", "В конце каждого хода карта с этим символом получает 2 здоровья, до предела в 10.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Draw", "Смертельный захват", Language.Russian);
            RegisterAbility("Dead Draw", "Смертельный захват");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card dies, draw a card from your deck.", "Когда погибает карта, не являющаяся самоцветом, возьмите карту из своей колоды.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emerald Heart", "Изумрудное сердце", Language.Russian);
            RegisterAbility("Emerald Heart", "Изумрудное сердце");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates an Emerald Mox in its place.", "Когда карта с этим символом погибает, на её месте создаётся Изумрудный мокс.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gooey", "Слизистый", Language.Russian);
            RegisterAbility("Gooey", "Слизистый");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, the striker loses 1 attack.", "Когда карту с этим символом ударяют, атакующий теряет 1 атаку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mental Gemnastics", "Камень за пазухой", Language.Russian);
            RegisterAbility("Mental Gemnastics", "Камень за пазухой");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw cards from your deck based on how many Gems are on the board.", "Когда разыгрывается карта с этим символом, возьмите из колоды столько карт, сколько самоцветов находится на доске.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loot", "Вымогатель", Language.Russian);
            RegisterAbility("Loot", "Вымогатель");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, draw cards from your deck based on how much damage was dealt.", "Когда карта с этим символом наносит прямой урон, возьмите из колоды столько карт, сколько урона нанесено.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Life Steal", "Похищение жизни", Language.Russian);
            RegisterAbility("Life Steal", "Похищение жизни");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil deals direct damage, the amount dealt will be healed to the owner of this card.", "Когда карта с этим символом наносит прямой урон, её владелец восстанавливает столько здоровья, сколько урона нанесено.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knockback Hit", "Отбрасывающий удар", Language.Russian);
            RegisterAbility("Knockback Hit", "Отбрасывающий удар");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil hits an opposing card, the opposing card will be kicked in the direction inscrybed in the sigil.", "Когда карта с этим символом бьёт карту соперника, цель отбрасывается в направлении, указанном на символе.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Impaled", "Пронзённый", Language.Russian);
            RegisterAbility("Impaled", "Пронзённый");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it creates a Spear in its placed. A spear is defined as Sharp, 0 power, 3 health.", "Когда карта с этим символом погибает, на её месте создаётся Копьё. У Копья «Колючие иголки», 0 силы и 3 здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnus Mox", "Великий мокс", Language.Russian);
            RegisterAbility("Magnus Mox", "Великий мокс");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, it provides an orange gem, a blue gem and a green gem to its owner.", "Пока карта с этим символом находится на доске, она даёт своему владельцу оранжевый, синий и зелёный самоцветы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Resurrection", "Воскрешение", Language.Russian);
            RegisterAbility("Resurrection", "Воскрешение");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-gem card perishes, the dead card will be brought back to life, but this card loses 3 health.", "Когда погибает карта, не являющаяся самоцветом, она воскресает, но эта карта теряет 3 здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rerolls", "Сила перебросов", Language.Russian);
            RegisterAbility("Rerolls", "Сила перебросов");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, a card bearing this sigils' base power will be increased by a random value between 0 and 3.", "В конце каждого хода базовая сила карты с этим символом становится случайным числом от 0 до 3.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Steel Trap", "Стальной капкан", Language.Russian);
            RegisterAbility("Steel Trap", "Стальной капкан");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the opposing card also perishes.", "Когда карта с этим символом погибает, карта напротив неё тоже погибает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Shield", "Самоцветный щит", Language.Russian);
            RegisterAbility("Gem Shield", "Самоцветный щит");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on the board gain a shield.", "Когда разыгрывается карта с этим символом, все самоцветы на доске получают щит.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Plating Work", "Нанесение покрытия", Language.Russian);
            RegisterAbility("Plating Work", "Нанесение покрытия");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all gems on your side of the board gain the Sharp Quills sigil, and 2 health.", "Пока карта с этим символом находится на доске, все самоцветы на вашей стороне доски получают символ «Колючие иголки» и 2 здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Animator", "Кукловод", Language.Russian);
            RegisterAbility("Animator", "Кукловод");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "While a card bearing this sigil is on the board, all non-mox cards with 0 power gain 2 power", "Пока карта с этим символом находится на доске, все карты с 0 силы, кроме моксов, получают 2 силы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "Поглотитель самоцветов", Language.Russian);
            RegisterAbility("Gem Absorber", "Поглотитель самоцветов");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all gems on your side of the board will perish. For each gem absorbed, gain 1 power and 2 health.", "Когда разыгрывается карта с этим символом, все самоцветы на вашей стороне доски погибают. За каждый поглощённый самоцвет эта карта получает 1 силу и 2 здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Submerge", "Погрузиться", Language.Russian);
            RegisterAbility("Submerge", "Погрузиться");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, a card bearing this sigil will submerge. Upon resubmerging, this card will become a random Tentacle Card.", "В конце хода карта с этим символом погружается под воду. Вновь появившись на поверхности, она превращается в случайную карту щупальца.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Familiar", "Фамильяр", Language.Russian);
            RegisterAbility("Familiar", "Фамильяр");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish if there are no non-gem cards on the board.", "Карта с этим символом погибает, если на доске нет карт, не являющихся самоцветами.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fading", "Угасание", Language.Russian);
            RegisterAbility("Fading", "Угасание");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will perish at the end of the turn.", "Карта с этим символом погибает в конце хода.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Morph", "Метаморф", Language.Russian);
            RegisterAbility("Morph", "Метаморф");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will mimic the card opposing it. If there is no card opposing it, this card will perish.", "Когда разыгрывается карта с этим символом, она подражает карте напротив. Если карты напротив нет, эта карта погибает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication", "Умножение", Language.Russian);
            RegisterAbility("Multiplication", "Умножение");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw another of this card, but with a different gem cost.", "Когда разыгрывается карта с этим символом, возьмите ещё одну такую же карту, но с другой стоимостью в самоцветах.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Cycle", "Цикл моксов", Language.Russian);
            RegisterAbility("Mox Cycle", "Цикл моксов");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, all the mox on the board will cycle into different gems.", "В конце каждого хода все моксы на доске по циклу превращаются в другие самоцветы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Strafe", "Смещение моксов", Language.Russian);
            RegisterAbility("Mox Strafe", "Смещение моксов");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, this card will move to the direction inscrybed on the sigil, and leave behind a mox.", "В конце хода эта карта перемещается в направлении, указанном на символе, и оставляет после себя мокс.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Purist", "Пуризм", Language.Russian);
            RegisterAbility("Purist", "Пуризм");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Any card directly opposing this one will have all it's sigils removed.", "Любая карта прямо напротив этой теряет все свои символы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brewery", "Пивоварня", Language.Russian);
            RegisterAbility("Brewery", "Пивоварня");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of every turn, you automatically draw a mox card from your side deck.", "В конце каждого хода вы автоматически берёте карту мокса из вспомогательной колоды.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "Поджечь", Language.Russian);
            RegisterAbility("Ignite", "Поджечь");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, every empty opposing slot will be filled with flames. A flame is defined as a 0/1, Annoying.", "Когда разыгрывается карта с этим символом, все пустые ячейки соперника заполняются пламенем. Пламя имеет 0/1 и символ «Надоеда».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Projection", "Звёздная проекция", Language.Russian);
            RegisterAbility("Projection", "Звёздная проекция");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is stuck, it will move and leave behind an astral projection of itself.", "Когда карту с этим символом ударяют, она перемещается и оставляет после себя свою астральную проекцию.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Book", "Книга заклинаний", Language.Russian);
            RegisterAbility("Spell Book", "Книга заклинаний");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random spell card.", "Когда разыгрывается карта с этим символом, возьмите случайную карту заклинания.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scholar", "Знаток заклинаний", Language.Russian);
            RegisterAbility("Scholar", "Знаток заклинаний");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random one of Bleene's Books.", "Когда разыгрывается карта с этим символом, возьмите случайную книгу Силёного.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Midas' Touch", "Прикосновение Мидаса", Language.Russian);
            RegisterAbility("Midas' Touch", "Прикосновение Мидаса");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil attacks another card, the attacked card will lose all of it's attack and turn to gold.", "Когда карта с этим символом атакует другую карту, цель теряет всю атаку и превращается в золото.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Made of Gold", "Из золота", Language.Russian);
            RegisterAbility("Made of Gold", "Из золота");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the killer will gain 2 crystals.", "Когда карта с этим символом погибает, убивший её получает 2 кристалла.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Runes", "Взрывные руны призыва", Language.Russian);
            RegisterAbility("Summon Runes", "Взрывные руны призыва");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will summon two runes beside it. A rune is defined as 0 power, 1 health, Detonator.", "Когда разыгрывается карта с этим символом, она призывает рядом с собой две руны. У руны 0 силы, 1 здоровье и «Детонатор».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Health", "Заклинание здоровья", Language.Russian);
            RegisterAbility("Spell of Health", "Заклинание здоровья");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +2 health.", "Когда разыгрывается заклинание с этим символом, все карты на вашей стороне доски получают +2 здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Attack", "Заклинание атаки", Language.Russian);
            RegisterAbility("Spell of Attack", "Заклинание атаки");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board gain +1 attack.", "Когда разыгрывается заклинание с этим символом, все карты на вашей стороне доски получают +1 атаку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Spell", "Морозное заклинание", Language.Russian);
            RegisterAbility("Frost Spell", "Морозное заклинание");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards belonging to the opponent will have their attack set to 0, but given +2 health.", "Когда разыгрывается заклинание с этим символом, атака всех карт соперника становится равной 0, но они получают +2 здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Wind", "Заклинание ветра", Language.Russian);
            RegisterAbility("Spell of Wind", "Заклинание ветра");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, all cards on your side of the board will become airborne.", "Когда разыгрывается заклинание с этим символом, все карты на вашей стороне доски получают символ «Летун».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruckus", "Переполох", Language.Russian);
            RegisterAbility("Ruckus", "Переполох");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, all cards on the board will move clockwise.", "Когда разыгрывается карта с этим символом, все карты на доске перемещаются по часовой стрелке.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Water", "Заклинание воды", Language.Russian);
            RegisterAbility("Spell of Water", "Заклинание воды");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, every card on the board will have their sigils erased.", "Когда разыгрывается заклинание с этим символом, у каждой карты на доске стираются все символы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell of Flame", "Заклинание пламени", Language.Russian);
            RegisterAbility("Spell of Flame", "Заклинание пламени");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a side of the board, every card on that side will lose 2 health (without perishing) and have their attack increased by 1.", "Выберите сторону доски. Все карты на ней теряют 2 здоровья, не погибая, и получают 1 атаку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Set Ablaze", "Поджечь", Language.Russian);
            RegisterAbility("Set Ablaze", "Поджечь");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every card on the opposite side will lose 2 health (without perishing) and have their attack increased by 1.", "Все карты на противоположной стороне теряют 2 здоровья, не погибая, и получают 1 атаку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Time Spell", "Одноразовое заклинание", Language.Russian);
            RegisterAbility("One Time Spell", "Одноразовое заклинание");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When the turn ends, a spell bearing this sigil will perish and be removed from your deck.", "В конце хода заклинание с этим символом погибает и удаляется из вашей колоды.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vase of Greed", "Сосуд жадности", Language.Russian);
            RegisterAbility("Vase of Greed", "Сосуд жадности");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, discard your current hand and draw 4 new cards.", "Когда разыгрывается заклинание с этим символом, сбросьте текущую руку и возьмите 4 новые карты.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gnomification", "Превращение в гнома", Language.Russian);
            RegisterAbility("Gnomification", "Превращение в гнома");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a slot to summon a Gnome card in.", "Выберите ячейку, в которой будет призвана карта Гнома.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed", "Проклятый", Language.Russian);
            RegisterAbility("Cursed", "Проклятый");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a spell bearing this sigil is played, it will immediately perish.", "Когда разыгрывается заклинание с этим символом, оно немедленно погибает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inspiration", "Вдохновение", Language.Russian);
            RegisterAbility("Inspiration", "Вдохновение");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to give Airborne + Looter for 1 turn.", "Выберите карту, которая получит «Летун» + «Вымогатель» на 1 ход.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calculus", "Математический анализ", Language.Russian);
            RegisterAbility("Calculus", "Математический анализ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to swap stats.", "Выберите карту, чтобы поменять местами её характеристики.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rage", "Бешенство", Language.Russian);
            RegisterAbility("Rage", "Бешенство");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to kill. The opponent of the card will recieve damage equal to the amount of health the card had.", "Выберите карту, которую нужно убить. Её противник получит урон, равный её прежнему здоровью.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fireball", "Огненный шар", Language.Russian);
            RegisterAbility("Fireball", "Огненный шар");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select a card to take 2 damage.", "Выберите карту, которая получит 2 урона.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cold to the Touch", "Ледяное прикосновение", Language.Russian);
            RegisterAbility("Cold to the Touch", "Ледяное прикосновение");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigils attack another card, that card will lose 1 attack.", "Когда карта с этим символом атакует другую карту, цель теряет 1 атаку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frozen", "Замороженный", Language.Russian);
            RegisterAbility("Frozen", "Замороженный");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, this card will lose its frozen health. When all frozen health is depleted, or this card is struck, it will defrost.", "В конце каждого хода эта карта теряет замороженное здоровье. Когда оно полностью иссякнет или карта получит удар, она разморозится.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strong Pull", "Мощное притяжение", Language.Russian);
            RegisterAbility("Strong Pull", "Мощное притяжение");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Every opposing card will be inclined to hit this card instead of any other.", "Все карты соперника предпочитают атаковать эту карту, а не другие.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Displacement", "Замещение", Language.Russian);
            RegisterAbility("Displacement", "Замещение");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is drawn, another of this card will be added randomly into your deck", "Когда вы берёте карту с этим символом, ещё одна такая карта добавляется в случайное место вашей колоды.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Reckoning", "Самоцветная расплата", Language.Russian);
            RegisterAbility("Gem Reckoning", "Самоцветная расплата");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of each turn, if the owner of this card does not control any gems, the leftmost card in your hand is discarded.", "В конце каждого хода, если владелец этой карты не контролирует ни одного самоцвета, крайняя левая карта в вашей руке сбрасывается.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Power", "Сила моксов", Language.Russian);
            RegisterAbility("Mox Power", "Сила моксов");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "Значение этого символа равно числу карт моксов на стороне владельца на столе.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Health", "Здоровье моксов", Language.Russian);
            RegisterAbility("Mox Health", "Здоровье моксов");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the number of Mox Cards that the owner has on their side of the table.", "Значение этого символа равно числу карт моксов на стороне владельца на столе.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Candle Proximity", "Близость свечи", Language.Russian);
            RegisterAbility("Candle Proximity", "Близость свечи");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to how close this card is to the Candle on the table.", "Значение этого символа определяется близостью карты к свече на столе.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Murder Power", "Убийственная сила", Language.Russian);
            RegisterAbility("Murder Power", "Убийственная сила");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal the total amount of power on the opponents board.", "Значение этого символа равно суммарной силе на стороне соперника на доске.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to half the total amount of power on your board.", "Значение этого символа равно половине суммарной силы на вашей стороне доски.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spell Power", "Сила заклинаний", Language.Russian);
            RegisterAbility("Spell Power", "Сила заклинаний");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during this current dungeon.", "Значение этого символа равно общему числу заклинаний, разыгранных в текущем подземелье.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to total amount of spells played during the battle.", "Значение этого символа равно общему числу заклинаний, разыгранных за битву.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Counterbattery Power", "Сила контрбатареи", Language.Russian);
            RegisterAbility("Counterbattery Power", "Сила контрбатареи");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented with this sigil will be equal to the amount of damage taken by you this battle, divided by two.", "Значение этого символа равно половине урона, полученного вами за эту битву.", Language.Russian);
            foreach (Ability ability in Enum.GetValues(typeof(Ability)))
            {
                var info = AbilitiesUtil.GetInfo(ability);
                if (info == null || info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的info，已跳过。");
                    continue;
                }
                if (info.rulebookName == null || Abilities.ContainsKey(info.rulebookName))
                {
                    Debug.LogWarning($"Ability {ability} 没有有效的rulebookName，或本身已注册，已跳过。");
                    continue;
                }
                RegisterAbility(info.rulebookName, RussianLanguagePack.Localize(info.rulebookName));
            }

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox", "мокс", Language.Russian);
            RegisterCard("Mox", "мокс", "its a me moxio", "это я, моксио");
            RegisterCard("Ruby Mox", "Рубиновый мокс", "its a me moxio", "это я, моксио");
            RegisterCard("Emerald Mox", "Изумрудный мокс", "its a me moxio", "это я, моксио");
            RegisterCard("Sapphire Mox", "Сапфировый мокс", "its a me moxio", "это я, моксио");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "its a me moxio", "это я, моксио", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear", "Копьё", Language.Russian);
            RegisterCard("Spear", "Копьё", "ayo", "ой");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ayo", "ой", Language.Russian);
            RegisterCard("Mage Pupil", "Ученица мага", "Though weak, it can always be useful in the right situation.", "Хоть и слаб, в нужной ситуации всегда пригодится.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Though weak, it can always be useful in the right situation.", "Хоть и слаб, в нужной ситуации всегда пригодится.", Language.Russian);
            RegisterCard("Junior Sage", "Младший мудрец", "Although simple, it can prove itself to be useful.", "Хоть и прост, он может оказаться полезным.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Although simple, it can prove itself to be useful.", "Хоть и прост, он может оказаться полезным.", Language.Russian);
            RegisterCard("Muscle Mage", "Мускулистый маг", "An abomination of muscles, developed from drinking too many potions of the alchemist..", "Мышечное чудовище, появившееся от чрезмерного употребления зелий алхимика...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An abomination of muscles, developed from drinking too many potions of the alchemist..", "Мышечное чудовище, появившееся от чрезмерного употребления зелий алхимика...", Language.Russian);
            RegisterCard("Green Mage", "Зелёный маг", "It draws its power from the mana of the mox on the board.", "Черпает силу из маны моксов на доске.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It draws its power from the mana of the mox on the board.", "Черпает силу из маны моксов на доске.", Language.Russian);
            RegisterCard("Blue Mage", "Синий маг", "Never doubt its utility.", "Никогда не сомневайся в его полезности.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Never doubt its utility.", "Никогда не сомневайся в его полезности.", Language.Russian);
            RegisterCard("Blue Sporemage", "Синий споромаг", "", "");
            RegisterCard("Force Mage", "Силовой маг", "A mage, proficient in a martial stance which allows it block nearly anything..", "Маг, владеющий боевой стойкой, которая позволяет блокировать почти всё...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage, proficient in a martial stance which allows it block nearly anything..", "Маг, владеющий боевой стойкой, которая позволяет блокировать почти всё...", Language.Russian);
            RegisterCard("Gem Fiend", "Фанат самоцветов", "A wretched, unstable creature of gems. It can tear through anything.", "Жалкое, нестабильное существо из самоцветов. Может разорвать что угодно.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wretched, unstable creature of gems. It can tear through anything.", "Жалкое, нестабильное существо из самоцветов. Может разорвать что угодно.", Language.Russian);
            RegisterCard("Hover Mage", "Парящая ведьма", "Using its spells it soars high to hit directly", "С помощью заклинаний взмывает ввысь и бьёт напрямую.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Using its spells it soars high to hit directly", "С помощью заклинаний взмывает ввысь и бьёт напрямую.", Language.Russian);
            RegisterCard("Mage Knight", "Волшебный рыцарь", "An intimidating and towering defense, however requiring gems to stay stable.", "Внушительная, устрашающая защита, но ей нужны самоцветы для устойчивости.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An intimidating and towering defense, however requiring gems to stay stable.", "Внушительная, устрашающая защита, но ей нужны самоцветы для устойчивости.", Language.Russian);
            RegisterCard("Orange Mage", "Оранжевая ведьма", "Using its spells, it boosts the damage of all gems.", "Своими заклинаниями усиливает урон всех самоцветов.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Using its spells, it boosts the damage of all gems.", "Своими заклинаниями усиливает урон всех самоцветов.", Language.Russian);
            RegisterCard("Practice Wizard", "Манекен чародея", "A lifeless practice target.. standing tall enough to block any attacks.", "Безжизненная мишень для тренировок... Достаточно высокая, чтобы блокировать любые атаки.");
