            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ruby Daemon", "Рубиновый демон", Language.Russian);
            RegisterCard("Ruby Daemon", "Рубиновый демон", "If not properly sustained, it will destroy your hand to fuel itself..", "Без должного питания уничтожит вашу руку, чтобы подпитать себя...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If not properly sustained, it will destroy your hand to fuel itself..", "Без должного питания уничтожит вашу руку, чтобы подпитать себя...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Friend", "Друг самоцветов", Language.Russian);
