            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Multiplication mage", "Маг умножения", Language.Russian);
            RegisterCard("Multiplication mage", "Маг умножения", "This cycle can go on forever..", "Этот цикл может продолжаться вечно...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cycle can go on forever..", "Этот цикл может продолжаться вечно...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Invisible mage", "Невидимый маг", Language.Russian);
            RegisterCard("Invisible mage", "Невидимый маг", "It drank the wrong potion and ended up invisible. How clumsy.", "Выпил не то зелье и стал невидимым. Как неловко.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It drank the wrong potion and ended up invisible. How clumsy.", "Выпил не то зелье и стал невидимым. Как неловко.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Crystal Sage", "Кристальный мудрец", Language.Russian);
            RegisterCard("Crystal Sage", "Кристальный мудрец", "A young scholar, profoundly studying mana crystals.", "Юный учёный, глубоко изучающий кристаллы маны.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A young scholar, profoundly studying mana crystals.", "Юный учёный, глубоко изучающий кристаллы маны.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Guardian", "Страж самоцветов", Language.Russian);
            RegisterCard("Gem Guardian", "Страж самоцветов", "The inverse of the Gem Detonator, this one seeks to protect all mox.", "Противоположность Детонатору самоцветов: этот стремится защитить все моксы.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The inverse of the Gem Detonator, this one seeks to protect all mox.", "Противоположность Детонатору самоцветов: этот стремится защитить все моксы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembound Ripper", "Жнец самоцветов", Language.Russian);
            RegisterCard("Gembound Ripper", "Жнец самоцветов", "It is unstable, but such is the price for unending power.", "Он нестабилен, но такова цена бесконечной силы.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is unstable, but such is the price for unending power.", "Он нестабилен, но такова цена бесконечной силы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Absorber", "Пожиратель самоцветов", Language.Russian);
            RegisterCard("Gem Absorber", "Пожиратель самоцветов", "It seeks out to consume all mana within Mox to grow stronger.", "Стремится поглотить всю ману моксов, чтобы стать сильнее.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seeks out to consume all mana within Mox to grow stronger.", "Стремится поглотить всю ману моксов, чтобы стать сильнее.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemagus", "Скелемаг", Language.Russian);
            RegisterCard("Skelemagus", "Скелемаг", "Great power for a few, fleeting moments..", "Великая сила на несколько кратких мгновений...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Great power for a few, fleeting moments..", "Великая сила на несколько кратких мгновений...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelesage", "Костяной мудрец", Language.Russian);
            RegisterCard("Skelesage", "Костяной мудрец", "One of my own Junior Sages, lost and revived.", "Один из моих Младших мудрецов, потерянный и возрождённый.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of my own Junior Sages, lost and revived.", "Один из моих Младших мудрецов, потерянный и возрождённый.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Erratic Scholar", "Непредсказуемый учёный", Language.Russian);
            RegisterCard("Erratic Scholar", "Непредсказуемый учёный", "A panicked scholar.. Always running from its problems..", "Паникующий учёный... Вечно убегает от своих проблем...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A panicked scholar.. Always running from its problems..", "Паникующий учёный... Вечно убегает от своих проблем...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mox Mage", "Мокс-маг", Language.Russian);
            RegisterCard("Mox Mage", "Мокс-маг", "A Mox disguised as a mage.. It's not going to fool anyone.", "Мокс, замаскированный под мага... Никого он не обманет.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Mox disguised as a mage.. It's not going to fool anyone.", "Мокс, замаскированный под мага... Никого он не обманет.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aurumtact", "Златокасатель", Language.Russian);
            RegisterCard("Aurumtact", "Златокасатель", "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "Пожилой учёный, проклятый за жадность. Всё, к чему он прикасается, оказывается погребено в чистом золоте.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elder scholar, cursed for his greed, entombing anything he touches in pure gold.", "Пожилой учёный, проклятый за жадность. Всё, к чему он прикасается, оказывается погребено в чистом золоте.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chained Mox", "Цепной мокс", Language.Russian);
            RegisterCard("Chained Mox", "Цепной мокс", "A collection of 3 moxen, tangled together, combining their mana energy.", "Скопление из 3 переплетённых моксов, объединяющих энергию маны.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A collection of 3 moxen, tangled together, combining their mana energy.", "Скопление из 3 переплетённых моксов, объединяющих энергию маны.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maux", "Мокс", Language.Russian);
            RegisterCard("Maux", "Мокс", "In all my years, I have NEVER seen an imitation cruder than this.", "За все свои годы я НИКОГДА не видел более грубой подделки.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In all my years, I have NEVER seen an imitation cruder than this.", "За все свои годы я НИКОГДА не видел более грубой подделки.", Language.Russian);
            RegisterCard("Stim Mage", "Маг стимуляции", "It strives to grow stronger, disregarding its own wellbeing..", "Стремится стать сильнее, не заботясь о собственном благополучии...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It strives to grow stronger, disregarding its own wellbeing..", "Стремится стать сильнее, не заботясь о собственном благополучии...", Language.Russian);
            RegisterCard("Gourmage", "Гурмаг", "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "Прожорливый маг, пожирающий тела ваших павших, чтобы стать сильнее... Отвратительно.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A gluttonous mage who devours the corpses of your fallen to grow stroner.. Disgusting.", "Прожорливый маг, пожирающий тела ваших павших, чтобы стать сильнее... Отвратительно.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dunce", "Недотёпа", Language.Russian);
            RegisterCard("Dunce", "Недотёпа", "This one can never seem to hit its target..", "Этот, похоже, никогда не попадает в цель...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to hit its target..", "Этот, похоже, никогда не попадает в цель...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grootslang", "Грутсланг", Language.Russian);
            RegisterCard("Grootslang", "Грутсланг", "The mere graze of its fangs is enough to kill any creature. No matter the size.", "Лёгкого касания его клыков достаточно, чтобы убить любое существо, независимо от размера.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The mere graze of its fangs is enough to kill any creature. No matter the size.", "Лёгкого касания его клыков достаточно, чтобы убить любое существо, независимо от размера.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bookworm", "Книжный червь", Language.Russian);
            RegisterCard("Bookworm", "Книжный червь", "A rare kind of insect that absorbs knowledge out of books.", "Редкое насекомое, впитывающее знания из книг.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A rare kind of insect that absorbs knowledge out of books.", "Редкое насекомое, впитывающее знания из книг.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alchemist", "Алхимик", Language.Russian);
            RegisterCard("Alchemist", "Алхимик", "A supporting one. It brews potions to empower your cards.", "Помощник. Варит зелья, усиливающие ваши карты.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A supporting one. It brews potions to empower your cards.", "Помощник. Варит зелья, усиливающие ваши карты.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Mage", "Маг колокольчиков", Language.Russian);
            RegisterCard("Chime Mage", "Маг колокольчиков", "Its chime can prove to be quite annoying..", "Его звон бывает весьма надоедливым...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its chime can prove to be quite annoying..", "Его звон бывает весьма надоедливым...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revivor", "Возродившийся", Language.Russian);
            RegisterCard("Revivor", "Возродившийся", "It brings a mage back from the dead, at the cost of its own health.", "Возвращает мага из мёртвых ценой собственного здоровья.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It brings a mage back from the dead, at the cost of its own health.", "Возвращает мага из мёртвых ценой собственного здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune Mage", "Рунный маг", Language.Russian);
            RegisterCard("Rune Mage", "Рунный маг", "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "При призыве создаёт рядом с собой взрывные руны. Не лучшая идея, должен сказать.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It conjures explosive runes alongside it when summoned. Not a good idea, I must say.", "При призыве создаёт рядом с собой взрывные руны. Не лучшая идея, должен сказать.", Language.Russian);
            RegisterCard("--~~--~~--", "--~~--~~--", "So it arrives.", "И вот он прибывает.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So it arrives.", "И вот он прибывает.", Language.Russian);
            RegisterCard("~-~-~-~-~-~", "~-~-~-~-~-~", "I foresaw its arrival.", "Я предвидел его прибытие.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I foresaw its arrival.", "Я предвидел его прибытие.", Language.Russian);
            RegisterCard("~~--~~--~~", "~~--~~--~~", "At last, it is here.", "Наконец-то он здесь.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At last, it is here.", "Наконец-то он здесь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sniper Sage", "Мудрец-снайпер", Language.Russian);
            RegisterCard("Sniper Sage", "Мудрец-снайпер", "A mage whose training allows it to cast spells from afar.", "Маг, которому подготовка позволяет творить заклинания издалека.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage whose training allows it to cast spells from afar.", "Маг, которому подготовка позволяет творить заклинания издалека.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rune", "Руна", Language.Russian);
            RegisterCard("Rune", "Руна", "This is the last call, for alcohol.", "Последний заказ на спиртное.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "Последний заказ на спиртное.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flame", "Магическое пламя", Language.Russian);
            RegisterCard("Flame", "Магическое пламя", "This is the last call, for alcohol.", "Последний заказ на спиртное.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "Последний заказ на спиртное.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbit", "Кролик", Language.Russian);
            RegisterCard("Rabbit", "Кролик", "This is the last call, for alcohol.", "Последний заказ на спиртное.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for alcohol.", "Последний заказ на спиртное.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for booze.", "Последний заказ на выпивку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is the last call, for ale.", "Последний заказ на эль.", Language.Russian);
            RegisterCard("Master Goranj", "Зелёнжевый хозяин", "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "Возвышающийся Зелёнжевый хозяин. Не только владеет грозной магией, но и обладает несокрушимой стойкой.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The towering Master Goranj. Not only a caster of fearsome Magicks, but possessed of a sturdy poise as well.", "Возвышающийся Зелёнжевый хозяин. Не только владеет грозной магией, но и обладает несокрушимой стойкой.", Language.Russian);
            RegisterCard("Master Bleene", "Силёный хозяин", "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "Самоотверженный Силёный хозяин. Он поможет в минуту крайней нужды… Ценой собственной способности защищаться. Достойно восхищения.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The selfless Master Bleene. It shall help you in times of dire need… At the cost of its own ability to defend itself. Admirable.", "Самоотверженный Силёный хозяин. Он поможет в минуту крайней нужды… Ценой собственной способности защищаться. Достойно восхищения.", Language.Russian);
            RegisterCard("Master Orlu", "Оранний хозяин", "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "Великий Оранний хозяин парит на бледных крыльях, атакует сверху и притягивает карты снизу...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The great Master Orlu, soaring on pale wings, it attacks from above and draws in cards from below..", "Великий Оранний хозяин парит на бледных крыльях, атакует сверху и притягивает карты снизу...", Language.Russian);
            RegisterCard("Master Magnus", "Верховный мастер Магнус", "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "Меня зовут... Шейк-Зула! Властитель микрофона! Старой школы король! Хочешь улететь? Я тебе это устрою...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "my name is.. Shake-Zula! The Mic rula! The Old Schoola! You want a trip? I'll bring it to ya...", "Меня зовут... Шейк-Зула! Властитель микрофона! Старой школы король! Хочешь улететь? Я тебе это устрою...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Magnus", "Верховный мастер Магнус", Language.Russian);
            RegisterCard("Master Magnus", "Верховный мастер Магнус", "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "Фрайлок, да, я на вершине, встряхну тебя, как коп. Митвад, ты следующий со своим «тук-тук»!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frylock yeah Im on top rock you like a cop, meatwad you're up next with your knock knock!", "Фрайлок, да, я на вершине, встряхну тебя, как коп. Митвад, ты следующий со своим «тук-тук»!", Language.Russian);
            RegisterCard("Master Magnus", "Верховный мастер Магнус", "Meatwad get the money, see. Meatwad get the honeys, G. ", "Митвад гребёт деньжата, понял? Митвад цепляет девчат, братан.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meatwad get the money, see. Meatwad get the honeys, G. ", "Митвад гребёт деньжата, понял? Митвад цепляет девчат, братан.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phoenix", "Феникс", Language.Russian);
            RegisterCard("Phoenix", "Феникс", "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "Величественная птица, по слухам бывшая сообщником Ораннего хозяина...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majestic avian, rumoured to have been an accomplice to Master Orlu...", "Величественная птица, по слухам бывшая сообщником Ораннего хозяина...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bleenehound", "Силёная ищейка", Language.Russian);
            RegisterCard("Bleenehound", "Силёная ищейка", "Loyalist canine, rumoured to have been Master Bleene's loyal companion.", "Верный пёс, по слухам бывший преданным спутником Силёного хозяина.");
