            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Portrait Mage", "Маг портретов", Language.Russian);
            RegisterCard("Portrait Mage", "Маг портретов", "Your own creation.. How did it get here?", "Твоё собственное творение... Как оно сюда попало?");
