    public class MagicExpansionMod
    {

        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagicExpansion Mod");
            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Angry Witch", "Ведьма гнева", Language.Russian);
            MagnificusMod.RegisterCard("Angry Witch", "Ведьма гнева", "The witch in charge of anger will ignite flames in the opposite battlefield.", "Ведьма, повелевающая гневом, зажжёт пламя на вражеском поле боя.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of anger will ignite flames in the opposite battlefield.", "Ведьма, повелевающая гневом, зажжёт пламя на вражеском поле боя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Arrogant Witch", "Ведьма гордыни", Language.Russian);
            MagnificusMod.RegisterCard("Arrogant Witch", "Ведьма гордыни", "The witch who mastered the power of arrogance appeared with the demon.", "Ведьма, овладевшая силой гордыни, явилась вместе с демоном.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who mastered the power of arrogance appeared with the demon.", "Ведьма, овладевшая силой гордыни, явилась вместе с демоном.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Mage", "Кофейный маг", Language.Russian);
            MagnificusMod.RegisterCard("Coffee Mage", "Кофейный маг", "Mages who love coffee use gems to regulate their breath.", "Маги, любящие кофе, используют самоцветы, чтобы выровнять дыхание.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mages who love coffee use gems to regulate their breath.", "Маги, любящие кофе, используют самоцветы, чтобы выровнять дыхание.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Funny MagiChiking", "Забавная магическая курица", Language.Russian);
            MagnificusMod.RegisterCard("Funny MagiChiking", "Забавная магическая курица", "A smelly Rooster who has learned magic.", "Вонючий петух, выучивший магию.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A smelly Rooster who has learned magic.", "Вонючий петух, выучивший магию.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gluttonous Witch", "Ведьма чревоугодия", Language.Russian);
            MagnificusMod.RegisterCard("Gluttonous Witch", "Ведьма чревоугодия", "The witch in charge of gluttony committed a terrible sin.", "Ведьма, повелевающая чревоугодием, совершила страшный грех.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of gluttony committed a terrible sin.", "Ведьма, повелевающая чревоугодием, совершила страшный грех.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greedy Witch", "Ведьма жадности", Language.Russian);
            MagnificusMod.RegisterCard("Greedy Witch", "Ведьма жадности", "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "Ведьма, управляющая силой алчности, увы, приносит нам пользу лишь после смерти.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch who controls the power of greed, unfortunately, can only bring value to us after death.", "Ведьма, управляющая силой алчности, увы, приносит нам пользу лишь после смерти.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inquisitive Witch", "Ведьма алчности", Language.Russian);
            MagnificusMod.RegisterCard("Inquisitive Witch", "Ведьма алчности", "Nothing is more powerful than her curiosity.", "Ничто не сильнее её любопытства.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing is more powerful than her curiosity.", "Ничто не сильнее её любопытства.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jealous Witch", "Ведьма зависти", Language.Russian);
            MagnificusMod.RegisterCard("Jealous Witch", "Ведьма зависти", "The witch in charge of jealousy has powerful magic and power.", "Ведьма, повелевающая завистью, обладает могучей магией и силой.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of jealousy has powerful magic and power.", "Ведьма, повелевающая завистью, обладает могучей магией и силой.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Witch", "Ведьма лени", Language.Russian);
            MagnificusMod.RegisterCard("Lazy Witch", "Ведьма лени", "The witch in charge of the power of laziness is really a lazy guy.", "Ведьма, управляющая силой лени, и впрямь лентяйка.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of the power of laziness is really a lazy guy.", "Ведьма, управляющая силой лени, и впрямь лентяйка.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lust Witch", "Ведьма похоти", Language.Russian);
            MagnificusMod.RegisterCard("Lust Witch", "Ведьма похоти", "The witch in charge of lust, don't look into her eyes.", "Ведьма, повелевающая похотью. Не смотри ей в глаза.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The witch in charge of lust, don't look into her eyes.", "Ведьма, повелевающая похотью. Не смотри ей в глаза.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nine Color Deer", "Девятицветный олень", Language.Russian);
            MagnificusMod.RegisterCard("Nine Color Deer", "Девятицветный олень", "The colorful nine color deer has precious value.", "Красочный девятицветный олень обладает драгоценной ценностью.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The colorful nine color deer has precious value.", "Красочный девятицветный олень обладает драгоценной ценностью.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stinky MagiChiking", "Вонючая магокурочка", Language.Russian);
            MagnificusMod.RegisterCard("Stinky MagiChiking", "Вонючая магокурочка", "Hatched by magic eggs.", "Вылупился из волшебных яиц.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hatched by magic eggs.", "Вылупился из волшебных яиц.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Maniac", "Бомбовый маньяк", Language.Russian);
            MagnificusMod.RegisterCard("Bomb Maniac", "Бомбовый маньяк", "Even if it detonates itself, it never surrenders to others.", "Даже взорвав себя, он никогда не сдаётся другим.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even if it detonates itself, it never surrenders to others.", "Даже взорвав себя, он никогда не сдаётся другим.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earl Bunny", "Кролик-граф", Language.Russian);
            MagnificusMod.RegisterCard("Earl Bunny", "Кролик-граф", "The versatile Earl Bunny, not everyone can comprehend this art.", "Разносторонний Кролик-граф. Не каждому дано постичь это искусство.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The versatile Earl Bunny, not everyone can comprehend this art.", "Разносторонний Кролик-граф. Не каждому дано постичь это искусство.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chinese Loong", "Китайский дракон", Language.Russian);
            MagnificusMod.RegisterCard("Chinese Loong", "Китайский дракон", "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "Погружаясь в бездну, он усмиряет четыре моря; взлетая, оберегает всё сущее и несёт покой. Путь дракона на тысячи миль — знак благой удачи.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Diving into the abyss will bring peace to the four seas, flying will protect all things and bring peace, and the dragon's journey of thousands of miles is a sign of good fortune.", "Погружаясь в бездну, он усмиряет четыре моря; взлетая, оберегает всё сущее и несёт покой. Путь дракона на тысячи миль — знак благой удачи.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "Сырный волшебник", Language.Russian);
            MagnificusMod.RegisterCard("Cheese Wizard", "Сырный волшебник", "A humorous wizard who is proficient in cooking, his cheese has magical power.", "Весёлый волшебник, искусный в готовке. Его сыр обладает волшебной силой.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A humorous wizard who is proficient in cooking, his cheese has magical power.", "Весёлый волшебник, искусный в готовке. Его сыр обладает волшебной силой.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frost Golem", "Ледяной голем", Language.Russian);
            MagnificusMod.RegisterCard("Frost Golem", "Ледяной голем", "Once on the field, there is a strong sense of oppression.", "При его появлении на доске ощущается сильное давление.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once on the field, there is a strong sense of oppression.", "При его появлении на доске ощущается сильное давление.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "Бейсбольный маг", Language.Russian);
            MagnificusMod.RegisterCard("Baseball Mage", "Бейсбольный маг", "His soul is bound under sportswear and can never be liberated.", "Его душа скована спортивной одеждой и никогда не обретёт свободу.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "His soul is bound under sportswear and can never be liberated.", "Его душа скована спортивной одеждой и никогда не обретёт свободу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Raid Mage", "Маг налёта", Language.Russian);
            MagnificusMod.RegisterCard("Raid Mage", "Маг налёта", "You will understand how terrifying it is for a robber to master magic.", "Ты поймёшь, насколько страшен разбойник, овладевший магией.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will understand how terrifying it is for a robber to master magic.", "Ты поймёшь, насколько страшен разбойник, овладевший магией.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jade Turtle", "Нефритовая черепаха", Language.Russian);
            MagnificusMod.RegisterCard("Jade Turtle", "Нефритовая черепаха", "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "Черепаха, с головы до ног укутанная изумрудами. Не могу не дивиться, что такая картина вообще существует.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A turtle draped in emeralds from head to toe—I can't help but marvel that such a painting even exists.", "Черепаха, с головы до ног укутанная изумрудами. Не могу не дивиться, что такая картина вообще существует.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Cheese", "Магический сыр", Language.Russian);
            MagnificusMod.RegisterCard("Magic Cheese", "Магический сыр", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scarlet Cuckoo", "Алый кукушонок", Language.Russian);
            MagnificusMod.RegisterCard("Scarlet Cuckoo", "Алый кукушонок", "The success or failure of the angry magic bird often depends on its face.", "Успех или неудача сердитой волшебной птицы часто зависят от выражения её морды.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The success or failure of the angry magic bird often depends on its face.", "Успех или неудача сердитой волшебной птицы часто зависят от выражения её морды.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spear Apprentice", "Ученик-копейщик", Language.Russian);
            MagnificusMod.RegisterCard("Spear Apprentice", "Ученик-копейщик", "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "Ученики магов-копейщиков. Мудрые всегда готовят запасной ход.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Apprentices of Spear Mages, wise people will leave behind their backs to prepare.", "Ученики магов-копейщиков. Мудрые всегда готовят запасной ход.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Eye of Darkness", "Око тьмы", Language.Russian);
            MagnificusMod.RegisterCard("The Eye of Darkness", "Око тьмы", "This precious pearl was once the devil's eye.", "Эта драгоценная жемчужина когда-то была глазом дьявола.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This precious pearl was once the devil's eye.", "Эта драгоценная жемчужина когда-то была глазом дьявола.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forest Spell", "Лесное заклинание", Language.Russian);
            MagnificusMod.RegisterCard("Forest Spell", "Лесное заклинание", "The forest spell obtained from Leshy can provide the most primitive defense.", "Лесное заклинание, полученное от Лешего, даёт самую первобытную защиту.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The forest spell obtained from Leshy can provide the most primitive defense.", "Лесное заклинание, полученное от Лешего, даёт самую первобытную защиту.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MoxShield", "Мокс-щит", Language.Russian);
            MagnificusMod.RegisterCard("MoxShield", "Мокс-щит", "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "Волшебный щит, инкрустированный самоцветами, одним присутствием даёт чувство безопасности.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A magic shield inlaid with gemstones always provides a sense of security with its presence.", "Волшебный щит, инкрустированный самоцветами, одним присутствием даёт чувство безопасности.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nebula Storm", "Буря туманности", Language.Russian);
            MagnificusMod.RegisterCard("Nebula Storm", "Буря туманности", "This cruel storm can directly take away an enemy.", "Эта жестокая буря может сразу унести врага.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cruel storm can directly take away an enemy.", "Эта жестокая буря может сразу унести врага.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soul Contract", "Контракт души", Language.Russian);
            MagnificusMod.RegisterCard("Soul Contract", "Контракт души", "Perhaps you need more card assistance, and a soul contract is a great choice.", "Возможно, тебе нужна дополнительная помощь карт. Договор души — отличный выбор.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you need more card assistance, and a soul contract is a great choice.", "Возможно, тебе нужна дополнительная помощь карт. Договор души — отличный выбор.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wailing Wall", "Стена плача", Language.Russian);
            MagnificusMod.RegisterCard("Wailing Wall", "Стена плача", "Such perseverance even moves the thorny walls to weep.", "Такое упорство тронет до слёз даже терновые стены.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such perseverance even moves the thorny walls to weep.", "Такое упорство тронет до слёз даже терновые стены.", Language.Russian);
            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coffee Time", "Время кофе", Language.Russian);
            MagnificusMod.RegisterAbility("Coffee Time", "Время кофе");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] receives the first damage, it gains 2 strength.", "Когда [creature] впервые получает урон, получает 2 силы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Arrogance", "Смерть гордыни", Language.Russian);
            MagnificusMod.RegisterAbility("Death of Arrogance", "Смерть гордыни");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 2 power.", "Когда [creature] погибает, соседние карты получают 2 силы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death of Greed", "Смерть жадности", Language.Russian);
            MagnificusMod.RegisterAbility("Death of Greed", "Смерть жадности");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 3 health.", "Когда [creature] погибает, соседние карты получают 3 здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "God Made", "Божье творение", Language.Russian);
            MagnificusMod.RegisterAbility("God Made", "Божье творение");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, a Homunculus is created on each empty adjacent space. The Homunculus has : 1 power, 1 health, Familiar.", "Когда [creature] разыгрывается, на каждой соседней пустой клетке создаётся гомункул. У гомункула: 1 сила, 1 здоровье, Фамильяр.", Language.Russian);
            MagnificusMod.RegisterAbility("Fir Caller", "Призыватель пихт");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, the empty slot on the cardholder's side is filled with Great Firs. Great Fir has: 0 Power, 3 Health, Mighty Leap.", "Когда [creature] погибает, пустые клетки на стороне владельца заполняются большими пихтами. У большой пихты: 0 силы, 3 здоровья, Мощный прыжок.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lingering Taste", "Послевкусие", Language.Russian);
            MagnificusMod.RegisterAbility("Lingering Taste", "Послевкусие");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, adjacent cards gain 1 health.", "Когда [creature] погибает, соседние карты получают 1 здоровье.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love of Cheese", "Любовь к сыру", Language.Russian);
            MagnificusMod.RegisterAbility("Love of Cheese", "Любовь к сыру");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, draw a cheese card, cheese has: 0 power, 2 health,Lingering Taste.", "Когда [creature] разыгрывается, возьми карту сыра. У сыра: 0 силы, 2 здоровья, Послевкусие.", Language.Russian);
            // Other
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Expansion", "Волшебное дополнение", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here comes the card of the fantasy world! More content will be added in the future!", "Вот и карты из мира фантазий! В будущем появится больше материалов!", Language.Russian);
        }
    }
    public class NevernamedsSigilariumMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for NevernamedsSigilarium Mod");
            // Consumable
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NevernamedsSigils", "Символы Nevernamed", Language.Russian);
