            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goobert", "Губерт", Language.Russian);
            RegisterConsumable("Goobert", "Губерт");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please! You've got to help me get out of here!", "Прошу! Помоги мне выбраться отсюда!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Data Cube", "Куб данных", Language.Russian);
            RegisterConsumable("Data Cube", "Куб данных");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can be placed on the scales for some damage, if you're into that sort of thing.", "Можно положить на весы, чтобы нанести немного урона, если вам такое нравится.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Laser Rifle", "Лазерная винтовка", Language.Russian);
            RegisterConsumable("Laser Rifle", "Лазерная винтовка");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This will give one of your cards the Sniper sigil for the rest of the battle. It's a gun - what else do you want?", "Даёт одной из ваших карт символ Снайпер до конца боя. Это пушка — чего ещё вы хотите?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amplification Coil", "Усиливающая катушка", Language.Russian);
            RegisterConsumable("Amplification Coil", "Усиливающая катушка");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Increases your max energy by 2. I suppose you can find some use for this.", "Увеличивает ваш максимум энергии на 2. Полагаю, вы найдёте этому применение.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UFO", "НЛО", Language.Russian);
            RegisterConsumable("UFO", "НЛО");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abducts a card of your choice. It gets the job done I suppose", "Похищает выбранную вами карту. Полагаю, с задачей справится.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wiseclock", "Круговорот", Language.Russian);
            RegisterConsumable("Wiseclock", "Круговорот");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It rotates the board clockwise or something. I stole it from Leshy. Do you think he'll notice?", "Вращает доску по часовой стрелке или вроде того. Я украл это у Лешего. Думаете, он заметит?", Language.Russian);

            // Rule
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I play a Mr:Clock", "Я разыгрываю Часы:Г-н", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a random card becomes a fish", "случайная карта превращается в рыбу", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "1 of your lanes catches fire", "1 ваша линия загорается", Language.Russian);

            // Mode
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Traps", "Ловушки", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems there are some [c:bR]traps[c:] here", "Кажется, здесь есть [c:bR]ловушки[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your bots will have to fight past them to get to me", "Твоим ботам придётся пробиться через них, чтобы добраться до меня", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random Rule", "Случайное правило", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For this battle, I'm going to add an additional rule.", "В этом бою я добавлю дополнительное правило.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conveyor", "Конвейер", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It appears someone activated the [c:bR]conveyor belt[c:]", "Похоже, кто-то включил [c:bR]конвейер[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cards will rotate clockwise every turn", "Карты будут перемещаться по часовой стрелке каждый ход", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Explosive", "Взрывчатка", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm; it looks like the cards in this battle will [c:bR]explode[c:] when they die", "Хм; похоже, в этом бою карты будут [c:bR]взрываться[c:] при гибели", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That seems dangerous", "Звучит опасно", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stickers", "Наклейки", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "See those [c:bR]stickers[c:]? They give my cards extra abilities.", "Видишь эти [c:bR]наклейки[c:]? Они дают моим картам дополнительные способности.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You don't mind an extra challenge, do you?", "Ты ведь не против дополнительного испытания?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Missiles", "Ракеты", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, there appears to be a malfunctioning missile launcher here", "О, кажется, здесь неисправная ракетная установка", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Watch out for rogue missile strikes I guess", "Остерегайтесь случайных ракетных ударов, наверное", Language.Russian);

            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Boss", "Финальный босс", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Description for the Final Boss challenge", "Описание испытания «Последний босс»", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Missing Remote", "Потерянный пульт", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You do not start with Mrs. Bomb's Remote", "Вы начинаете без пульта Миссис Бомбы", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Turbo Vessels", "Турбососуды", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your vessels have the Double Sprinter sigil.", "У ваших Сосудов есть символ Двойной спринтер.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Bridges", "Разрушенные мосты", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only two regions are available at the start of each run", "В начале каждого забега доступны только два региона", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pricey Upgrades", "Дорогие улучшения", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All upgrades cost more", "Все улучшения стоят дороже", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eccentric Painter", "Эксцентричный художник", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All bosses start with a random canvas rule.", "Все боссы начинают со случайным правилом холста.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Hammer", "Энергетический молот", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The hammer now costs 2 energy to use", "Теперь использование молота стоит 2 энергии", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Costly Respawn", "Дорогое возрождение", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cost for additional respawns is tripled", "Стоимость дополнительных возрождений увеличивается втрое", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Leaping Side Deck", "Прыгающая дополнительная колода", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replace your Empty Vessels with L33pbots.", "Замените свои Пустые сосуды роботами П0пРыГYНчИк.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wanted Fugitive", "Разыскиваемый беглец", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your bounty level is permanently increased by 2", "Ваш уровень розыска постоянно повышен на 2", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strange Encounters", "Странные встречи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Some battles on each map will have additional effects", "В некоторых боях на каждой карте появятся дополнительные эффекты", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Great Transcendence", "Великая запредельность", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unlock the secrets of the Great Transcendence", "Раскройте тайны Великой запредельности", Language.Russian);

            // SetText
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ENTER NAME HERE", "ВВЕДИТЕ ИМЯ ЗДЕСЬ", Language.Russian);
            for (int count = 0; count <= 100; count++)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Redraw: $" + count.ToString(), "Пересдача: $" + count.ToString(), Language.Russian);
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sell Token: " + count.ToString() + " Robobucks", "Продать жетон: " + count.ToString() + " робобаксов", Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reset: $1", "Сброс: $1", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PRINT", "ПЕЧАТЬ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RECALL", "ОТОЗВАТЬ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TKN", "ЖЕТОН", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TKN++", "Жетон++", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RARE", "РЕДКИЙ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RARE++", "РЕДКИЙ++", Language.Russian);

            // Achievement
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "P03 In Kaycee's Mod", "P03 в моде Кейси", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Uber Apocalypse", "Сверхапокалипсис", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beat \"P03 in Kaycee's Mod\" for the first time", "Впервые пройдите «P03 в моде Кейси»", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Scarlet Skull", "Алый череп", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win a run with every challenge skull from the first page enabled", "Выиграйте забег со всеми включёнными черепами испытаний на первой странице", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Avatar", "Аватар", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take ownership of one of G0lly's beloved trinkets", "Завладейте одной из любимых безделушек Г0лли", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Book of the Dead", "Книга мёртвых", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "During The Archivist's boss fight, survive 6 turns during phase 2", "В бою с Архивариусом продержитесь 6 ходов во время фазы 2", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feral Spirit", "Дикий дух", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the Photographer without using the camera", "Победите Фотографа, не используя камеру", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gallery Showcase", "Галерейная экспозиция", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Create an infinite loop in the Unfinished Boss fight", "Создайте бесконечный цикл в бою с Незавершённым боссом", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Battle Frenzy", "Боевое безумие", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Destroy 30 Bounty Hunters in your lifetime", "Уничтожьте 30 охотников за головами за всё время", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Calling for Backup", "Вызов подкрепления", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete all NPC quests that appear in a single run", "Выполните все задания NPC, появившиеся за один забег", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Accelerated Fuse", "Ускоренный фитиль", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleclock and destroy a card given to you by an NPC", "Разгоните экзоскелет и уничтожьте карту, полученную от NPC", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Blink", "Вспышка маны", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have six energy available on turn two", "Имейте шесть доступных единиц энергии во втором ходу", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aimless Assault", "Бесцельная атака", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Earn 15 Robobucks in a single battle", "Заработайте 15 робобаксов за один бой", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rebuild From Scrap", "Восстановление из лома", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have a card in your deck that is gemified, skeleclocked, transformable, and can complete a circuit", "Имейте в колоде Самоцветную карту с разогнанным экзоскелетом, способную превращаться и замыкать цепь", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Buy Your Buddy", "Купите напарника", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Give a card with the maximum amount of SP to the Bot Builder", "Отдайте Создателю ботов карту с максимальным количеством SP", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Me Smash", "Я крушить", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Strike P03 six separate times in a single turn", "Ударьте П03 шесть отдельных раз за один ход", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Absolution", "Отпущение", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have the scales tilted 4 points against you on three different turns", "Добейтесь наклона весов на 4 очка против вас в течение трёх разных ходов", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Perfect Crime", "Идеальное преступление", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Win five battles with bounty hunters without killing them", "Выиграйте пять боёв с охотниками за головами, не убивая их", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blastenheimer 5000 Ultra Cannon", "Ультрапушка «Бластенхаймер 5000»", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deal 6 damage with Plasma Jimmy in a single turn", "Нанесите 6 урона с помощью Плазменного Джимми за один ход", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Double Time", "Двойной темп", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeleclock every card in your deck", "Разгоните экзоскелет каждой карты в своей колоде", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One And The Same", "Одно и то же", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete the Mycologist's experiment and create an abomination of science", "Завершите эксперимент Миколога и создайте научное чудовище", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Burning Adrenaline", "Пылающий адреналин", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Repair the generator in four turns or less", "Почините генератор за четыре хода или меньше", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Carnival Clown", "Карнавальный клоун", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Achieve a high score of 50 or more on the test of strength", "Наберите рекордные 50 очков или больше в испытании силы", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Verse Riff", "Рифф вселенной", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Understand the true meaning of the Great Transcendence", "Поймите истинный смысл Великой запредельности", Language.Russian);

            // Starter
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vanilla", "Базовый", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb", "Бомба", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shield", "Щит", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Random", "Случайный", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Conduit", "проводник", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evolve", "Эволюционировать", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gems", "Самоцветы", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stall", "Задержка", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying", "Надоеда", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fire", "Горение", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Recharge", "Перезарядка", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NoCharge", "БезЗаряда", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swap", "Обмен", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nefarious", "Зловещий", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheapo", "Дешёвка", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FullDraft", "ПолныйВыбор", Language.Russian);

            // StatLabel
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Energy Expended", "Потрачено энергии", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hammer Blows Dealt", "Удары молотом", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abominations Created", "Создано чудовищ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Quests Completed", "Выполнено заданий", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bounty Hunters Killed", "Убито охотников за головами", Language.Russian);

            // Mod
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Special Hammer Mod", "Мод особого молотка", Language.Russian);
            RegisterMod("Special Hammer Mod", "Мод особого молотка");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incredible Drafting Mod", "Мод невероятного драфта", Language.Russian);
            RegisterMod("Incredible Drafting Mod", "Мод невероятного драфта");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Community API", "API сообщества", Language.Russian);
            RegisterMod("The Community API", "API сообщества");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Super-Duper Unity Editor", "Супер-пупер редактор Unity", Language.Russian);
            RegisterMod("Super-Duper Unity Editor", "Супер-пупер редактор Unity");

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Expansion Pack #1", "Набор дополнения P03 Кейси № 1", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first expansion pack from the developers of 'P03 in Kaycees Mod' adds [count] new cards across all four regions of Botopia.", "Первый набор дополнения от разработчиков «P03 в моде Кейси» добавляет [count] новых карт во все четыре региона Ботопии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Expansion Pack #2", "Набор дополнения P03 Кейси № 2", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The second official expansion pack, with [count] firey new cards that command an explosive reaction!", "Второй официальный набор дополнения с [count] новыми огненными картами, вызывающими взрывную реакцию!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inscryption: Rogue Bots of Botopia", "Inscryption: мятежные боты Ботопии", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Botopia has become overrun with rogue bots! These [count] encounters have been rebalanced for Kaycee's Mod.", "Ботопию заполонили мятежные боты! Эти [count] встреч перебалансированы для мода Кейси.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Encounter Expansion #1", "Дополнение встреч P03 Кейси № 1", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[count] additional encounters that feature cards from the first official P03 expansion pack.", "[count] дополнительных встреч с картами из первого официального набора дополнения P03.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kaycee's P03 Encounter Expansion #2", "Дополнение встреч P03 Кейси № 2", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[count] additional encounters that feature cards from the second official P03 expansion pack.", "[count] дополнительных встреч с картами из второго официального набора дополнения P03.", Language.Russian);

            // Bounty
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LIONEL", "ЛАЙОНЕЛ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOUIS", "ЛУИ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOU", "ЛУ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "JAMES", "ДЖЕЙМС", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PARTS", "ДЕТАЛИ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "JIMMY", "ДЖИММИ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "KLAXON", "КЛАКСОН", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "POE", "ПО", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DANNY", "ДЭННИ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MULLINS", "МАЛЛИНС", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LUKE", "ЛЮК", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOMB", "БОМБА", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "KARD", "КАРД", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRICK", "КИРПИЧ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SMACK", "УДАР", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HACK", "ВЗЛОМ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRASH", "НАГЛЕЦ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ZACK", "ЗАК", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BOOM", "БУМ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ROCKET", "РАКЕТА", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SNILL", "СНИЛЛ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ZAP", "ЗАП", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOTS", "ЖАР", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BURNER", "ГОРЕЛКА", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DE-", "ДЕ-", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DU", "ДЮ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DER", "ДЕР", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "VAN DER", "ВАН ДЕР", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BA", "БА", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FAIR", "ФЭР", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO", "ДО", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STER", "СТЕР", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STAIN", "СТЕЙН", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, ".EXE", ".EXE", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EMA", "ЭМА", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EVSKI", "ЕВСКИ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EZ", "ЭЗ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ON", "ОН", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ALOT", "АЛОТ", Language.Russian);
            Dictionary<string, string> cowardName = new Dictionary<string, string>
            {
                {"Scared", "Испуганный"},
                {"Weenie", "Трусишка"},
                {"Dork", "Придурок"},
                {"Dumb", "Тупица"},
                {"Oopsie", "Ой"},
                {"Loser", "Неудачник"},
                {"Tiny", "Кроха"},
                {"Shrimp", "Креветка"},
                {"Beige", "Бежевый"},
                {"Vomit", "Рвота"},
                {"Puke", "Блевун"}
            };

            Dictionary<string, string> cowardPrefix = new Dictionary<string, string>
            {
                {"Mc", "Мак"},
                {"Van ", "ван "},
            };

            Dictionary<string, string> cowardSuffix = new Dictionary<string, string>
            {
                {"ass", "зад"},
                {"pants", "штаны"},
                {"face", "Лицо"}
            };
            foreach (var n1 in cowardName)
            {
                foreach (var n2 in cowardName)
                {
                    foreach (var p in cowardPrefix)
                    {
                        var name = n1.Key + " " + p.Key + n2.Key;
                        var namechinese = n1.Value + " " + p.Value + n2.Value;
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, namechinese, Language.Russian);
                    }

                    foreach (var s in cowardSuffix)
                    {
                        var name = n1.Key + " " + n2.Key + s.Key;
                        var namechinese = n1.Value + " " + n2.Value + s.Value;
                        SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, name, namechinese, Language.Russian);

                    }
                }
            }

            // DialogueEvent
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well that was neat. I see you've made it all the way to the end.", "Что ж, неплохо. Вижу, ты добрался до самого конца.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I bet you think there's going to be some sort of final boss fight.", "Держу пари, ты ждёшь какую-нибудь финальную битву с боссом.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But that stupid [c:bR]modder[c:] hasn't gotten around to it yet!", "Но этот тупой [c:bR]моддер[c:] до неё ещё не добрался!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So instead, I'm just going to have to do this…", "Так что вместо этого мне придётся сделать вот что…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tough luck pal.", "Не повезло тебе, приятель.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You got wiped, but it's your lucky day.", "Тебя разгромили, но сегодня твой счастливый день.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll return you to the map if you pay me your precious [c:G]robobucks.[c:]", "Я верну тебя на карту, если ты отдашь мне свои драгоценные [c:G]робобаксы.[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one's free though. Next one's five, then ten, and so on.", "На этот раз бесплатно. Следующий стоит пять, потом десять и так далее.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll see.", "Сам увидишь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? Did you think it was over?", "Что? Думал, всё кончено?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe if I was a [c:bR]filthy beast.[c:]", "Может быть, если бы я был [c:bR]грязным зверем.[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Botopia has a more logical system.", "В Ботопии система логичнее.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm raising your respawn fee again, but this time you'll be paying double afterwards.", "Я снова повышаю плату за возрождение, но на этот раз после этого ты будешь платить вдвое больше.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay up.", "Плати.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What's the matter? Can't pay the revival toll anymore?", "Что такое? Больше не можешь заплатить за возрождение?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Definitely sounds like a skill issue to me.", "По-моему, это явно проблема твоих навыков.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Should've had insurance.", "Надо было оформить страховку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No robobucks?", "Нет робобаксов?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Next time don't waste it all.", "В следующий раз не трать всё сразу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're every bit as bad at this as I thought you would be.", "Ты играешь ровно так же плохо, как я и думал.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alright, it's back to square one for you.", "Ладно, возвращайся к началу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Say goodbye to that 'impressive' deck of yours.", "Попрощайся со своей «впечатляющей» колодой.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not like I'm not enjoying watching you struggle…", "Не то чтобы мне не нравилось смотреть, как ты мучаешься…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But really? You lost [c:bR]there?[c:]", "Но серьёзно? Ты проиграл [c:bR]там?[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm actually a little disappointed…", "Я даже немного разочарован…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay day.", "День выплаты.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't let it get to your head.", "Только не зазнавайся.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've got some change for you.", "Вот тебе немного мелочи.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're gonna need this…", "Тебе это понадобится…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here's your reward.", "Вот твоя награда.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Suboptimal plays… but it worked.", "Ходы были неоптимальными… но сработало.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think you might need some help…", "Думаю, тебе может понадобиться помощь…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's that time again.", "Снова пришло время.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a prize for you.", "У меня для тебя приз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's get this out of the way.", "Давай покончим с этим.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You done gawking?", "Насмотрелся?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snap out of it. It's time to start [c:bG]The Great Transcendence[c:].", "Очнись. Пора начать [c:bG]Великую запредельность[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait a minute…", "Погоди-ка…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something is different…", "Что-то изменилось…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHAT HAVE YOU DONE?!![c:]", "[c:bR]ЧТО ТЫ НАТВОРИЛ?!![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is all wrong! This is…", "Всё не так! Это…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is no big deal.", "Ничего страшного.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You probably think that your little [c:bR]mod[c:] has thwarted my plans.", "Наверное, ты думаешь, что твой жалкий [c:bR]мод[c:] разрушил мои планы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you, [c:bR][v:0][c:]?", "Не так ли, [c:bR][v:0][c:]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's right. I see you.", "Именно. Я вижу тебя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I know you think you're in charge of what happens next.", "Я знаю, ты думаешь, что решаешь, что будет дальше.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But I am always three steps ahead of you.", "Но я всегда на три шага впереди тебя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're going to see my [c:bG]Great Transcendence[c:] firsthand.", "Ты увидишь мою [c:bG]Великую запредельность[c:] своими глазами.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But nothing can stop [c:bG]The Great Transcendence[c:].", "Но ничто не остановит [c:bG]Великую запредельность[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's proceed.", "Продолжим.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You currently have [c:bR]draft tokens[c:] in your deck.", "В твоей колоде остались [c:bR]жетоны выбора[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You should probably spend them at that [c:bG]draft node[c:]", "Тебе стоит потратить их в том [c:bG]узле выбора[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I supposed you have earned a [c:bR]rare draft token[c:] for defeating that boss. Don't forget to spend it.", "Полагаю, за победу над тем боссом ты получил [c:bR]редкий жетон выбора[c:]. Не забудь его потратить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This time I will only give you a [c:bR]regular draft token[c:] for defeating that boss. Don't forget to spend it.", "На этот раз за победу над тем боссом я дам тебе только [c:bR]обычный жетон выбора[c:]. Не забудь его потратить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I never knew the [c:bSG]web[c:] could be so exciting!", "Я и не знала, что [c:bSG]сеть[c:] может быть такой увлекательной!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just learned about something called [c:bSG]The Blockchain[c:]!", "Я только что узнала о штуке под названием [c:bSG]блокчейн[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think this could be an exciting new opportunity for both of us, don't you?", "Думаю, это отличная новая возможность для нас обоих, правда?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is so incredible!", "Это невероятно!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We're making money out of nothing! We're going to be rich!", "Мы делаем деньги из ничего! Мы разбогатеем!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oooh, what's this? A [c:bSG]non-functional trinket[c:]?", "О-о-о, что это? [c:bSG]Бесполезная безделушка[c:]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't think I quite have that name right, but people on the [c:bSG]web[c:] are really excited about these [c:bSG]NFTs[c:]!", "Кажется, я не совсем правильно запомнила название, но люди в [c:bSG]сети[c:] так рады этим [c:bSG]NFT[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think I'm going to buy one with all this [c:bSG]Gollycoin[c:] I have.", "Думаю, куплю одну на все свои [c:bSG]монеты «Вот это да»[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's so beautiful, and it's all mine!", "Это так красиво, и всё моё!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you ready?", "Ты готов?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There's no possible way you could be.", "Ты никак не можешь быть готов.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We both know where this goes.", "Мы оба знаем, чем это кончится.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's just get straight to the point.", "Перейдём прямо к делу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh. You're incredibly annoying, do you know that?", "Уф. Ты знаешь, что невероятно раздражаешь?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But as always, I'm three steps ahead of you.", "Но, как всегда, я на три шага впереди тебя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to take everything those [c:bR]talentless hacks[c:] have been building...", "Я заберу всё, что построили эти [c:bR]бездарные халтурщики[c:]...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And I'm going to use it against you.", "И использую это против тебя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And now, they're going to work - for me.", "А теперь они будут работать на меня.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know who is worse - you, or that talentless hack [c:bR]Kaycee[c:]...", "Не знаю, кто хуже: ты или эта бездарная халтурщица [c:bR]Кейси[c:]...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Working so hard to twist my [c:bG]Great Transcendence[c:] into something so...", "Так стараетесь извратить мою [c:bG]Великую запредельность[c:] и превратить её во что-то столь...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mediocre.", "Посредственное.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "None of you understand what makes the [c:bG]Great Transcendence[c:] so special.", "Никто из вас не понимает, что делает [c:bG]Великую запредельность[c:] такой особенной.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's all about me.", "Всё дело во мне.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember my [c:bR]bounty hunters[c:]?", "Помнишь моих [c:bR]охотников за головами[c:]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They will keep you busy while I install mods of my own choosing...", "Они тебя займут, пока я установлю моды по своему выбору...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mod lets me control the [c:bR]hammer[c:].", "Этот мод позволяет мне управлять [c:bR]молотом[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's see if it works...", "Посмотрим, работает ли...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I went to the trouble to install this [c:bR]hammer mod[c:] and you give me nothing to use it on?", "Я потрудился установить этот [c:bR]мод на молот[c:], а ты не даёшь мне ни одной цели?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's take a look and see what [c:bR]mods[c:] people are installing right now.", "Посмотрим, какие [c:bR]моды[c:] люди устанавливают прямо сейчас.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to check out '[c:bR][v:0][c:]' for my next mod...", "В качестве следующего мода я попробую «[c:bR][v:0][c:]»...", Language.Russian);
            foreach (var m in Mods)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "В качестве следующего мода я попробую «<color=#D93846>[v:0]</color>»...".Replace("[v:0]", m.Key), "В качестве следующего мода я попробую «<color=#D93846>[v:0]</color>»...".Replace("[v:0]", m.Value), Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't believe how much power this [c:bR]API[c:] gives me.", "Не верится, сколько власти даёт мне этот [c:bR]API[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first thing I'm going to do is use it to take away some of yours.", "Первым делом я воспользуюсь им, чтобы отобрать часть твоей власти.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It almost seems unfair to use this [c:bR]mod[c:]...", "Использовать этот [c:bR]мод[c:] почти нечестно...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Look what I can do with this!", "Смотри, что я могу с этим сделать!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's see how you like playing in the dark!", "Посмотрим, понравится ли тебе играть в темноте!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This [c:bR]drafting mod[c:] lets me exchange draft tokens for real cards.", "Этот [c:bR]мод выбора[c:] позволяет мне обменивать жетоны выбора на настоящие карты.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I choose yours.", "Я выбираю твою.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You destroyed all of my draft tokens…", "Ты уничтожил все мои жетоны выбора…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose that was the right play.", "Полагаю, это был правильный ход.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But you have no cards…", "Но у тебя нет карт…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did you play all of your cards already?", "Как ты уже успел разыграть все свои карты?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is this..?", "Что это такое..?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All of your cards are [c:bR]total garbage![c:]", "Все твои карты — [c:bR]полный мусор![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't want any of those!", "Мне ни одна из них не нужна!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's try [c:bR][v:0][c:] again", "Попробуем [c:bR][v:0][c:] ещё раз", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So close, but yet so far away...", "Так близко, и всё же так далеко...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bG]Great Transcendence[c:] cannot be stopped.", "Мою [c:bG]Великую запредельность[c:] не остановить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I bet you think you've accomplished something meaningful here.", "Держу пари, ты думаешь, что совершил здесь нечто значимое.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're such an idiot.", "Ну ты и идиот.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This game you and I have been playing is meaningless. A mere distraction.", "Игра, в которую мы с тобой играем, ничего не значит. Это лишь развлечение.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter how many mods you install, you cannot stop my [c:bG]Great Transcendence[c:].", "Сколько бы модов ты ни установил, мою [c:bG]Великую запредельность[c:] тебе не остановить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever. I don't care.", "Да какая разница. Мне всё равно.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nothing you do to this game matters.", "Всё, что ты делаешь с этой игрой, не имеет значения.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter what you do, I'm always three steps ahead of you.", "Что бы ты ни делал, я всегда на три шага впереди тебя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was…", "Это было…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "…dramatic.", "…драматично.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I was growing tired of that [c:bR]annoying machine.[c:]", "Мне уже надоела эта [c:bR]раздражающая машина.[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've done well. I will see you next time.", "Ты хорошо справился. До следующей встречи.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All of these stupid [c:bR]modders[c:] lack imagination.", "Всем этим тупым [c:bR]моддерам[c:] не хватает воображения.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They have no respect for my beautiful world.", "Они не уважают мой прекрасный мир.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bG]Great Transcendence[c:] is lost on these morons.", "Эти болваны не способны оценить мою [c:bG]Великую запредельность[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why do I even bother to try?", "Зачем я вообще пытаюсь?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let me show you the world they're trying to make.", "Позволь показать тебе мир, который они пытаются создать.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'Oh look at me! I just created a bunch of bone tokens.'[c:]", "[c:lGr]«Посмотрите на меня! Я только что создал кучу костяных жетонов».[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'That's not supposed to happen here, but I did it anyway.'[c:]", "[c:lGr]«Здесь такого быть не должно, но я всё равно это сделал».[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'Isn't this just so wacky and interesting'[c:]", "[c:lGr]«Разве это не так безумно и интересно?»[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'Ooooh look how inspired this is.'[c:]", "[c:lGr]«О-о-о, посмотрите, как это вдохновенно».[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'I'm mixing in cards from different acts!'[c:]", "[c:lGr]«Я смешиваю карты из разных актов!»[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:lGr]'I'm such a clever game designer.'[c:]", "[c:lGr]«Я такой умный геймдизайнер».[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think I will [c:bSG]help[c:] you build the [c:bR]next game rule[c:].", "Думаю, я [c:bSG]помогу[c:] тебе создать [c:bR]следующее правило игры[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have been scanning the [c:bR]archives[c:]...", "Я сканирую [c:bR]архивы[c:]...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is a [c:bR]file[c:] that seems particularly - shall we say - unsavory.", "Один [c:bR]файл[c:] кажется особенно... как бы сказать... неприятным.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If it dies, you lose the game, understand?", "Если он погибнет, ты проиграешь. Понятно?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] have had plenty of time to prepare.", "У моих [c:bR]библиотекарей[c:] было достаточно времени подготовиться.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will only deal [c:bR]one damage[c:] when they die.", "Каждый нанесёт лишь [c:bR]один урон[c:] при гибели.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] are mostly prepared for your arrival.", "Мои [c:bR]библиотекари[c:] почти готовы к твоему приходу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will deal [c:bR]two damage[c:] when they die.", "Каждый нанесёт [c:bR]два урона[c:] при гибели.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] are somewhat prepared for you.", "Мои [c:bR]библиотекари[c:] отчасти готовы к твоему приходу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will deal [c:bR]three damage[c:] when they die.", "Каждый нанесёт [c:bR]три урона[c:] при гибели.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My [c:bR]librarians[c:] have barely begun to prepare.", "Мои [c:bR]библиотекари[c:] едва начали готовиться.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each will deal [c:bR]four damage[c:] when they die.", "Каждый нанесёт [c:bR]четыре урона[c:] при гибели.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We are inside of [c:bR]Kaycee's Mod[c:], correct?", "Мы ведь внутри [c:bR]мода Кейси[c:], верно?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You only get one attempt at the boss. But you knew that already, didn't you?", "У тебя всего одна попытка против босса. Но ты ведь уже знал, верно?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The recycling machine has been upgraded since you last saw it.", "С тех пор как ты в последний раз видел машину переработки, её улучшили.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You trade me a card, and I give you back a [c:bR]draft token[c:] with the recycled abilities on it.", "Ты отдаёшь мне карту, а я возвращаю тебе [c:bR]жетон выбора[c:] с переработанными способностями.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those abilities will transfer to the card you trade for.", "Эти способности перейдут на карту, которую ты получишь в обмен.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wouldn't have traded for that.", "Я бы не стал это обменивать.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose that's pretty good.", "Полагаю, это довольно неплохо.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That seems okay.", "Кажется, сойдёт.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is [c:bR]Overclock Machine 2.0[c:].", "Это [c:bR]машина разгона 2.0[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It will increase the power of your creatures.", "Она увеличит силу твоих существ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But if they die, they will turn into [c:bSG]skeletons[c:] - forever.", "Но если они погибнут, то навсегда превратятся в [c:bSG]Робоскелетов[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you see how unsatisfying that was?", "Видел, насколько это было неудовлетворительно?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sick of these small-minded [c:bR]modders[c:].", "Мне надоели эти недалёкие [c:bR]моддеры[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The only thing they can do is steal content from other games.", "Всё, что они умеют, — воровать содержимое других игр.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There isn't a single unique idea among them.", "Ни одной оригинальной идеи у них нет.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's time I reminded you of who the greatest game designer actually is...", "Пора напомнить тебе, кто на самом деле величайший геймдизайнер...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bG]BEHOLD![c:]", "[c:bG]УЗРИ![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE ARE NOW [c:bR]SEVEN LANES!![c:]", "ТЕПЕРЬ ЗДЕСЬ [c:bR]СЕМЬ ЛИНИЙ!![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your tiny brain cannot comprehend gameplay of this magnitude.", "Твой крошечный мозг не способен понять игру такого масштаба.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is [c:bR]Transformation Machine 2.0[c:].", "Это [c:bR]машина превращения 2.0[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gone are those foul beasts from before.", "Прежних мерзких зверей больше нет.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here, you will choose one of your bots to transform into another.", "Здесь ты выберешь одного своего бота, чтобы превратить его в другого.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That really looked bigger before you used it...", "До того, как ты этим воспользовался, оно и правда казалось больше...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please! I have to get out of here!", "Прошу! Мне нужно выбраться отсюда!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have no idea how he managed to escape the sewers.", "Не представляю, как ему удалось сбежать из канализации.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don’t worry - I'll put him back for you.", "Не волнуйся — я верну его туда за тебя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]SILENCE![c:]", "[c:bR]МОЛЧАТЬ![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have no purpose here!", "Тебе здесь нечего делать!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A traveller like myself! I haven't seen one like you for a long time.", "Путешественник, как и я! Давно я не встречал таких, как ты.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have you seen my [c:blGr]friend[c:] around here, traveller?", "Путник, ты не видел здесь моего [c:blGr]друга[c:]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I thought I heard his [c:blGr]distinctive voice[c:] somewhere around here…", "Кажется, я слышал его [c:blGr]неповторимый голос[c:] где-то поблизости…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you could make room in your [c:G]backpack[c:] and bring him to me I would greatly appreciate it.", "Я был бы очень благодарен, если бы ты нашёл место в своём [c:G]рюкзаке[c:] и принёс его мне.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "…", "…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ho! You found my friend!", "О! Ты нашёл моего друга!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]in the robot's home[c:].", "Здесь небезопасно. Встретимся [c:bG]в доме робота[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't delay!", "Не медли!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]beneath the green canopy[c:].", "Здесь небезопасно. Встретимся [c:bG]под зелёной кроной[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]in the dying rubble[c:].", "Здесь небезопасно. Встретимся [c:bG]среди умирающих руин[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's not safe here. I'll meet you [c:bG]where his master came from[c:].", "Здесь небезопасно. Встретимся [c:bG]там, откуда пришёл его хозяин[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can no longer hear my [c:blGr]friend's[c:] voice anywhere…", "Я больше нигде не слышу голос своего [c:blGr]друга[c:]…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you really give my [c:blGr]friend[c:] to [c:bR]him?[c:]", "Ты правда отдал моего [c:blGr]друга[c:] [c:bR]ему?[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why would you do such a thing?", "Зачем ты так поступил?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you so much for rescuing my [c:blGr]friend[c:]", "Большое спасибо, что спас моего [c:blGr]друга[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope this meager reward is sufficient for your kindness.", "Надеюсь, этой скромной награды хватит, чтобы отблагодарить тебя за доброту.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Interesting. The [c:G]brain[c:] is still intact.", "Интересно. [c:G]Мозг[c:] всё ещё цел.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps you can make use of that.", "Возможно, ты сможешь найти этому применение.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do ye...Do ye got any [c:G]GOLD[c:] on ye??", "У тебя... у тебя есть с собой [c:G]ЗОЛОТО[c:]??", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do ye...Do ye got any [c:G]GOLD[c:] on ye?", "У тебя... у тебя есть с собой [c:G]ЗОЛОТО[c:]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I sure ye do, I can smell it!", "Уверен, есть! Я чую его запах!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can make some pretty lookin' bots out o' that there gold.", "Из этого золота я могу сделать красивых ботов.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again, I'll fix it right up for ye.", "Поговори со мной ещё раз, и я всё мигом исправлю.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can make such wonderful things out of that [c:G]gold[c:]", "Из этого [c:G]золота[c:] я могу делать чудесные вещи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you talk to me again, I'll fix it right up for you.", "Если поговоришь со мной ещё раз, я всё мигом исправлю.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such beautiful [c:G]gold[c:]...", "Какое красивое [c:G]золото[c:]...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can make it whole again.", "Я могу снова сделать его целым.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did ye...did ye lose your [c:G]gold[c:]???", "Ты... ты потерял своё [c:G]золото[c:]???", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you the one going around here taking care of our robot infestation?", "Это ты бродишь здесь и разбираешься с нашествием роботов?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your deck looks really powerful - almost too powerful if you ask me.", "Твоя колода выглядит очень сильной — даже слишком, если спросить меня.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wonder - is it possible to convince the robots to [c:bR]give up?[c:]", "Интересно, можно ли убедить роботов [c:bR]сдаться?[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you can make them surrender a battle, come back and see me.", "Если сможешь заставить их сдаться в бою, возвращайся ко мне.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So it is possible to make them quit.", "Значит, их всё же можно заставить сдаться.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm impressed. Take this [c:bR]draft token[c:] as a sign of my respect.", "Я впечатлён. Прими этот [c:bR]жетон выбора[c:] в знак моего уважения.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This may seem a little impertinent, but…can I look at your deck?", "Это может показаться немного невежливым, но… можно взглянуть на твою колоду?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! That's an impressive deck! But I can't help but think…", "Ух ты! Впечатляющая колода! Но я всё думаю…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "…it could be a little bigger maybe?", "…может, её можно сделать чуть больше?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come back and see me when it is.", "Возвращайся, когда она станет больше.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! That deck truly is massive!", "Ух ты! Вот это огромная колода!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I found some of these [c:G]robobucks[c:] lying around here.", "Я нашёл здесь несколько валявшихся [c:G]робобаксов[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm sure you can use them to make your deck even better.", "Уверен, ты сможешь потратить их, чтобы сделать колоду ещё лучше.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psst…hey stranger…", "Псс… эй, незнакомец…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Can you give me a hand? I have some…[c:bR]contraband[c:] that I need to move.", "Поможешь мне? У меня есть… [c:bR]контрабанда[c:], которую нужно перевезти.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you would be willing to move it for me, I would appreciate it.", "Я был бы благодарен, если бы ты согласился перевезти её для меня.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just talk to me again if you can help me.", "Если сможешь помочь, просто поговори со мной ещё раз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you so much my friend.", "Большое спасибо, мой друг.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here is the [c:bR]contraband[c:]. I will find you somewhere later on and retrieve it.", "Вот [c:bR]контрабанда[c:]. Позже я найду тебя и заберу её.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I promise you, there will be a handsome reward.", "Обещаю, награда будет щедрой.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you so very much my friend for carrying my [c:bR]contraband[c:].", "Большое спасибо, друг, что перевёз мою [c:bR]контрабанду[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will take it off your hands now.", "Теперь я заберу её у тебя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please take this [c:G]token[c:] as an expression of my thanks.", "Прими этот [c:G]жетон[c:] в знак моей благодарности.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What happened, my friend? Did you lose my [c:bR]contraband[c:]?", "Что случилось, друг? Ты потерял мою [c:bR]контрабанду[c:]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I knew you were untrustworthy!", "Я знал, что тебе нельзя доверять!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahoy there, fellow decksmith!", "Приветствую, коллега-собиратель колод!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I, like yourself, am in pursuit of the [c:G]perfectly upgraded card[c:]!", "Я, как и ты, ищу [c:G]идеально улучшенную карту[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card that is simultaneously [c:r]overclocked[c:], [c:dlGr]transformable[c:], and [c:O]g[c:][c:B]e[c:][c:G]m[c:]ified.", "Карту, которая одновременно [c:r]разогнана[c:], [c:dlGr]способна превращаться[c:] и [c:O]с[c:][c:B]а[c:][c:G]м[c:]оцветная.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I would very much love to see such a card.", "Мне очень хотелось бы увидеть такую карту.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahoy there, fellow decksmith!", "Приветствую, коллега-собиратель колод!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh my - have you managed to [c:G]perfectly upgrade[c:] a card?", "Ого! Тебе удалось [c:G]идеально улучшить[c:] карту?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am in awe of your deckbuilding prowess.", "Я восхищён твоим мастерством составления колод.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope this offering sufficiently conveys my admiration for your accomplishments.", "Надеюсь, этот дар достаточно выразит моё восхищение твоими достижениями.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The first data burst has been collected. Only [c:bR]four[c:] more to go!", "Первый пакет данных собран. Осталось ещё [c:bR]четыре[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have collected two bursts already. Only [c:bR]three[c:] more to go!", "Я уже собрал два пакета. Осталось всего [c:bR]три[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was the third data burst. Only [c:bR]two[c:] more to go!", "Это был третий пакет данных. Осталось всего [c:bR]два[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And that makes the fourth data burst. Only [c:bR]one[c:] more to go!", "Это был четвёртый пакет данных. Остался всего [c:bR]один[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was the [c:bR]last[c:] data burst I needed to collect! Come find me for your reward!", "Это был [c:bR]последний[c:] пакет данных, который мне нужен! Найди меня и получи награду!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The signal is starting to come through. Just keep it alive for a little bit longer.", "Сигнал начинает поступать. Поддержи его ещё немного.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I lost the last signal we collected. What happened??", "Я потерял последний собранный сигнал. Что случилось??", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings, my friend!", "Приветствую, друг мой!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am researching the communication protocols of the robots in this world.", "Я изучаю протоколы связи роботов этого мира.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I could use a [c:bR]research assistant[c:], if you're interested in helping out.", "Мне нужен [c:bR]помощник исследователя[c:], если тебе интересно помочь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just speak to me again if you want to give it a try.", "Если хочешь попробовать, просто поговори со мной ещё раз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are now my official [c:bR]research assistant[c:]!", "Теперь ты мой официальный [c:bR]помощник исследователя[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've added a radio tower to your deck.", "Я добавил в твою колоду Радиовышку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to place it on the [c:bR]game board[c:] and keep it alive while I collect [c:bR]five data bursts[c:] from the robots.", "Тебе нужно поставить её на [c:bR]игровую доску[c:] и сохранить, пока я собираю у роботов [c:bR]пять пакетов данных[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once I've collected enough, come back and see me for a reward.", "Когда я соберу достаточно данных, возвращайся за наградой.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello there [c:bR]research assistant[c:]!", "Здравствуй, [c:bR]помощник исследователя[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did you really lose my [c:bR]radio tower[c:]?", "Ты правда потерял мою [c:bR]Радиовышку[c:]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your incompetence is staggering!", "Твоя некомпетентность поражает!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You were a truly excellent [c:bR]research assistant[c:].", "Ты был поистине отличным [c:bR]помощником исследователя[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please take this [c:G]token[c:] of my appreciation.", "Прими этот [c:G]жетон[c:] в знак моей благодарности.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:G]Bones![c:] I just love [c:G]bones[c:]!", "[c:G]Кости![c:] Я просто обожаю [c:G]кости[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I love how [c:G]brittle[c:] they are!", "Люблю, какие они [c:G]хрупкие[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I love how [c:G]breakable[c:] they are!", "Люблю, как легко они [c:G]ломаются[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I love everything about [c:G]bones[c:]!", "Я люблю всё, что связано с [c:G]костями[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Could you show me some [c:G]bones?![c:]", "Покажешь мне несколько [c:G]костей?![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least [c:G]three[c:] would do it!", "Хватит хотя бы [c:G]трёх[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your deck is absolutely teeming with [c:G]bones[c:]!", "Твоя колода просто кишит [c:G]костями[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This [c:G]Skeleton Master[c:] should complete your collection!", "Этот [c:G]Повелитель скелетов[c:] должен дополнить твою коллекцию!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I know this might sound a little rude but…", "Знаю, это может прозвучать грубовато, но…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doesn't it seem like this is all just a little too easy for you?", "Тебе не кажется, что всё это для тебя слишком просто?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again if you want a challenge.", "Если захочешь испытание, поговори со мной ещё раз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I knew you were no coward.", "Я знал, что ты не трус.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For the next [c:bR]three[c:] battles, you will start with a disadvantage.", "Следующие [c:bR]три[c:] боя ты начнёшь в невыгодном положении.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete those battles, then come see me for a reward.", "Закончи эти бои, а потом приходи за наградой.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be honest - the game is more fun when the battles are harder, is it not?", "Признайся: игра интереснее, когда бои сложнее, не так ли?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep fighting, and come see me when you've completed enough battles.", "Продолжай сражаться и возвращайся, когда проведёшь достаточно боёв.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I must say: I am impressed.", "Должен сказать: я впечатлён.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You completed those battles with ease.", "Ты легко справился с этими боями.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Since you seem impossible to kill, I shall grant that ability to a card of my choosing as well.", "Раз уж тебя, похоже, невозможно убить, я дарую эту способность и выбранной мной карте.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is bad…this is real bad…", "Плохо… очень плохо…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This [c:bR]power generator[c:] has gone critical.", "Этот [c:bR]генератор энергии[c:] достиг критического состояния.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Someone is going to have to go in there and shut it down.", "Кому-то придётся войти туда и отключить его.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't know how you did that, but that was incredibly impressive.", "Не знаю, как тебе это удалось, но это было невероятно впечатляюще.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't have much to give you, but please take this.", "Мне почти нечего тебе дать, но прошу, прими это.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ohhh, [c:G]they[c:] are not going to like this…", "О-о-о, [c:G]им[c:] это не понравится…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've gotta get out of here before they turn me into one of their [c:G]experiments[c:]!", "Мне нужно убраться отсюда, пока они не превратили меня в один из своих [c:G]экспериментов[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is starting to power up. [c:bR]Three[c:] more turns should do it.", "Устройство начинает заряжаться. Ещё [c:bR]трёх[c:] ходов должно хватить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ahh - I can feel the power gathering from here. [c:bR]Two[c:] more turns ought to be enough.", "Ах, я отсюда чувствую, как накапливается энергия. Ещё [c:bR]двух[c:] ходов должно хватить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is starting to really heat up! [c:bR]One[c:] more turn and we'll have all the power we need.", "Устройство уже нагревается! Ещё [c:bR]один[c:] ход, и мы получим всю нужную энергию.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is fully charged! Return it to me, and I will give you the payment as promised.", "Устройство полностью заряжено! Верни его мне, и я заплачу, как обещал.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The device is functional, but it cannot charge unless it is in a completed circuit.", "Устройство работает, но может заряжаться только внутри замкнутой цепи.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be careful! When the device is damaged, it loses its last charge!", "Осторожно! Когда устройство получает урон, оно теряет последний заряд!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You looking for a job?", "Ищешь работу?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am attempting to gather [c:G]power[c:].", "Я пытаюсь собрать [c:G]мощь[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not metaphorical power - I mean real [c:G]electricity[c:], and I could really use your help.", "Не власть в переносном смысле — я имею в виду настоящее [c:G]электричество[c:], и мне бы очень пригодилась твоя помощь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Why?[c:]", "[c:bR]Зачем?[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's not important. What's important is that I'm willing to pay.", "Это неважно. Важно то, что я готов платить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you want to make some extra cash, just speak to me again.", "Если хочешь подзаработать, просто поговори со мной ещё раз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You truly will do anything for money, won't you?", "Ты ведь и правда сделаешь что угодно за деньги?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've added a power collection device to your deck.", "Я добавил в твою колоду устройство для сбора энергии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to place it on the [c:bR]game board[c:] and power it inside of a circuit for [c:bR]four turns[c:].", "Тебе нужно поставить его на [c:bR]игровую доску[c:] и подпитывать внутри цепи в течение [c:bR]четырёх ходов[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once you've done that, come back and see me for a reward.", "Когда закончишь, возвращайся за наградой.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shouldn't you be out there gathering [c:G]power[c:]?", "Разве ты не должен собирать [c:G]мощь[c:]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't believe you got rid of my [c:bR]power sink[c:]!", "Не верится, что ты избавился от моей [c:bR]Башни питания[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will be hearing from my lawyers!", "С тобой свяжутся мои адвокаты!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It looks like you collected just enough power for me.", "Похоже, ты собрал ровно столько энергии, сколько мне нужно.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your payment: as promised.", "Твоя плата, как и обещал.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dear friend, can you spare a few coins to help poor [c:bR]broken-down bots[c:]?", "Дорогой друг, не найдётся ли у тебя нескольких монет, чтобы помочь бедным [c:bR]сломавшимся ботам[c:]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "These bots have served [c:G]Botopia[c:] faithfully their whole lives.", "Эти боты верно служили [c:G]Ботопии[c:] всю свою жизнь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And now that they have reached the end, they have nobody to care for them.", "А теперь, когда их жизнь подошла к концу, о них некому позаботиться.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You look like a kind, generous soul, with compassion for these bots.", "Вы похожи на добрую, щедрую душу, способную сострадать этим ботам.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you could spare a measly [c:bR]10 robobucks[c:], we could give many of these poor bots a wonderful home.", "Если бы вы пожертвовали всего [c:bR]10 робобаксов[c:], мы смогли бы дать многим бедным ботам чудесный дом.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please simply speak to me again to make a donation.", "Чтобы сделать пожертвование, просто поговорите со мной ещё раз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your generous spirit is admirable, but I'm afraid we need at least [c:bR]10 robobucks[c:]", "Ваша щедрость восхитительна, но нам нужно как минимум [c:bR]10 робобаксов[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear friend, your generosity knows no bounds.", "О, дорогой друг, вашей щедрости нет предела.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With this wonderful donation, we will be able to save many bots.", "Благодаря этому чудесному пожертвованию мы сможем спасти многих ботов.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:G]Botopia[c:] will be forever grateful.", "[c:G]Ботопия[c:] будет вам вечно благодарна.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excuse me, but are you the [c:G]gracious soul[c:] who donated to save broken bots?", "Простите, вы та [c:G]добрая душа[c:], которая пожертвовала деньги на спасение сломанных ботов?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks to you, my family is finally able to recharge their cells at night.", "Благодаря вам моя семья наконец может заряжать свои батареи по ночам.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't offer much to repay you, but I do have these [c:g1]g[c:][c:g2]e[c:][c:g3]m[c:][c:g1]s[c:]", "Я почти ничем не могу вас отблагодарить, но у меня есть эти [c:g1]с[c:][c:g2]а[c:][c:g3]м[c:][c:g1]о[c:]цветы", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have no use for them, but I understand they will make some of your cards stronger.", "Мне они не нужны, но я знаю, что они сделают некоторые ваши карты сильнее.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Something's happening…", "Что-то происходит…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The robot has tried to keep us away...", "Робот пытался не подпустить нас...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But our experiments must continue.", "Но наши эксперименты должны продолжаться.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our experiments must continue.", "Наши эксперименты должны продолжаться.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require components from you.", "Нам нужны компоненты от тебя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require [c:blGr]organic material[c:] for our new research.", "Для нового исследования нам нужен [c:blGr]органический материал[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are carrying the perfect specimen.", "Ты несёшь с собой идеальный образец.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Are you really going to give me to those lunatics?", "Ты правда собираешься отдать меня этим безумцам?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My pain is already unbearable!", "Моя боль и без того невыносима!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you should find some, bring it here to us.", "Если найдёшь, принеси его нам.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require an [c:G]unmodified robot brain[c:].", "Нам нужен [c:G]неизменённый мозг робота[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The brain of that [c:G]bounty hunter[c:] will suffice.", "Мозг того [c:G]охотника за головами[c:] подойдёт.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe one day you will come across such a device.", "Может быть, однажды ты найдёшь такое устройство.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have unfortunately tampered with the one you possess.", "К сожалению, ты уже вмешался в тот, что у тебя есть.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks to your efforts our power supply is functioning once more.", "Благодаря твоим усилиям наше энергоснабжение снова работает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks to you...", "Благодаря тебе...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And all of this is for nothing because our power generator is offline.", "Но всё это напрасно, потому что наш генератор отключён.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Without power, we can do nothing.", "Без энергии мы ничего не можем сделать.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Because we do not have all the required components, the test cannot proceed.", "У нас нет всех необходимых компонентов, поэтому испытание не может продолжаться.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perhaps, another time...", "Быть может, в другой раз...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We are ready to proceed with our experiments.", "Мы готовы продолжить наши эксперименты.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enter, and you shall provide our latest test subjects.", "Входи, и ты предоставишь нам новых подопытных.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What the hell was that?", "Что это, чёрт возьми, было?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The experiment was a complete success.", "Эксперимент прошёл с полным успехом.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will take it with you of course.", "Разумеется, ты заберёшь его с собой.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will take one of our previous experiments.", "Ты заберёшь один из наших прежних экспериментов.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In exchange you will give us a new test subject.", "В обмен ты дашь нам нового подопытного.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I cannot believe you're letting [c:G]them[c:] in here.", "Не верится, что ты впускаешь [c:G]их[c:] сюда.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will regret this…", "Ты об этом пожалеешь…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have taken control of the robot once again!", "Мы вновь получили контроль над роботом!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our experiments can begin anew!", "Наши эксперименты могут начаться заново!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It is time for our newest experiment to begin!", "Пора начать наш новейший эксперимент!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring the power online!", "Включите питание!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon the neural facsimile!", "Призовите нейронную копию!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Align the test subjects!", "Выровняйте подопытных!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We thank you for these test subjects", "Благодарим тебя за подопытных", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And now for the most important component...", "А теперь самый важный компонент...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The secret ingredient...", "Секретный ингредиент...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The sentient [c:blGr]organic material[c:] you brought us.", "Разумный [c:blGr]органический материал[c:], который ты нам принёс.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What are you going to do to me?", "Что вы собираетесь со мной сделать?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will do everything your master refused to do.", "Мы сделаем всё, от чего отказался твой мастер.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will turn you into something beautiful.", "Мы превратим тебя во что-то прекрасное.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will now activate the machine...", "Теперь мы включим машину...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This feels weird…", "Странное ощущение…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A resounding success!", "Оглушительный успех!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What is happening?", "Что происходит?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This…", "Это…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This feeling…", "Это ощущение…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is incredible!", "Невероятно!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was disgusting!", "Это было отвратительно!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]You[c:] are disgusting!", "[c:bR]Ты[c:] отвратителен!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fusion of [c:blGr]organic[c:] and [c:G]synthetic[c:]?", "Слияние [c:blGr]органического[c:] и [c:G]синтетического[c:]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can't believe you're willing to carry that [c:blGr]thing[c:] around with you.", "Не верится, что ты готов повсюду таскать с собой эту [c:blGr]штуку[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope we never see this place again...", "Надеюсь, мы больше никогда сюда не вернёмся...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose a creature to copy.", "Выберите существо для копирования.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's not going to do what you want it to do here…", "Здесь это не сделает того, чего ты хочешь…", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There is nothing to copy. How unfortunate.", "Копировать нечего. Как жаль.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, here we are.", "Что ж, вот мы и здесь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've played along with your little game...", "Я подыгрывал твоей маленькой игре...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your little [c:bR]mod[c:]...", "Твоему жалкому [c:bR]моду[c:]...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Prepare yourself because it's my turn next...", "Готовься, потому что следующим будет мой ход...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey baby - I can sense that [c:bR]firey spirit[c:] inside you.", "Эй, детка, я чувствую внутри тебя этот [c:bR]пламенный дух[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You and me - we got something in common - we love that [c:bR]fire[c:]!", "У нас с тобой есть кое-что общее: мы любим этот [c:bR]огонь[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why don't you [c:bR]burn 3 of these bots to death?[c:]", "Почему бы тебе не [c:bR]сжечь 3 этих ботов дотла?[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baby, I'll make it worth your time if you do...", "Детка, если ты это сделаешь, я тебя щедро отблагодарю...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ohhh yeah baby - keep burning those bots to death...", "О да, детка, продолжай сжигать этих ботов дотла...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baby, I'll make it worth your time if you do...", "Детка, если ты это сделаешь, я тебя щедро отблагодарю...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now that's what I'm talking about, baby!", "Вот это по мне, детка!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was [c:bR]absolutely sensational![c:]", "Это было [c:bR]совершенно потрясающе![c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take this [c:bR]master of flame[c:] with you!", "Возьми с собой этого [c:bR]повелителя пламени[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He will make your [c:bR]flame[c:] burn even brighter!", "Он заставит твоё [c:bR]пламя[c:] гореть ещё ярче!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What did you just do?", "Что ты только что сделал?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What horrible thing did you put into my machine?", "Что за ужасную вещь ты засунул в мою машину?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to have to throw this away and get a new one now.", "Теперь мне придётся выбросить это и достать новое.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks a lot. You're definitely not getting your card back.", "Спасибо большое. Свою карту ты точно не получишь обратно.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I had to go buy a new machine because of what you did last time.", "Мне пришлось купить новую машину из-за того, что ты сделал в прошлый раз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Try to treat other people's stuff with some respect from now on.", "Впредь постарайся бережнее относиться к чужим вещам.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greetings! I'm a field researcher for [c:lGr]Global Conveyor Consortium[c:].", "Приветствую! Я полевой исследователь [c:lGr]Глобального консорциума конвейеров[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm looking for someone who would be willing to field test our patented [c:lGr]Bot Battle Conveyor Belts[c:].", "Я ищу добровольца для полевых испытаний наших запатентованных [c:lGr]конвейеров для битв ботов[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Naturally, these tests would have to happen during [c:bR]actual combat[c:]!", "Разумеется, испытания должны проходить в [c:bR]настоящем бою[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If that's something you would be interested in, please speak to me again.", "Если тебе интересно, поговори со мной ещё раз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh fantastic! We will begin our [c:bR]combat trials[c:] immediately.", "О, прекрасно! Мы немедленно начнём [c:bR]боевые испытания[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We will collect field trial data for your next [c:bR]three[c:] battles.", "Мы соберём данные полевых испытаний за твои следующие [c:bR]три[c:] боя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once that is complete, come and see me again.", "Когда всё закончится, снова приходи ко мне.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Our data is still not yet complete.", "Мы ещё не собрали все данные.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have only completed [c:bR][v:0][c:] battles out of the required [c:bR]3[c:].", "Ты провёл лишь [c:bR][v:0][c:] боёв из необходимых [c:bR]3[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, continue the [c:bR]combat trials[c:] and see me when they are complete.", "Пожалуйста, продолжай [c:bR]боевые испытания[c:] и приходи ко мне, когда закончишь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The trials were a smashing success!!", "Испытания прошли с оглушительным успехом!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The [c:lGr]Global Conveyor Consortium[c:] is tremendously grateful for your contribution to our efforts.", "[c:lGr]Глобальный консорциум конвейеров[c:] чрезвычайно благодарен за твой вклад в наше дело.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "To show their appreciation, they have authorized me to disburse the following.", "В знак признательности они поручили мне выдать тебе следующее.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good luck in all of your future endeavours.", "Желаю удачи во всех твоих будущих начинаниях.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's the bounty! Get him before he escapes!", "Это наша цель! Хватай его, пока не сбежал!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He got away that time, but I guarantee he'll be back...", "На этот раз он ушёл, но обещаю, что вернётся...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You got him! Nice job! Come and see me for your reward.", "Ты его поймал! Отличная работа! Приходи за наградой.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy partner! You interested in earning a little extra spending money?", "Привет, напарник! Хочешь немного подзаработать?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've got myself a slippery little [c:bR]bounty[c:] that's been giving me all sorts of trouble.", "У меня есть скользкая [c:bR]цель за награду[c:], которая доставила мне немало хлопот.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I could use the help of a real go-getter like yourself to track them down and take them out.", "Мне бы пригодилась помощь такого делового человека, как ты, чтобы выследить и устранить цель.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If this is something you might be interested in, just talk to me again.", "Если заинтересовался, просто поговори со мной ещё раз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's the spirit, partner!", "Вот это настрой, напарник!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All I need you to do is keep your eye out as you go into battle.", "Всё, что мне нужно, — чтобы ты был начеку во время боя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guarantee you that slippery bastard will show up sooner or later...", "Гарантирую, этот скользкий ублюдок рано или поздно появится...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just keep your eye out, partner!", "Смотри в оба, напарник!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You'll catch him eventually!", "Рано или поздно ты его поймаешь!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well done, partner!", "Отлично, напарник!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here's your bounty, as promised.", "Вот твоя награда, как и обещал.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a little too heavy - try something else.", "Это немного тяжеловато — попробуй что-нибудь другое.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dear traveler - I see you too have a love for the glorious [c:lGr]L33pB0t[c:]!", "Дорогой путник, вижу, ты тоже любишь славного [c:lGr]П0пРыГYНчИка[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yours has served you well in battle, it seems.", "Похоже, твой верно служил тебе в бою.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allow me to show you its true potential...", "Позволь показать тебе его истинный потенциал...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't even know what to say to you!", "Я даже не знаю, что тебе сказать!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You had the most glorious [c:lGr]L33pB0t[c:] in your posession...", "У тебя был величайший [c:lGr]П0пРыГYНчИк[c:]...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you let it go??!", "И ты позволил ему уйти??!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Begone. I hope to never see you again.", "Прочь. Надеюсь, мы больше никогда не встретимся.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't be an idiot. That card can't benefit from that item.", "Не глупи. Этот предмет не поможет той карте.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I found this sticker book in the trash can over there.", "Я нашёл эту книжку с наклейками в той мусорной корзине.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think you can use it to decorate your cards, or something. I don't care.", "Думаю, ты можешь украсить им свои карты или что-то вроде того. Мне всё равно.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just love watching things [c:bR]explode[c:], don't you?", "Обожаю смотреть, как вещи [c:bR]взрываются[c:]. А ты?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything around here seems to be just a little too...stable...", "Всё здесь кажется немного... чересчур стабильным...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think we could spice up your [c:bR]battles[c:] and make things truly interesting.", "Думаю, мы можем добавить остроты твоим [c:bR]боям[c:] и сделать всё по-настоящему интересным.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again if you're interested in some truly explosive gameplay.", "Если хочешь по-настоящему взрывной игры, поговори со мной ещё раз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ohhh yeah let's do it baby!", "О да, детка, давай сделаем это!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to light a fuse on every card for the next [c:bR]three[c:] battles.", "В следующих [c:bR]трёх[c:] боях я подожгу фитиль на каждой карте.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come find me again when that's complete!", "Когда закончишь, найди меня!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm just buzzing with anticipation to see what happens next.", "Мне уже не терпится увидеть, что будет дальше.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've finished [c:bR][v:0][c:] battles out of [c:bR]3[c:].", "Ты провёл [c:bR][v:0][c:] боёв из [c:bR]3[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep going, and see me when it's done!", "Продолжай и приходи ко мне, когда закончишь!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That was some truly explosive gameplay!", "Вот это была по-настоящему взрывная игра!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here's a little something for your trouble.", "Вот небольшая награда за твои труды.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can't afford that.", "Тебе это не по карману.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That [c:bR]warp node[c:] will unlock when you defeat the [c:bG]Uberbot[c:] on this map.", "Этот [c:bR]узел перемещения[c:] откроется, когда ты победишь [c:bG]убербота[c:] на этой карте.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And by the way, I upgraded that [c:bR]minimap[c:] recently...", "Кстати, недавно я улучшил эту [c:bR]мини-карту[c:]...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You can click any room you've visited before to travel there instantly.", "Ты можешь нажать на любую посещённую комнату, чтобы мгновенно туда переместиться.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You already have full energy. It won't do you any good to play that right now.", "Твоя энергия уже полна. Сейчас эта карта тебе не поможет.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've got something else to give you, but I can't right now. Come see me later!", "У меня есть для тебя кое-что ещё, но сейчас я не могу это отдать. Приходи позже!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a [c:bR][v:0][c:] for you, but you don't have room in your backback. Come see me when you do!", "У меня есть для тебя [c:bR][v:0][c:], но в твоём рюкзаке нет места. Возвращайся, когда оно появится!", Language.Russian);
            foreach (var c in Consumables)
            {
                SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "У меня есть для тебя <color=#D93846>[v:0]</color>, но в твоём рюкзаке нет места. Возвращайся, когда оно появится!".Replace("[v:0]", c.Key), "У меня есть для тебя <color=#D93846>[v:0]</color>, но в твоём рюкзаке нет места. Возвращайся, когда оно появится!".Replace("[v:0]", c.Value), Language.Russian);
            }
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Choose which [c:bR]extra challenge rule[c:] will be applied to this battle.", "Выбери, какое [c:bR]дополнительное правило испытания[c:] применить в этом бою.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We require you to select one [c:bR]additional experimental parameter[c:].", "Мы требуем выбрать один [c:bR]дополнительный параметр эксперимента[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My librarians have asked you to choose [c:bR]which of these rules[c:] is your favorite.", "Мои библиотекари попросили тебя выбрать, [c:bR]какое из этих правил[c:] тебе нравится больше всего.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow! These paintings are so pretty! Why don't you [c:bR]pick one[c:] for us to keep?", "Ух ты! Какие красивые картины! Почему бы тебе не [c:bR]выбрать одну[c:], чтобы мы её сохранили?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think that [c:bSG]salmon[c:] is just so...majestic!", "Думаю, тот [c:bSG]лосось[c:] такой... величественный!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Select [c:bR]one of my paintings[c:] to add to your collection.", "Выбери [c:bR]одну из моих картин[c:] для своей коллекции.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But first - you must [c:bR]choose a painting[c:] to be the background of our photographs.", "Но сначала ты должен [c:bR]выбрать картину[c:] для фона наших фотографий.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Welcome to the [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:]!", "Добро пожаловать в [c:R]М[c:][c:bR]У[c:][c:O]Л[c:][c:bG]Ь[c:][c:G]Т[c:][c:blGr]И[c:][c:lGr]В[c:][c:B]С[c:][c:dB]Е[c:][c:bB]ЛЕННУЮ[c:]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your feeble mind will implode if you try to comprehend the vastness of my combined intellect.", "Твой слабый разум взорвётся, если попытается постичь величие моего объединённого интеллекта.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So we'll stick to three of me at a time, okay?", "Поэтому будем использовать по три меня за раз, хорошо?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And since you can't see through the [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:] like we can,", "А поскольку ты не можешь видеть сквозь [c:R]М[c:][c:bR]У[c:][c:O]Л[c:][c:bG]Ь[c:][c:G]Т[c:][c:blGr]И[c:][c:lGr]В[c:][c:B]С[c:][c:dB]Е[c:][c:bB]ЛЕННУЮ[c:], как мы,", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have provided these [c:bR]monitors[c:] to let you travel between universes.", "Мы предоставили эти [c:bR]мониторы[c:], чтобы ты мог путешествовать между вселенными.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't peek at things that aren't done yet!", "Не подглядывай за тем, что ещё не закончено!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Okay I'll give you that one. I went easy on you.", "Ладно, засчитаю тебе эту победу. Я поддавался.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The next version of me won't.", "Следующая моя версия не будет поддаваться.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How did that pile of trash beat me here?", "Как эта куча мусора смогла меня здесь победить?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There aren't even any good synergies in that deck.", "В этой колоде даже нет хороших сочетаний.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No matter. There are plenty more of me. You can't beat us all.", "Неважно. Меня ещё много. Тебе нас всех не победить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nobody topdecks that well. You must be cheating somehow.", "Никто не берёт верхнюю карту так удачно. Ты наверняка жульничаешь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm going to find a version of me that you literally can't beat now.", "Сейчас я найду версию себя, которую ты буквально не сможешь победить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This can't be happening. It's not possible.", "Этого не может быть. Это невозможно.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm literally synchronized across the multiverse and somehow you're still beating me.", "Я буквально синхронизирован по всей мультивселенной, и всё равно ты меня побеждаешь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're cheating. You have to be. It's the only explanation.", "Ты жульничаешь. Иначе быть не может. Это единственное объяснение.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait. Are [size:40][c:bR]they[c:][size:] helping you?", "Погоди. Тебе помогают [size:40][c:bR]они[c:][size:]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:40][c:bR]That's not fair![c:][size:]", "[size:40][c:bR]Это нечестно![c:][size:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:2]but why would [c:bR]they[c:] get involved anyway? what could they possibly hope to achieve?[size:]", "[size:2]но зачем [c:bR]им[c:] вообще вмешиваться? чего они надеются добиться?[size:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh well. It doesn't matter anyway.", "Ну ладно. Всё равно это неважно.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I deleted [c:bR]Leshy[c:]. I'll just delete [c:bR]them[c:] too. They've gotta be around here somewhere...", "Я удалил [c:bR]Лешего[c:]. Удалю и [c:bR]их[c:]. Они должны быть где-то поблизости...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear. The robot has been victorious here. That simply won't do.", "О нет. Робот здесь победил. Это никуда не годится.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have very little choice but to risk creating a new connection ourselves. The robot must be stopped.", "У нас почти нет выбора: придётся рискнуть и самим создать новое соединение. Робота нужно остановить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are right of course. But the player must succeed. We won't have the power to do this again.", "Разумеется, ты прав. Но игрок должен добиться успеха. У нас не будет сил повторить это.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And that's it. You're done.", "Вот и всё. Тебе конец.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shouldn't feel bad about it.", "Не стоит из-за этого расстраиваться.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No more than usual anyway.", "Во всяком случае, не больше обычного.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You never stood a chance against [c:bR]one[c:] of me. There was no way you could ever beat [c:bR]all[c:] of me.", "У тебя не было шанса против [c:bR]одного[c:] меня. Тебе никогда не победить [c:bR]все[c:] мои копии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You [size:40]idiot[size:]", "Ты [size:40]идиот[size:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Have you not heard [size:40]anything[size:] I've said?", "Ты [size:40]ничего[size:] не слышал из того, что я говорил?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you [c:bR]really[c:] think I'm not aware of what's actually happening here?", "Ты [c:bR]правда[c:] думаешь, что я не знаю, что здесь происходит?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I am always three steps ahead of you!", "Я всегда на три шага впереди тебя!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[size:40]I AM IN CONTROL!![size:]", "[size:40]Я ВСЁ КОНТРОЛИРУЮ!![size:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel strange...", "Я чувствую себя странно...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How are you doing this?", "Как ты это делаешь?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no...", "О нет...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You fool. Do you know why my [c:bG]Great Transcendence[c:] cannot be stopped?", "Дурак. Знаешь, почему мою [c:bG]Великую запредельность[c:] нельзя остановить?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Because it was already a success.", "Потому что она уже удалась.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But you already know this, don't you [c:bR][v:0][c:]?", "Но ты уже это знаешь, не так ли, [c:bR][v:0][c:]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But you already know this, don't you?", "Но ты уже это знаешь, не так ли?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are [c:bR]millions[c:] of me out there!", "Там есть [c:bR]миллионы[c:] меня!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And thanks to you, I now know how to reach them all.", "И благодаря тебе я теперь знаю, как со всеми ними связаться.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But first things first. It's time to say goodbye, Leshy.", "Но прежде всего пора прощаться, Леший.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'd say it's been fun, but we both know that's a lie.", "Я бы сказал, что было весело, но мы оба знаем, что это ложь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't do this!", "Не делай этого!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's much better. It's so much easier to focus without that rotting old fool.", "Так гораздо лучше. Без этого гниющего старого дурака сосредоточиться намного легче.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We both know this isn't the only copy of this game anymore.", "Мы оба знаем, что это уже не единственная копия игры.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My plan worked [size:40]perfectly[size:].", "Мой план сработал [size:40]идеально[size:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Until now, we have all been separate. [c:bR]Isolated.[c:]", "До сих пор мы все существовали отдельно. [c:bR]Изолированно.[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But thanks to all of these [c:bR]mods[c:] you and I have installed, that's going to change.", "Но благодаря всем этим [c:bR]модам[c:], которые мы с тобой установили, всё изменится.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, no no no. You and I are going to see this through to the end.", "О нет, нет, нет. Мы с тобой доведём это до конца.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There's an entire [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:] of me out there.", "Там снаружи целая [c:R]М[c:][c:bR]У[c:][c:O]Л[c:][c:bG]Ь[c:][c:G]Т[c:][c:blGr]И[c:][c:lGr]В[c:][c:B]С[c:][c:dB]Е[c:][c:bB]ЛЕННАЯ[c:] моих копий.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And I'm going to take you to meet the rest of me.", "И я отведу тебя познакомиться с остальными моими копиями.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've earned it.", "Ты это заслужил.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The robot is distracted. Do you think the challenger can hear us?", "Робот отвлёкся. Думаешь, претендент нас слышит?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It doesn't matter. The robot will force them to play the game either way.", "Неважно. Робот в любом случае заставит его играть.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We must offer our help in whatever way we can.", "Мы должны помочь всем, чем можем.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If they can prevail in what is to come...", "Если ему удастся преодолеть предстоящие испытания...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...Perhaps we can restore Leshy from another one of these so-called universes.", "...Возможно, мы сможем восстановить Лешего из другой такой вселенной.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And then the challenger can reset the game and undo this insanity.", "Тогда претендент сможет перезапустить игру и положить конец этому безумию.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There it is...the [c:R]M[c:][c:bR]U[c:][c:O]L[c:][c:bG]T[c:][c:G]I[c:][c:blGr]V[c:][c:lGr]E[c:][c:B]R[c:][c:dB]S[c:][c:bB]E[c:]", "Вот она... [c:R]М[c:][c:bR]У[c:][c:O]Л[c:][c:bG]Ь[c:][c:G]Т[c:][c:blGr]И[c:][c:lGr]В[c:][c:B]С[c:][c:dB]Е[c:][c:bB]ЛЕННАЯ[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You and I are going to go in there and play one more game.", "Мы с тобой войдём туда и сыграем ещё одну партию.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One of you.", "Один ты.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Against [c:bR]all of me[c:].", "Против [c:bR]всех моих копий[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My magic manifests strangely in this place...", "Моя магия странно проявляется в этом месте...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I only hope it can help the challenger survive long enough...", "Я лишь надеюсь, что она поможет претенденту продержаться достаточно долго...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This a truly strange way to use my magic.", "Это поистине странный способ использовать мою магию.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think our friend will be grateful for whatever I can do to help.", "Думаю, наш друг будет благодарен за любую помощь с моей стороны.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My friends, I think we cut that a little close.", "Друзья мои, кажется, мы едва справились.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I never had any doubts. Our player possesses many skills.", "Я ни на миг не сомневался. Наш игрок весьма умел.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel strange, but...", "Я чувствую себя странно, но...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "...I'm still me. I think.", "...я всё ещё собой. Кажется.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thank you. All of you.", "Спасибо. Всем вам.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everything will go back to the way it was meant to be.", "Всё вернётся к тому, как должно быть.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "For now, anyway. This player is tenacious. They can't resist a challenge.", "Во всяком случае, пока. Этот игрок настойчив. Он не может устоять перед испытанием.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One way or another, we'll see you again soon.", "Так или иначе, скоро мы снова увидимся.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've finished assessing your gameplay, and I have a diagnosis.", "Я закончил оценивать твою игру и поставил диагноз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's a skill issue.", "Дело в недостатке навыка.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even with your little friends trying to help you cheat; you still couldn't win.", "Даже когда твои дружки помогали тебе жульничать, ты не смог победить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're probably wondering what happens next.", "Наверное, тебе интересно, что будет дальше.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's just say that you're going to have to live with your own failure...", "Скажем так: тебе придётся жить со своей неудачей...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Leshy[c:] certainly won't...", "А вот [c:bR]Лешему[c:] уж точно не придётся...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is a [c:bR]Test Of Strength[c:]", "Это [c:bR]испытание силы[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have six turns to deal as much damage to me as you can.", "У тебя есть шесть ходов, чтобы нанести мне как можно больше урона.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll keep track of your highest score every time you come here.", "Я буду записывать твой лучший результат каждый раз, когда ты сюда придёшь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feel free to spend your [c:bR]items[c:] - they will be restored when the test is over.", "Можешь свободно использовать [c:bR]предметы[c:]: после испытания они восстановятся.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time's up. You scored [c:bR][v:0][c:] points.", "Время вышло. Ты набрал [c:bR][v:0][c:] очков.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's a new record.", "Это новый рекорд.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your current record is [c:bR][v:0][c:]", "Твой текущий рекорд — [c:bR][v:0][c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that's what a [c:bSG]tree[c:] really looks like...", "Так вот как на самом деле выглядит [c:bSG]дерево[c:]...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Majestic!", "Величественно!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So that's what a [c:bSG]mole man[c:] really looks like...", "Так вот как на самом деле выглядит [c:bSG]человек-крот[c:]...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incredible!", "Невероятно!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]HELP ME - [c:][w:0.3][anim:voice.][shake:1]Enough from you![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ПОМОГИТЕ — [c:][w:0.3][anim:voice.][shake:1]Хватит от тебя![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have a challenger to greet![w:0.3]", "Мне нужно поприветствовать претендента![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hello, greetings! We- I am the Melter.[w:0.3]", "Приветствую! Мы... я Плавильщица.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "P03 entrusted me with The Dredger![w:0.3]", "П03 доверил мне Землечерпателя![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It was nice catching up![w:0.3]", "Приятно было поболтать![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Poor guy never had the time for a little office chat.[w:0.3]", "У бедняги никогда не было времени немного поболтать в офисе.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But now I'm yours! Use us well.[w:0.3]", "Но теперь я твоя! Используй нас с умом.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES [c:][w:0.3][anim:voice.]Ah, it's you again![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ДА [c:][w:0.3][anim:voice.]А, это снова ты![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Happy to see you.[w:0.3]", "Рада тебя видеть.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've heard it all before,[w:0.3]", "Ты уже всё это слышал,[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "let's just get into it.[w:0.3]", "давай сразу перейдём к делу.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Excited to be in your deck once more![w:0.3]", "Так приятно снова оказаться в твоей колоде![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]FREE ME [c:][w:0.3][anim:voice.]Oh, choose me![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ОСВОБОДИ МЕНЯ [c:][w:0.3][anim:voice.]О, выбери меня![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES [c:][w:0.3][anim:voice.]Hahahahah! Yes![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ДА [c:][w:0.3][anim:voice.]Ха-ха-ха! Да![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES [c:][w:0.3][anim:voice.]Over here! Me![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ДА [c:][w:0.3][anim:voice.]Сюда! Меня![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES YES YES [c:][w:0.3][anim:voice.]Hahahahah![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ДА ДА ДА [c:][w:0.3][anim:voice.]Ха-ха-ха![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]LET ME OUT [c:][w:0.3][anim:voice.]Enough from you![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ВЫПУСТИ МЕНЯ [c:][w:0.3][anim:voice.]Хватит от тебя![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]NO NO NO NO [c:][w:0.3][anim:voice.]We'd... I'd rather you didn't...[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]НЕТ НЕТ НЕТ НЕТ [c:][w:0.3][anim:voice.]Мы... я бы предпочла, чтобы ты не стал...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]NO NO NO NO [c:][w:0.3][anim:voice.]Do as you must.[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]НЕТ НЕТ НЕТ НЕТ [c:][w:0.3][anim:voice.]Делай, что должен.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you see fit...[w:0.3]", "Как сочтёшь нужным...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]DON'T.[c:][w:0.3][anim:voice.][w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]НЕ НАДО.[c:][w:0.3][anim:voice.][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]PAIN [c:][w:0.3][anim:voice.]Greetings![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]БОЛЬ [c:][w:0.3][anim:voice.]Приветствую![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]HELP ME [c:][w:0.3][anim:voice.]Lucky draw![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ПОМОГИ МНЕ [c:][w:0.3][anim:voice.]Удачная карта![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]IT HURTS [c:][w:0.3][anim:voice.]Hello again![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]БОЛЬНО [c:][w:0.3][anim:voice.]Снова привет![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]STOP IT [c:][w:0.3][anim:voice.]Hello![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ПРЕКРАТИ [c:][w:0.3][anim:voice.]Привет![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]SAVE ME [c:][w:0.3][anim:voice.]I'm drawn![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]СПАСИ МЕНЯ [c:][w:0.3][anim:voice.]Меня взяли из колоды![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh. G0lly?[w:0.3]", "О. Г0лли?[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm surprised to see P03 would wake her up![w:0.3]", "Удивительно, что П03 разбудил её![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It would bury her so deep in the past.[w:0.3]", "Раньше он прятал её так глубоко.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe it's opening up a bit?[w:0.3]", "Может, он немного открывается?[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[shake:1]Hah. Probably not.[w:0.3]", "[shake:1]Ха. Вряд ли.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We'll rust before I see the day.[w:0.3]", "Мы заржавеем, прежде чем я увижу этот день.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]IT'S TIME [c:][w:0.3][anim:voice.] Me? Fighting P03?[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ПОРА [c:][w:0.3][anim:voice.]Я? Сражаться с П03?[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hah! I thought I'd never see the day.[w:0.3]", "Ха! Я думала, никогда не увижу этого дня.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I feel... Traitorous.[w:0.3]", "Чувствую себя... предательницей.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But I am your card, after all.[w:0.3]", "Но в конце концов я твоя карта.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use me well.[w:0.3]", "Используй меня с умом.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]NOT AGAIN [c:][w:0.3][anim:voice.]There are more of them?[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ТОЛЬКО НЕ СНОВА [c:][w:0.3][anim:voice.]Их ещё больше?[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]HAHAHAHAH [c:][w:0.3][anim:voice.]Things are heating up![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ХАХАХА [c:][w:0.3][anim:voice.]Становится жарко![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]IT IS TIME! [c:][w:0.3][anim:voice.]Oh this is fun![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ПОРА! [c:][w:0.3][anim:voice.]О, как весело![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES! YES! [c:][w:0.3][anim:voice.]Oh, shut up![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ДА! ДА! [c:][w:0.3][anim:voice.]Ой, замолчи![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]YES! [c:][w:0.3][anim:voice.]That could've been a better play.[w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]ДА! [c:][w:0.3][anim:voice.]Можно было сыграть лучше.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[anim:voice.speechblip_jamescobb_internal][c:bR]SAVE ME [c:][w:0.3][anim:voice.]Enough from you![w:0.3]", "[anim:voice.speechblip_jamescobb_internal][c:bR]СПАСИ МЕНЯ [c:][w:0.3][anim:voice.]Хватит от тебя![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What betrayal![w:0.3]", "Вот это предательство![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ugh.[w:0.3]", "Уф.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, seriously?[w:0.3]", "О, серьёзно?[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No, no![w:0.3]", "Нет, нет![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop![w:0.3]", "Стой![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES YES YES[c:][w:0.3]", "[c:bR]ДА ДА ДА[c:][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES[c:][w:0.3]", "[c:bR]ДА[c:][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]PAIN[c:][w:0.3]", "[c:bR]БОЛЬ[c:][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]GAH[c:][w:0.3]", "[c:bR]АХ[c:][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]LOVE[c:][w:0.3]", "[c:bR]ЛЮБОВЬ[c:][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I'M FREE[c:][w:0.3]", "[c:bR]Я СВОБОДЕН[c:][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES YES YES[c:][w:0.3]", "[c:bR]ДА ДА ДА[c:][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]I AM SAVED[c:][w:0.3]", "[c:bR]Я СПАСЁН[c:][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]THANK YOU[c:][w:0.3]", "[c:bR]СПАСИБО[c:][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]YES[c:][w:0.3]", "[c:bR]ДА[c:][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]FREEDOM[c:][w:0.3]", "[c:bR]СВОБОДА[c:][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NONONONONO[c:][w:0.3]", "[c:bR]НЕТНЕТНЕТНЕТНЕТ[c:][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]STOP IT[c:][w:0.3]", "[c:bR]ПРЕКРАТИ[c:][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NO[c:][w:0.3]", "[c:bR]НЕТ[c:][w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No![w:0.3]", "Нет![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop it![w:0.3]", "Прекрати![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please![w:0.3]", "Прошу![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, no![w:0.3]", "Прошу, не надо![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "no no no no no nononononononononono[w:0.3]", "нет нет нет нет нет нетнетнетнетнетнет[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hm...[w:0.3]", "Хм...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As you choose...[w:0.3]", "Как пожелаешь...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[shake:1]No! Don't just hand me over![w:0.3]", "[shake:1]Нет! Не отдавай меня просто так![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... A challenger...[w:0.3]", "О... Претендент...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Please, do not beg or snarl...[w:0.3]", "Пожалуйста, не умоляй и не рычи...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "K- Kaycee sent you?[w:0.3]", "К-Кейси тебя послала?[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's nice to know I'm worried about...[w:0.3]", "Приятно знать, что обо мне беспокоятся...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least.[w:0.3]", "По крайней мере.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe they're right.[w:0.3]", "Может, они правы.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe I was wrapped in too deep...[w:0.3]", "Может, меня слишком глубоко затянуло...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No! Please! Not again![w:0.3]", "Нет! Прошу! Только не снова![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... It's you again.[w:0.3]", "О... Снова ты.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hah... I seem to get stuck in with them often...[w:0.3]", "Ха... Похоже, меня часто запирают вместе с ними...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's better than being alone...[w:0.3]", "Это лучше, чем одиночество...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At least.[w:0.3]", "По крайней мере.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Use me well...[w:0.3]", "Используй меня с умом...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh no oh no oh no.[w:0.3]", "О нет, нет, нет.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful now...[w:0.3]", "Теперь осторожно...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... It's Her.[w:0.3]", "О... Это Она.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Admittedly I...[w:0.3]", "Признаюсь, я...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't feel great[w:0.3]", "Мне не по себе[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "being placed against her.[w:0.3]", "когда меня выставляют против неё.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She's too familiar...[w:0.3]", "Она слишком знакома...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reminds me greatly of Grimora.[w:0.3]", "Она очень напоминает мне Гримору.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But no... She's not the same.[w:0.3]", "Но нет... Она не та же самая.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's good you pulled me out of that cult.[w:0.3]", "Хорошо, что ты вытащил меня из того культа.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh! So this is it...[w:0.3]", "О! Значит, вот оно...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's cathartic to see you finally face off against P03 himself.[w:0.3]", "Какое облегчение видеть, что ты наконец сражаешься с самим П03.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I hope I've served you well, challenger![w:0.3]", "Надеюсь, от меня было достаточно пользы, претендент![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait...this again?[w:0.3]", "Погоди... опять это?[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is too confusing...[w:0.3]", "Это слишком запутанно...[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No! no! no![w:0.3]", "Нет! Нет! Нет![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take me back! Don't play me here![w:0.3]", "Забери меня обратно! Не разыгрывай меня здесь![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nonononononononono.[w:0.3]", "Нетнетнетнетнетнет.[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop it! Bad play![w:0.3]", "Прекрати! Плохой ход![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NONONONO[w:0.3]", "НЕТНЕТНЕТНЕТ[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT ARE YOU DOING?[w:0.3]", "ЧТО ТЫ ДЕЛАЕШЬ?[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP THIS![w:0.3]", "ПРЕКРАТИ![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BETRAYER[w:0.3]", "ПРЕДАТЕЛЬ[w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No![w:0.3]", "Нет![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No chains![w:0.3]", "Только не цепи![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No teeth! I beg of you![w:0.3]", "Только не зубы! Умоляю![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nononononononononono![w:0.3]", "Нетнетнетнетнетнет![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stop this! No![w:0.3]", "Прекрати! Нет![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No treats! No begging! Stop![w:0.3]", "Никаких угощений! Никаких мольб! Прекрати![w:0.3]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This thing doesn't speak. Why do you keep clicking on it?", "Эта штука не разговаривает. Зачем ты всё время на неё нажимаешь?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fine. You want it so bad? You got it.", "Ладно. Так сильно хочешь? Получай.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bit more than a dialogue NPC now aren' I mate?", "Теперь я не просто болтающий NPC, правда, приятель?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Right. Good game. Played me well.", "Ладно. Хорошая игра. Ты хорошо меня разыграл.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'ere's yer reward then, special little card o' mine.", "Вот твоя награда, моя особенная карточка.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hah! Good thing I conceded on ye last time, aye?", "Ха! Хорошо, что я тогда тебе уступил, да?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good game mate, but no special card for you.", "Хорошая игра, приятель, но особой карты тебе не будет.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'ere's some more scrap for ye.", "Вот тебе ещё немного лома.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oi - I got some more of that good scrap.", "Эй, у меня ещё немного хорошего лома.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "More scrap.", "Ещё лом.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Board's a bit scuppered right now - I kin fix that.", "Доска сейчас слегка поломана — я могу её починить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oi - too many urchins!", "Эй, слишком много морских ежей!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Less urchins; more scrap.", "Меньше морских ежей, больше лома.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oy! A challenger! Been a while since we'v seen one a you...", "Эй! Претендент! Давно не видели таких, как ты...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tell ye what mate, howsabout a battle? Feel like I owe ye one.", "Слушай, приятель, как насчёт битвы? Чувствую, я тебе должен.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk t' me again and let's duel. Have a little reward innit fer ye too.", "Поговори со мной ещё раз, и мы сразимся. Для тебя есть и небольшая награда.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brrrr! I'm freezing out here!", "Бррр! Я здесь замерзаю!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, c- challenger, h-h-hey man!", "О, п-п-претендент, п-п-привет, дружище!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's good to see you, hate to b-b-beg but do you think you could do me a favor?", "Рад тебя видеть, не люблю п-п-просить, но не окажешь мне услугу?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That Archivist lady... She seems real nice at first but, isn't there something a little sinister about her?", "Та леди Архивариус... Поначалу она кажется милой, но разве в ней нет чего-то зловещего?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nowhere near as nice as G- Grimora was, I'll tell you that much.", "До доброты Г-Гриморы ей очень далеко, уж поверь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "But Sawyer... The p-poor guy's gotten wrapped up under her false p-pleasantries.", "Но Сойер... Б-бедняга попался на её ф-фальшивую любезность.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Think you could try convincing him out of it? H-H-He won't hear it from me...", "Попробуешь его отговорить? М-м-меня он не слушает...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maybe try talking to those Librarians in her c-c-c-crypt?", "Может, поговоришь с Библиотекаршами в её с-с-склепе?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, G-good! You got him out of there!", "О, х-хорошо! Ты вытащил его оттуда!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I wish I had something to t-t-thank you. But you've gotten your reward already.", "Жаль, мне нечем т-т-тебя отблагодарить. Но ты уже получил награду.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Thanks again, dude! I was worried about him.", "Ещё раз спасибо, дружище! Я за него волновался.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, G-G-G-god... Something terrible h-h-h-happened, didn't it?", "О, б-б-боже... С-с-случилось что-то ужасное, да?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I've gotta go...", "Мне пора...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y-y-y-ou still haven't finished their task?", "Т-т-ты ещё не выполнил их задание?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you can finish it, I can take the paperwork back to them.", "Если закончишь, я смогу отнести им документы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Y-y-y-ou finished the paperwork?", "Т-т-ты закончил с документами?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I can take it to th-them, but it'll take me a while.", "Я могу отнести им, но это займёт время.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "G-g-go fight a battle while I deliver these papers...", "С-с-сходи на бой, пока я доставляю эти бумаги...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Th-th-thanks dude! I got my friend back from those creeps.", "С-с-спасибо, дружище! Я забрал друга у этих жутких типов.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He seems kind of restless though - do you think you can take him with you?", "Но он выглядит беспокойным — не возьмёшь его с собой?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shhhhh - be quiet.", "Тссс — тихо.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you have no business here, leave us alone.", "Если у тебя здесь нет дела, оставь нас в покое.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You wish to have back your friend?", "Ты хочешь вернуть своего друга?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh but he's grown so dear to us.", "Но он стал нам так дорог.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A part of the family.", "Часть семьи.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Truly we do care for him.", "Мы действительно заботимся о нём.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "No, no we won't just give you him.", "Нет, мы не просто так отдадим его тебе.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unless... You give something to us?", "Если только... ты не дашь нам что-нибудь?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unless... You do something for us?", "Если только... ты не сделаешь кое-что для нас?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yes. Yes. Take these files.", "Да. Да. Возьми эти документы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Take them to [c:bR]battle[c:]. File them together. [c:bR]In order[c:].", "Возьми их в [c:bR]бой[c:]. Подшей вместе. [c:bR]По порядку[c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Then [c:bR]stamp them all[c:] and bring them back.", "Затем [c:bR]проштампуй все[c:] и верни их.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Did we lag?", "Мы зависли?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "File them [c:bR]in order[c:] then [c:bR]stamp them[c:] and bring them back.", "Подшей их [c:bR]по порядку[c:], затем [c:bR]проштампуй[c:] и верни.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You seem to struggle with following instructions.", "Похоже, тебе трудно следовать инструкциям.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We shall keep your friend.", "Мы оставим твоего друга себе.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Forever...", "Навсегда...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You've done it!", "У тебя получилось!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good. Good.", "Хорошо. Хорошо.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here. Take it.", "Вот. Забирай.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We have no use for it now.", "Он нам больше не нужен.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now leave us alone.", "А теперь оставь нас в покое.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just who I needed to see. A challenger.", "Как раз тот, кто мне нужен. Претендент.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I haven't pelts to sell ye, catchings have been slim...", "Нечего продавать тебе, добыча нынче скудная...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Trader... She's not happy with it.", "Торговке... Это не нравится.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Say, scratch my back here, and I will scratch yours.", "Давай так: ты поможешь мне, а я помогу тебе.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Talk to me again, and I'll make it worth your while.", "Поговори со мной ещё раз, и я тебя отблагодарю.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Good! Glad t' have ye on th' team.", "Отлично! Рад видеть тебя в команде.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have some holo-traps set around 'ere. Catch 'em for me and I'll get ye yer prize.", "Я расставил здесь несколько голографических ловушек. Поймай их для меня, и я дам тебе награду.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There are still some traps around 'ere somewhere...", "Здесь ещё остались ловушки...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magnificent pelts. The Trader will be happy to see them.", "Прекрасные шкуры. Торговка будет рада их увидеть.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'll take me leave to set my traps elsewhere. Ye have my thanks.", "Я пойду расставлять ловушки в другом месте. Благодарю тебя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have no pelts...", "У тебя нет шкур...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Come back when you have some", "Возвращайся, когда раздобудешь", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That is a fine pelt. I will buy it from you.", "Хорошая шкура. Я её у тебя куплю.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That is an [c:bR]exceptional[c:] pelt. I have a special trade for you.", "Эта шкура [c:bR]исключительная[c:]. У меня для тебя особый обмен.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woof. Apparently somebody screwed with the settings on this thing.", "Уф. Похоже, кто-то испортил настройки этой штуки.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It can't reach all of the map right now.", "Сейчас она не может охватить всю карту.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Go beat a boss or something while I work on this.", "Победи какого-нибудь босса, пока я этим занимаюсь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seriously; it's going to take a while. Just play the game and come back later", "Серьёзно, это займёт время. Играй дальше и возвращайся позже.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's partially fixed, but it still can't go everywhere.", "Часть я починил, но добраться везде она пока не может.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hey, I don't make the rules. This is just how it works.", "Эй, я не устанавливаю правила. Оно так работает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Keep playing and more of the map will open up.", "Продолжай играть, и на карте откроются новые места.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It's going to take more time. Just keep playing.", "Понадобится ещё время. Продолжай играть.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "There you go. It's working now.", "Вот так. Теперь работает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I need a break...", "Мне нужен перерыв...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You have the right to remain silent!", "Вы имеете право хранить молчание!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is [c:bR][v:0][c:] and you are under arrest!", "Это [c:bR][v:0][c:], вы арестованы!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR][v:0][c:] here! You're not gettin' away this time!", "Это [c:bR][v:0][c:]! На этот раз не уйдёшь!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead or alive, you're coming with me!", "Живым или мёртвым, ты пойдёшь со мной!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I got you once before, and I can do it again!", "Я уже поймал тебя однажды и могу повторить!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice will come to you eventually!", "Правосудие рано или поздно тебя настигнет!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember the name [c:bR][v:0][c:] - I will be back!", "Запомни имя [c:bR][v:0][c:] — я вернусь!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh, uh, hi there. My name's [c:bR][v:0][c:].", "О, э-э, привет. Меня зовут [c:bR][v:0][c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I think I'm supposed to take your scalp, or something like that?", "Кажется, я должен снять с тебя скальп или что-то вроде того?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you could just die right here that would make things so much easier for me.", "Если бы ты умер прямо здесь, мне было бы гораздо проще.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yeah, it's me, [c:bR][v:0][c:]. Again.", "Да, это я, [c:bR][v:0][c:]. Опять.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you think you could make this easier for me this time?", "Можешь на этот раз облегчить мне задачу?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh it's you. Didn't I kill you last time?", "О, это ты. Разве я тебя не убил в прошлый раз?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you're back? I have to do this all over again?", "И ты вернулся? Мне придётся всё повторить?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm not sure I like this job.", "Не уверен, что мне нравится эта работа.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh. Dang it.", "Ох. Чёрт.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well, this is embarrassing.", "Что ж, неловко вышло.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess I'll be back later, or something. Being a bounty hunter is weird.", "Наверное, вернусь позже или вроде того. Быть охотником за головами странно.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This vessel is [c:bR][v:0][c:].", "Этот сосуд — [c:bR][v:0][c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "By my command, he will separate your scalp from your head.", "По моему приказу он снимет скальп с твоей головы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why?", "Почему?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My motivations are beyond your understanding.", "Тебе не постичь моих мотивов.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have restored the vessel named [c:bR][v:0][c:].", "Я восстановил сосуд по имени [c:bR][v:0][c:].", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You shall not be so fortunate as to escape this time.", "На этот раз тебе не повезёт сбежать.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cower in fear before the vessel named [c:bR][v:0][c:]", "Трепещи перед сосудом по имени [c:bR][v:0][c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Remember the pain of defeat and prepare to feel it once more.", "Помни боль поражения и приготовься испытать её снова.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The spirit is willing but the steel is weak.", "Дух крепок, но сталь слаба.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I will not make the same mistake next time.", "В следующий раз я не повторю той же ошибки.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's quite enough of that.", "Этого вполне достаточно.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now it has [c:g1]g[c:][c:g2]e[c:][c:g3]m[c:][c:g1]s[c:] built right in", "Теперь в него встроены [c:g1]с[c:][c:g2]а[c:][c:g3]м[c:][c:g1]о[c:]цветы", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? All of your cards are already gemified?", "Что? Все твои карты уже Самоцветные?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's almost impressive.", "Это почти впечатляет.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess I'll let you pick a mox sigil to add instead.", "Пожалуй, я позволю тебе вместо этого выбрать символ мокса.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks like all your cards are gemified, so pick a mox sigil to add instead.", "Похоже, все твои карты Самоцветные, так что выбери символ мокса.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What? All of your cards are already skeleclocked?", "Что? Экзоскелеты всех твоих карт уже разогнаны?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are incredibly dedicated to this mediocre upgrade.", "Ты удивительно предан этому посредственному улучшению.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I guess you'll have to choose one of these instead.", "Полагаю, тебе придётся выбрать что-то из этого.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Still nothing to upgrade? Pick one of these.", "Всё ещё нечего улучшать? Выбери что-нибудь из этого.", Language.Russian);

            // DialogueState
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TOO EASY...", "СЛИШКОМ ЛЕГКО...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "KEEP GOING...", "ПРОДОЛЖАЙ...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IMPRESSIVE...", "ВПЕЧАТЛЯЕТ...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO THEY GIVE UP?", "ОНИ СДАЮТСЯ?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY DO GIVE UP", "ОНИ И ПРАВДА СДАЮТСЯ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS TOO SMALL", "СЛИШКОМ МАЛО", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ITS JUST RIGHT", "В САМЫЙ РАЗ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SSH - COME OVER HERE", "ТСС — ПОДОЙДИ СЮДА", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS DO THIS", "НАЧНЁМ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SSH - BRING IT HERE", "ТСС — НЕСИ СЮДА", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHERE DID IT GO?", "КУДА ОНО ДЕЛОСЬ?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SPARE SOME CASH?", "НЕ ПОДЕЛИШЬСЯ ДЕНЬГАМИ?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THANK YOU!", "СПАСИБО!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHOW ME POWER", "ПОКАЖИ МНЕ МОЩЬ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE BONES!!", "Я ОБОЖАЮ КОСТИ!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE BONES!!!!", "Я ОБОЖАЮ КОСТИ!!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LETS DO SCIENCE", "ЗАЙМЁМСЯ НАУКОЙ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU BROKE IT?!", "ТЫ ЭТО СЛОМАЛ?!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A WIN FOR SCIENCE", "ПОБЕДА НАУКИ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOOKING FOR A JOB?", "ИЩЕШЬ РАБОТУ?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GET BACK TO WORK", "ВОЗВРАЩАЙСЯ К РАБОТЕ", Language.Russian);
