    public class CursesMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for Curses Mod");
            // Ability/Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bitten By Predator", "Укус хищника", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card was bitten by a predator", "Эту карту укусил хищник", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bow and Arrow", "Лук и стрела", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Capture", "Захват", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spike Trap", "Ловушка с шипами", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mega Shark", "Мегаакула", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Swallow Whole", "Проглотить целиком", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dynamite!?", "Динамит!?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Booby Trap", "Ловушка-сюрприз", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If this is in your hand at the end of your turn, it explodes. If it is on the board at the end of your opponent's turn, it explodes. Either way, it explodes.", "Если эта карта в твоей руке в конце твоего хода, она взрывается. Если она на доске в конце хода противника, она взрывается. В любом случае она взрывается.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This is more difficult than anticipated...", "Это сложнее, чем ожидалось...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We - We may have made things worse", "Мы... мы, возможно, всё усугубили", Language.Russian);

            // Achievement
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cursed Achievements", "Проклятые достижения", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here For A Good Time", "Ради веселья", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete a run with a negative challenge level", "Завершите забег с отрицательным уровнем испытания", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Here For A Hard Time", "Ради трудностей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete a run with a challenge level above 250", "Завершите забег с уровнем испытания выше 250", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utter Insanity", "Полное безумие", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Complete a run with two Chaotic Enemy skulls active", "Завершите забег с двумя активными черепами «Хаотичные враги»", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Too Spooky", "Слишком жутко", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reach the maximum deathcard haunt level", "Достигните максимального уровня преследования картами смерти", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's No Moon", "Это не луна", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defeat the Limoncello with the Bigger Moon skull active", "Победите Лимончелло с активным черепом «Большая луна»", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "'Tis But A Flesh Wound", "Всего лишь царапина", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Retrieve a damaged card from the belly of a Mega Shark", "Достаньте повреждённую карту из брюха Мегаакулы", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Munitions Expert", "Эксперт по боеприпасам", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Safely dispose of a stick of dynamite", "Безопасно избавьтесь от шашки динамита", Language.Russian);


            // Challenge
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Full Moon", "Полная луна", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Giant cards like the moon have more attack and health", "Гигантские карты, например луна, имеют больше силы и здоровья", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Minor Boon of the Bone Lord", "Малый дар Владыки костей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start the game with a Minor Boon of the Bone Lord", "Начните игру с Малым даром Владыки костей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Checking to see if we should add a deathcard...", "Проверяем, нужно ли добавить карту смерти...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Haunted Past", "Призраки прошлого", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deathcards will sometimes attack you in battle", "Карты смерти иногда будут атаковать тебя в бою", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exploding Cards", "Взрывные карты", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dynamite is added to your deck after every boss battle", "После каждого боя с боссом в твою колоду добавляется динамит", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Golden Beginnings", "Золотое начало", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start the game with the ability to draft a rare card", "Начните игру с возможностью выбрать редкую карту", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boss Revenge", "Месть боссов", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each boss has an additional phase", "У каждого босса есть дополнительная фаза", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Two Turn Minimum", "Не меньше двух ходов", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You cannot deal lethal damage on the first turn.", "Вы не можете нанести смертельный урон в первом ходу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chaotic Enemies", "Хаотичные враги", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Opposing creatures gain random abilities", "Противостоящие существа получают случайные способности", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Totem Collector", "Коллекционер тотемов", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You start with all tribal totem tops", "Вы начинаете со всеми верхними частями племенных тотемов", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Extra Candle", "Дополнительная свеча", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You are given an extra life", "Вы получаете дополнительную жизнь", Language.Russian);

            // DialogueEvent
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you feel a chill in the air", "ты чувствуешь холод в воздухе", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the hair stands up on the back of your neck", "волосы на твоём затылке встают дыбом", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR][v:0][c:] has arrived", "[c:bR][v:0][c:] прибыл", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you suddenly feel weak", "ты внезапно чувствуешь слабость", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "your teeth start to chatter", "твои зубы начинают стучать", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR][v:0][c:] is coming", "[c:bR][v:0][c:] приближается", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you can't explain how", "ты не можешь объяснить, как", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "but you can feel the presence of [c:bR][v:0][c:]", "но чувствуешь присутствие [c:bR][v:0][c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it finally happened: [c:bR][v:0][c:] is here", "наконец это случилось: [c:bR][v:0][c:] здесь", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:O]\"I have been looking for you\"[c:] says the apparition", "[c:O]«Я искал тебя»[c:], говорит призрак", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:O]\"And now you must die!\"[c:]", "[c:O]«А теперь ты должен умереть!»[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the apparition has nothing to say", "призраку нечего сказать", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "but you sense that it is here for you", "но ты чувствуешь, что он пришёл за тобой", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:O]\"you made a mistake coming here\"[c:] it growls", "[c:O]«Ты совершил ошибку, придя сюда»[c:], рычит он", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:O]\"let me show you the way home\"[c:]", "[c:O]«Позволь показать тебе дорогу домой»[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the apparition seems lonely", "призрак кажется одиноким", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "it wants you to join it in the afterlife", "он хочет, чтобы ты присоединился к нему в загробном мире", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the apparition fades into the wind", "призрак растворяется на ветру", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you can't shake the feeling there are [c:O]more[c:] out there waiting", "тебя не покидает ощущение, что где-то ждут [c:O]другие[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR][v:0][c:] shivers with delight as your candle is extinguished", "[c:bR][v:0][c:] дрожит от радости, когда твоя свеча гаснет", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "do you see the [c:O]apparition[c:] encircling you?", "видишь [c:O]призрака[c:], окружающего тебя?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "you have become [c:O]haunted[c:] by [c:O]those who have come before[c:]", "тебя начали [c:O]преследовать[c:] [c:O]те, кто пришёл раньше[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the more you [c:O]win in battle[c:] the angrier they become", "чем чаще ты [c:O]побеждаешь в бою[c:], тем сильнее они злятся", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and they may [c:O]oppose you in battle[c:] in the future", "и в будущем они могут [c:O]выступить против тебя в бою[c:]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's play longer this time!", "Давай на этот раз поиграем подольше!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A lil' more fun never hurt nobody!", "Немного лишнего веселья ещё никому не вредило!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I got a little somethin' special for ya!", "У меня для тебя кое-что особенное!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heeeeeeee-haaw! Let's keep the fun goin'!", "И-и-и-ха! Продолжим веселье!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You want more fish?", "Хочешь ещё рыбы?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "We get extra fish.", "Будет больше рыбы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Many fish this time.", "В этот раз много рыбы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'm afraid our encounter today will take a little more time", "Боюсь, наша сегодняшняя встреча займёт немного больше времени", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It looks like you and I have extra business to attend to", "Похоже, нам с тобой нужно обсудить ещё кое-какие дела", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He swalled it whole..", "Он проглотил это целиком..", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Eating that was a bad idea..", "Съесть это было плохой идеей..", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That's a little uncomfortable..", "Это немного неудобно..", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bR][v:0][c:] has been fully digested. You will never see it again.", "Твой [c:bR][v:0][c:] полностью переварен. Ты его больше никогда не увидишь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your [c:bR][v:0][c:] is being slowly digested. It has [c:bR][v:1][c:] health left.", "Твой [c:bR][v:0][c:] медленно переваривается. Осталось [c:bR][v:1][c:] здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I have yet another trade to propose", "У меня есть ещё одно предложение об обмене", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This time, let us trade our whole decks", "На этот раз обменяемся целыми колодами", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He's hungry again", "Он снова голоден", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Time for more morsels", "Пора ещё перекусить", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Back on the hunt", "Снова на охоту", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Think fast!", "Быстрее!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Catch!", "Лови!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heads up!", "Берегись!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You're a dad-gum pain in my backside!", "Ну и заноза же ты у меня в заднице!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Let's see you get past this!", "Посмотрим, как ты с этим справишься!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish not big enough. Get bigger fish.", "Рыба недостаточно большая. Нужна рыба побольше.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Little fish bad. Big fish better.", "Маленькая рыба плохая. Большая рыба лучше.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Need better fish.", "Нужна рыба получше.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That fella looks mighty curious about that [c:bR]empty lane[c:]", "Кажется, этот малый очень интересуется той [c:bR]пустой линией[c:]", Language.Russian);

        }
    }
    public class EndlessAct2Mod
    {
        public static void RegisterTranslations()
