            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] submerges itself during its opponent's turn. While submerged, opposing creatures attack its owner directly, unless that creature has this sigil.", "[creature] погружается под воду во время хода противника. Пока она под водой, существа напротив атакуют её владельца напрямую, если только у них тоже нет этого символа.", Language.Russian);

        }
    }
    public class TooManySigilsMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for TooManySigils Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ants Minus", "Муравьи с вычетом", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cards power is equal to the amount of Ant's on field, minus this one.", "Сила этой карты равна числу муравьёв на поле за вычетом этой карты.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is damaged, It takes half the Damage it would normally.", "Когда эта карта получает урон, она получает лишь половину обычного урона.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bell Presser", "Звонарь", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This cards power is equal to the amount of times the bell has been rung.", "Сила этой карты равна числу ударов в колокол.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Borrowed Time", "Отсроченное время", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card perishes its Icecube is summoned if done in time, or else if over the EvolveTurns a corrupt version will be summoned.", "Если эта карта вовремя погибает, заключённое в ней во льду существо призывается. Если срок эволюции уже истёк, призывается его испорченная версия.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Coins Within", "Монеты внутри", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card is struck it provides 1 foil to its owner, as long as it lives anyway.", "Когда эта карта получает удар и выживает, её владелец получает 1 фойловую карту.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Covalesce", "Выздоровление", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is alive during your endstep, This card gains 1 health.", "Если карта с этим символом жива в конце вашего хода, она получает 1 ед. здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dead Pack", "Посмертный свёрток", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it provides 1 Item to its owner.", "Когда карта с этим символом погибает, её владелец получает 1 предмет.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fish Out Of Water", "Рыба без воды", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the turn, this card switches from having Airborne to Waterborne and so on. If neither are present will start with Waterborne.", "В конце хода эта карта меняет символ «Летун» на «Амфибия» и обратно. Если у неё нет ни одного из них, она сначала получает «Амфибия».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain One Battery", "Получить одну батарею", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains one Max Energy.", "Когда карта с этим символом разыгрывается, её владелец получает одну единицу максимальной энергии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Two Batteries", "Получить две батареи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains two Max Energy.", "Когда карта с этим символом разыгрывается, её владелец получает две единицы максимальной энергии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Three Batteries", "Получить три батареи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains three Max Energy.", "Когда карта с этим символом разыгрывается, её владелец получает три единицы максимальной энергии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Four Batteries", "Получить четыре батареи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains four Max Energy.", "Когда карта с этим символом разыгрывается, её владелец получает четыре единицы максимальной энергии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Five Batteries", "Получить пять батарей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains five Max Energy.", "Когда карта с этим символом разыгрывается, её владелец получает пять единиц максимальной энергии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gain Six Batteries", "Получить шесть батарей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner gains six Max Energy.", "Когда карта с этим символом разыгрывается, её владелец получает шесть единиц максимальной энергии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Locked", "Запертое сердце", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is damaged, It only takes 1 Damage.", "Когда карта с этим символом получает урон, она получает лишь 1 ед. урона.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is damaged, a card is added to your hand.", "Когда карта с этим символом получает урон, вам в руку добавляется карта.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is on the field during your endstep, a card is launched to one of your empty spaces.", "Если карта с этим символом находится на поле в конце вашего хода, в одну из ваших пустых ячеек попадает карта.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose One Battery", "Потерять одну батарею", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses one Max Energy.", "Когда карта с этим символом разыгрывается, её владелец теряет одну единицу максимальной энергии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Two Batteries", "Потерять две батареи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses two Max Energy.", "Когда карта с этим символом разыгрывается, её владелец теряет две единицы максимальной энергии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Three Batteries", "Потерять три батареи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses three Max Energy.", "Когда карта с этим символом разыгрывается, её владелец теряет три единицы максимальной энергии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Four Batteries", "Потерять четыре батареи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses four Max Energy.", "Когда карта с этим символом разыгрывается, её владелец теряет четыре единицы максимальной энергии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Five Batteries", "Потерять пять батарей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses five Max Energy.", "Когда карта с этим символом разыгрывается, её владелец теряет пять единиц максимальной энергии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lose Six Batteries", "Потерять шесть батарей", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, the owner loses six Max Energy.", "Когда карта с этим символом разыгрывается, её владелец теряет шесть единиц максимальной энергии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One Fourth Chance Instakill", "Случайная мгновенная смерть", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When this card would be attacked, there is a 25% chance that the striker perishes.", "Когда эту карту собираются атаковать, с вероятностью 25% атакующая карта погибает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rotting", "Гниение", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is alive during your endstep, this card loses 1 power and 1 health.", "Если карта с этим символом жива в конце вашего хода, она теряет 1 ед. силы и 1 ед. здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If a card bearing this sigil is on field during your endstep, this card moves in the direction inscribed in the sigil, and a card is played in its previous space.", "Если карта с этим символом находится на поле в конце вашего хода, она перемещается в указанном символом направлении, а на её прежнем месте разыгрывается карта.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is damaged, It takes 1 less Damage.", "Когда карта с этим символом получает урон, она получает на 1 ед. урона меньше.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Treasure Tracker", "Искатель сокровищ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At The end of the Owners turn, this card will provide the owner with 1 foil.", "В конце хода владельца эта карта даёт ему 1 фойловую карту.", Language.Russian);

        }
    }
    public class PizzaTowerCardsMod
