        {
            Debug.Log("Registering Translations for PizzaTowerCards Mod");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pizza Tower Expansion", "Дополнение Pizza Tower", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pizza Tower Themed Cards", "Карты по мотивам Pizza Tower", Language.Russian);
