    public class AgasMagnificusExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for AgasMagnificusExpansion Mod");

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aga's Magnificus Expansion", "Дополнение Магнификуса от Aga", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An unofficial expansion to the Magnificus Mod featuring [count] unique and colourful mages", "Неофициальное дополнение к моду Магнификуса с [count] уникальными и красочными магами.", Language.Russian);

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ascension Mage", "Маг вознесения", Language.Russian);
            MagnificusMod.RegisterCard("Ascension Mage", "Маг вознесения", "Utilising the power of time they grant knowledge and experience from far beyond", "Используя силу времени, они делятся знаниями и опытом далёких времён.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Utilising the power of time they grant knowledge and experience from far beyond", "Используя силу времени, они делятся знаниями и опытом далёких времён.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ash Mage", "Маг пепла", Language.Russian);
            MagnificusMod.RegisterCard("Ash Mage", "Маг пепла", "Ashes he sheds from his own body, scorching any and all who oppose him", "Пепел осыпается с его тела, обжигая каждого, кто ему противостоит.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ashes he sheds from his own body, scorching any and all who oppose him", "Пепел осыпается с его тела, обжигая каждого, кто ему противостоит.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Broken Egg", "Разбитое яйцо", Language.Russian);
            MagnificusMod.RegisterCard("Broken Egg", "Разбитое яйцо", "Only the greatest of trainers might find this treasure", "Только величайшие наставники смогут найти это сокровище.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "Только величайшие наставники смогут найти это сокровище.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chosen One", "Избранный", Language.Russian);
            MagnificusMod.RegisterCard("Chosen One", "Избранный", "My selected favourite. He still clings to his elders though...", "Мой избранный любимец. Хотя он всё ещё привязан к старшим...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My selected favourite. He still clings to his elders though...", "Мой избранный любимец. Хотя он всё ещё привязан к старшим...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanliness Mage", "Маг чистоты", Language.Russian);
            MagnificusMod.RegisterCard("Cleanliness Mage", "Маг чистоты", "The proudest of all my pupils. None come close to his bath superpowers", "Самый гордый из моих учеников. Никто не сравнится с его банными сверхспособностями.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The proudest of all my pupils. None come close to his bath superpowers", "Самый гордый из моих учеников. Никто не сравнится с его банными сверхспособностями.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleric", "Жрец", Language.Russian);
            MagnificusMod.RegisterCard("Cleric", "Жрец", "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "Силой своей божественной магии он принимает чужую боль и исцеляет раны.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With the virtue of his divine Magicks, he bears the pain of all and rids them of their wounds", "Силой своей божественной магии он принимает чужую боль и исцеляет раны.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Clock Mage", "Часовой маг", Language.Russian);
            MagnificusMod.RegisterCard("Clock Mage", "Часовой маг", "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "Маг, повелевающий самим временем. На пороге смерти он возвращается в прошлое и оживает.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wizard with a mastery over time itself. When he nears his demise, he reverts to the past, and comes back to life", "Маг, повелевающий самим временем. На пороге смерти он возвращается в прошлое и оживает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creature Collector", "Собиратель существ", Language.Russian);
            MagnificusMod.RegisterCard("Creature Collector", "Собиратель существ", "He had searched far and wide for his little companion, you see", "Видите ли, он повсюду искал своего маленького спутника.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He had searched far and wide for his little companion, you see", "Видите ли, он повсюду искал своего маленького спутника.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division Mage", "Маг разделения", Language.Russian);
            MagnificusMod.RegisterCard("Division Mage", "Маг разногласий", "So the card says at least... I assumed those freaks were long dealth with", "По крайней мере, так написано на карте... Я думал, с этими уродами давно покончили.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So the card says at least... I assumed those freaks were long dealth with", "По крайней мере, так написано на карте... Я думал, с этими уродами давно покончили.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Egg", "Яйцо", Language.Russian);
            MagnificusMod.RegisterCard("Egg", "Яйцо", "Only the greatest of trainers might find this treasure", "Только величайшие наставники смогут найти это сокровище.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Only the greatest of trainers might find this treasure", "Только величайшие наставники смогут найти это сокровище.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Druid", "Друид", Language.Russian);
            MagnificusMod.RegisterCard("Druid", "Друид", "Nature's primal devotee, feeding on sapped mana to cure his allies", "Первобытный служитель природы, исцеляющий союзников за счёт поглощённой маны.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nature's primal devotee, feeding on sapped mana to cure his allies", "Первобытный служитель природы, исцеляющий союзников за счёт поглощённой маны.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enchanter", "Зачарователь", Language.Russian);
            MagnificusMod.RegisterCard("Enchanter", "Зачарователь", "He spews cosmic magicks upon his demise, enchanting everything nearby", "Умирая, он извергает космическую магию, зачаровывая всё вокруг.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He spews cosmic magicks upon his demise, enchanting everything nearby", "Умирая, он извергает космическую магию, зачаровывая всё вокруг.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "EveryMage", "Универсальный маг", Language.Russian);
            MagnificusMod.RegisterCard("EveryMage", "Универсальный маг", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "mage", "маг", Language.Russian);
            MagnificusMod.RegisterCard("mage", "маг", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evoker", "Заклинатель", Language.Russian);
            MagnificusMod.RegisterCard("Evoker", "Заклинатель", "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "Зловещий кретин с отвратительным учением. Призываемые им змеи смертельно опасны.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ominous crettin of disgusting teachings. It's summonable snakes are of the deadliest caliber", "Зловещий кретин с отвратительным учением. Призываемые им змеи смертельно опасны.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Summon", "Призыв змеи", Language.Russian);
            MagnificusMod.RegisterCard("Serpent Summon", "Призыв змеи", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firebender", "Повелитель огня", Language.Russian);
            MagnificusMod.RegisterCard("Firebender", "Повелитель огня", "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "Бодрый в пылу сражения, он всегда ищет следующую жертву своих огненных шаров.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chipper in the heat of battle, he is always on the hunt for the next victim of his fireballs", "Бодрый в пылу сражения, он всегда ищет следующую жертву своих огненных шаров.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "Маг предвидения", Language.Russian);
            MagnificusMod.RegisterCard("Foresight Mage", "Маг предвидения", "As he gazes upon your future, attacks that may come his way he forever predicts", "Вглядываясь в ваше будущее, он всегда предсказывает атаки, которые могут обрушиться на него.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As he gazes upon your future, attacks that may come his way he forever predicts", "Вглядываясь в ваше будущее, он всегда предсказывает атаки, которые могут обрушиться на него.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foresight Mage", "Маг предвидения", Language.Russian);
            MagnificusMod.RegisterCard("Foresight Mage", "Маг предвидения", "Gazing into the future, he may see any body who dares make an approach", "Глядя в будущее, он видит любого, кто осмелится приблизиться.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gazing into the future, he may see any body who dares make an approach", "Глядя в будущее, он видит любого, кто осмелится приблизиться.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Glacier", "Ледник", Language.Russian);
            MagnificusMod.RegisterCard("Glacier", "Ледник", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gashadokuro", "Гасядокуро", Language.Russian);
            MagnificusMod.RegisterCard("Gashadokuro", "Гасядокуро", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Sentinel", "Самоцветный часовой", Language.Russian);
            MagnificusMod.RegisterCard("Gem Sentinel", "Самоцветный часовой", "the elite warrior unit enchanted with the aura of my moxen", "Отряд элитных воинов, зачарованный аурой моих моксов.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the elite warrior unit enchanted with the aura of my moxen", "Отряд элитных воинов, зачарованный аурой моих моксов.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grand Astrologer", "Великий звездочёт", Language.Russian);
            MagnificusMod.RegisterCard("Grand Astrologer", "Великий звездочёт", "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "Поле боя навсегда остаётся его игровой площадкой, а пространство — его оружием. Всё открыто его взору.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The battlefield is forever his playground, and space is his weapon. All is bare before him.", "Поле боя навсегда остаётся его игровой площадкой, а пространство — его оружием. Всё открыто его взору.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gravity Mage", "Маг гравитации", Language.Russian);
            MagnificusMod.RegisterCard("Gravity Mage", "Маг гравитации", "A master of the forces of gravity. Any and all mox bend to his unwavering will", "Мастер сил гравитации. Любой мокс подчиняется его несгибаемой воле.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A master of the forces of gravity. Any and all mox bend to his unwavering will", "Мастер сил гравитации. Любой мокс подчиняется его несгибаемой воле.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Illusion Mage", "Маг иллюзий", Language.Russian);
            MagnificusMod.RegisterCard("Illusion Mage", "Маг иллюзий", "Dawning his tricks and disguises, there is none scarier. At first glance", "С его уловками и маскировкой нет никого страшнее. На первый взгляд.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dawning his tricks and disguises, there is none scarier. At first glance", "С его уловками и маскировкой нет никого страшнее. На первый взгляд.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Infestation Mage", "Маг заражения", Language.Russian);
            MagnificusMod.RegisterCard("Infestation Mage", "Маг заражения", "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "Полагаю, такой захватчик, как вы, может позволить себе немного магии превращения.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I suppose a usurping challenger such as yourself could endulge in a dosage of skinwalking", "Полагаю, такой захватчик, как вы, может позволить себе немного магии превращения.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insulting Mirror", "Оскорбляющее зеркало", Language.Russian);
            MagnificusMod.RegisterCard("Insulting Mirror", "Оскорбляющее зеркало", "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "Магическая угроза носится вокруг, осыпая всех насмешками и дерзостями. Ваш гнев она обращает в собственную силу.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Magick Menace Flies About All Spitting Taunts And Hurling Cheeky Comments, Your Anger, It Channels Into A Strength Of It's Own", "Магическая угроза носится вокруг, осыпая всех насмешками и дерзостями. Ваш гнев она обращает в собственную силу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Iron Maiden", "Железная дева", Language.Russian);
            MagnificusMod.RegisterCard("Iron Maiden", "Железная дева", "My finest of paladins working the finest of hours. No soul goes through his grand wall", "Лучший из моих паладинов трудится часами. Ни одна душа не пройдёт сквозь его великую стену.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "My finest of paladins working the finest of hours. No soul goes through his grand wall", "Лучший из моих паладинов трудится часами. Ни одна душа не пройдёт сквозь его великую стену.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kickmoxer", "Моксобоксёр", Language.Russian);
            MagnificusMod.RegisterCard("Kickmoxer", "Моксобоксёр", "He dedicated his life to the art of combat, and may adapt to whomever he faces", "Он посвятил жизнь искусству боя и способен приспособиться к любому противнику.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He dedicated his life to the art of combat, and may adapt to whomever he faces", "Он посвятил жизнь искусству боя и способен приспособиться к любому противнику.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mass Grave", "Братская могила", Language.Russian);
            MagnificusMod.RegisterCard("Mass Grave", "Братская могила", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Agairan", "Мастер Агайран", Language.Russian);
            MagnificusMod.RegisterCard("Master Agairan", "Мастер Агайран", "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "Багровая химера. Учитель алхимии наполняет ядами, смертельнее которых не сыскать.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Crimson Chimera. The teacher of alchemy instills the deadliest of toxins", "Багровая химера. Учитель алхимии наполняет ядами, смертельнее которых не сыскать.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Bluetwo", "Мастер Блуту", Language.Russian);
            MagnificusMod.RegisterCard("Master Bluetwo", "Мастер Блуту", "The steel knight of sapphire. Even after death her psychic presence commands our foes", "Стальная рыцарка сапфира. Даже после смерти её дух управляет нашими врагами.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The steel knight of sapphire. Even after death her psychic presence commands our foes", "Стальная рыцарка сапфира. Даже после смерти её дух управляет нашими врагами.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Doublin", "Мастер Дублин", Language.Russian);
            MagnificusMod.RegisterCard("Master Doublin", "Мастер Дублин", "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "Мессия Повелителя костей. Учитель молитвы научился искусно красть сущность.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Bone Lord's messiah. The teacher of prayer has learned apt essence stealing.", "Мессия Повелителя костей. Учитель молитвы научился искусно красть сущность.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Megawizard", "Мегаволшебник", Language.Russian);
            MagnificusMod.RegisterCard("Megawizard", "Мегаволшебник", "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "Громоздок в своей угрозе, грозен в своей тупости. Такая грубая сила не продержится вечно.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hulking he is in his menace, meanacing he is in his dim. Such raw power would never last an eternity", "Громоздок в своей угрозе, грозен в своей тупости. Такая грубая сила не продержится вечно.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Meteorologist", "Метеоролог", Language.Russian);
            MagnificusMod.RegisterCard("Meteorologist", "Метеоролог", "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "Они внимательно наблюдают за вселенной, обрушивая метеорные бури на тех, кого сочтут нужным. Жестоки ли они? Или нет? Только они знают.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "They carefully observe the universe, casting storms of meteors upon whom they see fit. Maybe they're cruel? Maybe not? Only they know", "Они внимательно наблюдают за вселенной, обрушивая метеорные бури на тех, кого сочтут нужным. Жестоки ли они? Или нет? Только они знают.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Miniwizard", "Миниволшебник", Language.Russian);
            MagnificusMod.RegisterCard("Miniwizard", "Миниволшебник", "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "Маг, проклятый своим крошечным размером. Но не волнуйтесь, он нашёл решение.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mage accursed by it's miniscule size. Worry not though, to such ends he found a solution.", "Маг, проклятый своим крошечным размером. Но не волнуйтесь, он нашёл решение.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Phantom Thief", "Призрачный вор", Language.Russian);
            MagnificusMod.RegisterCard("Phantom Thief", "Призрачный вор", "A billowing cloud of crime, darting in and out, and stealing his foes", "Клубящееся облако преступности, которое то появляется, то исчезает, обкрадывая врагов.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A billowing cloud of crime, darting in and out, and stealing his foes", "Клубящееся облако преступности, которое то появляется, то исчезает, обкрадывая врагов.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Preformence Mage", "Маг пролога", Language.Russian);
            MagnificusMod.RegisterCard("Preformence Mage", "Маг пролога", "Who knows to what ends his mystery rabbit has been through", "Кто знает, через что пришлось пройти его загадочному кролику?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows to what ends his mystery rabbit has been through", "Кто знает, через что пришлось пройти его загадочному кролику?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Queen's Familiar", "Фамильяр королевы", Language.Russian);
            MagnificusMod.RegisterCard("Queen's Familiar", "Фамильяр королевы", "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "Величественная химера из прекрасных зверей. Она держит свои армии внутри себя.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A majestic chimera of beautiful beasts. It keeps it's armies close inside", "Величественная химера из прекрасных зверей. Она держит свои армии внутри себя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RisingHunger", "Нарастающий голод", Language.Russian);
            MagnificusMod.RegisterCard("RisingHunger", "Нарастающий голод", "", "");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roach Familiar", "Фамильяр-таракан", Language.Russian);
            MagnificusMod.RegisterCard("Roach Familiar", "Фамильяр-таракан", "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "Духовно созданный таракан. Его воля даёт ему способность воскресать! Которая в итоге не срабатывает.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A spiritually manufacrued cockroach. It's will allows it ressurection abilities! that ultimately fail.", "Духовно созданный таракан. Его воля даёт ему способность воскресать! Которая в итоге не срабатывает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Wizard", "Призрачный волшебник", Language.Russian);
            MagnificusMod.RegisterCard("Shadow Wizard", "Призрачный волшебник", "A mobster of the underseen. He calls the shadows to gang on it's foes", "Гангстер из подземного мира. Он зовёт тени, чтобы те набросились на врагов.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mobster of the underseen. He calls the shadows to gang on it's foes", "Гангстер из подземного мира. Он зовёт тени, чтобы те набросились на врагов.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shinobi", "Синоби", Language.Russian);
            MagnificusMod.RegisterCard("Shinobi", "Синоби", "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "Воины тьмы наносят удары исподтишка, там, где никто ничего не видит и не притязает.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warrior of the dark, They strike from the unawares, where nobody lays claim or sight", "Воины тьмы наносят удары исподтишка, там, где никто ничего не видит и не притязает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shower Mage", "Маг душа", Language.Russian);
            MagnificusMod.RegisterCard("Shower Mage", "Маг душа", "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "Изгой моей школы, и заслуженно! Его вонь можно описать только с помощью магии...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The outcast of my school and rightfully so! His levels of stentch could only be described with magic...", "Изгой моей школы, и заслуженно! Его вонь можно описать только с помощью магии...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sludge Mage", "Илистый маг", Language.Russian);
            MagnificusMod.RegisterCard("Sludge Mage", "Илистый маг", "An entity of unknown origins, powered off the ill spreading plague to all", "Существо неизвестного происхождения, питающееся болезнью и распространяющее заразу на всех.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An entity of unknown origins, powered off the ill spreading plague to all", "Существо неизвестного происхождения, питающееся болезнью и распространяющее заразу на всех.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sui-Sage", "Мудрец Суй", Language.Russian);
            MagnificusMod.RegisterCard("Sui-Sage", "Мудрец Суй", "The leader of a pack, soon to be packed away", "Вожак стаи, которого скоро отправят восвояси.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The leader of a pack, soon to be packed away", "Вожак стаи, которого скоро отправят восвояси.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summoner", "Призыватель", Language.Russian);
            MagnificusMod.RegisterCard("Summoner", "Призыватель", "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "Безумец, постигший искусство жизни: он создаёт её из ничего, да ещё с пугающим чутьём.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mad man of the arts of life, he creates it out of thin air. And with frightning sensibilities", "Безумец, постигший искусство жизни: он создаёт её из ничего, да ещё с пугающим чутьём.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Symmetrical Mage", "Симметричный маг", Language.Russian);
            MagnificusMod.RegisterCard("Symmetrical Mage", "Симметричный маг", "Everyone has two sides to them, you see. Especially once they mess with my temper", "Видите ли, у каждого есть две стороны. Особенно когда меня выводят из себя.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone has two sides to them, you see. Especially once they mess with my temper", "Видите ли, у каждого есть две стороны. Особенно когда меня выводят из себя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Teleportation Mage", "Маг телепортации", Language.Russian);
            MagnificusMod.RegisterCard("Teleportation Mage", "Маг телепортации", "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "Вестник бесконечных порталов, беспрестанно скачущий по полю боя и отражающий удары.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A herald of endless portals, jolting around the battlefield in infinitum and negating incoming strikes", "Вестник бесконечных порталов, беспрестанно скачущий по полю боя и отражающий удары.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torrent Mage", "Маг потока", Language.Russian);
            MagnificusMod.RegisterCard("Torrent Mage", "Маг потока", "An apprentice of the ocean utilising it to drown the lands and the terrain above", "Ученик океана, который использует его, чтобы затопить сушу и местность над ней.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An apprentice of the ocean utilising it to drown the lands and the terrain above", "Ученик океана, который использует его, чтобы затопить сушу и местность над ней.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Untamed Dragon", "Неукрощённый дракон", Language.Russian);
            MagnificusMod.RegisterCard("Untamed Dragon", "Неукрощённый дракон", "Legends whisper this beast, was once a companion to the mox master Goranj", "Легенды гласят, что этот зверь когда-то был спутником Зелёнжевого, мастера моксов.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Legends whisper this beast, was once a companion to the mox master Goranj", "Легенды гласят, что этот зверь когда-то был спутником Зелёнжевого, мастера моксов.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Warlock", "Чернокнижник", Language.Russian);
            MagnificusMod.RegisterCard("Warlock", "Чернокнижник", "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "Почерневший волшебник, изучающий магию крови. Он превращает кровотечение в ужасное оружие.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A blackened wizard pursuiting the studies of the blood magicks. Such bleeding he turns into a horrible weapon", "Почерневший волшебник, изучающий магию крови. Он превращает кровотечение в ужасное оружие.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wicked Witch", "Злая ведьма", Language.Russian);
            MagnificusMod.RegisterCard("Wicked Witch", "Злая ведьма", "A flying jesting witch, laughing your sorrows and posioning your armies", "Летающая ведьма-насмешница, которая смеётся над вашими печалями и отравляет ваши армии.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A flying jesting witch, laughing your sorrows and posioning your armies", "Летающая ведьма-насмешница, которая смеётся над вашими печалями и отравляет ваши армии.", Language.Russian);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Acid Aura", "Кислотная аура", Language.Russian);
            MagnificusMod.RegisterAbility("Acid Aura", "Кислотная аура");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] deals 1 damage to the creature opposing it every turn", "[creature] наносит 1 ед. урона существу напротив каждый ход.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awakening", "Пробуждение", Language.Russian);
            MagnificusMod.RegisterAbility("Awakening", "Пробуждение");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it's owner chooses an ally creature to evolve into a higher form.", "Когда [creature] разыгрывается, её владелец выбирает союзное существо для превращения в высшую форму.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Backfire Strike", "Обратный удар", Language.Russian);
            MagnificusMod.RegisterAbility("Backfire Strike", "Обратный удар");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] damages creatures that oppose those it attacks.", "[creature] наносит урон существам на своей стороне, стоящим напротив её целей.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Blood Guzzler", "Бухарик кровью", Language.Russian);
            MagnificusMod.RegisterAbility("Blood Guzzler", "Бухарик кровью");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] deals damage, it gains 1 health for each damage dealt.", "Когда [creature] наносит урон, она получает 1 ед. здоровья за каждую единицу нанесённого урона.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brute Parasite", "Жестокий паразит", Language.Russian);
            MagnificusMod.RegisterAbility("Brute Parasite", "Жестокий паразит");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, an Egg is created on the opposing space.", "Когда [creature] разыгрывается, в ячейке напротив создаётся Яйцо.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Deluge", "Потоп", Language.Russian);
            MagnificusMod.RegisterAbility("Deluge", "Потоп");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, opponent creatures with 0 power drown and get given the Waterborne sigil.", "Когда [creature] разыгрывается, существа противника с силой 0 погружаются и получают символ «Амфибия».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Division", "Деление", Language.Russian);
            MagnificusMod.RegisterAbility("Division", "Деление");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] splits into 2 identical clones, each bearing half of it's original stats.", "После атаки [creature] делится на 2 одинаковых клона, каждый из которых имеет половину её исходных характеристик.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sentry", "Часовой", Language.Russian);
            MagnificusMod.RegisterAbility("Sentry", "Часовой");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a creature moves into the space opposing [creature], they are dealt 1 damage.", "Когда существо перемещается в ячейку напротив [creature], оно получает 1 ед. урона.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, let one never underestimate the speed of a Foresight Mage.", "Ах, никогда не стоит недооценивать скорость Мага предвидения.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healing Aura", "Аура исцеления", Language.Russian);
            MagnificusMod.RegisterAbility("Healing Aura", "Аура исцеления");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] heals nearby allied creatures. The healing is proportionate to it's power.", "[creature] исцеляет соседних союзных существ. Лечение пропорционально её силе.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart Stealer", "Похититель сердец", Language.Russian);
            MagnificusMod.RegisterAbility("Heart Stealer", "Похититель сердец");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "when [creature] kills a creature, it gets added to your hand.", "Когда [creature] убивает существо, убитое существо добавляется вам в руку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignis Incant", "Огненное заклятье", Language.Russian);
            MagnificusMod.RegisterAbility("Ignis Incant", "Огненное заклятье");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 blood for [creature] to deal 2 damage to a chosen opposing slot.", "Заплатите 1 кровь, чтобы [creature] нанесла 2 ед. урона выбранной ячейке противника.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Intimidate", "Запугать", Language.Russian);
            MagnificusMod.RegisterAbility("Intimidate", "Запугать");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is placed on the board, the creature opposing it will flee to their right.", "Когда [creature] помещается на доску, существо напротив убегает вправо от себя.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lonesome", "Одинокий", Language.Russian);
            MagnificusMod.RegisterAbility("Lonesome", "Одинокий");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains +1 power for each adjacent empty space.", "[creature] получает +1 силы за каждую соседнюю пустую клетку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Magic Burst", "Магический всплеск", Language.Russian);
            MagnificusMod.RegisterAbility("Magic Burst", "Магический всплеск");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After perishing, creatures adjascent to [creature] have their powers increased by 1.", "После гибели [creature] сила соседних существ увеличивается на 1.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Psystrike", "Психический удар", Language.Russian);
            MagnificusMod.RegisterAbility("Psystrike", "Психический удар");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After [creature] perishes, it manipulates the creature opposing it to strike both of it's adjascent allies.", "После гибели [creature] заставляет существо напротив атаковать обоих его соседних союзников.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Serpent Master", "Повелитель змей", Language.Russian);
            MagnificusMod.RegisterAbility("Serpent Master", "Повелитель змей");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of every turn, [creature] spawns a Summon Serpent on a space of it's owner's choosing. A Summon Serpent is defined as: 1 power, 1 health.", "В начале каждого хода [creature] создаёт карту «Призыв змеи» в ячейке по выбору владельца. У карты «Призыв змеи» 1 ед. силы и 1 ед. здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shadow Strike", "Призрачный удар", Language.Russian);
            MagnificusMod.RegisterAbility("Shadow Strike", "Призрачный удар");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] calls upon the shadows of creatures adjascent to it's target to strike it as well.", "[creature] призывает тени существ по соседству с целью, чтобы и они атаковали её.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tidal Lock", "Синхронное вращение", Language.Russian);
            MagnificusMod.RegisterAbility("Tidal Lock", "Синхронное вращение");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the beginning of it's owner's turn, [creature] will pull small creatures, like squirrels, into it's orbit.", "В начале хода владельца [creature] притягивает на свою орбиту маленьких существ, например Белок.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wizard's Heart", "Сердце волшебника", Language.Russian);
            MagnificusMod.RegisterAbility("Wizard's Heart", "Сердце волшебника");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Mox card corresponding to the current gems you control takes it's place.", "Когда [creature] погибает, её место занимает карта мокса, соответствующая контролируемым вами самоцветам.", Language.Russian);

        }
    }
    public class MagModExpansionMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for MagModExpansion Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beaver's Defense", "Защита бобра", Language.Russian);
            MagnificusMod.RegisterCard("Beaver's Defense", "Защита бобра", "Curating defensive dams upon use, not bad for a dire situation.", "Создаёт защитные плотины при использовании. Неплохо для трудной ситуации.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Curating defensive dams upon use, not bad for a dire situation.", "Создаёт защитные плотины при использовании. Неплохо для трудной ситуации.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bomb Sage", "Мудрец-бомбист", Language.Russian);
            MagnificusMod.RegisterCard("Bomb Sage", "Мудрец-бомбист", "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "Когда на этого мудреца нападают, он славится тем, что взрывается... В прямом и переносном смысле.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When attacked, this sage is known for blowing up.. Literally and metaphorically.", "Когда на этого мудреца нападают, он славится тем, что взрывается... В прямом и переносном смысле.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Boxing Champ", "Чемпион по боксу", Language.Russian);
            MagnificusMod.RegisterCard("Boxing Champ", "Чемпион по боксу", "Rejecting the use of wands, this champion prefers to settle things with his fists.", "Отказываясь от волшебных палочек, этот чемпион предпочитает решать всё кулаками.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejecting the use of wands, this champion prefers to settle things with his fists.", "Отказываясь от волшебных палочек, этот чемпион предпочитает решать всё кулаками.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brontosaurus", "Бронтозавр", Language.Russian);
            MagnificusMod.RegisterCard("Brontosaurus", "Бронтозавр", "I LOVE DINO MOD!!!!!", "Я ОБОЖАЮ МОД ДИНОЗАВРОВ!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "Я ОБОЖАЮ МОД ДИНОЗАВРОВ!!!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheese Wizard", "Сырный волшебник", Language.Russian);
            MagnificusMod.RegisterCard("Cheese Wizard", "Сырный волшебник", "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "Будучи обученными поварами-магами, Сырные волшебники используют ум и мистические силы для достижения своих целей.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "As trained Chef-Magi, Cheese Wizards use their intellect and Mysticality to accomplish their goals.", "Будучи обученными поварами-магами, Сырные волшебники используют ум и мистические силы для достижения своих целей.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cheezling", "Сырок", Language.Russian);
            MagnificusMod.RegisterCard("Cheezling", "Сырок", "With cheese like this, who needs friends?", "С таким сыром кому нужны друзья?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "With cheese like this, who needs friends?", "С таким сыром кому нужны друзья?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Telepathy", "Телепатия", Language.Russian);
            MagnificusMod.RegisterCard("Telepathy", "Телепатия", "A pupil can gather all the resources they need through sheer will alone.", "Ученик способен собрать все необходимые ресурсы одной лишь силой воли.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A pupil can gather all the resources they need through sheer will alone.", "Ученик способен собрать все необходимые ресурсы одной лишь силой воли.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Direct Hit", "Прямое попадание", Language.Russian);
            MagnificusMod.RegisterCard("Direct Hit", "Прямое попадание", "Upon being casted, your opponent will instantly take three damage.", "При применении противник немедленно получит три единицы урона.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Upon being casted, your opponent will instantly take three damage.", "При применении противник немедленно получит три единицы урона.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mysterious Egg", "Таинственное яйцо", Language.Russian);
            MagnificusMod.RegisterCard("Mysterious Egg", "Таинственное яйцо", "Who knows what could hatch from this egg...", "Кто знает, кто может вылупиться из этого яйца...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Who knows what could hatch from this egg...", "Кто знает, кто может вылупиться из этого яйца...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faceless", "Безликий", Language.Russian);
            MagnificusMod.RegisterCard("Faceless", "Безликий", "A hollow shell of a mage, desperately looking for something to call its own.", "Пустая оболочка мага, отчаянно ищущая что-то, что можно назвать своим.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hollow shell of a mage, desperately looking for something to call its own.", "Пустая оболочка мага, отчаянно ищущая что-то, что можно назвать своим.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Faker", "Подделыватель", Language.Russian);
            MagnificusMod.RegisterCard("Faker", "Подделыватель", "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "Ложь. Обман. Отрицание. На что только не пойдёт Притворщик, чтобы выйти сухим из воды...");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lie. Cheat. Deny. The lengths the Faker will go to in order to escape unharmed...", "Ложь. Обман. Отрицание. На что только не пойдёт Притворщик, чтобы выйти сухим из воды...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Figletar", "Фиглетар", Language.Russian);
            MagnificusMod.RegisterCard("Figletar", "Фиглетар", "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "Волшебник, обрёкший злого короля на ужасную участь. Он кое-что смыслит в боях на ринге.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A wiz who brought an evil king to a terrible fate, this one knows a thing or two in the ring.", "Волшебник, обрёкший злого короля на ужасную участь. Он кое-что смыслит в боях на ринге.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Firestarter", "Поджигатель", Language.Russian);
            MagnificusMod.RegisterCard("Firestarter", "Поджигатель", "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "Будьте осторожны с этим заклинанием: ученики сообщают, что на дуэльной площадке может стать жарковато.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Careful when casting this one, pupils have reported that the dueling grounds can get a little toasty.", "Будьте осторожны с этим заклинанием: ученики сообщают, что на дуэльной площадке может стать жарковато.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Fridge Mage", "Маг холодильника", Language.Russian);
            MagnificusMod.RegisterCard("Fridge Mage", "Маг холодильника", "Its cold atmosphere will chill foes, weakening their offensive power.", "Его ледяная атмосфера охлаждает врагов, ослабляя их атакующую силу.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Its cold atmosphere will chill foes, weakening their offensive power.", "Его ледяная атмосфера охлаждает врагов, ослабляя их атакующую силу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gembro", "Самоцветный братан", Language.Russian);
            MagnificusMod.RegisterCard("Gembro", "Самоцветный братан", "The ability to tank any hit once, this pupil has high gusto.", "Этот ученик способен один раз выдержать любой удар. Смелости ему не занимать.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The ability to tank any hit once, this pupil has high gusto.", "Этот ученик способен один раз выдержать любой удар. Смелости ему не занимать.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gem Tick", "Самоцветный клещ", Language.Russian);
            MagnificusMod.RegisterCard("Gem Tick", "Самоцветный клещ", "An elusive tick, which grants power to others via its mox body.", "Неуловимый клещ, который дарует силу другим благодаря своему телу из мокса.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An elusive tick, which grants power to others via its mox body.", "Неуловимый клещ, который дарует силу другим благодаря своему телу из мокса.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ghost Dinosaur", "Призрачный динозавр", Language.Russian);
            MagnificusMod.RegisterCard("Ghost Dinosaur", "Призрачный динозавр", "I LOVE DINO MOD!!!!!", "Я ОБОЖАЮ МОД ДИНОЗАВРОВ!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "Я ОБОЖАЮ МОД ДИНОЗАВРОВ!!!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Third Eye", "Третий глаз", Language.Russian);
            MagnificusMod.RegisterCard("Third Eye", "Третий глаз", "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "Силой третьего глаза заклинание позволяет выбрать карту из оставшейся колоды и добавить её в руку.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harnessing the power of a third eye, the spell allows its caster to gain any card that it has.", "Силой третьего глаза заклинание позволяет выбрать карту из оставшейся колоды и добавить её в руку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Baseball Mage", "Бейсбольный маг", Language.Russian);
            MagnificusMod.RegisterCard("Baseball Mage", "Бейсбольный маг", "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "Палочка этого мага служит также бейсбольной битой. На удивление прочная.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage's wand doubles as a baseball bat as well. It's suprisingly durable.", "Палочка этого мага служит также бейсбольной битой. На удивление прочная.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Golem", "Ледяной голем", Language.Russian);
            MagnificusMod.RegisterCard("Ice Golem", "Ледяной голем", "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "Этот зверь родом с ледяной горной вершины, и таяние его, похоже, никогда не тревожило.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hailing from an icy mountaintop, melting never seemed to phase this brute.", "Этот зверь родом с ледяной горной вершины, и таяние его, похоже, никогда не тревожило.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looting Bandit", "Бандит-мародёр", Language.Russian);
            MagnificusMod.RegisterCard("Looting Bandit", "Бандит-мародёр", "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "Далёкая последовательница валькирий Ораннего хозяина, которая учится быть похожей на них.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A distant follower of the Master Orlu's Valkyries, training to become just like them.", "Далёкая последовательница валькирий Ораннего хозяина, которая учится быть похожей на них.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mage", "Маг маны", Language.Russian);
            MagnificusMod.RegisterCard("Mana Mage", "Маг маны", "Brings together the energy that emits from Mana to deliver powerful strikes.", "Собирает энергию, исходящую от маны, чтобы наносить мощные удары.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brings together the energy that emits from Mana to deliver powerful strikes.", "Собирает энергию, исходящую от маны, чтобы наносить мощные удары.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pondering Pupil", "Задумчивый ученик", Language.Russian);
            MagnificusMod.RegisterCard("Pondering Pupil", "Задумчивый ученик", "It draws from your gem pile using the powers of its mind alone.", "Берёт карты из вашей стопки самоцветов одной лишь силой мысли.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It draws from your gem pile using the powers of its mind alone.", "Берёт карты из вашей стопки самоцветов одной лишь силой мысли.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror Mage", "Зеркальный маг", Language.Russian);
            MagnificusMod.RegisterCard("Mirror Mage", "Зеркальный маг", "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "Свет мой, зеркальце, скажи: кто из Переписчиков всех лучше?");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mirror, mirror, on the wall, who's the best Scrybe of them all?", "Свет мой, зеркальце, скажи: кто из Переписчиков всех лучше?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whack-A-Mage", "Стукни мага", Language.Russian);
            MagnificusMod.RegisterCard("Whack-A-Mage", "Стукни мага", "Always popping up to cause mischief whenever he can.", "При каждом удобном случае появляется, чтобы нашкодить.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Always popping up to cause mischief whenever he can.", "При каждом удобном случае появляется, чтобы нашкодить.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mononykus", "Мононик", Language.Russian);
            MagnificusMod.RegisterCard("Mononykus", "Мононик", "I LOVE DINO MOD!!!!!", "Я ОБОЖАЮ МОД ДИНОЗАВРОВ!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "Я ОБОЖАЮ МОД ДИНОЗАВРОВ!!!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PLUTO", "ПЛУТОН", Language.Russian);
            MagnificusMod.RegisterCard("PLUTO", "ПЛУТОН", "Hmph. So this is where that one went.", "Хмф. Вот, значит, куда он делся.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph. So this is where that one went.", "Хмф. Вот, значит, куда он делся.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protect", "Защищать", Language.Russian);
            MagnificusMod.RegisterCard("Protect", "Защищать", "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "Попали в беду? Это заклинание полностью защитит одну из ваших карт от следующей атаки.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In a tough spot? This spell will give one of your cards full immunity to the next attack it recieves.", "Попали в беду? Это заклинание полностью защитит одну из ваших карт от следующей атаки.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pterodactyl", "Птеродактиль", Language.Russian);
            MagnificusMod.RegisterCard("Pterodactyl", "Птеродактиль", "I LOVE DINO MOD!!!!!", "Я ОБОЖАЮ МОД ДИНОЗАВРОВ!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "Я ОБОЖАЮ МОД ДИНОЗАВРОВ!!!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rabbid Sage", "Кролик-мудрец", Language.Russian);
            MagnificusMod.RegisterCard("Rabbid Sage", "Кролик-мудрец", "A raving magician with a field of electricity at his disposal.", "Неистовый маг, распоряжающийся электрическим полем.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A raving magician with a field of electricity at his disposal.", "Неистовый маг, распоряжающийся электрическим полем.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelemox", "Скелемокс", Language.Russian);
            MagnificusMod.RegisterCard("Skelemox", "Скелемокс", "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "Бедный скелет под контролем Зелёного мокса. Мне его почти жаль.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A poor skeleton being controlled by a Green Mox, I almost feel bad for it.", "Бедный скелет под контролем Зелёного мокса. Мне его почти жаль.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Slime Wiz", "Слизевый маг", Language.Russian);
            MagnificusMod.RegisterCard("Slime Wiz", "Слизевый маг", "It'll use the slime against the enemies, to drop their attack whence struck.", "Использует слизь против врагов, снижая их атаку, когда они его бьют.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It'll use the slime against the enemies, to drop their attack whence struck.", "Использует слизь против врагов, снижая их атаку, когда они его бьют.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smug Witch", "Самодовольная ведьма", Language.Russian);
            MagnificusMod.RegisterCard("Smug Witch", "Самодовольная ведьма", "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "Самодовольнейший ученик во всём краю. По легенде, его Самодовольному броску нет равных.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The smuggest pupil in all the land. Legends say his Smug Throw is unrivaled.", "Самодовольнейший ученик во всём краю. По легенде, его Самодовольному броску нет равных.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Summon Spear", "Копьё призыва", Language.Russian);
            MagnificusMod.RegisterCard("Summon Spear", "Копьё призыва", "Roots up a spear from the ground, acting as a sturdy counter.", "Вырывает из земли копьё, служащее надёжным средством противодействия.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Roots up a spear from the ground, acting as a sturdy counter.", "Вырывает из земли копьё, служащее надёжным средством противодействия.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spike Mage", "Маг шипов", Language.Russian);
            MagnificusMod.RegisterCard("Spike Mage", "Маг шипов", "This mage learned from the best of my Pike Mage's Scarecrows.", "Этот маг учился у лучшего из Пугал моего Мага-копейщика.");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This mage learned from the best of my Pike Mage's Scarecrows.", "Этот маг учился у лучшего из Пугал моего Мага-копейщика.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "T-Rex", "Тираннозавр", Language.Russian);
            MagnificusMod.RegisterCard("T-Rex", "Тираннозавр", "I LOVE DINO MOD!!!!!", "Я ОБОЖАЮ МОД ДИНОЗАВРОВ!!!!!");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I LOVE DINO MOD!!!!!", "Я ОБОЖАЮ МОД ДИНОЗАВРОВ!!!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Virtual King", "Виртуальный король", Language.Russian);
            MagnificusMod.RegisterCard("Virtual King", "Виртуальный король", "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "Самопровозглашённый правитель виртуальных земель, который не признаёт жалких «правил карточной игры».");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Self-proclaimed ruler of the virtual lands who won't abide to measly “card game rules”.", "Самопровозглашённый правитель виртуальных земель, который не признаёт жалких «правил карточной игры».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moron Core", "Ядро идиота", Language.Russian);
            MagnificusMod.RegisterCard("Moron Core", "Ядро идиота", "An odd core hailing from an abandoned factory, hates the word \"moron\".", "Странное ядро из заброшенной фабрики. Ненавидит слово «идиот».");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An odd core hailing from an abandoned factory, hates the word \"moron\".", "Странное ядро из заброшенной фабрики. Ненавидит слово «идиот».", Language.Russian);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Smughtro's MagMod Expansion", "Расширение MagMod от Smughtro", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Adds 19 common cards, 7 rare cards, 7 spells, and 6 token cards to Magnificus Mod.", "Добавляет в мод Магнификуса 19 обычных карт, 7 редких карт, 7 заклинаний и 6 карт-фишек.", Language.Russian);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Death Assist", "Посмертная помощь", Language.Russian);
            MagnificusMod.RegisterAbility("Death Assist", "Посмертная помощь");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, it will deal 3 damage to the opponent.", "Когда карта с этим символом погибает, она наносит 3 ед. урона противнику.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Emmental Elemental", "Эмментальский элементаль", Language.Russian);
            MagnificusMod.RegisterAbility("Emmental Elemental", "Эмментальский элементаль");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, summon a Cheezling.", "Когда карта с этим символом разыгрывается, она призывает Сырок.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "First Strike", "Первый удар", Language.Russian);
            MagnificusMod.RegisterAbility("First Strike", "Первый удар");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, it will instantly attack the opposing lane. If there are no opposing cards, no damage will be dealt.", "Когда карта с этим символом разыгрывается, она немедленно атакует ряд напротив. Если там нет карты противника, урон не наносится.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Unknown Hatching", "Неизвестное вылупление", Language.Russian);
            MagnificusMod.RegisterAbility("Unknown Hatching", "Неизвестное вылупление");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of your turn, a card bearing this sigil will hatch into a random dinosaur.", "В начале хода владельца карта с этим символом вылупляется и превращается в случайного динозавра.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Healthy Death", "Здоровая смерть", Language.Russian);
            MagnificusMod.RegisterAbility("Healthy Death", "Здоровая смерть");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil perishes, the cards to the left and right of the sigil bearer heal 1 health.", "Когда карта с этим символом погибает, карты слева и справа от неё восстанавливают по 1 ед. здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mana Mess", "Хаос маны", Language.Russian);
            MagnificusMod.RegisterAbility("Mana Mess", "Хаос маны");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is played, draw a random non-rare Mana costing card.", "Когда карта с этим символом разыгрывается, возьмите случайную не редкую карту со стоимостью в мане.", Language.Russian);

        }
    }
    public class FloweysMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for FloweysMod Mod");


            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flowey", "Флауи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A fanatical leader hell-bent on bringing about the apocalypse by reviving the great Cthulhu through behind-the-scenes scheming.", "Фанатичный лидер, одержимый идеей устроить апокалипсис, воскресив великого Ктулху с помощью тайных интриг.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You Idiot", "Ты идиот", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an Idiot if you think you can defeat me!", "Ты настоящий идиот, если думаешь, что сможешь меня победить!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Omega Flowey", "Омега Флауи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You really are an idiot.", "Ты и правда идиот.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Patience", "Терпение", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "patient.", "терпеливый.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bravery", "Храбрость", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Brave.", "Храбрый.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Integrity", "Честность", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "integrant.", "Честный.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perseverence", "Упорство", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Persevering.", "Упорный.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kindness", "Доброта", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Kind.", "Добрый.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice", "Справедливость", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Justice.", "Справедливость.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy- Uh i meant Are you ready to Die?", "Приветик! То есть... Ты готов умереть?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Howdy! it's me Flowey, Flowey the Flower!", "Приветик! Это я, Флауи, цветочек Флауи!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You know whats going on here, dont you?", "Ты ведь знаешь, что здесь происходит?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You just wanted to see me suffer[c:0]!", "Ты просто хотел увидеть, как я страдаю[c:0]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do You know that ive been watching you?", "Ты знал, что я за тобой наблюдал?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well i took over Inscryption now!", "Что ж, теперь я захватил Inscryption!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "and i know what Secrets are hiding beneath Inscryption...", "И я знаю, какие секреты скрываются за Inscryption...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Now nothing stands in my Way to take over the World now!", "Теперь ничто не помешает мне захватить мир!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What do you think this Fight was about?", "Как ты думаешь, для чего была эта битва?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I just used it as a cover to snoop through Inscryptions Files!", "Я просто использовал её как прикрытие, чтобы покопаться в файлах Inscryption!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And your PC of course!", "И твой компьютер, конечно!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "And you may have noticed, BUT iam now connected to the Internet!", "И, возможно, ты заметил, НО теперь я подключён к интернету!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So now its time to begin Uploading Inscryption!", "А теперь пора начать загрузку Inscryption!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You REALLY are an Idiot!", "Ты ДЕЙСТВИТЕЛЬНО идиот!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I don't even need the Power of Human Souls if i just use the OLD_DATA!", "Мне даже не нужна сила человеческих душ, если я использую СТАРЫЕ_ДАННЫЕ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Do you know what you are achieving by this? Nothing", "[c:bR]Знаешь, чего ты этим добьёшься? Ничего.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]You cant get rid of me! No matter what you do, i will always be there!", "[c:bR]Тебе от меня не избавиться! Что бы ты ни делал, я всегда буду здесь!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Th- The Souls?", "[c:bR]Д-души?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]wh- where are my Powers?", "[c:bR]Г-где мои силы?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHAT HAVE YOU DONE?!", "[c:bR]ЧТО ТЫ НАДЕЛАЛ?!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Floweys Defence dropped to [c:bR]0!", "Защита Флауи упала до [c:bR]0!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOOOOOO", "[c:bR]НЕЕЕЕТ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "What just happened...", "Что только что произошло...?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hmph seemms you have won this time...", "Хмф, похоже, на этот раз ты победил...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]NOBODY IS GOING TO HELP YOU!", "[c:bR]НИКТО ТЕБЕ НЕ ПОМОЖЕТ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP CALLING FOR [c:bR]HELP!", "ПЕРЕСТАНЬ ЗВАТЬ НА [c:bR]ПОМОЩЬ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Did you really think id let you kill me so easily?", "[c:bR]Ты правда думал, что я позволю тебе так легко меня убить?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]what the-", "[c:bR]Что за...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Flowey thought they could just use me...", "[c:bR]Флауи думал, что может просто использовать меня...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]He didnt even know what I am!", "[c:bR]Он даже не знал, что я такое!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]But now IAM in control...", "[c:bR]Но теперь всё под МОИМ контролем...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]How pathetic of him to not set his HP to Infinite... I won't make that mistake", "[c:bR]Как жалко: он не сделал своё здоровье бесконечным... Я такой ошибки не совершу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Try all you want you can't kill me!", "[c:bR]Старайся сколько хочешь, тебе меня не убить!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Now lets see what this does...", "[c:bR]А теперь посмотрим, что это делает...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]WHY CANT I UNDO THIS???", "[c:bR]ПОЧЕМУ Я НЕ МОГУ ЭТО ОТМЕНИТЬ???", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SEEING YOU DIE OVER AND OVER AGIAN IS REALLY [c:bR]FUN!", "СМОТРЕТЬ, КАК ТЫ УМИРАЕШЬ СНОВА И СНОВА, ТАК [c:bR]ВЕСЕЛО!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOT EVEN A SINGLE POINT OF DAMAGE!", "НИ ЕДИНОЙ ЕДИНИЦЫ УРОНА!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SOMEONE LIKE [c:bR]YOUCANT BEAT ME!", "ТАКОЙ, КАК [c:bR]ТЫ, НЕ МОЖЕТ МЕНЯ ПОБЕДИТЬ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[c:bR]Starvation wont interrupt this fight!", "[c:bR]Голод не прервёт этот бой!", Language.Russian);


        }
    }
    public class UndertaleMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for UndertaleMod Mod");

            // Card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Card Pack:U", "Набор карт: Undertale", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Aaron", "Аарон", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, Aaron the bold, aaron the beautiful. can you manage to take your eyes off his muscles?", "Ах да, смелый Аарон, прекрасный Аарон. Можете оторвать взгляд от его мышц?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Alphys", "Альфис", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr. Alphys is responsible for the creation of some of the more 'unnerving' individuals you've seen here... or should I say... MULTI-viduals.", "Доктор Альфис создала некоторых из наиболее «жутких» особей, встреченных вами здесь... Или, может, сказать... МНОГОособей?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loveable, yet pestulant. The duality of this creature is unparalleled.", "Милое, но раздражающее. Двойственность этого существа не знает равных.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Asgore", "Азгор", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The king of monsters... he truly is an intimidating force of brute strength, but also... compassion?", "Король монстров... Внушительная грубая сила, а ещё... сострадание?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "asriel dreemurr", "Азриэль Дримурр", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the most powerful being in the underground... hopefully you find some use for him.", "Сильнейшее существо Подземелья... надеюсь, вы найдёте ему применение.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Astigmatism", "Астигматизм", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The frustrating astigmatism... it can't make up its mind.", "Досадный Астигматизм... он никак не может определиться.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gaster Blaster", "Бластер Гастера", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Block of Ice", "Глыба льда", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A peculiarly large ice cube... Who knows what could be inside.", "Необычайно большой куб льда... Кто знает, что внутри.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chara", "Чара", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy", "Догами", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogamy and his wife, Dogaressa, love to tag-team the battlefield. Just don't let one of them perish...", "Догами и его жена Догаресса любят сражаться вместе. Только не дайте никому из них погибнуть...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogaressa", "Догаресса", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doggo", "Догго", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah, the blind doggo... He leaps towards any sound of movement.", "Ах, слепой пёс... Он бросается на любой звук движения.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "doodlebog", "Дудлбог", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy", "Манекен", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the bland dummy... not as charismatic as its 'mad' counterpart", "Скучный манекен... ему далеко до харизмы его «безумного» собрата.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amalgamate", "Амальгама", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Endogeny", "Эндогения", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "null", "нет", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Froggit", "Последний Фроггит", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the ultimate boss of froggits... Still as easily fooled as its lesser evolved kin.", "Ах да, главный из фроггитов... Его так же легко обмануть, как и менее развитых сородичей.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Frisk", "Фриск", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Froggit", "Фроггит", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, as shy as they come... the froggit wishes not to engage in conflict. how unfortunate.", "Ах, сама застенчивость... фроггит не желает вступать в конфликт. Какая досада.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "W.D.Gaster", "У. Д. Гастер", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "glyde", "Глайд", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Such a narcisist, it can only attack if a card is in front of it to watch.", "Такой нарцисс, что атакует лишь тогда, когда перед ним стоит карта, которая может на него смотреть.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Greater Dog", "Большой пёс", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "truly and nobly adequate, it is the highest form of evolution a canine can become.", "Поистине достойный и благородный, он представляет высшую форму развития собаки.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Gyftrot", "Гифтрот", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Be kind to this creature, it has gone through enough.", "Будьте добры к этому существу, ему и так досталось.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ice Wolf", "Ледяной волк", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, this buff creature spawns a block of ice upon death.", "Ах да, это мускулистое существо создаёт глыбу льда после смерти.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Icecap", "Айс Кэп", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Jerry", "Джерри", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Just ditch him already.", "Да бросьте вы его уже.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Knight Knight", "Рыцарь-ночник", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the forboding knight knight... a sentinel of sleep. She is relentless in her conquest..", "Ах, зловещая Найт-Найт... страж сна. Она не знает пощады в своих завоеваниях...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lemon Bread", "Лимонный хлеб", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lesser Dog", "Маленький пёс", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A mediocre canine at best... at least in its current form.", "В лучшем случае посредственный пёс... по крайней мере, в нынешнем виде.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Loox", "Лукс", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The cunning Loox EyeWalker... you would be wise not to pick on him.", "Хитрый Лукс Глазоходец... лучше его не задирать.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mad Dummy", "Безумный манекен", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dummy?", "Манекен?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Looks can be deceiving...", "Внешность обманчива...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Madjick", "Мэджик", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "quite the magician...", "Ну и волшебник...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Memoryhead", "Голова памяти", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton", "Меттатон", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A hyper-intelligent, systematic, complex data analyzer... reminds me of an old 'friend'.", "Сверхразумный, систематичный и сложный анализатор данных... Напоминает мне одного старого «друга».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mettaton Ex", "Меттатон EX", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migosp", "Майгосп", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the irritable Migosp... its attack increases in a crowd.", "Раздражительный Мигосп... его атака растёт в толпе.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Migospel", "Мигоспел", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldbygg", "Молдбигг", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldsmal", "Молдсмол", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one's giving me imposter vibes.", "От него веет самозванством.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Moldessa", "Молдесса", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ah, the gelatinous moldsmal. you probably never wondered what it's made of.", "Ах, студенистый Молдсмол. Вы, наверное, никогда не задумывались, из чего он состоит.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Muffet", "Маффет", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ah yes, the spider queen. her rapid play game is remarkable.", "Ах да, королева пауков. Её стремительная игра впечатляет.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Napstablook", "Напстаблук", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most melancholy of ghosts... it cares not of battle, but still fights to impress.", "Самый меланхоличный из призраков... Ему безразличен бой, но он всё же сражается, чтобы произвести впечатление.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "onionsan", "Оньонсан", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not much strategy with one... It becomes a random tentcle card one the second turn.", "Особой стратегии тут нет... На втором ходу он превращается в случайную карту щупальца.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A boney brute, papyrus is. He will generate bones like nobody's business.", "Папирус — костлявый громила. Он производит кости быстрее всех.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Parsnik", "Парсник", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pyrope", "Пайроуп", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Pyrope wants nothing more than to crank up the heat, let's see how fatal that can be.", "Пайроуп только и хочет, что поддать жару. Посмотрим, насколько это может быть опасно.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reaper Bird", "Птица-жнец", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Royal Guards", "Королевские стражи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "two star-crossed lovers... will they ever focus on what's important?", "Двое влюблённых, которым судьба не благоволит... Сумеют ли они сосредоточиться на важном?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "if you pick this card, i feel like i'm going to have a bad time.", "Если вы выберете эту карту, боюсь, мне придётся несладко.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shyren", "Шайрен", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The musically inclined shyren... strike her bells to watch her sing.", "Музыкальная Шайрен... ударьте в её колокольчики, чтобы услышать пение.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Snowdrake", "Сноудрейк", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The laughable Snowdrake... striving to prove his father wrong. Will you let him succeed?", "Забавный Сноудрейк... он старается доказать, что отец неправ. Поможете ему?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So Cold", "Так холодно", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "so sorry", "мне жаль", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "he's very sorry", "ему очень жаль", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie", "Темми", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Temmie the immortal cat... at least i think she's a feline. Nothing to lose, everything to gain.", "Темми, бессмертная кошка... по крайней мере, я думаю, что она кошка. Терять нечего, а приобрести можно всё.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Toriel", "Ториэль", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The keeper of the ruins... She will protect your side of the board to the best of her ability.", "Хранительница руин... Она будет защищать вашу сторону доски изо всех сил.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Tsunderplane", "Цундэрплан", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "She can't decide between wanting your attention and wanting you to back off... i suggest the latter.", "Она не может решить, хочет ли вашего внимания или чтобы вы ушли... Советую второе.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Undyne", "Андайн", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How could I forget Undyne? She is a true warrior, with an almighty aim on her spear.", "Как я мог забыть Андайн? Настоящая воительница, безупречно владеющая копьём.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vegetoid", "Вегетоид", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "eat your greens. (not monitored by the fda)", "Ешьте зелень. (Не контролируется FDA.)", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vulkin", "Валкин", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A very passionate creature, this one. It's not his intention to harm, but that doesn't stop him.", "Очень пылкое создание. Он не хочет никого ранить, но это его не останавливает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsalot", "Вимзалот", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the noble whimsalot... pray that it deems your conquest riteous.", "Благородный Вимсалот... молитесь, чтобы он счёл ваши завоевания праведными.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whimsun", "Вимсан", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "the insignificant whimsun... it flees the battle after a single attack.", "Незначительный Вимсан... он сбегает из боя, совершив всего одну атаку.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Woshua", "Вошуа", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This creature has no lust for blood. His will lies with helping others. But it will fight if provoked.", "Это существо не жаждет крови. Оно стремится помогать другим, но будет сражаться, если его спровоцировать.", Language.Russian);

            // Ability
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Antisocial", "Нелюдимый", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will gain an attack buff if you have at least 1 other card on your side of the board.", "Карта с этим символом получает прибавку к атаке, если на вашей стороне доски есть хотя бы 1 другая карта.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Cleanser", "Очиститель", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will heal every card on its owner's side of the board, except the sigil bearer, for 1 health, at the start of every turn.", "В начале боевой фазы владельца карта с этим символом восстанавливает 1 ед. здоровья всем остальным картам на его стороне стола.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Determination", "Решимость", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will move to any open slot its owner chooses, it will also gain EXP and LV after a kill. But is that really what you want?", "Карта с этим символом может переместиться в любую пустую ячейку по выбору владельца. За убийство она также получает опыт и уровень. Но действительно ли вы этого хотите?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Incendiary", "Поджигатель", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil damages a card, that card gains the \"ablaze\" sigil. While a card is ablaze, it will lose one health per turn.", "Когда карта с этим символом атакует другую карту, та получает символ «Горение». Горящая карта получает 1 ед. урона в начале боевой фазы владельца.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ablaze", "Горение", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card bearing this sigil will take 1 damage at the start of its owner's turn.", "Карта с этим символом получает 1 ед. урона в начале боевой фазы владельца.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Indecisive", "Нерешительный", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it has a 50/50 chance to either gain a stat buff, or perish; creating a copy of this card in your hand.", "Когда карту с этим символом бьют, с шансом 50/50 она либо получает прибавку к характеристике, либо погибает, создавая свою копию у вас в руке.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Everyone knows Jerry. Makes Turns 2 seconds longer. Cards gain a stat buff when Jerry is killed or sacrificed.", "Все знают Джерри. Он продлевает ходы на 2 секунды. Карты на вашей стороне доски получают прибавку к характеристикам, когда Джерри убивают или приносят в жертву.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mercy", "Милосердие", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A 'Determined' card will be granted this sigil when the card opposing it has low health, prompting the player to make a moral decision.", "Карта с «Решимостью» получает этот символ, когда у карты напротив мало здоровья, и игроку предстоит моральный выбор.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Insight", "Проницательность", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you wanna have a bad time?", "Хочешь, чтобы тебе пришлось несладко?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Doodler", "Рисовальщик", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a card bearing this sigil is struck, it will sometimes summon doodlebogs on adjacent spaces.", "Когда карту с этим символом бьют, она иногда призывает дудлбогов в соседние ячейки.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Timid", "Робость", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When an opponent card moves into the opposing space of a card bearing this sigil, the sigil bearer will try to move one space over.", "Когда карта противника перемещается в ячейку напротив карты с этим символом, носитель пытается сместиться на одну ячейку в сторону.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You ditched Jerry.", "Вы бросили Джерри.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wow, you guys SUCK at this.", "Ух ты, ну вы и БЕЗДАРИ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The wi-fi here sucks.", "Здесь отвратительный вайфай.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SHHHH! Im THINKING, guys!!", "ТШШШ! Я ДУМАЮ, ребята!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Get your own, twerp.", "Раздобывай сам, мелочь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Why are we doing this? What a fail.", "Зачем мы это делаем? Вот провал.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guys. its COLD. Does ANYONE care?", "Ребята, ХОЛОДНО. КОГО-НИБУДЬ это волнует?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ka-SIGH", "Тяжёлый вздох...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DUH! Who DOESNT know?", "ДУХ! Кто этого НЕ знает?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Well... can YOU give me a ride home?", "Ну... ТЫ можешь подвезти меня домой?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Awkwarrrd.", "Как неловко.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "So, like, what are you even doing?", "Так что ты вообще делаешь?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Huh? Did they ditch me...? SOME friends!", "А? Они меня бросили...? Вот это друзья!", Language.Russian);



        }
    }
    public class RevenantMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for RevenantMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DanseMacabre", "Пляска смерти", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to reverse this sigil effect. At the end of the owner's turn, all creatures on the board gain 1 health.", "Заплатите 2 кости, чтобы обратить эффект этого символа. В конце хода владельца все существа на доске получают 1 ед. здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LifeDraw", "Вытягивание жизни", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Blood to draw a card from your main deck.", "Заплатите 1 кровь, чтобы взять карту из основной колоды.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "Врата душ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 1 Bone to gain 1 Energy, lose as much Max Energy at the end of the owner's turn.", "Заплатите 1 кость, чтобы получить 1 энергию. В конце хода владельца потеряйте столько же максимальной энергии.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Evocation", "Призыв", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 3 Energy to return the oldest non-Brittle allied creature from the graveyard to your hand.", "Заплатите 3 энергии, чтобы вернуть в руку союзное существо без символа «Немощь», которое дольше всех находится на кладбище.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dormant", "Дремлющий", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay Bones equal to the Power of [creature] to disable this sigil for 1 turn. [creature] cannot attack normally.", "Заплатите кости в количестве, равном силе [creature], чтобы отключить этот символ на 1 ход. [creature] не может атаковать обычным образом.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Transmute", "Трансмутация", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pay 2 Bones to transform [creature] to its alternate form.", "Заплатите 2 кости, чтобы превратить [creature] в её другую форму.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Protector", "Защитник", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] gain 1 max health.", "Соседние с [creature] существа получают 1 ед. максимального здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CalamityEffusion", "Излияние бедствия", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board lose 1 health.", "В конце хода владельца все существа на доске теряют 1 ед. здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ComfortAura", "Аура утешения", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, creatures adjacent to [creature] heal 1 health.", "В конце хода владельца существа рядом с [creature] восстанавливают 1 ед. здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CorpseParty", "Пир мертвецов", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, a Zombie enters your hand. A Zombie is defined as: 1 Power, 1 Health.", "Когда существо без символа «Немощь» на стороне владельца погибает в бою, вам в руку попадает Зомби. У Зомби 1 ед. силы и 1 ед. здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathKnock", "Стук мертвеца", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, it strikes back then perishes.", "Когда [creature] погибает в бою, она наносит ответный удар и затем погибает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DeathMetal", "Металл смерти", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, adjacent creatures and opposing creatures to the left, right, and center of it take 1 damage. It gains 1 Power for each affected creature.", "Когда [creature] разыгрывается, соседние существа и существа напротив слева, справа и в центре получают 1 ед. урона. За каждое затронутое существо она получает 1 ед. силы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Defiler", "Осквернитель", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, draw a card then choose one to discard from your hand.", "Когда [creature] погибает, возьмите карту, затем выберите карту в руке и сбросьте её.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Encroachment", "Вторжение", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] creates a copy of it in your hand after 2 turns on the board.", "Через 2 хода на доске [creature] создаёт свою копию у вас в руке.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skeletonize", "Превращение в скелет", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, a Skeleton with its old sigils enters your hand. A Skeleton is defined as: 1 Power, 1 Health, Brittle.", "Когда [creature] погибает, вам в руку попадает Скелет с её прежними символами. У Скелета 1 ед. силы, 1 ед. здоровья и «Немощь».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcise", "Изгнание духа", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, Bones equal to the Bone cost of the opposing creature are granted to the player.", "Когда [creature] разыгрывается, игрок получает кости в количестве, равном стоимости в костях существа напротив.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ExplodingCorpse", "Взрывающийся труп", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, all empty spaces on the board are filled with a Guts card.", "Когда [creature] погибает в бою, все пустые ячейки доски заполняются картами «Внутренности».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GrudgeCollector", "Собиратель обид", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power for every 2 times opponent creatures deal direct damage to its owner.", "[creature] получает 1 ед. силы за каждые 2 случая, когда существа противника наносят прямой урон её владельцу.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Chime Power", "Сила колокольчиков", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bell cards on the board.", "Значение этого символа равно числу карт «Колокольчик» на доске.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bone Digger Power", "Сила Костекопа", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The value represented by this sigil will be equal to the number of Bone and Digger related sigils on the board.", "Значение этого символа равно числу символов, связанных с костями и копанием, на доске.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignition", "Возгорание", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] gains 1 power at the cost of 1 health after each turn on the board.", "После каждого хода на доске [creature] получает 1 ед. силы ценой 1 ед. здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Digger Latch", "Копательная защёлка", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain the Bone Digger sigil.", "В конце хода владельца [creature] создаёт 1 кость. Когда она погибает, её владелец выбирает существо, которое получит символ «Костекоп».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Primed Digger Latch", "Усиленная защёлка Костекопа", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will generate 1 Bone. When it perishes, its owner chooses a creature to gain this sigil.", "В конце хода владельца [creature] создаёт 1 кость. Когда она погибает, её владелец выбирает существо, которое получит этот символ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rejuvenation", "Омоложение", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Fledgling sigil.", "Когда [creature] погибает, её владелец выбирает существо, которое получит символ «Детёныш».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skull Storm", "Буря черепов", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, this sigil is replaced with another sigil at random. When it perishes, its owner chooses a creature to gain this sigil.", "В конце хода владельца этот символ заменяется другим случайным символом. Когда карта погибает, её владелец выбирает существо, которое получит этот символ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ignite", "Поджечь", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, its owner chooses a creature to gain the Ignition sigil.", "Когда [creature] погибает, её владелец выбирает существо, которое получит символ «Возгорание».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MacabreBonePulse", "Мрачный костяной импульс", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, it perishes immediately, dropping Bones equal to double the amount of creatures on the owner's side.", "Когда [creature] разыгрывается, она немедленно погибает, оставляя кости в количестве, вдвое превышающем число существ на стороне владельца.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Maternal", "Материнский", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Creatures adjacent to [creature] are inscrybed by Waterborne.", "Соседние с [creature] существа получают символ «Амфибия».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Necrosis", "Некроз", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] loses 1 power and 1 max health after each turn on the board.", "После каждого хода на доске [creature] теряет 1 ед. силы и 1 ед. максимального здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Limbo", "Лимб", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it returns to the top of your deck.", "Когда [creature] погибает, она возвращается наверх вашей колоды.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RelentlessRevenant", "Неутомимый восставший", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the start of the owner's turn, creatures adjacent to [creature] transform into a Revenant. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "В начале хода владельца существа рядом с [creature] превращаются в Восставших. У Восставшего 3 ед. силы, 1 ед. здоровья и «Немощь».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revedue", "Возвращение восставших", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "After attacking, [creature] perishes, then shuffle 2 Revenants with its old sigils into your side deck. A Revenant is defined as: 3 Power, 1 Health, Brittle.", "После атаки [creature] погибает, затем замешайте 2 Восставших с её прежними символами в дополнительную колоду. У Восставшего 3 ед. силы, 1 ед. здоровья и «Немощь».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bad Omen", "Дурное предзнаменование", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will deal 1 damage to the owner.", "В конце хода владельца [creature] наносит ему 1 ед. урона.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Rancor", "Злоба", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes, it leaves a permanent 1 power buff in the space it occupied.", "Когда [creature] погибает, она оставляет постоянную прибавку в 1 ед. силы на своей ячейке.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SoothingMeadows", "Умиротворяющие луга", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, all creatures on the board gain 1 health.", "В конце хода владельца все существа на доске получают 1 ед. здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PartingStroke", "Последний штрих", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When a non-brittle creature on the owner's side perishes by combat, its owner chooses a creature to lose all of its sigils.", "Когда существо без символа «Немощь» на стороне владельца погибает в бою, владелец выбирает существо, которое потеряет все свои символы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SplittingCorpse", "Разделённый труп", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] perishes by combat, create a Dysmorphia on each empty adjacent space.", "Когда [creature] погибает в бою, в каждой пустой соседней ячейке создаётся Дисморфия.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Torpid", "Вялость", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] cannot attack normally.", "[creature] не может атаковать обычным образом.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grim Epitaph", "Мрачная эпитафия", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is played, you may choose a card that has already been put to rest, to bring back to your hand.", "Когда [creature] разыгрывается, вы можете выбрать уже упокоенную карту и вернуть её себе в руку.", Language.Russian);


            //card
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bigfoot", "Снежный человек", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a mysterious creature lurking the forests, only few have claimed to see one.", "Таинственное существо, скрывающееся в лесах. Лишь немногие утверждают, что видели его.", Language.Russian);
            GrimoraMod.RegisterCard("Bigfoot", "Снежный человек");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Goblin", "Гоблин", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A loyal barbaric beast, a fine addition to your army.", "Верный дикий зверь, отличное пополнение вашей армии.", Language.Russian);
            GrimoraMod.RegisterCard("Goblin", "Гоблин");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Vila", "Вила", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Love at first sight, at least that's what it wants you to think.", "Любовь с первого взгляда. По крайней мере, он хочет, чтобы вы так думали.", Language.Russian);
            GrimoraMod.RegisterCard("Vila", "Вила");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Yaramayawho", "Яра-ма-йха-ху", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one can never seem to finish it's meals...", "Похоже, он никак не может доесть...", Language.Russian);
            GrimoraMod.RegisterCard("Yaramayawho", "Яра-ма-йха-ху");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Test Limbs", "Испытательные конечности", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Those parts used to belong to someone, or now some thing...(Test)", "Эти части когда-то принадлежали кому-то, а теперь чему-то... (Тест)", Language.Russian);
            GrimoraMod.RegisterCard("Test Limbs", "Испытательные конечности");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Allip", "Аллип", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The remnants of the insane! You never know what story lies behind that face, but it's sure to be filled with fervor.", "Останки безумцев! Неизвестно, какая история скрывается за этим лицом, но пыла в ней наверняка немало.", Language.Russian);
            GrimoraMod.RegisterCard("Allip", "Аллип");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Amami Rabbit", "Кролик амами", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hiding their young in holes, they wish for their best safety.", "Они прячут детёнышей в норах, чтобы те были в безопасности.", Language.Russian);
            GrimoraMod.RegisterCard("Amami Rabbit", "Кролик амами");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Ankhame", "Анхейм", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A relic that is drawn to your blood, perhaps you could give it a swing!", "Реликвия, которую привлекает ваша кровь. Может, попробуете ею взмахнуть?", Language.Russian);
            GrimoraMod.RegisterCard("Ankhame", "Анхейм");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anneta", "Аннета", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "That ink keeps on pouring, is she even there anymore? All that death promises is that you will wake up again.", "Чернила всё льются. Осталась ли она там? Смерть обещает лишь то, что вы снова проснётесь.", Language.Russian);
            GrimoraMod.RegisterCard("Anneta", "Аннета");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Anorexia", "Анорексия", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Overflowing you with self loathing, you never know what form it may take on next.", "Она переполняет вас ненавистью к себе, и никогда не знаешь, какой облик примет в следующий раз.", Language.Russian);
            GrimoraMod.RegisterCard("Anorexia", "Анорексия");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lych Bell", "Колокол лича", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It seems like they found a new way to use bells.", "Кажется, они нашли новый способ использовать колокольчики.", Language.Russian);
            GrimoraMod.RegisterCard("Lych Bell", "Колокол лича");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "TheBloated", "Раздутый труп", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grotesque boils, ready to burst.", "Отвратительные нарывы, готовые лопнуть.", Language.Russian);
            GrimoraMod.RegisterCard("TheBloated", "Раздутый труп");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BrainJar", "Мозг в банке", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "One shudders to imagine what inhuman thoughts lie inside that jar...", "От одной мысли о том, какие бесчеловечные мысли скрыты в этой банке, бросает в дрожь...", Language.Russian);
            GrimoraMod.RegisterCard("BrainJar", "Мозг в банке");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Combustor", "Воспламенитель", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh dear, what a fall from such a stimulatingly high status, now all that's left is a metal carcass, and the last of that watchful substance...", "Ох, какое падение с головокружительной высоты! Теперь остались лишь металлическая туша и последние следы этой бдительной субстанции...", Language.Russian);
            GrimoraMod.RegisterCard("Combustor", "Воспламенитель");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Misplayed Stoat", "Неудачно разыгранный горностай", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A decaying Stoat whose oh-so perfect strategies failed him tremendously.", "Разлагающийся Горностай, которого его якобы совершенные стратегии жестоко подвели.", Language.Russian);
            GrimoraMod.RegisterCard("Misplayed Stoat", "Неудачно разыгранный горностай");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia", "Дисморфия", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Left.", "Дисморфия слева.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dysmorphia Right.", "Дисморфия справа.", Language.Russian);
            GrimoraMod.RegisterCard("Dysmorphia", "Дисморфия");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Exorcist", "Экзорцист", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He still thinks banishing the dammed will do him good, does he know where he is?", "Он всё ещё думает, что изгнание проклятых пойдёт ему на пользу. Он знает, где находится?", Language.Russian);
            GrimoraMod.RegisterCard("Exorcist", "Экзорцист");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flembones", "Гнойные кости", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wait until he plays with his webcam.", "Подождите, пока он поиграет со своей веб-камерой.", Language.Russian);
            GrimoraMod.RegisterCard("Flembones", "Гнойные кости");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stein & Frank", "Штейн и Франк", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Even hell was not hot enough to split them.", "Даже в аду не хватило жара, чтобы их разлучить.", Language.Russian);
            GrimoraMod.RegisterCard("Stein & Frank", "Штейн и Франк");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulmineSkull", "Громовой череп", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "If you listen closely, you can still hear the cackling of flame on bone... as well as their voice.", "Если прислушаться, всё ещё можно услышать треск пламени на костях... а также их голос.", Language.Russian);
            GrimoraMod.RegisterCard("FulmineSkull", "Громовой череп");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FulurOssa", "Громовые кости", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "It never truly left the electric chair.", "Он так и не покинул электрический стул.", Language.Russian);
            GrimoraMod.RegisterCard("FulurOssa", "Громовые кости");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PrometheusFlame", "Пламя Прометея", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This one is quite unique, the lingering spoils of a thief to benefit humanity! Fancy liver by chance?", "Это нечто особенное — оставшееся достояние вора, послужившее человечеству! Не желаете печёнки?", Language.Russian);
            GrimoraMod.RegisterCard("PrometheusFlame", "Пламя Прометея");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Guts", "Внутренности", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying guts.", "Раздражающие внутренности.", Language.Russian);
            GrimoraMod.RegisterCard("Guts", "Внутренности");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Harbinger", "Предвестник", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A powerful fiend that extols a heavy price for its servitude.", "Могущественный демон, требующий высокую цену за свою службу.", Language.Russian);
            GrimoraMod.RegisterCard("Harbinger", "Предвестник");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hastur", "Хастур", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "He came from beyond the stars, gifting pieces of his reflection to kings and fools alike. Will you accept this piece?", "Он пришёл из-за звёзд, даря частицы своего отражения и королям, и глупцам. Примете ли вы эту частицу?", Language.Russian);
            GrimoraMod.RegisterCard("Hastur", "Хастур");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Common Imp", "Обычный бес", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A tiny creature known for causing trouble and mayhem wherever it goes, with its mischievous grin and playful nature!", "Крошечное существо с озорной ухмылкой и игривым нравом, известное тем, что повсюду устраивает переполох!", Language.Russian);
            GrimoraMod.RegisterCard("Common Imp", "Обычный бес");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochimitama", "Дух Ороти", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... He is not supposed to be here...", "Ох... Ему не место здесь...", Language.Russian);
            GrimoraMod.RegisterCard("Orochimitama", "Дух Ороти");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Inochi", "Иноти", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A soothing presence to heal your creatures, a calm before the storm.", "Успокаивающее присутствие исцеляет ваших существ — затишье перед бурей.", Language.Russian);
            GrimoraMod.RegisterCard("Inochi", "Иноти");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Trail of Torment.", "Тропа мучений.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Possessed Limbs", "Одержимые конечности", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Once attached to a living person, they now belong to something else entirely.", "Когда-то они принадлежали живому человеку, а теперь — совсем другому существу.", Language.Russian);
            GrimoraMod.RegisterCard("Possessed Limbs", "Одержимые конечности");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mole Digger", "Крот-могильщик", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The stalwart Mole... Digger? Whatever this is...", "Стойкий Крот... могильщик? Что бы это ни было...", Language.Russian);
            GrimoraMod.RegisterCard("Mole Digger", "Крот-могильщик");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros", "Некрос", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nekros possesses the board, challenger. Death is his playground.", "Некрос владеет доской, претендент. Смерть — его игровая площадка.", Language.Russian);
            GrimoraMod.RegisterCard("Nekros", "Некрос");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NekrosPrime", "Некрос Прайм", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You will find no greater power... than the simple thought of your own name... inscrybed upon a grave.", "Вам не найти силы большей... чем простая мысль о собственном имени... начертанном на могиле.", Language.Russian);
            GrimoraMod.RegisterCard("NekrosPrime", "Некрос Прайм");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Nuckelavee", "Наклави", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The Administrator of its sea, you better hope it's breath doesn't taint your Thralls!", "Владыка своего моря. Надейтесь, что его дыхание не осквернит ваших прислужников!", Language.Russian);
            GrimoraMod.RegisterCard("Nuckelavee", "Наклави");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OdiousMass", "Мерзкая масса", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "How unsightly.", "Какое безобразие.", Language.Russian);
            GrimoraMod.RegisterCard("OdiousMass", "Мерзкая масса");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Orochi", "Ороти", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "Жертвы необходимы.", Language.Russian);
            GrimoraMod.RegisterCard("Orochi", "Ороти");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Master Ouro", "Мастер Оуро", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "From within the endless torment and suffering, they had somehow learned a way to see inside this poor broken thing... and take away its pain.", "Среди бесконечных мук и страданий они каким-то образом научились заглядывать внутрь этого бедного сломленного существа... и унимать его боль.", Language.Russian);
            GrimoraMod.RegisterCard("Master Ouro", "Мастер Оуро");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "An endless cycle of life and death has taken a toll on these discarded remains. The pain was real, but death is never final!", "Бесконечный круг жизни и смерти изнурил эти брошенные останки. Боль была настоящей, но смерть никогда не бывает концом!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GanCeann", "Ган Кьян", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Countless legends tell of the dullahan, but all fail to convey the true extent of its pique.", "Бесчисленные легенды рассказывают о дуллахане, но ни одна не передаёт всей силы его гнева.", Language.Russian);
            GrimoraMod.RegisterCard("GanCeann", "Ган Кьян");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dark Prince", "Тёмный принц", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The power of fluffy bois shines within you.", "Сила пушистых ребят сияет внутри вас.", Language.Russian);
            GrimoraMod.RegisterCard("Dark Prince", "Тёмный принц");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Stillborn Raven", "Мертворождённый ворон", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Feels good to be young again!", "Как же хорошо снова быть молодым!", Language.Russian);
            GrimoraMod.RegisterCard("Stillborn Raven", "Мертворождённый ворон");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Reanimated", "Воскрешённый", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BRINGING THE SCYTHE OF DEATH, THE REVENANT... WAIT, WHAT?", "С КОСОЙ СМЕРТИ ЯВЛЯЕТСЯ ВОССТАВШИЙ... ПОСТОЙТЕ, ЧТО?", Language.Russian);
            GrimoraMod.RegisterCard("Reanimated", "Воскрешённый");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "RevenantEldritch", "Ревенант Элдрич", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The source of Calamity, relentless and unerring.", "Источник Бедствия, неумолимый и безошибочный.", Language.Russian);
            GrimoraMod.RegisterCard("RevenantEldritch", "Ревенант Элдрич");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lazy Bones", "Ленивые кости", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A slothful skeleton with a knack for jokes. I adore him.", "Ленивый скелет, умеющий шутить. Обожаю его.", Language.Russian);
            GrimoraMod.RegisterCard("Lazy Bones", "Ленивые кости");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Skelephone", "Костефон", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A way to communicate with the dead, for a price.", "Способ общаться с мёртвыми, но за определённую цену.", Language.Russian);
            GrimoraMod.RegisterCard("Skelephone", "Костефон");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Soulgate", "Врата душ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A chance to enter the soul realm, how delightful? I hope you can afford the price.", "Возможность войти в царство душ, как чудесно! Надеюсь, вы сможете заплатить цену.", Language.Russian);
            GrimoraMod.RegisterCard("Soulgate", "Врата душ");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SpadeWarrior", "Воин пик", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This fearsome warrior will put you six feet under, in every possible sense.", "Этот грозный воин закопает вас глубоко под землю во всех смыслах.", Language.Russian);
            GrimoraMod.RegisterCard("SpadeWarrior", "Воин пик");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadCivilian", "Мирная нежить", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Lost in eternal darkness, this poor soul desperately seeks a way out. Perhaps you can light his way?", "Затерянная в вечной тьме, эта бедная душа отчаянно ищет выход. Может, вы осветите ей путь?", Language.Russian);
            GrimoraMod.RegisterCard("UndeadCivilian", "Мирная нежить");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "UndeadVillage", "Деревня нежити", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Abandoned and forlorn, this village seeks new residents to fill its decrepit homes.", "Заброшенная и одинокая, эта деревня ждёт новых жителей для своих ветхих домов.", Language.Russian);
            GrimoraMod.RegisterCard("UndeadVillage", "Деревня нежити");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "In every town, in every city, someone must work to bury the dead. In time, they too will be buried.", "В каждом городе и деревне кто-то должен хоронить мёртвых. Со временем похоронят и их.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dr.Bones", "Доктор Кости", Language.Russian);
            GrimoraMod.RegisterCard("Dr.Bones", "Доктор Кости");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whatever doesn't kill you simply makes you, saner.", "Всё, что вас не убивает, просто делает вас более здравомыслящим.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Wendigo", "Вендиго", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Returned from the deep wilds, reminds me of a friend.", "Вернувшись из диких земель, он напоминает мне друга.", Language.Russian);
            GrimoraMod.RegisterCard("Wendigo", "Вендиго");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mister Win", "Мистер Победа", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A card that wins. It always wins. That's why it's called Mister Win.", "Карта, которая побеждает. Она побеждает всегда. Поэтому её зовут Мистер Победа.", Language.Russian);
            GrimoraMod.RegisterCard("Mister Win", "Мистер Победа");
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Not that one, I'm afraid.", "Боюсь, не та.", Language.Russian);

            // Dlg
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You... you murderous monster.", "Ты... ты чудовищный убийца.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh Dear... The flow of Calamity will pursue you.", "О нет... Поток Бедствия будет преследовать вас.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hecatomb the village you once lived.", "Предайте смерти жителей деревни, где вы когда-то жили.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Seak for the shovel that digs forever.", "Отыщите лопату, которая копает вечно.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bring me the lost one with a spark in hand.", "Приведите ко мне потерянного с искрой в руке.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Compelled by the beckoning of an ancient entity,", "Повинуясь зову древней сущности,", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "a forbidden ritual has been initiated.", "начался запретный ритуал.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The pain reaches the ancient great serpent of death.", "Боль доходит до древнего великого змея смерти.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Sacrifices must be made.", "Жертвы необходимы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Oh... There are no dead cards yet.", "Ох... Мёртвых карт ещё нет.", Language.Russian);

            // Pack
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Revenant Mod Card Pack", "Набор карт мода Revenant", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "This card pack consists of mainly cards that return to the player in a variety of ways.", "Этот набор в основном состоит из карт, возвращающихся к игроку разными способами.", Language.Russian);
        }
    }
    public class SquirrelBombMod
    {
        public static void RegisterTranslations()
        {
            Debug.Log("Registering Translations for SquirrelBombMod Mod");

            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis", "Пипис", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pipis.", "Пипис.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Help", "Помощь", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn [creature] will sacrifice itself to heal the adjacent cards by 1.", "В конце хода владельца [creature] приносит себя в жертву, восстанавливая соседним картам по 1 ед. здоровья.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pass-through", "Прохождение насквозь", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "When [creature] is about to get attacked by a card with an attack higher than this card's health, this card perishes.", "Когда [creature] собирается атаковать карта, чья атака выше её здоровья, она погибает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Call", "Спам-звонок", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Empty spaces within a circuit completed by [creature] spawn Spam Mail at the end of the owner's turn.", "В конце хода владельца [creature] пустые ячейки внутри замкнутой ею цепи создают Спам.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NEO Strike", "Удар NEO", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[creature] will strike each opposing space that is occupied by a creature and additionally every side of the board occupied by a creature. It will strike directly if no creatures oppose it.", "[creature] атакует каждую занятую существом ячейку противника, а также обе ячейки каждой половины его стороны, где есть существо. Если существ противника нет, она атакует две центральные ячейки.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A Call for Help", "Зов о помощи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "At the end of the owner's turn, [creature] will call for help.", "В конце хода владельца [creature] зовёт на помощь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Run Forth", "Вперёд", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Before [creature] attacks, its power will be set to at least 1.", "Перед атакой сила [creature] устанавливается как минимум на 1.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Flying Head", "Летающая голова", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The most important part.", "Самая важная часть.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Cart", "Тележка со спамом", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with spam mail. Absorbs all kinds of attacks.", "Полон спама. Поглощает любые атаки.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spam Mail", "Спам", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Has all kinds of unforgettable deals.", "Здесь всевозможные незабываемые предложения.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Big Shooter", "Крупнокалиберный стрелок", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Shoots big shots.", "Стреляет крупными снарядами.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Heart on a Chain", "Сердце на цепи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Beautiful.", "Прекрасно.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Spamgel", "Спамгель", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The result of pressing F1.", "Результат нажатия F1.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Hand Phone", "Ручной телефон", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Do you really need anyone else?", "Вам действительно нужен кто-то ещё?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE POWER OF NEO!!!", "СИЛА NEO!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Don't you wanna be a big shot?", "Разве вы не хотите стать большой шишкой?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Receiver", "Приёмник", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "The voice runs out eventually.", "Голос рано или поздно стихает.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis", "Гриззлипис", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Grizzlipis.", "Гриззлипиз.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Cart", "Тележка с медведями", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Filled with bears. Absorbs all kinds of attacks.", "Полна медведей. Поглощает любые атаки.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Mail", "Медвежья почта", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Mail for bears.", "Почта для медведей.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear on a Chain", "Медведь на цепи", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Bear Hand", "Медвежья лапа", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrel Bomb", "Беличья бомба", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Squirrels explode when killed, dealing 10 damage to adjacent cards.", "Белки взрываются при гибели, нанося 10 ед. урона соседним картам.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance Party", "Танцевальная вечеринка", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Your cards move each turn. The cards that can't move die.", "Ваши карты перемещаются каждый ход. Карты, которые не могут переместиться, погибают.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Again", "снова", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All opponent cards attack twice.", "Все карты противника атакуют дважды.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Starving", "Голодный", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Pray.", "Молитесь.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dogfish", "Катран", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Each battle starts with a Bait Bucket that has Guardian.", "Каждый бой начинается с Ведра с наживкой и символом «Страж».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Annoying Totems", "Тотемы Надоеды", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Start each battle with an Annoying totem for your most used tribe.", "Начинайте каждый бой с тотемом «Надоеда» для своего наиболее используемого племени.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Draws", "Болезненное взятие", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the main deck deals 1 damage.", "Взятие карты из основной колоды наносит 1 ед. урона.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Painful Squirrels", "Болезненные белки", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Drawing from the side deck deals 1 damage.", "Взятие карты из дополнительной колоды наносит 1 ед. урона.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Runes", "Руны", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Enemy cards of the dominant tribe get random sigils.", "Карты противника из преобладающего племени получают случайные символы.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dentistry", "Стоматология", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Item events and Trinket Bearer cards only give pliers.", "События с предметами и карты с символом «Любитель безделушек» дают только Пассатижи.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Archived", "В архиве", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "A random card choice is hidden in every card choice event.", "При каждом выборе карт один случайный вариант скрыт.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Foundation", "Основа", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "All cards have 1 less attack. Side deck cards have Leader.", "У всех ваших карт атака снижена на 1. Карты дополнительной колоды имеют символ «Лидер».", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Final Boss v2", "Финальный босс v2", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Replaces Leshy as the final boss with a true BIG SHOT.", "Заменяет Лешего в роли финального босса настоящей БОЛЬШОЙ ШИШКОЙ.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You must dance! Don't stop dancing!!", "Вы должны танцевать! Не прекращайте танцевать!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Whoever stops dancing at my party will suffer the consequences.", "Тот, кто перестанет танцевать на моей вечеринке, понесёт последствия.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Is that mechanic annoying?", "Этот приём раздражает?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Perfect. That's the point of it.", "Прекрасно. В этом и смысл.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "Dance my puppet! Daaaance.", "Танцуй, моя марионетка! Тааанцуй.", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "You need to pass, remember?", "Тебе нужно пройти, помнишь?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'M [_spamton_0,STEALING] YOUR KROMER", "Я [_spamton_0,КРАДУ] ТВОИ КРОМЕРЫ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HOLY [_spamton_0,CUNGADERO] DO I FEEL GOOD", "СВЯТОЙ [_spamton_0,КУНГАДЕРО], КАК ЖЕ МНЕ ХОРОШО", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HERE I AM!!!", "А ВОТ И Я!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BIG", "ОПУПЕННЫЙ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=10>BIG!!!</size>", "<size=10>БОЛЬШОЙ!!!</size>", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "<size=15>[_spamton_0,BIGGER AND BETTER THAN EVER]</size>", "<size=15>[_spamton_0,БОЛЬШЕ И ЛУЧШЕ ЧЕМ КОГДА-ЛИБО]</size>", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND NOW THAT I'M IN THIS [_spamton_0,GAME OF CARDS]", "И ТЕПЕРЬ, КОГДА Я В ЭТОЙ [_spamton_0,КАРТОЧНОЙ ИГРЕ]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I CAN'T BE DEFEATED!!!", "МЕНЯ НЕ ПОБЕДИТЬ!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,ABSOLUTELY OBLITERATED] BY [_spamton_0,THE POWER OF NEO]!!!", "ПРИГОТОВЬСЯ БЫТЬ [_spamton_0,ПОЛНОСТЬЮ УНИЧТОЖЕННЫМ] [_spamton_0,СИЛОЙ NEO]!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,THIS] AGAIN???", "СНОВА [_spamton_0,ЭТО]???", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO GET [_spamton_0,DESTROYED]!!!", "ПРИГОТОВЬСЯ К [_spamton_0,УНИЧТОЖЕНИЮ]!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WON'T STAND A CHANGE, YOU [_spamton_0,LITTLE RING WORM]!!!", "У ТЕБЯ НЕТ ШАНСОВ, ТЫ [_spamton_0,МАЛЕНЬКИЙ КОЛЬЦЕВОЙ ЧЕРВЬ]!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "PREPARE TO [_spamton_0,GET PUNCHED] IN YOUR [_spamton_0,FACE]!!!", "ПРИГОТОВЬСЯ ПОЛУЧИТЬ [_spamton_0,УДАР] В СВОЁ [_spamton_0,ЛИЦО]!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BEHOLED [_spamton_0,ME]!!! BEHOLD [_spamton_0,YOU]!!!", "УЗРИ [_spamton_0,МЕНЯ]!!! УЗРИ [_spamton_0,СЕБЯ]!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,HYPERLINK BLOCKED]", "[_spamton_0,ГИПЕРССЫЛКА ЗАБЛОКИРОВАНА]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ISN'T THIS BODY JUST [_spamton_0,HEAVEN]LY?", "РАЗВЕ ЭТО ТЕЛО НЕ ПРОСТО [_spamton_0,РАЙСКОЕ]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "2X THE [_spamton_0,FIRE]POWER", "2X [_spamton_0,ОГНЕВОЙ] МОЩИ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "3X THE [_spamton_0,WATER]POWER", "3X [_spamton_0,ВОДНОЙ] МОЩИ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "AND MOST IMPORTANTLY", "И САМОЕ ГЛАВНОЕ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "FLYING HEADS!!!", "ЛЕТАЮЩИЕ ГОЛОВЫ!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WE'LL TURN THOSE [_spamton_0,SCHMOES] AND [_spamton_0,DAVES]", "МЫ ПРЕВРАТИМ ЭТИХ [_spamton_0,ПРОСТАКОВ] И [_spamton_0,ПРИДУРКОВ]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,ROSEN GRAVES]", "В [_spamton_0,РОЗОВЫЕ МОГИЛЫ]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THOSE [_spamton_0,CATHODE SCREENS]", "ЭТИ [_spamton_0,КАТОДНЫЕ ЭКРАНЫ]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "INTO [_spamton_0,CATHODE SCREAMS]", "В [_spamton_0,КАТОДНЫЕ КРИКИ]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA BE [_spamton_0,PART] OF MY BEAUTIFUL [_spamton_0,HEART]?!", "РАЗВЕ ТЫ НЕ ХОЧЕШЬ СТАТЬ [_spamton_0,ЧАСТЬЮ] МОЕГО ПРЕКРАСНОГО [_spamton_0,СЕРДЦА]?!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OR... DID YOU NEED A LITTLE [_spamton_0,SPECIL TOUR]?", "ИЛИ... ТЕБЕ НУЖНА НЕБОЛЬШАЯ [_spamton_0,ОСОБЯ ЭКСКУРСИЯ]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHAT]?!", "[_spamton_0,ЧТО]?!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU [_spamton_0,STOLE] MY [_spamton_0,HEART]?", "ТЫ [_spamton_0,УКРАЛ] МОЁ [_spamton_0,СЕРДЦЕ]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CAN'T BE [_spamton_0,STEALING] MY [_spamton_0,HEART], IT IS MY [_spamton_0,HEART]!", "ТЫ НЕ МОЖЕШЬ [_spamton_0,УКРАСТЬ] МОЁ [_spamton_0,СЕРДЦЕ], ЭТО МОЁ [_spamton_0,СЕРДЦЕ]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "STOP [_spamton_0,STEALING] MY HEART YOU [_spamton_0,!@#$]", "ХВАТИТ [_spamton_0,КРАСТЬ] МОЁ СЕРДЦЕ, ТЫ [_spamton_0,!@#$]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "O U C [_spamton_0,HYPERLINK BLOCKED]", "А Й [_spamton_0,ГИПЕРССЫЛКА ЗАБЛОКИРОВАНА]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU JUST [_spamton_0,BROKE] MY [_spamton_0,$4.99] HEART", "ТЫ ТОЛЬКО ЧТО [_spamton_0,РАЗБИЛ] МОЁ СЕРДЦЕ ЗА [_spamton_0,$4.99]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO YOU KNOW THAT IT [_spamton_0,HURTS] WHEN YOU [_spamton_0,DO] THAT?!", "ТЫ ЗНАЕШЬ, ЧТО МНЕ [_spamton_0,БОЛЬНО], КОГДА ТЫ ЭТО [_spamton_0,ДЕЛАЕШЬ]?!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA HELP YOUR OLD PAL SPAMTON?", "РАЗВЕ ТЫ НЕ ХОЧЕШЬ ПОМОЧЬ СВОЕМУ СТАРОМУ ДРУГУ СПАМТОНУ?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THINK! WHAT ARE MY [_spamton_0,EGGS] GOING TO DO!?", "ПОДУМАЙ! ЧТО СТАНУТ ДЕЛАТЬ МОИ [_spamton_0,ЯЙЦА]!?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S CALLING...", "ОН ЗОВЁТ...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY [_spamton_0,HEART]...", "МОЁ [_spamton_0,СЕРДЦЕ]...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY [_spamton_0,HANDS]...", "МОИ [_spamton_0,РУКИ]...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "LOOK AT THE [_spamton_0,POWER OF NEO] AND ASK YOURSELF...", "ПОСМОТРИ НА [_spamton_0,СИЛУ NEO] И СПРОСИ СЕБЯ...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU?", "РАЗВЕ НЕ ХОЧЕШЬ?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DON'T YOU WANNA BE A [_spamton_0,BIG SHOT]!?", "РАЗВЕ НЕ ХОЧЕШЬ СТАТЬ [_spamton_0,БОЛЬШОЙ ШИШКОЙ]!?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MY ESTEEM CUSTOMER I SEE YOU ARE ATTEMPTING TO DEPLETE MY HP!", "ДОРОГОЙ КЛИЕНТ, ВИЖУ, ВЫ ПЫТАЕТЕСЬ ЛИШИТЬ МЕНЯ ЗДОРОВЬЯ!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I'LL ADMIT YOU'VE GOT SOME [_spamton_0,GUTS]!", "ПРИЗНАЮ, У ТЕБЯ ХВАТАЕТ [_spamton_0,ДУХУ]!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "BUT IN A [_spamton_0,1 FOR 1] BATTLE, NEO NEVER LOSES!!!", "НО В БОЮ [_spamton_0,1 НА 1] NEO НИКОГДА НЕ ПРОИГРЫВАЕТ!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S TIME FOR A LITTLE [_spamton_0,BLUELIGHT SPECIL]", "ВРЕМЯ ДЛЯ НЕБОЛЬШОЙ [_spamton_0,СИНЕЙ ОСОБОЙ АКЦЫИ]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ARE YOU [_spamton_0,SURPRISED] THAT YOU CAN'T JUST [_spamton_0,DESTROY] ME WITH YOUR [_spamton_0,PATHETIC LITTLE] [_spamton_0,CARDS]?", "ТЕБЯ [_spamton_0,УДИВЛЯЕТ], ЧТО ТЫ НЕ МОЖЕШЬ МЕНЯ [_spamton_0,УНИЧТОЖИТЬ] СВОИМИ [_spamton_0,ЖАЛКИМИ МАЛЕНЬКИМИ] [_spamton_0,КАРТАМИ]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DIDN'T YOU KNOW [_spamton_0,NEO] IS FAMOUS FOR ITS HIGH DEFENSE!?", "РАЗВЕ ТЫ НЕ ЗНАЛ, ЧТО [_spamton_0,NEO] СЛАВИТСЯ ВЫСОКОЙ ЗАЩИТОЙ!?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOW... ENJ0Y THE FIR3WORKS!!!", "А ТЕПЕРЬ... НАСЛАЖДАЙСЯ ФЕЙЕРВ3РК0М!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ENJOY THE FIREWORKS!!!!", "НАСЛАЖДАЙСЯ ФЕЙЕРВЕРКОМ!!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT?", "ЧТО?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHO] ARE YOU TRYING TO [_spamton_0,CALL]???", "[_spamton_0,КОМУ] ТЫ ПЫТАЕШЬСЯ [_spamton_0,ПОЗВОНИТЬ]???", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU HAVE NO [_spamton_0,FRIENDS] IN THIS [_spamton_0,WORLD]!!!", "У ТЕБЯ НЕТ [_spamton_0,ДРУЗЕЙ] В ЭТОМ [_spamton_0,МИРЕ]!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THEY'RE ALL [_spamton_0,PAPER CARDS]!!!", "ОНИ ВСЕГО ЛИШЬ [_spamton_0,БУМАЖНЫЕ КАРТЫ]!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHO'RE YOU GONNA CALL, THE [_spamton_0,POLICE]?", "КОМУ ТЫ ПОЗВОНИШЬ, В [_spamton_0,ПОЛИЦИЮ]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU'RE [_spamton_0,PATHETIC]!!", "ТЫ [_spamton_0,ЖАЛОК]!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,SCREAMING] FOR [_spamton_0,HELP] [_spamton_0,AT THE BOTTOM OF A DUMPSTER]!!!", "[_spamton_0,КРИЧИШЬ] О [_spamton_0,ПОМОЩИ] [_spamton_0,НА ДНЕ МУСОРНОГО БАКА]!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE'S NO [_spamton_0,HELP] FOR YOU!!!", "НИКТО ТЕБЕ НЕ [_spamton_0,ПОМОЖЕТ]!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR [_spamton_0,VOICE] IS GOING TO RUN OUT EVENTUALLY!!", "ТВОЙ [_spamton_0,ГОЛОС] РАНО ИЛИ ПОЗДНО ИСЧЕЗНЕТ!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "GIVE UP!!!", "СДАВАЙСЯ!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU CAN'T WIN!!!", "ТЕБЕ НЕ ПОБЕДИТЬ!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "I AM UNSTOPPABLE!!!", "МЕНЯ НЕ ОСТАНОВИТЬ!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOUR [_spamton_0,FREE TRIAL OF] LIFE IS ABOUT TO [_spamton_0,EXPIRE]!!!", "[_spamton_0,БЕСПЛАТНЫЙ ПРОБНЫЙ ПЕРИОД] ТВОЕЙ ЖИЗНИ СКОРО [_spamton_0,ИСТЕЧЁТ]!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,GOOBERT]?", "[_spamton_0,ГУБЕРТ]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IS IT THAT [_spamton_0,PATHETIC] LITTLE [_spamton_0,JAR] OF [_spamton_0,GOO]?", "ЭТО ТА [_spamton_0,ЖАЛКАЯ] [_spamton_0,БАНОЧКА] С [_spamton_0,ЖИЖЕЙ]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT [_spamton_0,HELP] WILL IT [_spamton_0,PROVIDE] TO [_spamton_0,YOU]???", "КАКУЮ [_spamton_0,ПОМОЩЬ] ОН МОЖЕТ [_spamton_0,ОКАЗАТЬ] [_spamton_0,ТЕБЕ]???", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,MAGNIFICUS]??", "[_spamton_0,МАГНИФИКУС]??", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT IS A [_spamton_0,MAGNIFICUS]? IS IT A KIND OF [_spamton_0,BLOWFISH]?", "ЧТО ТАКОЕ [_spamton_0,МАГНИФИКУС]? ЭТО КАКАЯ-ТО [_spamton_0,РЫБА ФУГУ]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT'S A [_spamton_0,BLOWFISH] GONNA [_spamton_0,DO TO ME]??", "ЧТО МНЕ МОЖЕТ [_spamton_0,СДЕЛАТЬ] [_spamton_0,РЫБА ФУГУ]??", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,LESHY]???", "[_spamton_0,ЛЕШИЙ]???", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IS THAT THE [_spamton_0,GUY] WHO I [_spamton_0,HIT] AT THE BEGGINING OF OUR [_spamton_0,FIGHT]???", "ЭТО ТОТ [_spamton_0,ПАРЕНЬ], КОТОРОГО Я [_spamton_0,УДАРИЛ] В НАЧАЛЕ НАШЕГО [_spamton_0,БОЯ]???", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "HA! I'M NOT EVEN SURE THAT HE IS [_spamton_0,ALIVE AND WELL]!!!", "ХА! Я ДАЖЕ НЕ УВЕРЕН, ЧТО ОН [_spamton_0,ЖИВ И ЗДОРОВ]!!!", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_1,ROYAL]?", "[_spamton_1,РОЙАЛ]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "ROYAL [_spamton_0,WHAT]? ROYAL [_spamton_0,WHO]?", "РОЙАЛ [_spamton_0,ЧТО]? РОЙАЛ [_spamton_0,КТО]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,WHO/WHAT/WHEN/WHY/HOW] IS [_spamton_0,ROYAL]?", "[_spamton_0,КТО/ЧТО/КОГДА/ПОЧЕМУ/КАК] ТАКОЙ [_spamton_0,РОЙАЛ]?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU'RE SO PATHETIC", "ТЫ ТАКОЙ ЖАЛКИЙ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "MUMBLING NONSENSE WORDS THROUGH A [_spamton_0,PLAYING CARD]", "БОРМОЧЕШЬ БЕССМЫСЛИЦУ ЧЕРЕЗ [_spamton_0,ИГРАЛЬНУЮ КАРТУ]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DO YOU THINK YOU CAN [_spamton_0,AVOID] YOUR [_spamton_0,UNAVOIDABLE, QUICKLY APPROACHING] DEMISE?", "ДУМАЕШЬ, ТЕБЕ УДАСТСЯ [_spamton_0,ИЗБЕЖАТЬ] СВОЕЙ [_spamton_0,НЕИЗБЕЖНОЙ И БЫСТРО ПРИБЛИЖАЮЩЕЙСЯ] ГИБЕЛИ?", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "[_spamton_0,THERE]", "[_spamton_0,ТАМ]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WHAT ARE YOU GONNA DO WITHOUT YOUR [_spamton_0,COMMUNICATION DEVICE]???", "ЧТО ТЫ БУДЕШЬ ДЕЛАТЬ БЕЗ СВОЕГО [_spamton_0,УСТРОЙСТВА СВЯЗИ]???", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "WAIT IS IT JUST [_spamton_0,ME]", "ПОСТОЙ, ЭТО ТОЛЬКО [_spamton_0,МНЕ]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "OR DOES IT SOUND LIKE A [_spamton_0,SHIP] IS COMING [_spamton_0,OUR] WAY??", "ИЛИ КАЖЕТСЯ, ЧТО [_spamton_0,КОРАБЛЬ] ИДЁТ В [_spamton_0,НАШУ] СТОРОНУ??", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S PROBABLY [_spamton_0,NOTHING] [_spamton_0,AT HALF PRICE]", "НАВЕРНОЕ, ЭТО ПРОСТО [_spamton_0,НИЧТО] [_spamton_0,ЗА ПОЛЦЕНЫ]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "IT'S PROBABLY JUST A SOUND IN MY [_spamton_0,HEAD], IN MY [_spamton_0,EARS]", "НАВЕРНОЕ, ЭТО ПРОСТО ЗВУК У МЕНЯ В [_spamton_0,ГОЛОВЕ], В МОИХ [_spamton_0,УШАХ]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THERE'S NO WAY A [_spamton_0,SHIP] COULD FIT IN THIS LITTLE [_spamton_0,CABIN FOR SALE]", "НИКАКОЙ [_spamton_0,КОРАБЛЬ] НЕ ПОМЕСТИТСЯ В ЭТОЙ МАЛЕНЬКОЙ [_spamton_0,ХИЖИНЕ НА ПРОДАЖУ]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "YOU WILL NEVER DEFEAT-", "ТЕБЕ НИКОГДА НЕ ПОБЕДИТЬ-", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "SAY [_spamton_0,GOODBYE] [_spamton_0,TO YOUR FRIENDS AND FAMILY]", "СКАЖИ [_spamton_0,ПРОЩАЙ] [_spamton_0,ДРУЗЬЯМ И СЕМЬЕ]", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "THE [_spamton_0,POWER OF NEO] WAS TOO MUCH FOR YOU", "[_spamton_0,СИЛА NEO] ОКАЗАЛАСЬ ТЕБЕ НЕ ПО ЗУБАМ", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "CONFIDENTIAL", "СЕКРЕТНО", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "DEFEATED BY A WEAKLING HUMAN...", "ПОБЕЖДЁН СЛАБЫМ ЧЕЛОВЕКОМ...", Language.Russian);
            SimplifiedChineseLanguagePackPlugin.Translate(SimplifiedChineseLanguagePackPlugin.GUID, null, "NOOOOOOOOOOOOOOO!!!!!!", "НЕЕЕЕЕЕЕЕЕТ!!!!!!", Language.Russian);


        }
    }
